const PHOTO_METADATA_BY_RECORD_ID = Object.freeze({
  "mobile-retail-27": {"descriptionVi":"Xe bán cà phê dạng rơ moóc, thân sơn xanh mint viền inox, có cửa kính phục vụ, đèn trong xe và biển chữ LED neon trên nóc. Dành cho quán đồ uống bán ở phố đi bộ, ven sông hay sự kiện đêm: kéo đi được, biển sáng giúp khách thấy quán từ xa.","descriptionEn":"Trailer coffee cart with a mint-green body and stainless trim, a glass service window, interior lights and an LED neon sign on the roof. For drink sellers on walking streets, riversides and night events, it can be towed anywhere, and the lit sign lets customers see it from afar.","altVi":"Xe đẩy cà phê xanh mint có biển neon, bánh xe, ven sông buổi tối","altEn":"Mint-green coffee cart with neon sign and wheels beside river at dusk","source":"/assets/content/projects/advertising/mobile-retail/mobile-retail-27-imagegen-20261018.webp","sha256":"ea5504087901b097a7c171a3638e9af9b4b2e8ba26416bbbed188cf47ee84c0b","provenance":"AI-generated illustration; ChatGPT web image edit (owner chat 6adfd119-c174-83ec-b69c-0c08da7c248f); upscaled RunningHub SeedVR2 tile to 3072; owner approved 2026-10-27 01:07Z; master PNG SHA256 47ddc2bf76782995ec43ad63b337283c931562d280c124659a1c13ed7a4b0055."},
  "kiosk-posm-41": {"descriptionVi":"Quầy lễ tân sự kiện khung gỗ ốp laminate trắng, có LED hắt sáng chân và mặt hộp đèn in logo, đặt trước backdrop bạt in. Dành cho hội thảo, hội nghị chuyên ngành, lễ ra mắt tại khách sạn, đặt ở sảnh đón, giúp khu đăng ký chuyên nghiệp, đồng bộ nhận diện và dễ tháo lắp chở đi.","descriptionEn":"Event reception counter with a wooden frame clad in white laminate, LED base lighting and a lightbox end panel printed with the logo, set before a printed backdrop. For seminars, industry conferences and hotel launches, in the welcome lobby, it makes registration look professional, on-brand and easy to move.","altVi":"Quầy lễ tân trắng có đèn hắt chân và backdrop chữ hội thảo","altEn":"White reception counter with base uplighting and conference backdrop lettering","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-41-imagegen-20261015.webp","sha256":"f9427c6f3f8f26de991bd747b07a13debdc431314ab28a2879cf1c6d90fd7a20","provenance":"AI-generated illustration; source ID imagegen:2026-10-15:kiosk-posm-08-x1; original SHA256 1bc7290a5439864b3adcb49ce2cfe84b67113ea7ab0c3a37a81ff3381ff45832; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "kiosk-posm-42": {"descriptionVi":"Quầy đón khách tiệc cưới mặt gỗ, thân hộp mica trong chứa hoa trắng, đế LED hắt sáng, kèm hộp mica đựng phong bì. Dành cho nhà hàng tiệc cưới, wedding planner, đặt ở sảnh vào, giúp khu nhận quà sang trọng, nổi bật trong ảnh cưới và tái sử dụng bằng cách thay hoa theo tông tiệc.","descriptionEn":"Wedding welcome counter with a wooden top, a clear acrylic body filled with white flowers, an LED-lit base and an acrylic envelope box. For wedding venues and planners, in the entrance hall, it makes the gift table elegant, shines in wedding photos and is reused by changing flowers to each theme.","altVi":"Quầy tiếp tân acrylic trong có hoa trắng bên trong và đèn hắt chân","altEn":"Clear acrylic reception desk holding white flowers inside with base uplighting","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-42-imagegen-20261015.webp","sha256":"3b40903de721758973f8e212e9261d6f6565e37336860e1950c4ed002b72275e","provenance":"AI-generated illustration; source ID imagegen:2026-10-15:kiosk-posm-08-x3; original SHA256 2a1a725b8533cd4d1825c070032b8bd05c39fef55692aab59d15df5173bfbd83; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "kiosk-posm-43": {"descriptionVi":"Quầy đăng ký sự kiện khung gỗ ốp gỗ dừa, mặt trước in chữ, kèm vách sau trang trí lá dừa. Dành cho hội thảo, hội chợ chủ đề xanh, nông sản, đặt ở sảnh đón khách, giúp khu đăng ký đúng tinh thần sự kiện, mộc mạc, gọn và tháo ráp mang đi nhiều nơi.","descriptionEn":"Event registration counter with a wooden frame clad in coconut wood, a printed front and a back wall with a palm-leaf motif. For green-themed seminars, fairs and agricultural events, in the welcome lobby, it matches the event spirit, feels natural and packs down for travel.","altVi":"Quầy đăng ký ốp gỗ có chữ quầy đăng ký và hình lá cọ trên tường","altEn":"Timber-clad registration desk with check-in lettering and palm leaf graphic on wall","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-43-imagegen-20261017.webp","sha256":"c60a25778edd6858ad2fbc39ef37527c1d868364978df946a6d3f7b9c32d6351","provenance":"AI-generated illustration; source ID imagegen:2026-10-17:kiosk-posm-08-x2; original SHA256 48c74cefc857062198f2e55e86c9b596f56f7361bf96df09067bea1221200eb3; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "led-displays-lightboxes-25": {"descriptionVi":"Màn hình LED module trong nhà gắn cố định trên khung thép âm tường, viền ốp gỗ đồng bộ với sân khấu hội trường. Dành cho khách sạn, trung tâm tiệc cưới, hội nghị, giúp đổi phông theo từng sự kiện chỉ bằng file hình, tiết kiệm chi phí in phông và giữ hội trường luôn gọn đẹp.","descriptionEn":"Indoor LED module screen fixed on a recessed steel frame with timber trim that matches the ballroom stage. For hotels, wedding venues and conference centres, it changes the backdrop for each event with just an image file, saving print costs and keeping the hall tidy.","altVi":"Màn LED nền xanh ghi HỘI NGHỊ KHÁCH HÀNG, cạnh bàn tiệc tròn","altEn":"Blue-background LED screen reading CUSTOMER CONFERENCE beside round banquet tables","source":"/assets/content/projects/advertising/led-displays-lightboxes/led-displays-lightboxes-25-imagegen-20261017.webp","sha256":"336b21834ad67e780a7b6eb1d41678643ac939703d5afb336fbd6b5aac423aab","provenance":"AI-generated illustration; source ID imagegen:2026-10-17:led-man-hoi-nghi; original SHA256 8e940b125fc19290d91f1a74ebd14585eb34359b2df8af6c568596865afcf31a; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "led-displays-lightboxes-26": {"descriptionVi":"Màn hình LED module trong nhà gắn cố định trên vách ốp gỗ phía sau sân khấu, viền khung đen mảnh, lưới cabinet đều. Dành cho trường học, hội trường cơ quan, nhà văn hóa, giúp trình chiếu lễ khai giảng, hội nghị, văn nghệ rõ ràng cho cả hội trường mà không cần máy chiếu hay phông in.","descriptionEn":"Indoor LED module screen fixed to the timber-clad wall behind the stage, with a thin black frame and an even cabinet grid. For schools, public halls and community centres, it shows ceremonies, meetings and performances clearly to the whole hall without a projector or printed backdrop.","altVi":"Màn LED ghi CHÀO MỪNG NĂM HỌC MỚI, đối diện dãy ghế gỗ hội trường","altEn":"Large LED screen reading WELCOME NEW SCHOOL YEAR facing rows of timber hall seats","source":"/assets/content/projects/advertising/led-displays-lightboxes/led-displays-lightboxes-26-imagegen-20261018.webp","sha256":"8eec776c219f989eb84b04022e24e5009d11811c461223ead8c281109b085347","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:led-man-hoi-truong; original SHA256 ab7fe2aea7cdbe46e169cdb6c166abde18f863a86beac7685c4ef468b501a7a4; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "led-displays-lightboxes-27": {"descriptionVi":"Bảng hiệu chữ nổi LED và logo tròn phát sáng, dựng trên khung thép mái tòa nhà, kèm dòng phụ đề nhỏ phía dưới. Dành cho trung tâm hội nghị, nhà hàng tiệc cưới, khách sạn nhiều tầng, giúp tên công trình thấy rõ từ xa vào buổi tối và làm điểm nhận diện cho cả khu vực.","descriptionEn":"Rooftop sign of LED-lit raised letters and a glowing round logo on a steel frame, with a smaller subtitle line below. For convention centres, wedding venues and multi-storey hotels, it makes the building name visible from far away at night and becomes a landmark for the area.","altVi":"Bảng hiệu chữ LED sáng trên mái, kèm logo tròn phát sáng","altEn":"Illuminated LED lettering on rooftop sign with glowing round logo","source":"/assets/content/projects/advertising/led-displays-lightboxes/led-displays-lightboxes-27-imagegen-20261018.webp","sha256":"1eeccb25da108360c05d831468b4f94d64f2fb2d9e7e6aa667da3f2ca7433849","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:led-chu-diem-nong; original SHA256 f71b98ac97735464567d84cec164b9426ce3a664bb4abce962a8e61f9c97549d; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "led-displays-lightboxes-28": {"descriptionVi":"Chữ nổi mặt mica vàng có đèn LED và logo tròn, gắn trên mảng mặt dựng phía trên lối vào, kèm đèn rọi tường. Dành cho quán cà phê, nhà hàng, cửa hàng mặt phố, giúp tên quán sáng nổi bật vào buổi tối, đọc rõ từ bên kia đường và mặt tiền trông ấm, sang.","descriptionEn":"Raised letters with yellow acrylic faces lit by LED and a round logo, mounted on the fascia above the entrance with wall washers. For cafes, restaurants and street-front stores, it makes the name glow at night, reads clearly from across the street and gives the frontage a warm, upscale look.","altVi":"Bảng hiệu chữ vàng phát sáng và logo ly cà phê trên mặt tiền","altEn":"Gold illuminated lettering and coffee cup logo on a facade sign","source":"/assets/content/projects/advertising/led-displays-lightboxes/led-displays-lightboxes-28-imagegen-20261018.webp","sha256":"ef359877ae2bedd780214c94719ac5ece63d695aebb6a8c467ef2fbf49720d3a","provenance":"AI-generated illustration; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-31; master PNG SHA256 3050157fc62f6aa8c0cb3fa921f5d21e32e9d1acef64b0bc6ba53c2957f0f18d."},
  "led-displays-lightboxes-29": {"descriptionVi":"Bảng vẫy LED khung nhôm, chữ LED nhiều màu, viền đèn chạy đuổi, treo trên tay sắt vươn ra từ mặt tiền. Dành cho tiệm sửa xe, gara, cửa hàng dịch vụ ven đường, giúp khách đi hai chiều thấy tên và dịch vụ từ xa, nhất là khi trời tối, chi phí vừa phải.","descriptionEn":"Projecting LED sign in an aluminium frame with multi-colour LED lettering and a chasing light border, hung on a steel arm from the frontage. For motorbike repair shops, garages and roadside service stores, it shows the name and services to traffic in both directions from afar, especially at night, at moderate cost.","altVi":"Bảng vẫy LED viền chạy đuổi ghi sửa xe, vá vỏ, thay nhớt, rửa xe","altEn":"Chasing-light LED sign listing repair, tyre patching, oil change and car wash","source":"/assets/content/projects/advertising/led-displays-lightboxes/led-displays-lightboxes-29-imagegen-20261018.webp","sha256":"611779680e318905418c08e6a80953b93b5d31d63422e9b8984bd29e0722dabe","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:led-bang-vay-sua-xe; original SHA256 de2e80159d32df89b423f70c24efae12ddd35afaab12db8f63729daa7b4833ee; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "led-displays-lightboxes-30": {"descriptionVi":"Bảng LED đứng khung thép đen có chân, chữ LED điểm nhiều màu, viền đèn vàng, đặt trực tiếp trên vỉa hè cạnh quầy bán. Dành cho xe bánh mì, quán ăn sáng, cửa hàng nhỏ không có chỗ treo biển, giúp khách thấy tên quán từ xa và dọn vào trong sau giờ bán.","descriptionEn":"Freestanding LED board on a black steel stand with multi-colour dot LED lettering and a yellow light border, placed on the pavement next to the stall. For banh mi carts, breakfast spots and small shops with nowhere to hang a sign, it shows the name from afar and can be brought inside after hours.","altVi":"Bảng LED chữ đỏ trắng vàng có viền bóng chạy, đặt trên vỉa hè","altEn":"Red, white and yellow LED lettering with chasing border standing on the pavement","source":"/assets/content/projects/advertising/led-displays-lightboxes/led-displays-lightboxes-30-imagegen-20261018.webp","sha256":"d996d5ccf33b96abedb0d18555c8ffecf4ebcc23bcad92e4f938a0eef627e017","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:led-bang-vay-banh-mi; original SHA256 2435727590731d7d2a195f27dd3d656d623a698d468de6522e07fcee3a5e452c; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "office-signs-wayfinding-33": {"descriptionVi":"Kỷ niệm chương hình khiên bằng gỗ, kim loại và pha lê, mặt khắc hoặc in nội dung vinh danh, đặt trên đế gỗ hoặc kim loại. Dành cho doanh nghiệp, cơ quan, hiệp hội tổ chức lễ tri ân, khen thưởng, giúp ghi nhận đóng góp trang trọng và người nhận lưu giữ, trưng bày lâu dài.","descriptionEn":"Shield-shaped award plaques in timber, metal and crystal, engraved or printed with the honour, on timber or metal bases. For companies, agencies and associations holding award and appreciation ceremonies, they recognise contributions formally and give recipients a keepsake to display for years.","altVi":"Ba kỷ niệm chương hình khiên gỗ và pha lê khắc chữ, đặt trên bàn","altEn":"Three shield-shaped timber and crystal plaques engraved with text on a table","source":"/assets/content/projects/advertising/office-signs-wayfinding/office-signs-wayfinding-33-owner-20261012.webp","sha256":"dcaf9b2ee58d97bd4db7d15854f66f0be5d2b81fe4631412edb40ebbb9949325","provenance":"AI-generated illustration; owner approved 2026-10-12; original SHA256 1be51ed9a12dd456abc7a1d54077c068fa7eca1d009583d187237f13d49f1e41; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "office-signs-wayfinding-34": {"descriptionVi":"Kỷ niệm chương acrylic cắt hình ngọn lửa, mặt sau phủ nhũ bạc, in UV màu và nội dung ghi nhận, gắn trên đế đen. Dành cho doanh nghiệp, cơ quan trao thưởng nhân viên, đối tác, nhà tài trợ, giúp phần thưởng màu sắc theo nhận diện, nhẹ, bền và chi phí hợp lý khi đặt số lượng.","descriptionEn":"Flame-shaped acrylic award with a silver-backed face, UV colour print and recognition text, set on a black base. For companies and agencies rewarding staff, partners and sponsors, it carries the brand colours, is light and durable, and is affordable in quantity.","altVi":"Kỷ niệm chương acrylic hình ngọn lửa in đỏ xanh vàng, đế đen","altEn":"Flame-shaped acrylic plaques in red, blue and yellow print on black bases","source":"/assets/content/projects/advertising/office-signs-wayfinding/office-signs-wayfinding-34-owner-20261012.webp","sha256":"bde62af54755c8d0f13783d278333982d8b099f943be72d81b3494830f09fd6c","provenance":"AI-generated illustration; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-31; master PNG SHA256 3480c197a7bc764b2397ec64abd2491c73c7a49138a65b1fadc91d42a7b74c6d."},
  "office-signs-wayfinding-35": {"descriptionVi":"Kỷ niệm chương hình khiên bằng gỗ đỏ, gắn tấm đồng mạ vàng khắc nội dung, hoa văn đúc nổi viền, kèm chân đỡ gỗ. Dành cho cơ quan, doanh nghiệp, hiệp hội trao danh hiệu, tri ân, giúp ghi nhận trang trọng, sang và người nhận đặt trên bàn làm việc hoặc tủ trưng bày lâu dài.","descriptionEn":"Shield-shaped award plaque in red timber with an engraved gold-plated brass plate and cast ornamental border, with a timber stand. For agencies, companies and associations presenting honours and thanks, it recognises achievements formally and elegantly and sits on a desk or display cabinet for years.","altVi":"Kỷ niệm chương hình khiên gỗ đỏ có tấm đồng vàng khắc chữ vinh danh","altEn":"Red timber shield plaque with gold-toned brass plate engraved with honour text","source":"/assets/content/projects/advertising/office-signs-wayfinding/office-signs-wayfinding-35-owner-20261012.webp","sha256":"1967275f462327c73798ee628a316d9b3ebb9d4514ac01b00810dcefefbba1cc","provenance":"AI-generated illustration; owner approved 2026-10-12; original SHA256 7f4f07d1522a254a4b7ed299a25254d55427e6877fea4ec9063ed1d14d14764e; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "office-signs-wayfinding-36": {"descriptionVi":"Kỷ niệm chương pha lê cắt cạnh hình ngọn lửa, khắc chữ và biểu tượng, phần chân phủ màu xanh chuyển sắc, gắn trên đế gỗ óc chó. Dành cho doanh nghiệp, cơ quan, trường học trao danh hiệu vinh danh, giúp phần thưởng sang trọng, bắt sáng đẹp khi đặt trên kệ và lưu giữ lâu dài.","descriptionEn":"Facet-cut crystal award in a flame shape, engraved with text and an emblem, its base fading into blue, set on a walnut stand. For companies, agencies and schools presenting honours, it looks premium, catches the light on a shelf and lasts for years.","altVi":"Kỷ niệm chương pha lê hình ngọn lửa khắc chữ vinh danh trên đế gỗ","altEn":"Flame-shaped crystal plaque engraved with honour text on timber base","source":"/assets/content/projects/advertising/office-signs-wayfinding/office-signs-wayfinding-36-owner-20261012.webp","sha256":"bc6c745f86afee306f175bf13feec7651002887a4caf827de3bdc78f5b48b01c","provenance":"AI-generated illustration; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-31; master PNG SHA256 65943c8db20627b28dba9535786cc1ff53f12ad7ca7a11db42a0bc86088a0dd8."},
  "office-signs-wayfinding-37": {"descriptionVi":"Bộ kỷ niệm chương pha lê nhiều hình dáng như núi, ngọn lửa, khối đa giác, in UV màu và khắc chữ, gắn đế gỗ sáng có mẫu hình ngôi sao. Dành cho doanh nghiệp tổ chức lễ vinh danh nhiều hạng mục, giúp mỗi giải có kiểu riêng mà vẫn đồng bộ, trưng bày đẹp trên kệ văn phòng.","descriptionEn":"Set of crystal awards in mountain, flame and faceted shapes, UV-printed and engraved, on light wood bases including a star-shaped one. For companies holding multi-category award nights, each prize has its own look while the set stays consistent and displays well on office shelves.","altVi":"Năm kỷ niệm chương pha lê đế gỗ khắc chữ vinh danh","altEn":"Five crystal plaques on timber bases engraved with honour and trusted partner text","source":"/assets/content/projects/advertising/office-signs-wayfinding/office-signs-wayfinding-37-owner-20261012.webp","sha256":"cd17e8277c42d4bd9886d121db4a9a4628131eaece49ccd89be861a602da4245","provenance":"AI-generated illustration; owner approved 2026-10-12; original SHA256 c140e21b768459efdce0f4553cc1e44dc6f40d1df1e1dbb5222ffe7d4f9aa00c; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "office-signs-wayfinding-38": {"descriptionVi":"Kỷ niệm chương inox cắt laser hình ngọn lửa, mạ vàng xen các dải sơn xanh, khắc nội dung ghi nhận, gắn trên đế đá đen. Dành cho doanh nghiệp, hiệp hội trao giải cho cá nhân, đối tác tiêu biểu, giúp phần thưởng cứng cáp, nổi bật trên sân khấu và giữ màu bền theo thời gian.","descriptionEn":"Laser-cut stainless steel award in a flame shape, gold-plated with painted blue bands and engraved recognition text, mounted on a black stone base. For companies and associations honouring outstanding people and partners, it is sturdy, stands out on stage and keeps its colour for years.","altVi":"Kỷ niệm chương mạ vàng xanh lam có chữ vinh danh, đặt trên đế đá đen","altEn":"Blue-and-gold plated plaque engraved with honour text on a black stone base","source":"/assets/content/projects/advertising/office-signs-wayfinding/office-signs-wayfinding-38-owner-20261012.webp","sha256":"d6ba0b1792a46a2e7b6b7ec14879f234a7e70a3dff33b597c8a5db9c9336f8a1","provenance":"AI-generated illustration; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-31; master PNG SHA256 79dd72a9cb49343f8037c03cfcf086708214abbbe2f75300d362d15d17094a9b."},
  "office-signs-wayfinding-39": {"descriptionVi":"Kỷ niệm chương pha lê cắt hình ngọn lửa, in UV màu chuyển sắc và nội dung vinh danh, gắn trên đế pha lê. Dành cho doanh nghiệp, tổ chức trao giải nhân viên xuất sắc, đối tác, nhà tài trợ, giúp phần thưởng nổi bật trên sân khấu, màu sắc theo nhận diện và đáng trưng bày.","descriptionEn":"Flame-shaped crystal awards UV-printed with colour gradients and the honour text, mounted on crystal bases. For companies and organisations awarding top staff, partners and sponsors, they stand out on stage, carry the brand colours and are worth displaying.","altVi":"Ba kỷ niệm chương pha lê đỏ, xanh, lục khắc chữ ghi nhận đóng góp","altEn":"Three crystal plaques in red, blue and green engraved with contribution recognition text","source":"/assets/content/projects/advertising/office-signs-wayfinding/office-signs-wayfinding-39-owner-20261012.webp","sha256":"f34e5acb9bd0b2b77fefbfe49bffbeda611900457bdd14615a40ac425ddc2ead","provenance":"AI-generated illustration; owner approved 2026-10-12; original SHA256 9af21b2824ea33a3301775ee82464dc83ab3d12e2dcd06c81e28425f2b71d317; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "office-signs-wayfinding-40": {"descriptionVi":"Kỷ niệm chương pha lê mài giác nhiều mặt, khắc laser hoặc in nội dung kỷ niệm, gắn trên đế gỗ. Dành cho doanh nghiệp tổ chức lễ kỷ niệm thành lập, tri ân nhân viên lâu năm, đối tác, giúp phần quà lấp lánh trên sân khấu, trang trọng và được trưng bày lâu dài.","descriptionEn":"Faceted cut-crystal award, laser-engraved or printed with the anniversary text, mounted on a timber base. For companies celebrating anniversaries and honouring long-serving staff and partners, it sparkles on stage, feels formal and is displayed for years.","altVi":"Kỷ niệm chương pha lê khắc laser trên đế gỗ đỏ","altEn":"Laser-engraved crystal anniversary plaque on a red timber base","source":"/assets/content/projects/advertising/office-signs-wayfinding/office-signs-wayfinding-40-owner-20261012.webp","sha256":"1d3bf559c5b12b4d68c62af3764b549a5f00f33311e0a22e2bc98de0b5baa7d1","provenance":"AI-generated illustration; owner approved 2026-10-12; original SHA256 ceaff512305ac5a321caf7d8d7d1432ebff3d5fc53b41798ae9d5c1845989529; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "print-decals-22": {"descriptionVi":"Bộ bao bì giấy kraft gồm túi quai xách và hộp gấp, in một màu tên và logo tiệm. Dành cho tiệm bánh mì, tiệm bánh, quán ăn bán mang đi, giúp đựng bánh gọn, giữ bánh khô ráo, thân thiện môi trường và mỗi túi khách cầm đi là một lần quảng bá thương hiệu.","descriptionEn":"Kraft paper packaging set of handled bags and folding boxes printed in one colour with the shop name and logo. For banh mi shops, bakeries and takeaway eateries, it holds food neatly, keeps bread dry, is eco-friendly, and every bag a customer carries advertises the brand.","altVi":"Hộp và túi giấy kraft nâu in chữ bánh mì nướng và hình lúa mì","altEn":"Brown kraft boxes and bags printed with grilled bread lettering and wheat ears","source":"/assets/content/projects/advertising/print-decals/print-decals-22-owner-20261012.webp","sha256":"ad0aadbd8cdca026c6c99cccd108b87d0207a8987d5b071b1d1d55045a402392","provenance":"AI-generated illustration; owner approved 2026-10-12; original SHA256 88d3486d4883426d5bf5e533a500e497c2d62008247df20ff6d116fc02186fb6; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "print-decals-23": {"descriptionVi":"Thẻ thành viên nhựa PVC in màu, viền ép nhũ vàng, kèm phong bì giấy mỹ thuật in logo. Dành cho cửa hàng, spa, nhà hàng, siêu thị làm chương trình khách hàng thân thiết, giúp khách giữ thẻ lâu dài, cảm thấy được trân trọng và quay lại mua thường xuyên hơn.","descriptionEn":"Full-colour PVC membership cards with gold foil accents, with art paper envelopes printed with the logo. For shops, spas, restaurants and supermarkets running loyalty programmes, they last in customers' wallets, make them feel valued and bring them back more often.","altVi":"Thẻ thành viên PVC xanh dương viền vàng và phong bì in logo trên bàn gỗ","altEn":"Blue PVC membership cards with gold edge and logo envelope on timber table","source":"/assets/content/projects/advertising/print-decals/print-decals-23-owner-20261012.webp","sha256":"1affde812e9444682a216373f9c1ab9e7656a0f9de96d6c05beff72ac7f88913","provenance":"AI-generated illustration; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-31; master PNG SHA256 48ce7948e13cd2c8d30dbe18e165c181587789b1663306f81956dc92a4215425."},
  "print-decals-24": {"descriptionVi":"Vé vào cổng in màu trên giấy cứng, ép nhũ, đánh số nhảy từng vé, có đường răng cưa xé cuống. Dành cho ban tổ chức sự kiện, hội chợ, triển lãm, khu vui chơi, giúp kiểm soát số lượng khách, hạn chế vé giả và tạo ấn tượng chuyên nghiệp ngay từ cổng.","descriptionEn":"Admission tickets printed in colour on card stock with foil accents, individually numbered and perforated for a tear-off stub. For event organisers, fairs, exhibitions and amusement parks, they control attendance, deter counterfeits and create a professional impression right at the gate.","altVi":"Vé cổng in xanh navy và vàng có số thứ tự, đặt trên mặt gỗ","altEn":"Three navy and gold entry tickets with sequence numbers on timber surface","source":"/assets/content/projects/advertising/print-decals/print-decals-24-owner-20261012.webp","sha256":"b7eb7e3aefe11dd845d9a0c7403d3e5eb7e8874751bfa50bfa17caecc8626dbd","provenance":"AI-generated illustration; owner approved 2026-10-12; original SHA256 2fa8a114b32e9f3a6fb4a803cdc8708bf68112a56dc688164ac66a2308020f3b; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "signage-raised-letters-27": {"descriptionVi":"Chữ nổi inox mặt kín, đèn LED hắt sáng phía sau tạo quầng trên tường, gắn chân nổi lên mặt tiền. Dành cho nhà hàng, khách sạn, văn phòng, cửa hàng cao cấp, giúp tên thương hiệu sang, nổi khối ban ngày và tỏa quầng sáng mềm khi chạng vạng mà không chói.","descriptionEn":"Closed-face stainless raised letters with LED halo lighting behind, stood off the frontage wall. For restaurants, hotels, offices and premium stores, they make the brand name look upscale with solid relief by day and a soft glow at dusk without glare.","altVi":"Chữ nổi inox xước có viền sáng vàng ấm, gắn trên tường trắng cạnh góc phố","altEn":"Brushed stainless raised letters with warm yellow edge light on white wall at a corner","source":"/assets/content/projects/advertising/signage-raised-letters/signage-raised-letters-27-imagegen-20261014.webp","sha256":"98cb8efa5834f9fd48ff1827260cd31e9c52979e3754f3fa99faec9dbae9dfb6","provenance":"AI-generated illustration; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-31; master PNG SHA256 446ebdda39ce59857913591a40f862218c6e0089e37b0c1ee329614b64121374."},
  "signage-raised-letters-28": {"descriptionVi":"Chữ nổi mặt mica đỏ có đèn LED, thành chữ inox hoặc alu, gắn trực tiếp lên mặt tường trắng tòa nhà. Dành cho cửa hàng, nhà hàng, văn phòng mặt phố, giúp tên thương hiệu sáng rõ vào buổi tối, đọc được từ xa và mặt tiền gọn hơn bảng hiệu hộp.","descriptionEn":"Raised letters with red acrylic faces lit by LED and stainless or aluminium returns, fixed straight to the white building wall. For street-front shops, restaurants and offices, they make the brand name glow at night, read from afar and keep the frontage cleaner than a box sign.","altVi":"Chữ nổi mica đỏ phát sáng gắn trên mặt tường trắng của tòa nhà","altEn":"Glowing red acrylic dimensional letters on white building wall at evening","source":"/assets/content/projects/advertising/signage-raised-letters/signage-raised-letters-28-imagegen-20261014.webp","sha256":"08843c54915040f0908905f7514ec9ea7d8b7db95c00248cd2e6c470bca678ae","provenance":"AI-generated illustration; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-31; master PNG SHA256 2079a09a85c3f75b0dcf1869379a8ff932a9b63d5b23e40a8eb26df53d3db8ef."},
  "signage-raised-letters-29": {"descriptionVi":"Chữ nổi inox vàng xước gia công tại xưởng, mặt chữ dày, cạnh hàn kín, đặt thử trên tấm nền trước khi lắp. Dành cho tiệm vàng bạc, cửa hàng trang sức, showroom cao cấp, gắn lên mặt tiền hoặc vách sau quầy, giúp thương hiệu sáng sang, không gỉ và bền màu ngoài trời.","descriptionEn":"Brushed gold stainless steel raised letters made in the workshop, with thick faces and sealed welded returns, test-laid on a backing panel before installation. For gold shops, jewellers and premium showrooms, fixed on the facade or the wall behind the counter, they look rich, resist rust and hold their colour outdoors.","altVi":"Chữ nổi inox vàng xước đặt trên bàn trong xưởng sản xuất","altEn":"Brushed gold stainless raised letters laid on a workshop table","source":"/assets/content/projects/advertising/signage-raised-letters/signage-raised-letters-29-imagegen-20261014.webp","sha256":"d920748eecc234d08ebcbc49e5bc32b417a553d0ce9c026447309b0730ccfdf6","provenance":"AI-generated illustration; source ID imagegen:2026-10-14:signage-detail-x1-xuong-a; original SHA256 4b16f7c196a4d2eaee2113df7cc35981c2ea85496e67cafb11a724d64ff87536; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "signage-raised-letters-30": {"descriptionVi":"Chữ nổi inox mạ PVD màu đồng, chân đế cách tường, gắn LED hắt sáng phía sau, đang thử đèn tại xưởng trước khi giao. Dành cho cửa hàng, spa, văn phòng, showroom gắn lên mặt tiền hoặc vách sảnh, giúp tên thương hiệu có viền sáng mềm về đêm và màu kim loại bền lâu.","descriptionEn":"PVD bronze-coated stainless steel letters on stand-off pins with LED backlighting, being light-tested in the workshop before delivery. For shops, spas, offices and showrooms, fixed on the facade or a lobby wall, they give the brand name a soft halo at night and a long-lasting metal finish.","altVi":"Chữ nổi inox vàng có đèn hắt phía sau, gắn trên panel trắng trong xưởng","altEn":"Gold stainless letters with backlight mounted on white panel in workshop","source":"/assets/content/projects/advertising/signage-raised-letters/signage-raised-letters-30-imagegen-20261014.webp","sha256":"72933ebaa09cf1c613136ad5307dea77d8eb356ab600b56692a375710c10428d","provenance":"AI-generated illustration; source ID imagegen:2026-10-14:signage-detail-x1-xuong-b; original SHA256 271892d0d4094b540c925888fde58188334ea2dc492255ab19a57a4c4adeddd1; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "signage-raised-letters-31": {"descriptionVi":"Chữ nổi hộp mặt mica đỏ sáng mặt, thành nhôm sơn trắng, bên trong gắn LED module, đang thử đèn tại xưởng. Dành cho quán ăn, nhà hàng, cửa hàng gắn trên bảng hiệu mặt tiền, giúp tên quán đỏ rực đều màu cả ngày lẫn đêm, đọc rõ từ xa và tiết kiệm điện.","descriptionEn":"Channel letters with red front-lit acrylic faces, white aluminium returns and LED modules inside, being light-tested in the workshop. For eateries, restaurants and shops on the facade sign, they glow evenly red day and night, read clearly from afar and use little power.","altVi":"Chữ nổi đỏ có viền trắng phát sáng, đặt trên bàn trong xưởng","altEn":"Red raised letters with white edge and glow placed on a workshop table","source":"/assets/content/projects/advertising/signage-raised-letters/signage-raised-letters-31-imagegen-20261014.webp","sha256":"a7995de4c2a9b7917bfc93986c11e1bf2084366bd85fae9c4e6a1e8564961edf","provenance":"AI-generated illustration; source ID imagegen:2026-10-14:signage-detail-x2-xuong-a; original SHA256 7195f21c740eb5c18a3aedfa5e6eab97b3ee7f9150e6a72fdb146e6dc6c79cf3; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "signage-raised-letters-32": {"descriptionVi":"Thợ lắp mặt mica đỏ vào thân chữ nhôm trắng, bắt vít chân và đi dây LED trên bàn xưởng trước khi mang ra công trình. Dành cho cửa hàng, công ty cần chữ nổi sáng mặt cho bảng hiệu, giúp chữ hoàn thiện kín bụi, dễ thay đèn và lắp đặt nhanh tại mặt tiền.","descriptionEn":"A worker fits red acrylic faces into white aluminium letter bodies, fixing pins and LED wiring on the workshop bench before site installation. For shops and companies needing front-lit channel letters, it gives dust-tight letters, easy LED replacement and fast fitting on the facade.","altVi":"Thợ lắp chữ nổi đỏ viền trắng, cạnh vít và tuốc nơ vít","altEn":"Technician fitting red raised letters with white edge on workbench beside screws and screwdriver","source":"/assets/content/projects/advertising/signage-raised-letters/signage-raised-letters-32-imagegen-20261014.webp","sha256":"c34982e47d026ecc18934594ac756e9ecdb47836a30db69986fc55ed9b0c0a36","provenance":"AI-generated illustration; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-31; master PNG SHA256 f06e41cfab3af538f1c612037009d0a1b04082984087983981b95687c09b3bd2."},
  "signage-raised-letters-33": {"descriptionVi":"Bảng mica trong uốn dây LED neon thành chữ và hình ly cà phê, treo bằng dây cáp phía trên quầy pha chế. Dành cho quán cà phê, quán bar, tiệm bánh, giúp tạo không khí ấm cúng, thành góc chụp hình cho khách và làm tên quán nổi bật trong không gian tối.","descriptionEn":"Clear acrylic panel with LED neon flex shaped into lettering and a coffee cup, hung on cables above the bar. For cafes, bars and bakeries, it creates a cosy mood, becomes a photo spot for customers and makes the shop name stand out in a dim interior.","altVi":"Bảng mica trong có chữ cà phê và hình ly cà phê phát sáng kiểu neon","altEn":"Clear acrylic panel with coffee lettering and cup symbol glowing neon-style","source":"/assets/content/projects/advertising/signage-raised-letters/signage-raised-letters-33-imagegen-20261018.webp","sha256":"aa6d4deee95a5be8d91f893e21d50fb519ae908c98ec876ae02a831ad550f28b","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:signage-raised-letters-33-1; original SHA256 836cf541752a3801d9fea68a82c000aa5b27b3991575706e0fd0201da6f80fa9; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "signage-raised-letters-34": {"descriptionVi":"Bảng hiệu mặt tiền ốp lam gỗ theo chiều dọc, dải LED uốn lượn hắt sáng, bảng tên chữ nổi và logo gắn trên nền tối phía trên cửa kính. Dành cho nhà hàng, quán ăn gia đình nhà phố, giúp mặt tiền ấm cúng, nổi bật khi lên đèn và khách nhận diện quán từ đầu phố.","descriptionEn":"Facade sign clad in vertical wood louvres with a wavy LED line, raised-letter name and logo on a dark band above the glass front. For family restaurants in townhouses, it makes the front warm and striking once lit and lets diners spot the place from down the street.","altVi":"Mặt tiền nhà hàng ốp gỗ có dải đèn LED và bảng chữ mạ vàng","altEn":"Timber-clad restaurant facade with LED strip and gold-plated lettering panel","source":"/assets/content/projects/advertising/signage-raised-letters/signage-raised-letters-34-imagegen-20261014-audit-a270-v1.webp","sha256":"9efb63286f36857d0017cf5aa2935bf7b2b3805139e03f37127386132918fb41","provenance":"AI-generated illustration; owner selected A270-v1 in HTML audit and confirmed in chat 2026-10-22; ChatGPT web gpt-image; original SHA256 9d1b0167aeeabadb36d0d8f8295c85516780d92fa54c9c633166c2c54af52e57; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "kiosk-posm-38": {"descriptionVi":"Vách trưng bày thương hiệu ốp lam gỗ, mảng in tên và hình sản phẩm, khoang vòm có kệ đèn LED, kèm bục tròn bày mẫu. Dành cho thương hiệu hương liệu, mỹ phẩm, đồ cao cấp làm điểm bán trong trung tâm thương mại, giúp kể câu chuyện thương hiệu và làm sản phẩm nổi bật trong ánh sáng ấm.","descriptionEn":"Brand display wall with timber slats, printed name and product imagery, an arched niche with LED-lit shelves and round plinths for samples. For fragrance, cosmetics and premium brands with a mall sales point, it tells the brand story and makes products stand out in warm light.","altVi":"Vách trưng bày ốp gỗ, mica đen, có kệ tròn và bục gỗ tròn","altEn":"Timber-clad display wall in black acrylic with round shelves and round wooden plinth","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-38-imagegen-20261014-audit-a057-v1.webp","sha256":"03341ea5b459ac298c407b25979e6d171b06f49dd4c441e76b88d1e474452fb3","provenance":"AI-generated illustration; ChatGPT web image edit (owner chat 6adfd3c3-f4e0-83ec-b65e-ec700ba3d93f); upscaled RunningHub SeedVR2 tile to 3072; owner approved 2026-10-27 01:07Z; master PNG SHA256 4cd3cb2b16015f49da0c34667169bfab2ba1dd8cef33c2e14603848c4c3a52fd."},
  "office-signs-wayfinding-32": {"descriptionVi":"Biển tên inox xước chữ ăn mòn tô màu đen, bắt bốn chốt inox lên trụ cổng. Dành cho khách sạn, nhà nghỉ, biệt thự, văn phòng công ty, giúp khách đến bằng xe máy, ô tô nhận ra lối vào đúng chỗ, bền ngoài trời, không gỉ và trông chỉn chu, đáng tin.","descriptionEn":"Brushed stainless name plate with etched, black-filled lettering, fixed with four stainless standoffs to the gate pillar. For hotels, guesthouses, villas and company offices, it shows guests arriving by motorbike or car the right entrance, lasts outdoors without rust and looks neat and trustworthy.","altVi":"Biển tên inox xước ghi tên khách sạn, gắn trên trụ cổng trắng","altEn":"Brushed stainless hotel name plate fixed to white gate pillar","source":"/assets/content/projects/advertising/office-signs-wayfinding/office-signs-wayfinding-32-imagegen-20261014.webp","sha256":"338b567e59c749b23e5f568bd4401a57edde1f2ec35de8011055ce39594ef1b0","provenance":"AI-generated illustration; source ID imagegen:2026-10-14:new-bang-ten-cong-ty-x1; original SHA256 c050e9578fa849ae430d95ad47db2fa01340b2fc77cb152256eebfccaa30bd36; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "led-displays-lightboxes-19": {"descriptionVi":"Bảng đèn LED siêu mỏng để quầy, khung nhôm bạc, mặt in hình ly đồ uống chiếu sáng đều, cắm điện là dùng. Dành cho quán trà sữa, cà phê mang đi, đặt trên quầy order, giúp giới thiệu món mới ngay tầm mắt khách, gợi ý món bán chạy và đổi tranh dễ.","descriptionEn":"Ultra-thin LED counter light panel in a silver aluminium frame with an evenly lit printed drinks image, plug and use. For bubble tea and takeaway coffee shops, on the order counter, it shows new drinks at eye level, nudges customers toward featured items and takes new prints easily.","altVi":"Bảng mỏng nền xanh có chữ trà mây xanh, ly trà đặt trên quầy gỗ","altEn":"Slim blue panel with green tea lettering and tea cup on timber counter","source":"/assets/content/projects/advertising/led-displays-lightboxes/led-displays-lightboxes-19-imagegen-20261014.webp","sha256":"1bb415230a5bd26d1b53a0c5c9faeb21fdee9688fa4378cd6af0124424012c89","provenance":"AI-generated illustration; source ID imagegen:2026-10-14:led-displays-lightboxes-c1; original SHA256 65f6d421e1852500b1b13a4e33e0f33b930226ad3448ee5b16985aad08cf66c3; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "led-displays-lightboxes-20": {"descriptionVi":"Hộp đèn LED để bàn chân nhôm, mặt in hình bánh mì và tên tiệm chiếu sáng đều, cắm điện là dùng. Dành cho tiệm bánh mì, xe đẩy, quầy đồ ăn sáng, đặt trên mặt quầy bán, giúp món chính hiện rõ ngay tầm mắt người đi đường, kể cả lúc sáng sớm và chiều tối.","descriptionEn":"Tabletop LED lightbox on an aluminium stand, its face printed with a banh mi image and the shop name, evenly lit, plug and use. For banh mi shops, carts and breakfast stalls, on the sales counter, it shows the signature item at passers-by's eye level, even at dawn and dusk.","altVi":"Hộp đèn LED để bàn có ảnh bánh mì và chữ tên tiệm trên quầy","altEn":"Tabletop LED light box with bread photo and shop name on counter","source":"/assets/content/projects/advertising/led-displays-lightboxes/led-displays-lightboxes-20-imagegen-20261014.webp","sha256":"e5800b57f1fbc4cc59216155983da705634f4c20e5b9985025b3ab6a30825fa8","provenance":"AI-generated illustration; source ID imagegen:2026-10-14:led-displays-lightboxes-c2; original SHA256 bf895132855e1501be62e2fb76b9e32e54211bacd28ba62ce9f43e7250cdeeb1; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "led-displays-lightboxes-21": {"descriptionVi":"Hộp đèn LED treo tường khung nhôm mỏng, mặt in hình món gà rán và tên quán chiếu sáng đều. Dành cho quán gà rán, đồ ăn nhanh, quán ăn vặt, gắn trên vách gần cửa hoặc sau quầy, giúp món chủ lực hút mắt khách đi ngang, tăng cảm giác ngon miệng và dễ thay tranh khi đổi món.","descriptionEn":"Wall-mounted LED lightbox with a slim aluminium frame, its face printed with fried chicken and the shop name, evenly lit. For fried chicken, fast food and snack shops, on a wall near the door or behind the counter, it draws passers-by to the signature dish, whets appetites and takes a new print when the menu changes.","altVi":"Bảng dọc nền xanh có ảnh gà rán và chữ, treo tường","altEn":"Vertical blue panel with fried chicken photo and lettering hung on wall","source":"/assets/content/projects/advertising/led-displays-lightboxes/led-displays-lightboxes-21-imagegen-20261014.webp","sha256":"b1ec465d603d6f7f0b96770055b5a8704bf7ff50b69168c2cbc56a7513f64dc4","provenance":"AI-generated illustration; source ID imagegen:2026-10-14:led-displays-lightboxes-c3; original SHA256 490c15ef8bee1b92a351c4034bffe5b7559026a5ad2818d9e7f608908b507142; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "led-displays-lightboxes-22": {"descriptionVi":"Khung poster nhôm mỏng treo tường, có thể gắn đèn LED, mặt in hình bánh ngọt và tên món, thay tranh nhanh bằng nẹp mở. Dành cho tiệm bánh, quán cà phê, tiệm trà, treo trên vách khu ngồi hoặc gần tủ bánh, giúp giới thiệu món mới, làm đẹp tường và kích thích khách gọi thêm.","descriptionEn":"Slim aluminium poster frame for the wall, LED-lit as an option, printed with pastries and their names, with snap-open edges for quick changes. For bakeries, cafes and tea shops, on seating-area walls or near the cake display, it presents new items, decorates the wall and prompts extra orders.","altVi":"Hai khung poster in ảnh bánh ngọt và bánh sừng bò treo trên tường","altEn":"Two framed posters with cake and croissant photos hung on wall","source":"/assets/content/projects/advertising/led-displays-lightboxes/led-displays-lightboxes-22-imagegen-20261014.webp","sha256":"a01f1714ebefa85e6085526b8bfd427d97835e9eac7fb4d7041ffba2b3b768c7","provenance":"AI-generated illustration; source ID imagegen:2026-10-14:led-displays-lightboxes-c4; original SHA256 c0523aaec955c3bf6bee0b7eabe0ea40d78c230537728d58294b5ea5f888acba; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "led-displays-lightboxes-23": {"descriptionVi":"Hộp đèn LED treo tường khổ đứng, khung nhôm mỏng, mặt in hình giày và khẩu hiệu chiếu sáng đều. Dành cho cửa hàng giày dép, thời trang, shop phụ kiện, gắn trên vách giữa các kệ trưng bày, giúp sản phẩm chủ lực nổi bật, không gian sáng hơn và đổi tranh theo mùa dễ dàng.","descriptionEn":"Portrait wall-mounted LED lightbox with a slim aluminium frame, its face printed with a shoe and a tagline, evenly lit. For shoe, fashion and accessory shops, on the wall between display shelves, it highlights the hero product, brightens the space and swaps prints by season.","altVi":"Hộp đèn LED dọc màu cam có ảnh giày trắng và chữ cửa hàng","altEn":"Vertical orange LED light box with white shoe photo and shop lettering","source":"/assets/content/projects/advertising/led-displays-lightboxes/led-displays-lightboxes-23-imagegen-20261014.webp","sha256":"2a8dcb35b9798a1dbb98520ffccf94b5e262df3816c2cbdd381e63bc189e5a2c","provenance":"AI-generated illustration; source ID imagegen:2026-10-14:led-displays-lightboxes-c5; original SHA256 98b747ddba57d4f06f2fcf6a3fc7d698acc89eeed3a7bdb143b73f5facc07208; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "kiosk-posm-39": {"descriptionVi":"Hình cắt sắt sơn đen hình ly cà phê, khói và hạt cà phê, gắn chân cách tường với LED hắt sáng phía sau. Dành cho quán cà phê sân vườn, nhà hàng, gắn lên mảng tường trống ngoài trời hoặc trong nhà, giúp không gian có điểm nhấn về đêm và góc chụp hình cho khách.","descriptionEn":"Black-painted cut steel artwork of a coffee cup, steam and beans, on stand-off pins with LED backlighting. For garden cafes and restaurants, fixed on a blank wall indoors or out, it gives the space a night-time focal point and a photo corner for guests.","altVi":"Tách cà phê bằng sắt đen gắn tường, phía sau có đèn LED hắt sáng","altEn":"Black iron coffee cup cut-out on wall with LED backlighting behind","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-39-imagegen-20261014.webp","sha256":"018cdd09ed5d58bc942f2445e1c7f90f5aca50fc5049eb5365f091c172a23cd4","provenance":"AI-generated illustration; source ID imagegen:2026-10-14:new-led-decor-c6; original SHA256 531e6ac18c78379de0482798db983fc6264008898b4bf93c18d1ce2e926ea07d; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "kiosk-posm-40": {"descriptionVi":"Chữ LED neon đỏ uốn theo tên tiệm và khẩu hiệu, gắn trên tấm mica trong, treo trên vách sau quầy. Dành cho tiệm hoa, shop quà tặng, studio nhỏ, gắn trên tường chính hoặc sau quầy gói hoa, giúp tiệm có điểm nhấn ấm áp, dễ nhớ tên và tạo góc chụp hình cho khách.","descriptionEn":"Red LED neon lettering bent to the shop name and tagline, mounted on clear acrylic and hung on the wall behind the counter. For florists, gift shops and small studios, on the main wall or behind the wrapping counter, it adds a warm accent, makes the name memorable and creates a photo corner.","altVi":"Bảng LED neon đỏ có chữ hoa tươi và tên tiệm gắn tường trong tiệm hoa","altEn":"Red LED neon sign with fresh flowers lettering mounted on flower shop wall","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-40-imagegen-20261018.webp","sha256":"cbd9dfd65b390b749b1cb9c7f4165830e0b27ae958c88f27dc2d8c9155c863cf","provenance":"AI-generated illustration; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-31; master PNG SHA256 eda3ec59633daa9ada59f843b4656d2970da80b9c3dffee1a34b59542c435284."},
  "signage-raised-letters-35": {"descriptionVi":"Bảng vẫy hộp đèn tròn hai mặt, mặt mica hút nổi in logo và tên thương hiệu, viền nhôm đen, gắn tay thép vuông góc tường. Dành cho quán cà phê, tiệm trà, cửa hàng mặt phố, giúp khách đi dọc vỉa hè nhìn thấy từ xa, logo nổi khối đẹp cả ngày lẫn đêm và tạo điểm nhận diện riêng.","descriptionEn":"Double-sided round lightbox with vacuum-formed acrylic faces printed with the logo and brand name, a black aluminium rim, on a steel bracket at right angles to the wall. For cafes, tea shops and street-front stores, it is seen from afar along the pavement, the raised logo looks good day and night, and it gives the shop its own mark.","altVi":"Hộp đèn tròn mica có hình lá và hạt cà phê, chữ BREWTIFUL, gắn trên tay vươn tường","altEn":"Round acrylic light box with a leaf and coffee bean motif and BREWTIFUL lettering on a wall bracket","source":"/assets/content/projects/advertising/signage-raised-letters/signage-raised-letters-35-brewtiful-20261115.webp","sha256":"874507ec96a9e96851bad05f69fd0812b0d162dbd5c5bb84164f6e41764b307c","provenance":"AI-generated illustration; ChatGPT web gpt-image edit (chat 6af9c15b-99f4-83ec-8aab-6e4dcbebdff7); owner approved 2026-11-15; original PNG SHA256 12ec53c629a0ef147994fc59266eb861d23eae2352f4de2463aca30f6328ced2."},
  "signage-raised-letters-36": {"descriptionVi":"Hộp đèn LED dọc hai mặt khung nhôm sơn đen, chữ đen trên mặt mica trắng sáng đều, gắn tay vẫy vuông góc tường, kèm bảng phụ nhỏ. Dành cho quán cà phê, tiệm nhỏ trong hẻm hoặc phố đi bộ, giúp người đi hai chiều thấy quán từ xa, hợp mặt tiền hẹp và đẹp cả ngày lẫn đêm.","descriptionEn":"Double-sided vertical LED lightbox in a black aluminium frame with black lettering on an evenly lit white acrylic face, on a projecting wall bracket with a small sub-sign. For cafes and small shops in alleys or pedestrian streets, it is seen from both directions, suits narrow fronts and looks good day and night.","altVi":"Hộp đèn LED dọc có chữ cà phê gắn vuông góc tường mặt tiền quán","altEn":"Vertical LED light box with coffee lettering at right angles to shop facade","source":"/assets/content/projects/advertising/signage-raised-letters/signage-raised-letters-36-imagegen-20261014.webp","sha256":"136f160f81565a358564d4b79f00b00360dbec825189baffd33eab1d5971c05e","provenance":"AI-generated illustration; source ID imagegen:2026-10-14:signage-raised-letters-c9; original SHA256 69fd78f15f870a32e42fd24d57e3abca4013b95ac654c4eadbd83e575ec32f6d; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "led-displays-lightboxes-24": {"descriptionVi":"Bảng hiệu 3D hình tô bún và đũa làm từ xốp phủ composite sơn màu, kèm bảng tên đỏ có đèn, đặt trên khung sắt chân đế. Dành cho quán bún, phở, quán ăn ven đường, đặt trên vỉa hè trước quán, giúp món chính hiện rõ từ xa, hút mắt người đi đường và thành điểm nhận diện quán.","descriptionEn":"3D noodle bowl and chopsticks sign in painted composite-coated foam with a lit red name panel, on a steel frame base. For noodle, pho and roadside eateries, on the pavement before the shop, it shows the main dish from afar, catches passers-by and becomes the shop's landmark.","altVi":"Bảng hiệu 3D hình tô bún và đũa gắn trên chân sắt đặt ven đường","altEn":"Three-dimensional sign of noodle bowl and chopsticks on iron stand by road","source":"/assets/content/projects/advertising/led-displays-lightboxes/led-displays-lightboxes-24-imagegen-20261014.webp","sha256":"d18a07a6f781a392bfed73ef3a6db19e099a6f278434fe3b71692850c6d36702","provenance":"AI-generated illustration; source ID imagegen:2026-10-14:led-displays-lightboxes-c10; original SHA256 b505af2475dcbcbd6e34c56642ad283f59009ef75f30ebd6302c973742a9888e; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "mobile-retail-22": {"descriptionVi":"Xe bán nước mía khung gỗ, mái tôn che, máy ép inox trên mặt quầy, thân trước in hình sản phẩm và tên quán, bánh xe có khóa. Dành cho người bán nước mía, đồ uống giải khát ở bờ kè, công viên, phố đi bộ, giúp xe gọn, sạch, dễ di chuyển và khách thấy quán từ xa.","descriptionEn":"Timber sugarcane juice cart with a metal roof, a stainless juice press on the counter, a front panel printed with the product and shop name, and locking wheels. For sugarcane juice and drink sellers on riverside walks, parks and walking streets, it stays compact and clean, moves easily and is seen from afar.","altVi":"Xe gỗ bán nước mía có mái tôn trắng, decal tên quán và bánh xe","altEn":"Timber juice cart with white corrugated roof, shop decal and wheels","source":"/assets/content/projects/advertising/mobile-retail/mobile-retail-22-imagegen-20261018.webp","sha256":"bb7ec390f77600a08686105f26a61355d37257622ab8f1b09b848c8abb557190","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:mobile-retail-22-1; original SHA256 38c0a74a55cb71c34a37ef2f8b4e14b12219bf837ed8e8ca3a308a4effa0f3b2; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "mobile-retail-23": {"descriptionVi":"Xe đẩy bán kem xôi khung thép sơn đen, bánh xe lớn kiểu cổ điển, mái bạt đen, mặt quầy gỗ, bảng tên treo trên khung. Dành cho tiệc cưới ngoài trời, sự kiện sân vườn, quầy món tráng miệng, giúp tạo góc phục vụ có phong cách riêng, dễ dời chỗ và thành điểm chụp hình cho khách.","descriptionEn":"Black-painted steel sticky-rice ice cream cart with large vintage-style wheels, a black canvas roof, a timber counter and a name board hung from the frame. For outdoor weddings, garden events and dessert stations, it creates a stylish serving corner, moves easily and becomes a photo spot for guests.","altVi":"Xe đẩy đen bán kem xôi, bánh xe lớn, mái bạt, bảng đen viết tay","altEn":"Black cart with large wheels, canvas awning and handwritten chalkboard for ice cream","source":"/assets/content/projects/advertising/mobile-retail/mobile-retail-23-imagegen-20261018.webp","sha256":"6540ef003c270b016c47e0fc0a67cf4932f2163f6e0082285fbf17bcb7498831","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:mobile-retail-23-1; original SHA256 0d92f866e54606452c402b27cb626690db7776b727a4b2ac795046d245fba64e; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "mobile-retail-24": {"descriptionVi":"Xe bán đồ uống khung thép đen, mái phẳng, mặt quầy gỗ có cánh gấp, thân in tranh hoa sen và tên quán, bánh xe có khóa. Dành cho người bán trà, nước giải khát trước cổng trường, công viên, khu văn phòng, giúp bày hũ nguyên liệu gọn, phục vụ nhanh và khách nhớ thương hiệu qua hình in.","descriptionEn":"Drinks cart with a black steel frame, a flat roof, a timber top with fold-out flaps, a body printed with lotus artwork and the brand name, and locking wheels. For tea and soft drink sellers outside schools, parks and office areas, it keeps ingredient jars tidy, serves quickly and makes the brand memorable through its print.","altVi":"Xe đẩy khung đen bán trà sen, mái trắng, bảng xanh và hũ trà thủy tinh","altEn":"Black-frame cart selling lotus tea with white roof, green board and glass tea jars","source":"/assets/content/projects/advertising/mobile-retail/mobile-retail-24-imagegen-20261018.webp","sha256":"5eb0e9b3cf23c418ec8641e2fe8112259c4e1825015599dde440a28ee4f1b0db","provenance":"AI-generated illustration; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-31; master PNG SHA256 c03398b387cd1a8d87b16709c0868fe06abd76ad9e1259943e23495fd1482c28."},
  "mobile-retail-25": {"descriptionVi":"Ki-ốt bán đồ uống ngoài trời khung gỗ ốp tôn trắng, chữ nổi đèn LED trên nóc, dây bóng đèn trang trí, mái hiên bạt và quầy phục vụ. Dành cho quán trà chanh, đồ uống mang đi ở bờ sông, phố đi bộ, khu vui chơi, giúp quán nổi bật về đêm, phục vụ nhanh và che nắng mưa.","descriptionEn":"Outdoor drinks kiosk with a timber frame clad in white metal sheet, LED raised letters on the roof, festoon lights, a canvas awning and a service counter. For lemon tea and takeaway drink stalls on riverbanks, walking streets and amusement areas, it stands out at night, serves fast and shelters from sun and rain.","altVi":"Quầy gỗ tôn trắng bán trà chanh có chữ đèn phát sáng và đèn dây bóng","altEn":"White corrugated timber counter with lit lettering and festoon bulbs","source":"/assets/content/projects/advertising/mobile-retail/mobile-retail-25-imagegen-20261018.webp","sha256":"06608206d7e6802dcb42bd8ef7ec0d866797c10824f4900d01dee69edb98618b","provenance":"AI-generated illustration; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-31; master PNG SHA256 df208bc7322a4aedf278c7d20a15694df7f11a77033c4a5c2dc12fb66a3ce3c5."},
  "mobile-retail-26": {"descriptionVi":"Xe bán đồ uống khung thép đen, thân trắng in logo trái cây, đèn LED hắt dưới mặt quầy, khung lưới phía trên gắn chữ LED neon. Dành cho quán trà, nước ép bán ở bờ hồ, phố đi bộ, chợ đêm, giúp quầy nổi bật khi trời tối, thành điểm chụp hình và dễ đẩy đến nơi đông người.","descriptionEn":"Drinks cart with a black steel frame, white body printed with a fruit logo, LED lighting under the counter and a mesh frame on top holding LED neon lettering. For tea and juice stalls by lakes, walking streets and night markets, it stands out after dark, becomes a photo spot and wheels easily to busy spots.","altVi":"Xe đẩy bán trà đào có bảng neon hồng trên khung lưới đen và bánh xe","altEn":"Wheeled peach tea cart with pink neon sign on black mesh frame","source":"/assets/content/projects/advertising/mobile-retail/mobile-retail-26-imagegen-20261014.webp","sha256":"0cc75e8137414966b6990c019306130f22c04f595d556d2bdca06801dde7ea8b","provenance":"AI-generated illustration; source ID imagegen:2026-10-14:mobile-retail-c6; original SHA256 fec2ad4f78a61e9885b245ef547ed9b4ae393d9f56824e15c9a9fe953757b892; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "mobile-retail-21": {"descriptionVi":"Quầy bán hàng di động tủ thép sơn trắng, cửa có khóa, mặt gỗ tự nhiên, bánh xe có phanh. Dành cho thương hiệu nước dừa, đồ uống, nông sản bán ở chợ phiên, phố đi bộ, sự kiện ngoài trời, giúp bày hàng trên mặt quầy, cất hàng và dụng cụ trong tủ an toàn và đẩy đi dễ.","descriptionEn":"Mobile counter with a white-painted lockable steel cabinet, a natural timber top and braked wheels. For coconut water, drink and farm produce brands at weekend markets, walking streets and outdoor events, it displays goods on top, stores stock and tools securely inside and wheels away easily.","altVi":"Tủ quầy trắng có bánh xe, mặt gỗ và bình nước dừa ngoài trời","altEn":"White counter cabinet with wheels, timber top and coconut water containers outdoors","source":"/assets/content/projects/advertising/mobile-retail/mobile-retail-21-owner-20260924.webp","sha256":"d418b4db4ce0d3f88e0781e186abd1c8c9c9114ca3df02134d6138f1332f2854","provenance":"AI-generated illustration; owner approved 2026-09-24; original SHA256 aaa5b58ce7c4d1d257b557250ec61c26d326047914010feda5c304185c09c6bf; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "print-decals-21": {"descriptionVi":"Decal mờ in chữ và họa tiết lá màu, dán ngang tầm mắt trên vách kính phòng họp. Dành cho văn phòng, coworking, phòng khám có vách kính, giúp nhận diện phòng, che bớt tầm nhìn vào trong để giữ riêng tư, chống va vào kính mà phòng vẫn sáng.","descriptionEn":"Frosted film printed with text and coloured leaf motifs, applied at eye level on the meeting room glass. For offices, coworking spaces and clinics with glass partitions, it identifies the room, screens the view for privacy and prevents people walking into the glass while keeping the room bright.","altVi":"Decal mờ có chữ PHÒNG HỌP và họa tiết lá, dán trên vách kính","altEn":"Frosted decal reading PHÒNG HỌP with leaf motif on glass partition","source":"/assets/content/projects/advertising/print-decals/print-decals-21-owner-20260924.webp","sha256":"de9fad1d893ffaf62567f79a1d096c00b3a0caf397545d3e3dd5f81c009f4041","provenance":"AI-generated illustration; owner approved 2026-09-24; original SHA256 f68bceaa3940ae9723950d49cf0387f3d52849adab01a64eeda8f15316c5b84a; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "office-signs-wayfinding-31": {"descriptionVi":"Bảng bản đồ lối tham quan in UV trên tấm alu, đóng khung gỗ, mái lá che mưa, dựng trên hai cột gỗ ven đường đi. Dành cho khu du lịch sinh thái, nông trại, công viên, giúp du khách tự tìm điểm tham quan, hợp cảnh quan tự nhiên và bản đồ không bị phai do mưa nắng.","descriptionEn":"Visitor route map UV-printed on aluminium in a timber frame under a thatched roof, set on two timber posts along the path. For eco-resorts, farms and parks, it helps visitors find attractions on their own, blends into the natural setting and keeps the map from fading in sun and rain.","altVi":"Bảng gỗ mái lá có bản đồ lối tham quan, đặt bên đường đi","altEn":"Thatched-roof timber board with visitor route map beside a path","source":"/assets/content/projects/advertising/office-signs-wayfinding/office-signs-wayfinding-31-owner-20260924-v2.webp","sha256":"b9e3b1ec3517dc24d57ba7b4048bba5ee8089f8df8c17c0ae9a690c24524687c","provenance":"AI-generated illustration; ChatGPT web image edit (owner chat 6adf826e-ad58-83ec-a342-7d8fda687896, card #873); upscaled RunningHub SeedVR2 tile to 3072; owner approved 2026-10-26 18:24Z; master PNG SHA256 c38ba183fe9f61cf394b30ef8d59a5591e49714cefc1c4c13afd1e8c8c7170a3."},
  "office-signs-wayfinding-30": {"descriptionVi":"Biển tên đường mặt alu xanh chữ trắng phản quang, bắt cùm lên cột thép mạ kẽm chân đế bắt bu lông. Dành cho khu công nghiệp, khu đô thị, khu dân cư mới, giúp xe tải, người lao động, khách tìm đúng đường nội bộ, đọc rõ cả ban đêm và bền ngoài trời nhiều năm.","descriptionEn":"Street name sign in blue aluminium with white reflective lettering, clamped to a galvanised steel post with a bolted base. For industrial parks, urban areas and new estates, it helps trucks, workers and visitors find internal roads, reads clearly at night and lasts outdoors for years.","altVi":"Biển xanh ghi tên đường trên cột thép mạ kẽm bên đường khu công nghiệp","altEn":"Blue road name sign on galvanised steel post beside industrial estate road","source":"/assets/content/projects/advertising/office-signs-wayfinding/office-signs-wayfinding-30-owner-20260924.webp","sha256":"39665f0c2baba7cf323e064a52a47875ed7331b68ace2b65f251e902073b6f1c","provenance":"AI-generated illustration; owner approved 2026-09-24; original SHA256 c2aff88e9b41268d56e8fc8ee2d08577570557af0c924b7fe0029eac1629652d; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "kiosk-posm-37": {"descriptionVi":"Standee chữ X chân thép, căng bạt in hình trái dừa và thông điệp thương hiệu, gấp gọn kèm túi đựng. Dành cho cơ sở đồ uống, đặc sản dừa, gian hàng hội chợ, đặt trước lều hoặc lối đi, giúp quảng bá sản phẩm nhanh, dễ mang đi nhiều điểm bán và thay bạt khi đổi chương trình.","descriptionEn":"X-banner stand with steel legs and a printed banner showing coconuts and a brand message, folding into a carry bag. For drinks brands, coconut specialty makers and fair booths, set before the tent or in the aisle, it promotes products fast, travels between sales points and takes new banners for new campaigns.","altVi":"Standee X bạt in hình dừa tươi và lá cọ đặt trên vỉa hè chợ","altEn":"Fabric X-stand printed with fresh coconut and palm leaves on market pavement","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-37-owner-20260924.webp","sha256":"b38041557622d29d87cb67316b99cb26aec365f4792d2e0f4630ac547bcaf169","provenance":"AI-generated illustration; upscaled RunningHub SeedVR2 tile, edited by owner; owner approved to site 2026-10-27; master PNG SHA256 38e6120d02791c54f37cd0067d37209bfac51878ea0352001c587dc3104387ab."},
  "kiosk-posm-36": {"descriptionVi":"Standee chân chữ H khung ống trắng, treo bạt in hình minh họa và thông điệp bộ sưu tập mới, tháo lắp không cần dụng cụ. Dành cho cửa hàng thời trang, váy cưới, shop trong trung tâm thương mại, đặt trước cửa hoặc lối đi, giúp giới thiệu mẫu mới và mời khách bước vào.","descriptionEn":"H-frame standee with a white tube frame and a printed banner showing artwork and a new-collection message, assembled without tools. For fashion and bridal shops and mall boutiques, placed at the door or in the aisle, it introduces new styles and invites shoppers in.","altVi":"Standee bạt chân trắng vẽ người phụ nữ mặc váy đặt trước cửa hàng","altEn":"White-base fabric standee painted with a woman in a dress outside a shop","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-36-owner-20260924.webp","sha256":"7a646ff46ca20164472705c6d1a19b4ec0c1a170a817c4868388ca3198eac089","provenance":"AI-generated illustration; ChatGPT web image edit (owner chat 6adfd461-3fac-83ec-8784-a4ded59b03ca); upscaled RunningHub SeedVR2 tile to 3072; owner approved 2026-10-27 01:07Z; master PNG SHA256 6a2dae3033da006aae4e7503e15126bbd1155e40ee3b6de3b57f3302be0e30e4."},
  "kiosk-posm-35": {"descriptionVi":"Standee chân chữ T khung ống trắng, căng bạt in hình bộ sưu tập, tháo lắp nhanh, gấp gọn khi cất. Dành cho shop thời trang, cửa hàng phụ kiện, đặt trong cửa hàng hoặc trước cửa, giúp giới thiệu bộ sưu tập mới, khuyến mãi cho khách đi ngang với chi phí thấp.","descriptionEn":"T-base standee with a white tube frame and a stretched printed banner of the collection, quick to assemble and compact to store. For fashion and accessory shops, inside or at the door, it introduces new collections and offers to passers-by at low cost.","altVi":"Standee bạt chân trắng có chữ và hình váy áo trong cửa hàng","altEn":"White-base fabric standee with lettering and dress graphic inside a shop","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-35-owner-20260924.webp","sha256":"4c0a4ceb22cf4dddaf268e84e1c83c575905a6a7ade62db4d25084e7f2669c4e","provenance":"AI-generated illustration; owner approved 2026-09-24; original SHA256 6702c522fd825b58be45ea1eecb094ff2237107b96b1b77089738d63b24f3aed; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "kiosk-posm-34": {"descriptionVi":"Standee khung sắt hộp sơn đen, chân đế chữ nhật vững, hai mặt lồng poster hoặc bạt in, thay nội dung dễ dàng. Dành cho quán đồ uống, nhà hàng, cửa hàng, đặt trước cửa hoặc trong sảnh, giúp quảng bá món mới, chương trình khuyến mãi bền và chắc hơn standee nhựa.","descriptionEn":"Standee with a black-painted box-steel frame and a solid rectangular base, holding a poster or printed banner on both sides, easy to change. For drink shops, restaurants and stores, placed at the door or in the lobby, it promotes new items and offers and is sturdier and longer-lasting than plastic standees.","altVi":"Standee khung đen có poster trà trái cây nhiệt đới, đặt cạnh cửa kính","altEn":"Black standee frame with tropical fruit tea poster beside a glass door","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-34-owner-20260924.webp","sha256":"a888e334fc87438bffe309e09d1521adfa4581612e4c46423b7abdbea00c15ec","provenance":"AI-generated illustration; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-31; master PNG SHA256 46be69d3976e5d1341bc0c174365f7d7ad73d33d3da3f66202bbb1958825c30f."},
  "kiosk-posm-33": {"descriptionVi":"Standee khung ống thép sơn trắng bo tròn, đế nhựa đổ nước chống đổ, hai mặt căng poster in hình sản phẩm. Dành cho quán trà sữa, cà phê, cửa hàng đồ uống, đặt trước cửa hoặc lối đi, giúp giới thiệu món mới, khuyến mãi cho người đi ngang và thay poster nhanh theo mùa.","descriptionEn":"Standee with a rounded white-painted steel tube frame and a water-filled plastic base against tipping, carrying printed product posters on both sides. For bubble tea shops, cafes and drink stores, placed by the door or walkway, it promotes new drinks and offers to passers-by and swaps posters quickly each season.","altVi":"Standee khung trắng bo tròn có poster trà sữa, đế nước màu trắng","altEn":"Round-corner white standee frame with milk tea poster on white water base","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-33-owner-20260924.webp","sha256":"a4d6bb1e22cfe2295ee164c542eb4644b0ed5e4dcf498d52f7ae793799bf3858","provenance":"AI-generated illustration; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-31; master PNG SHA256 6e3f8e0c7e7246044ae2b02123a5446366efc5dbe36a31b592814e7f22a3d423."},
  "signage-raised-letters-26": {"descriptionVi":"Chữ nổi formex cắt CNC, sơn trắng, đặt đứng hoặc dán lên mặt kệ, bàn đá, tường. Dành cho studio chụp ảnh, showroom, văn phòng nhỏ, quầy lễ tân, giúp tên thương hiệu nổi khối rõ nét, chi phí thấp, nhẹ, lắp nhanh và hợp phong cách tối giản.","descriptionEn":"CNC-cut foam PVC letters painted white, free-standing or bonded to shelves, stone counters or walls. For photo studios, showrooms, small offices and reception desks, they give the brand name crisp relief at low cost, are light and quick to install, and suit a minimal style.","altVi":"Chữ nổi trắng dạng 3D đặt trên bệ bê tông, bên cửa sổ và cây xanh","altEn":"White 3D lettering on a concrete plinth beside a window and green plants","source":"/assets/content/projects/advertising/signage-raised-letters/signage-raised-letters-26-owner-20260924.webp","sha256":"6f34ac8241b1538d58b1bdf790751366076934b823383ad0363287b9c3034e0d","provenance":"AI-generated illustration; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-31; master PNG SHA256 b749d1b56cebccf56b53b4074b1edab320a8d04e4029c80dd054e228e2c5d1f3."},
  "signage-raised-letters-25": {"descriptionVi":"Chữ nổi mica vàng sáng mặt, thành chữ alu hoặc inox, đèn LED bên trong, gắn trực tiếp lên tường trắng phía trên cửa kính. Dành cho quán cà phê, nhà hàng, cửa hàng có tên thương hiệu ngắn, giúp mặt tiền tối giản, hiện đại và tên quán đọc rõ từ vỉa hè cả ngày lẫn đêm.","descriptionEn":"Front-lit yellow acrylic raised letters with aluminium or stainless returns and LED inside, fixed straight to a white wall above the glass doors. For cafes, restaurants and shops with short brand names, it keeps the frontage minimal and modern and the name readable from the pavement day and night.","altVi":"Chữ nổi vàng sáng gắn trên tường trắng phía trên cửa kính","altEn":"Glowing gold dimensional letters on white wall above glass door","source":"/assets/content/projects/advertising/signage-raised-letters/signage-raised-letters-25-owner-20260924-audit-a261-v1.webp","sha256":"653fc0cdedbcee613875ef995f364063ad5df9296be676ca0c08b166092fe9a6","provenance":"AI-generated illustration; owner selected A261-v1 in HTML audit and confirmed in chat 2026-10-22; ChatGPT web gpt-image; original SHA256 9ea2e1cd527c7b7e1e4f8099b8b19508270f9d03d8ad0a6da410896bdb770928; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "print-decals-20": {"descriptionVi":"Tem decal in màu cắt bế theo khuôn tròn hoặc vuông, mỗi loại sản phẩm một mẫu riêng, cắt trên máy và giao theo tờ. Dành cho cơ sở sản xuất đồ uống, nông sản, thực phẩm đóng gói, dán lên chai, hũ, hộp, giúp sản phẩm có nhãn đẹp, ghi đúng loại và tiết kiệm hơn in bao bì riêng.","descriptionEn":"Full-colour decal labels die-cut in round or square shapes, a separate design for each product, plotter-cut and delivered on sheets. For drink, farm produce and packaged food producers, applied to bottles, jars and boxes, they give products attractive, correctly labelled packaging at less cost than custom-printed packs.","altVi":"Máy cắt vinyl đang cắt tem nhãn cam và tem trà xanh xếp trên bàn gỗ","altEn":"Vinyl cutter trimming orange label and green tea stickers laid out on a timber table","source":"/assets/content/projects/advertising/print-decals/print-decals-20-owner-20260924.webp","sha256":"8102fa0b38a47d2055daf94f0089f5b6f2dbe91c58ac576450c0171584027dbd","provenance":"AI-generated illustration; owner approved 2026-09-24; original SHA256 ae0e791a292804e6c91dc994ed1d96fff625cd1c98587d2928a8a762f282fda6; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "signage-raised-letters-24": {"descriptionVi":"Billboard khung thép dựng trên mái tòa nhà, mặt bạt in hình sản phẩm và thương hiệu, kèm đèn pha chiếu sáng phía trên. Dành cho nhãn hàng thực phẩm, nông sản, chuỗi cửa hàng thuê mái nhà ở giao lộ, trục đường lớn, giúp thương hiệu thấy từ xa, cả khi trời u ám và ban đêm.","descriptionEn":"Steel-framed rooftop billboard with a printed banner face showing products and the brand, plus floodlights above. For food, produce brands and store chains renting rooftops at junctions and main roads, it keeps the brand visible from afar even on overcast days and at night.","altVi":"Billboard bạt in trên mái tòa nhà trắng, quảng cáo trái cây tươi","altEn":"Printed fabric billboard on white building roof advertising fresh fruit under overcast sky","source":"/assets/content/projects/advertising/signage-raised-letters/signage-raised-letters-24-imagegen-20261018.webp","sha256":"9e0e64574995218495f220b21d534ac34379929edb9fa2f267946e1dda94a53a","provenance":"AI-generated illustration; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-31; master PNG SHA256 e394f8051362eec75f550fab7fc882e19c7d437817acb8e6e4eeafeec66bd2bd."},
  "mobile-retail-20": {"descriptionVi":"Xe bánh mì khung inox, tủ kính hai tầng bày bánh, khay nhân, mái bạt sọc vàng trắng, thân dán decal in hình sản phẩm và bánh xe lớn. Dành cho người bán bánh mì, đồ ăn sáng ở vỉa hè, chợ, khu ăn uống, giúp đồ ăn sạch, bán nhanh và khách nhận ra món từ xa.","descriptionEn":"Stainless steel banh mi cart with a two-tier glass bread case, filling trays, a yellow and white striped canopy, a body wrapped in printed product decals and large wheels. For banh mi and breakfast sellers on pavements, markets and food courts, it keeps food clean, speeds service and shows the dish from afar.","altVi":"Xe inox bán bánh mì, mái bạt vàng trắng, decal hình bánh mì","altEn":"Stainless steel bread cart with yellow and white awning and bread decals","source":"/assets/content/projects/advertising/mobile-retail/mobile-retail-20-owner-20260924.webp","sha256":"aae0a07aacb81f50f86faf6f54c12e184691dfe3e421ba65238e0db2a8750375","provenance":"AI-generated illustration; owner approved 2026-09-24; original SHA256 e88f3a2376eb6703308a623915f98105c309d8c57d1233ed3d7bed4fcfa64402; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "mobile-retail-19": {"descriptionVi":"Quầy trà sữa di động khung nhôm, mặt quầy inox, hộp đèn tên thương hiệu phía trên, thân dán decal in hình sản phẩm, bánh xe có khóa. Dành cho quán trà sữa, đồ uống mở điểm bán tại trung tâm thương mại, hội chợ, giúp quầy nổi bật, đủ chỗ đặt máy móc và dời đi nhanh.","descriptionEn":"Mobile bubble tea counter with an aluminium frame, stainless top, a brand lightbox overhead, a body wrapped in printed product decals and locking wheels. For bubble tea and drink shops opening points in malls and fairs, it stands out, holds the equipment and moves quickly.","altVi":"Quầy trà sữa di động có bánh xe, mái đèn LED và decal ly trà sữa","altEn":"Mobile milk tea counter with wheels, LED-lit canopy and milk tea cup decals","source":"/assets/content/projects/advertising/mobile-retail/mobile-retail-19-owner-20260924.webp","sha256":"8e7ad357214551549b869dc2d22d8a10841f9f6afeced101887e2552509e3d97","provenance":"AI-generated illustration; owner approved 2026-09-24; original SHA256 8390376e92834f068e85ef01876132fffea3a46e6ba62200e64cbb7b7017094a; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "mobile-retail-18": {"descriptionVi":"Xe bán kem khung inox, tủ đông kem, tủ kính trưng bày ốc quế, mái bạt sọc in tên, thân dán decal hình kem và bánh xe có khóa. Dành cho thương hiệu kem, quán tráng miệng bán ở khu vui chơi, chợ đêm, sự kiện, giúp giữ kem lạnh, bày món hấp dẫn và nổi bật khi lên đèn.","descriptionEn":"Stainless ice cream cart with a freezer, a glass cone display, a striped printed canopy, a body wrapped in ice cream decals and locking wheels. For ice cream brands and dessert shops at amusement areas, night markets and events, it keeps ice cream frozen, shows treats temptingly and stands out under the lights.","altVi":"Xe inox bán kem, mái bạt hồng sọc trắng, decal kem trên thân xe","altEn":"Stainless steel ice cream cart with pink striped awning and cream decals on the body","source":"/assets/content/projects/advertising/mobile-retail/mobile-retail-18-owner-20260924.webp","sha256":"68c69fee07f022c4990e515ec6493d6e046bb2f6c6c722b421ef36bac2982c83","provenance":"AI-generated illustration; owner approved 2026-09-24; original SHA256 7338594e3a32b58e0c06984456cb6e1310d85f56d45dbcfb7a9e18612c6d5e53; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "office-signs-wayfinding-29": {"descriptionVi":"Bảng sơ đồ phân lô khổ lớn mặt alu in UV nhiều màu, khung thép hộp dựng trên hai trụ có móng bê tông. Dành cho khu công nghiệp, dự án đất nền, khu đô thị, đặt cạnh cổng kiểm soát, giúp nhà đầu tư, xe hàng xác định lô đất, đường nội bộ nhanh và thể hiện quy mô dự án.","descriptionEn":"Large lot plan board, multi-colour UV print on aluminium, in a box-steel frame on two posts with concrete footings. For industrial parks, land projects and urban developments, placed by the security gate, it helps investors and trucks locate plots and internal roads fast and shows the project's scale.","altVi":"Bảng bản đồ các lô đất in màu đặt trên hai trụ ngoài cổng dự án","altEn":"Colour-printed land plot map board set on two posts outside the project gate","source":"/assets/content/projects/advertising/office-signs-wayfinding/office-signs-wayfinding-29-imagegen-20261018.webp","sha256":"2ebf6bf51e33eeefedfc6e86d9e06da5b13e160c8bee368eb1f6fb056448f1b6","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:office-signs-wayfinding-29-1; original SHA256 2c3b0fc6dedd293ace2228236509592f889e75bc09b382acdd3ccb5b0fd88e7f; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "office-signs-wayfinding-28": {"descriptionVi":"Biển số nhà hộp nền đen, số chữ nổi mica trắng, đèn LED hắt sáng viền ra tường, gắn lên trụ cổng ốp đá. Dành cho biệt thự, nhà phố, căn hộ sân vườn, giúp khách và shipper thấy số nhà rõ cả ban đêm và làm cổng nhà hiện đại, sang hơn.","descriptionEn":"Black box house number with white acrylic raised digits and LED halo lighting onto the wall, mounted on a stone-clad gate pillar. For villas, townhouses and garden homes, it lets guests and couriers read the number clearly even at night and gives the gate a modern, upscale look.","altVi":"Biển số nhà đen có chữ nổi phát sáng hắt ra viền, gắn trên tường đá","altEn":"Glowing raised numerals on a dark plate, mounted on a stone wall","source":"/assets/content/projects/advertising/office-signs-wayfinding/office-signs-wayfinding-28-owner-20260924.webp","sha256":"5a62420c95009d643e30c2e38d110678a9e4ca7a152ca1baa7fde1d70cea2885","provenance":"AI-generated illustration; owner approved 2026-09-24; original SHA256 35596237a12705f0edb66a8ed5bb78da5c85f656f31cab5710b41f87eb688b3c; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "mobile-retail-17": {"descriptionVi":"Quầy bán hàng gấp khung nhôm, mặt bàn trắng, bạt in hình bọc mặt trước, gấp gọn vào túi đựng có quai xách, kèm khung treo banner. Dành cho thương hiệu mỹ phẩm, đồ uống tham gia hội chợ, sự kiện ngoài trời, giúp dựng quầy trong vài phút, mang đi bằng xe máy và thay bạt theo chiến dịch.","descriptionEn":"Folding aluminium promo counter with a white top, a printed fabric front wrap and a header banner frame, packing into a carry bag. For cosmetics and drink brands at fairs and outdoor events, it sets up in minutes, travels by motorbike and swaps graphics for each campaign.","altVi":"Quầy bàn gấp có bạt in chủ đề dừa, kèm túi đựng màu đen","altEn":"Folding table counter with coconut-themed printed fabric and black carry bag","source":"/assets/content/projects/advertising/mobile-retail/mobile-retail-17-owner-20260924.webp","sha256":"3eb6c5222ee9b669b5fc7618e657c738c5f0d393b6be4461212099cb95abd44f","provenance":"AI-generated illustration; ChatGPT web image edit with owner mask (chat 6ae5c7a4-9430-83ec-b818-abc5d473266f); upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-27; master PNG SHA256 4de4dd6e1d6ce7dded777aef1daa7ab7f13d4a5c04a0905735d09fef75191144."},
  "print-decals-19": {"descriptionVi":"Bộ bao bì in đồng bộ gồm ly giấy, ly nhựa, túi giấy kraft, hộp và bao thư, in họa tiết theo từng dòng sản phẩm. Dành cho quán cà phê, cơ sở làm mứt, đặc sản, giúp đóng gói mang đi gọn, phân biệt sản phẩm dễ và thương hiệu xuất hiện trên mọi đơn hàng.","descriptionEn":"Matching packaging set of paper cups, plastic cups, kraft bags, boxes and envelopes, printed with motifs for each product line. For cafes and jam or specialty food makers, it makes takeaway packing neat, tells products apart easily and puts the brand on every order.","altVi":"Ly giấy, ly nhựa, túi kraft và hộp in chữ cà phê, mứt trái cây","altEn":"Paper and plastic cups, kraft bags and boxes printed with coffee and fruit jam text","source":"/assets/content/projects/advertising/print-decals/print-decals-19-owner-20260924.webp","sha256":"303f34e783859069731980a4744737366b0a1c3d03470df67f85020a25bee603","provenance":"AI-generated illustration; ChatGPT web image edit (owner chat 6adfd27c-fe40-83ec-871a-be181f952768); upscaled RunningHub SeedVR2 tile to 3072; owner approved 2026-10-27 01:07Z; master PNG SHA256 ab3e45b55f1a7f46c1ce7891b2a12a46da9202b940b2677160ba88edf5c89873."},
  "office-signs-wayfinding-27": {"descriptionVi":"Bảng bản đồ khu nhà máy mặt alu in UV, khung thép sơn màu nhận diện, dựng trên hai trụ có móng bê tông ngoài cổng. Dành cho nhà máy, khu sản xuất, kho bãi, giúp tài xế, khách đến lần đầu tìm đúng xưởng, kho, văn phòng và giảm việc hỏi đường ở cổng bảo vệ.","descriptionEn":"Factory site map UV-printed on aluminium in a steel frame painted in the brand colour, on two posts with concrete footings outside the gate. For factories, production sites and warehouses, it helps drivers and first-time visitors find the right workshop, store or office and cuts questions at the security gate.","altVi":"Bảng bản đồ nền trắng khung xanh, hai chân thép ngoài cổng","altEn":"White map board with blue frame and two steel legs outside gate","source":"/assets/content/projects/advertising/office-signs-wayfinding/office-signs-wayfinding-27-imagegen-20261018.webp","sha256":"9ea52017bbb32337e65b76ef036fbc5a7b2d0fdb5d68b1fdf5839740adf724b0","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:office-signs-wayfinding-27-2; original SHA256 1ffed7c355b6b63dace0ccaddd743056f048fa7fd8539163e3fe0705293830e8; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "signage-raised-letters-23": {"descriptionVi":"Biển chỉ dẫn mặt alu in chữ và mũi tên, viền nhôm định hình, dựng trên hai trụ thép mạ kẽm chân đế bê tông. Dành cho nhà máy, khu công nghiệp, đặt ở sân, ngã rẽ nội bộ, giúp xe hàng và khách đi đúng khu sản xuất, kho bãi mà không cần người hướng dẫn.","descriptionEn":"Aluminium wayfinding sign with printed text and arrow in an extruded aluminium frame, on two galvanised steel posts with concrete bases. For factories and industrial parks, placed in yards and internal junctions, it guides trucks and visitors to production areas and warehouses without staff.","altVi":"Biển xanh có mũi tên ghi KHU SẢN XUẤT, gắn trên trụ kim loại trước xưởng","altEn":"Green directional sign with arrow reading production zone mounted on metal post before factory","source":"/assets/content/projects/advertising/signage-raised-letters/signage-raised-letters-23-imagegen-20261018.webp","sha256":"97df347854168d225b8529215223f0d318a4d4791ebbc6951d7aadf146ff5eb3","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:signage-raised-letters-23-1; original SHA256 3092d67cb620777cf038a545d86ac387b2bc1a745a2330ca814e9ca15401b08c; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "print-decals-18": {"descriptionVi":"Tem decal in màu, bế theo hình bằng máy, giao dạng tờ dễ bóc dán. Dành cho quán trà sữa, đồ uống, cơ sở đóng chai, dán lên ly, nắp, chai và túi đựng, giúp mỗi loại nước có tem nhận diện riêng, trông chuyên nghiệp và dễ phân biệt khi giao hàng.","descriptionEn":"Full-colour decal labels die-cut to shape on a cutting plotter, delivered on easy-peel sheets. For bubble tea and drink shops and bottlers, applied to cups, lids, bottles and bags, they give each drink its own identity, look professional and are easy to tell apart on delivery.","altVi":"Máy cắt đang cắt tem decal tròn in trà sen, sữa dừa và nước sâm","altEn":"Cutting machine trimming round decal stickers printed with lotus tea and coconut milk","source":"/assets/content/projects/advertising/print-decals/print-decals-18-owner-20260924.webp","sha256":"28d708e29ff13e5fc335489ee6c92922f6ecf1fbfb42b3f72ba5029aa237cf37","provenance":"AI-generated illustration; ChatGPT web (chat 6ae651a8-4a9c-83ec-81e0-c981c6a2a390); upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-31; master PNG SHA256 4c1ac8013ade5a32d45682094452fdd7567c05bcae05628a0458e94ea5026b98."},
  "kiosk-posm-32": {"descriptionVi":"Bộ POSM bằng carton in gồm kệ đựng sản phẩm, kệ tầng có khay mica, wobbler treo, standee mini để bàn và dải dán mép kệ. Dành cho nhãn hàng mỹ phẩm bày tại quầy, kệ siêu thị hay nhà thuốc, giúp sản phẩm nổi bật giữa nhiều nhãn và khách dễ lấy thử.","descriptionEn":"Printed cardboard POSM set with a product dispenser, a tiered unit with acrylic trays, a hanging wobbler, a mini table standee and a shelf strip. For cosmetics brands on counters, supermarket shelves and pharmacies, it makes products stand out among many brands and easy for shoppers to pick up and try.","altVi":"Kệ POSM carton in mặt nạ dừa kèm standee, hộp đựng và thẻ treo","altEn":"Printed carton POSM with standee, product boxes and hanging tags on a counter","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-32-owner-20260924.webp","sha256":"e255ea6bf683a5e82b9c553a478b60d9850d914a3885fdb06718fbb974275651","provenance":"AI-generated illustration; ChatGPT web image edit (owner chat 6adfd47d-66f8-83ec-a335-672fa602cbac); upscaled RunningHub SeedVR2 tile to 3072; owner approved incl. design system 2026-10-27 01:54Z; master PNG SHA256 3e40fc46c79977bbd8f99a027128962bfdd06b4b74f901a34c42cbcc49797025."},
  "office-signs-wayfinding-26": {"descriptionVi":"Bảng sơ đồ tầng in UV trên tấm mica, gắn tường bằng ốc pát inox, có điểm \"Bạn ở đây\" và mũi tên lối ra. Đặt ở sảnh thang máy hoặc hành lang tòa văn phòng, nhà xưởng, giúp khách và nhân viên mới tự tìm phòng và lối thoát hiểm, không cần hỏi lễ tân.","descriptionEn":"Floor plan sign UV-printed on acrylic, wall-mounted with stainless standoffs, showing a \"You are here\" point and exit arrows. Placed in lift lobbies or corridors of offices and factories, it lets visitors and new staff find rooms and emergency exits on their own without asking reception.","altVi":"Bảng mica trắng sơ đồ tầng có mũi tên lối ra và chấm đỏ, gắn tường","altEn":"White acrylic floor directory with exit arrow and red location dot on wall","source":"/assets/content/projects/advertising/office-signs-wayfinding/office-signs-wayfinding-26-owner-20260924.webp","sha256":"2ac9c90eb767383b4fb78ec46bc7e5a316626570bd2b628d4285c71214190c66","provenance":"AI-generated illustration; owner approved 2026-09-24; original SHA256 fe412b6b8630b97c84471c16624af40d0f5371d3c57b5b1633a5fdb9d0ea81ab; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "kiosk-posm-31": {"descriptionVi":"Kiosk trưng bày khung gỗ, mái cong in tên chương trình, màn hình cảm ứng tích hợp trên quầy, kệ chai mẫu và thân in hình sản phẩm. Dành cho thương hiệu thực phẩm, đồ uống tham gia hội chợ, sự kiện, giúp khách tự tra cứu thông tin, chọn hương vị và nhân viên ghi lại thông tin khách quan tâm.","descriptionEn":"Display kiosk with a timber frame, a curved roof printed with the campaign name, a touch screen built into the counter, sample bottle shelves and a printed product body. For food and drink brands at fairs and events, it lets visitors look up information and choose flavours themselves while staff note down interested visitors.","altVi":"Kiosk có màn hình cảm ứng, kệ chai và trái dừa trong hội chợ","altEn":"Kiosk with touch screen, bottle shelves and whole coconuts at a trade fair","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-31-owner-20260924.webp","sha256":"82b5371a01ea9f286ae05a76437273de9b5d5935d4cd71e81e9bfcdb94794aca","provenance":"AI-generated illustration; owner approved 2026-09-24; original SHA256 fcff2bf7b424b9b83a3af01181a1744953f9c30ca4679439ffc4c8db4b7592a6; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "print-decals-17": {"descriptionVi":"Kệ menu mica trong chữ T đặt đứng trên đế mica, kẹp tờ menu in hai mặt theo nhóm món, thay giấy dễ dàng. Dành cho quán cà phê, tiệm bánh, quán trà, đặt trên bàn khách hoặc quầy order, giúp khách xem món nhanh, chọn món trong lúc chờ và quán đổi giá chỉ cần in lại tờ giấy.","descriptionEn":"Clear acrylic T-shaped menu stands on acrylic bases holding double-sided printed menus by category, with easily swapped inserts. For cafes, bakeries and tea shops, on tables or the order counter, they let customers browse quickly while waiting, and changing prices only means reprinting the sheet.","altVi":"Ba thực đơn mica hình chữ T để bàn có in cà phê, trà, bánh ngọt","altEn":"Three clear acrylic T-shaped table menus with coffee, tea and cake listings","source":"/assets/content/projects/advertising/print-decals/print-decals-17-owner-20260924.webp","sha256":"5e0059dc9044466240831f47e5c0b3ec6ec63efd2aedffc6b3f4fbbf41812786","provenance":"AI-generated illustration; owner approved 2026-09-24; original SHA256 97bf80cb3404f34bf1ca902841c6a2245af947a482f9d87de5f40a64b3b36c5a; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "office-signs-wayfinding-14": {"descriptionVi":"Biển phòng họp inox xước in song ngữ kèm icon, bắt ốc pát chân nổi trên tường phía trên khung cửa. Dành cho văn phòng công ty, tòa nhà cho thuê, trường học, giúp nhân viên và khách tìm đúng phòng, đồng bộ với hệ biển của tòa nhà và bền, dễ lau chùi.","descriptionEn":"Brushed stainless meeting-room sign printed in two languages with an icon, fixed with standoff bolts on the wall above the door frame. For company offices, rental buildings and schools, it helps staff and visitors find the right room, matches the building's sign system and lasts with easy cleaning.","altVi":"Biển phòng họp inox xước có icon và chữ Meeting Room, gắn trên cửa gỗ","altEn":"Brushed stainless meeting room sign with icon and text on a timber door","source":"/assets/content/projects/advertising/office-signs-wayfinding/meeting-brushed-01-above-door.webp","sha256":"2fba8a439ccc9600112e46638118de5c666022a7b57273c1ec38af6d2a66dc3b","provenance":"AI-generated illustration; ChatGPT web image generation 2026-10-24; owner approved audit #789 in chat; original SHA256 32b2f047df331c70ec6a29e4829ad1d09db278b9ab9873bdddc572c7f4cb5aef; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "office-signs-wayfinding-15": {"descriptionVi":"Biển phòng họp mica trong in UV mặt sau, chữ song ngữ và icon xanh navy, bắt ốc pát inox chân nổi lên tường cạnh cửa kính. Dành cho văn phòng hiện đại, coworking, trung tâm đào tạo, giúp nhận diện phòng rõ ràng, trông nhẹ, sạch và hợp với vách kính khung đen.","descriptionEn":"Clear acrylic meeting-room sign reverse UV-printed with bilingual text and a navy icon, fixed on stainless standoffs to the wall beside the glass door. For modern offices, coworking spaces and training centres, it marks rooms clearly and looks light and clean beside black-framed glass.","altVi":"Biển mica trắng có icon phòng họp và chữ xanh, gắn tường cạnh cửa kính","altEn":"White acrylic meeting sign with icon and blue lettering on wall beside glass door","source":"/assets/content/projects/advertising/office-signs-wayfinding/meeting-acrylic-02-audit-a149-v1.webp","sha256":"0bc58f81ead03d1b5bde065e9f04be8430e24516755418ed901b35f472e7f554","provenance":"AI-generated illustration; KIE gpt-image-2-5-flare-image-to-image; task 8a76af7091c7cd088293887ddfaacf1a; owner approved A149-v1 in chat; original SHA256 5db89eb2f7c5c847a90d8bbb4c93777fe7fc43276e2e40a4f4580f1dc3963661; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "office-signs-wayfinding-16": {"descriptionVi":"Biển phòng họp gỗ sồi tự nhiên, chữ khắc CNC sâu tô màu tối, gắn keo hoặc vít âm lên tường cạnh khung cửa. Dành cho văn phòng, trường học, studio thích phong cách mộc, giúp nhận diện phòng rõ ràng, mang lại cảm giác ấm và hợp với cửa, nội thất gỗ.","descriptionEn":"Natural oak meeting-room sign with deep CNC-engraved, dark-filled lettering, bonded or concealed-screwed beside the door frame. For offices, schools and studios with a natural style, it marks the room clearly, feels warm and matches timber doors and furniture.","altVi":"Biển gỗ sồi ghi PHÒNG HỌP, gắn tường cạnh cửa phòng họp","altEn":"Oak timber sign reading PHÒNG HỌP mounted on wall beside meeting room door","source":"/assets/content/projects/advertising/office-signs-wayfinding/meeting-timber-03.webp","sha256":"d1ded95f8d7355b92ebe145780d58d4459ba1142cc89f099b1f925b621ba360a","provenance":"AI-generated illustration; ChatGPT web image generation 2026-11-11, version q2, chat 6af43e13-c79c-83ec-9a16-0d296de0c4f8; original PNG SHA256 dbdeccf501bc9984a75c4a47b85b7df1a7781a7f6c21e3e7afc8c55cd340149c; 1024x1536, not upscaled yet; owner approved to site 2026-11-11."},
  "office-signs-wayfinding-17": {"descriptionVi":"Biển phòng ban inox bóng mờ in icon và chữ xanh, bắt bốn chốt inox chân nổi lên tường cạnh cửa. Dành cho cơ quan, bệnh viện, nhà máy, văn phòng công ty, giúp khách tìm đúng phòng ban, biển bền, không gỉ, ít bám vân tay và dễ làm đồng bộ cho cả tòa nhà.","descriptionEn":"Satin-finish stainless department sign printed with an icon and blue text, fixed with four stainless standoffs beside the door. For public offices, hospitals, factories and company offices, it helps visitors find the right department, resists rust and fingerprints and is easy to standardise across a building.","altVi":"Biển inox bóng mờ ghi PHÒNG KẾ HOẠCH, gắn tường cạnh cửa phòng làm việc","altEn":"Satin stainless sign reading PHÒNG KẾ HOẠCH beside an office room door","source":"/assets/content/projects/advertising/office-signs-wayfinding/office-planning-01.webp","sha256":"b3b2abbe7eb393b7740b2faa31669157dc375ba2bdd6d4af841818bc07df734f","provenance":"AI-generated illustration; ChatGPT web image generation 2026-11-11, version r3, chat 6af443b7-74bc-83ec-88cc-45c664c00eaf; original PNG SHA256 c5c11b7b1f725f8096364fbff9098bb1444e7d647d9fabdfa4c9afd144764a75; 1024x1536, not upscaled yet; owner approved to site 2026-11-11."},
  "office-signs-wayfinding-18": {"descriptionVi":"Biển phòng họp mica đen mờ, chữ song ngữ và icon in nhũ vàng, dán keo hai mặt lên cánh cửa gỗ ngang tầm mắt. Dành cho văn phòng, khách sạn, tòa nhà cho thuê, giúp khách và nhân viên nhận ra phòng ngay, lắp nhanh không khoan cửa và hợp với cửa gỗ ấm.","descriptionEn":"Matte black acrylic meeting-room sign with bilingual text and an icon printed in gold, fixed with double-sided tape on the timber door at eye level. For offices, hotels and rental buildings, it identifies the room at a glance, installs fast without drilling the door and suits warm timber doors.","altVi":"Biển mica đen viền vàng có icon và chữ phòng họp, gắn trên cửa gỗ","altEn":"Black acrylic sign with gold edge, icon and meeting room text on a timber door","source":"/assets/content/projects/advertising/office-signs-wayfinding/office-design-02-audit-a152-v1.webp","sha256":"834c480e95374c8bb0e39efa9b464465c7162cacde2fb8cc0c2234d36d713f62","provenance":"AI-generated illustration; KIE gpt-image-2-5-flare-image-to-image; task c64c3f682146dca4b010c7737e075274; owner approved A152-v1 in chat; original SHA256 baad7b9d493e0410cc94ec39fa6bdf6f9aa9f1b3da655cddaa681c269afa703d; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "office-signs-wayfinding-19": {"descriptionVi":"Biển phòng in decal nền xanh navy chữ trắng lớn, viền dải vàng, dán trên tấm tôn rồi bắt vít lên cánh cửa thép chống cháy. Dành cho nhà máy, tòa nhà, khu kỹ thuật, đặt ở phòng điện, phòng máy, giúp nhận diện phòng kỹ thuật rõ từ xa, bền trong môi trường công nghiệp và giá thành thấp.","descriptionEn":"Room sign printed on navy decal with large white text and a yellow strip, applied to a steel sheet and screwed to a steel fire door. For factories, buildings and plant areas, on electrical and machine rooms, it identifies technical rooms from afar, holds up in industrial settings and costs little.","altVi":"Biển decal dán tôn ghi PHÒNG KỸ THUẬT nền xanh đen, viền vàng, gắn cửa thép","altEn":"Decal-on-steel sign reading PHÒNG KỸ THUẬT, dark blue with a yellow strip, on a steel door","source":"/assets/content/projects/advertising/office-signs-wayfinding/office-technical-room-door.webp","sha256":"e201b082a42527c9acfb061618c97ad66877eb3547abf552974340a718d3f9d4","provenance":"AI-generated illustration; ChatGPT web image edit (owner chat 6adf74ca-c558-83ec-a8a6-ff556b2b35c0, card #861); upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-26 19:32Z; master PNG SHA256 da47bf8dc1de766b18533f961033bfae0dcad4c00191e5cc63ddfdf63e32a52e."},
  "office-signs-wayfinding-20": {"descriptionVi":"Trụ bảng chỉ dẫn hình tháp, mặt trắng chữ nổi xanh, viền khung màu nhận diện, đặt trên bệ đá granite có bồn cây. Dành cho khu đô thị, công viên, khu dân cư cao cấp, đặt ở lối vào và lối đi bộ, giúp người dân, khách tìm đúng khu tiện ích và tạo cảnh quan đồng bộ.","descriptionEn":"Tower-shaped sign with a white face, green raised lettering and a brand-colour frame, on a granite plinth with a planter. For new urban areas, parks and premium estates, placed at entrances and walkways, it guides residents and visitors to amenities and keeps the landscape consistent.","altVi":"Trụ bảng chỉ dẫn có chữ xanh nổi trên nền trắng, đế đá granite","altEn":"Wayfinding pillar with raised blue lettering on white and a granite base","source":"/assets/content/projects/advertising/office-signs-wayfinding/urban-park-01.webp","sha256":"91d5c9f91830cdb433a58491dd202e6851f206ee85cbfc3003ca610f92e3d340","provenance":"AI-generated illustration; ChatGPT web image generation 2026-11-11, owner-edited image in the ChatGPT chat, chat 6af4602a-e4ec-83ec-b725-137f861849f8; original PNG SHA256 428b1b850c23e0f1e4606b0326c6d7cf37ae54986185dc3b95131495525e73d3; 1024x1536, not upscaled yet; owner approved to site 2026-11-11."},
  "office-signs-wayfinding-21": {"descriptionVi":"Cột chỉ dẫn thép sơn đen, hộp tên khu phố phía trên và ba cánh chỉ hướng nhiều màu có icon, chôn chân trên vỉa hè. Dành cho khu phố thương mại, khu dân cư ven sông, chợ, giúp người đi bộ biết hướng đến dãy nhà, công viên, chợ và tạo điểm nhận diện riêng cho khu.","descriptionEn":"Black-painted steel signpost with a district name box on top and three colour-coded direction blades with icons, set into the pavement. For shopping streets, riverside estates and markets, it shows walkers the way to housing blocks, parks and markets and gives the area its own landmark.","altVi":"Trụ đen ba mũi tên cam, xanh, xanh dương chỉ KHU PHỐ BẾN ĐÁ","altEn":"Black post sign with three arrows in orange, green and blue pointing to a district","source":"/assets/content/projects/advertising/office-signs-wayfinding/office-signs-wayfinding-21-imagegen-20261019.webp","sha256":"1e328409e82a13a18bb6a735338e3539cbc7a8ea5b3e0727178b9e8339e85c17","provenance":"AI-generated illustration; source ID imagegen:2026-10-19:office-signs-wayfinding-21-a-2; original SHA256 19db2e575683c6d2fe13a84291e7b1152b649bd095d17956df669f1a0ef6ceef; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "office-signs-wayfinding-22": {"descriptionVi":"Biển tên nền kem chữ đen, khung hộp kim loại sơn tối, dựng trên hai trụ thép chôn móng trước công trình. Dành cho nhà văn hóa, nhà sinh hoạt cộng đồng, trường học, cơ quan phường xã, giúp người dân nhận ra công trình từ đường, bền ngoài trời và trông trang nghiêm, gọn gàng.","descriptionEn":"Name sign with black text on cream in a dark-painted metal box frame, on two steel posts set in footings in front of the building. For community halls, cultural houses, schools and ward offices, it helps residents recognise the building from the road, lasts outdoors and looks dignified and tidy.","altVi":"Biển chữ đen đậm trên nền kem, đứng trên hai chân thép sơn đen","altEn":"Cream sign with bold black lettering standing on two black painted steel legs","source":"/assets/content/projects/advertising/office-signs-wayfinding/urban-community-03.webp","sha256":"a85c8c9d544cc42d50d74e2d327743b681881b1819d2a270611b2b969a9a57d6","provenance":"AI-generated illustration; ChatGPT web image generation 2026-11-11, version r2, chat 6af442ca-5618-83ec-926b-eabad9dae7c9; original PNG SHA256 321ed368e0e95a77271e4708e7c144eb7bd1558a2b384a5c298a5338f586142f; 1024x1536, not upscaled yet; owner approved to site 2026-11-11."},
  "office-signs-wayfinding-23": {"descriptionVi":"Bộ biển WC nam, nữ bằng đồng xước mạ vàng, chỉ có pictogram, dán hoặc bắt vít âm lên cánh cửa. Dành cho nhà hàng, khách sạn, văn phòng cao cấp, đặt ở cửa nhà vệ sinh, giúp khách nhận ra ngay không cần chữ và hợp với cửa gỗ, nội thất sang trọng.","descriptionEn":"Pair of men's and women's toilet signs in brushed gold-tone brass with pictograms only, bonded or screwed flush onto the door. For restaurants, hotels and premium offices, fitted on toilet doors, they are recognised at a glance without text and suit timber doors and upscale interiors.","altVi":"Biển WC nam nữ bằng đồng mạ vàng gắn trên cánh cửa gỗ tối màu","altEn":"Gold-plated brass restroom sign for men and women fixed to a dark timber door","source":"/assets/content/projects/advertising/office-signs-wayfinding/washroom-brass-01-on-door.webp","sha256":"c5948bd4bba9b46aec84f7c7ba3a9a11f2f8cf3b5323a5a1875c5c352d979dfd","provenance":"AI-generated illustration; ChatGPT web image edit (owner chat 6adf74fb-0894-83ec-8fee-bbfa5df0d286, card #862); upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-26 19:32Z; master PNG SHA256 7eff6a87ccaabe53965ae7ebaea291d043c6badd95c3ec3a0385f58f91ae913f."},
  "office-signs-wayfinding-24": {"descriptionVi":"Biển cảnh báo tam giác nền vàng in hình tia sét và chữ cảnh báo, chất liệu decal hoặc alu, dán hoặc bắt vít lên cửa tủ điện. Dành cho nhà máy, tòa nhà, khu kỹ thuật, giúp người đi qua biết nguy hiểm, hỗ trợ công tác an toàn lao động, phòng cháy.","descriptionEn":"Triangular yellow warning sign printed with a lightning bolt and warning text, in decal or aluminium, bonded or screwed to the electrical cabinet door. For factories, buildings and plant areas, it alerts passers-by to danger and supports workplace and fire safety practice.","altVi":"Tam giác vàng hình sét, chữ CẨN THẬN ĐIỆN gắn trên tủ điện xám","altEn":"Yellow triangle sign with lightning symbol and CẨN THẬN ĐIỆN on grey electrical cabinet","source":"/assets/content/projects/advertising/office-signs-wayfinding/warning-electric-02.webp","sha256":"2ad92f18bd880ed85b45008761061541b0c73f5da8c62fcd7e816f5008646359","provenance":"AI-generated illustration; ChatGPT web image generation 2026-11-11, version v2, chat 6af4264c-6060-83ec-a149-15964d3e6178; original PNG SHA256 0d6ecd25c2e5b1864af7ffb48f9deacb073fbfd14e8d86984b8f1789334db3df; 1536x1024, not upscaled yet; owner approved to site 2026-11-11."},
  "office-signs-wayfinding-25": {"descriptionVi":"Biển WC hộp vuông hai mặt nền đen, in pictogram nam nữ và chữ trắng, gắn pát vuông góc với tường hành lang. Dành cho nhà hàng, khách sạn, văn phòng, trung tâm thương mại, giúp người đi từ hai đầu hành lang nhìn thấy nhà vệ sinh từ xa, không cần đến gần cửa mới biết.","descriptionEn":"Double-sided black box toilet sign with men and women pictograms and white text, mounted on a bracket at right angles to the corridor wall. For restaurants, hotels, offices and malls, it lets people coming from either end of the corridor see the toilets from afar without walking up to the door.","altVi":"WC hộp vuông đen có icon nam nữ, gắn vuông góc trên tường gỗ","altEn":"Square black washroom box sign with male and female icons on timber corridor wall","source":"/assets/content/projects/advertising/office-signs-wayfinding/washroom-projecting-03.webp","sha256":"e436624498599feb2efb96f5f5d06685c6181cdcfef809150de574b2ac5bc9db","provenance":"AI-generated illustration; ChatGPT web image generation 2026-11-11, version s3, chat 6af443d3-248c-83ec-9423-d0fe073d0d84; original PNG SHA256 193a6984da755a679ca1b34e67ad694495f7d9e9b13d470ed05e0aa3dfe2f86a; 1024x1536, not upscaled yet; owner approved to site 2026-11-11."},
  "kiosk-posm-01": {"descriptionVi":"Gian hàng triển lãm khung gỗ cột lam, vách nền in tranh phong cảnh, quầy tiếp khách và kệ gỗ bày sản phẩm đặc sản. Dành cho điểm du lịch, hợp tác xã tham gia hội chợ, đặt trong nhà triển lãm, giúp khách nhận ra địa phương từ xa và có chỗ thử, mua sản phẩm.","descriptionEn":"Exhibition booth with a slatted timber frame, a printed landscape back wall, a reception counter and timber shelving for local products. Built for tourist destinations and cooperatives at trade fairs, it lets visitors spot the region from afar and gives them a place to try and buy.","altVi":"Gian hàng khung gỗ, nền xanh vẽ làng quê, kệ sản phẩm và bàn ghế","altEn":"Wood-framed booth with green countryside mural, product shelves, and a table with chairs","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-01-exhibition-booths-v3.webp","sha256":"813285a78066be19f2dc8ab8208857eb5a9b4cf26d84920381c6e30a528a3133","provenance":"AI-generated illustration; ChatGPT web image edit (owner chat 6adf7528-510c-83ec-8d67-bc7773648b99, card #854); upscaled RunningHub SeedVR2 tile to 3072; owner approved 2026-10-26 18:24Z; master PNG SHA256 219e784bd19392f94ff226b0a364e502328b6b2b59e3998630c6f79217a034ad."},
  "kiosk-posm-02": {"descriptionVi":"Quầy bar mặt gỗ ốp lam sóng in họa tiết lá, đèn LED hắt chân, kèm tủ kính lạnh bày trái cây và kệ gỗ treo tường hắt sáng. Dành cho quán nước ép, sinh tố, trà trái cây, đặt ngay lối vào, giúp khách thấy nguyên liệu tươi, gọi món nhanh và nhớ phong cách quán.","descriptionEn":"Timber bar counter clad in wave-cut slats with a printed leaf motif, LED base lighting, a chilled glass case for fresh fruit and backlit wall shelving. For juice, smoothie and fruit tea shops at the entrance, it shows fresh ingredients, speeds up ordering and makes the shop's style memorable.","altVi":"Quầy bar gỗ hắt đèn LED, tủ kính bày trái cây tươi và kệ chai nước","altEn":"Wooden bar counter with LED uplighting, glass case of fresh fruit and bottle shelves","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-02-product-display-counters-and-shelving-v2-audit-a021-v3.webp","sha256":"7f9da4b88cb86f9c615a7175d3a520ec1671b9b4f88703a51a83469eecba7fdb","provenance":"AI-generated illustration; owner explicitly approved latest chat image A021-v3 on 2026-10-23; ChatGPT web; model unknown; original SHA256 c6bd887c8d81cd06a39559d2a49e79f9a45f7f8bd88dbe9984206580314610b1; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "kiosk-posm-03": {"descriptionVi":"Tủ trưng bày kính mắt gồm nhiều khoang khung đen, kệ kính cường lực có đèn LED hắt từng tầng, tủ gỗ có ngăn kéo bên dưới. Dành cho cửa hàng kính mắt, đồng hồ, phụ kiện, đặt dọc tường, giúp bày nhiều mẫu gọn gàng, mỗi gọng kính đều được chiếu sáng và cất hàng dự trữ ngay dưới.","descriptionEn":"Eyewear display wall of black-framed bays with tempered glass shelves lit by LED on each tier and timber drawer cabinets below. For optical, watch and accessory shops along a wall, it shows many models neatly, lights every frame and keeps spare stock right underneath.","altVi":"Tủ kính trưng bày kính mắt có kệ đèn LED hắt sáng và đáy gỗ","altEn":"Glass eyewear cabinet with LED-lit shelves and a wooden base","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-03-custom-display-cabinets-audit-a022-v1.webp","sha256":"1b1f73c52393740fee61c81ca62959f2849c29416029019e7da0c3e76f735689","provenance":"AI-generated illustration; ChatGPT web image edit with owner mask (chat 6ae5c729-5f14-83ec-a2e4-163bde88716c); upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-27; master PNG SHA256 091b159645c6cb2c4fb48d26ee8945466f556c5bea281303e9a82fbf975ce4ae."},
  "kiosk-posm-04": {"descriptionVi":"Quầy kệ gỗ trưng bày nhiều tầng, chân ốp lam tròn, đèn LED hắt dưới từng tầng kệ, banner tên thương hiệu trên khung cong phía trên. Dành cho cửa hàng đặc sản, bánh kẹo, quà tặng, đặt ở lối đi chính, giúp bày nhiều hộp sản phẩm gọn mắt và khách dễ chọn, dễ lấy.","descriptionEn":"Multi-tier timber display counter with a round slatted base, LED lighting under each shelf and a brand banner on a curved frame above. For specialty food, confectionery and gift shops on the main aisle, it shows many boxes neatly and makes products easy to choose and pick up.","altVi":"Kệ gỗ bày bánh kẹo đặc sản dưới banner đề chữ, có đèn hắt chân","altEn":"Timber shelves holding sweets under a lettered banner with base uplighting","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-04-custom-display-shelving-audit-a023-v3.webp","sha256":"35f4451b6dc2521cf29c503a7f4e9bb4de42536f6482a2dd9166c0b0fdddd50a","provenance":"AI-generated illustration; owner approved A023-v3 in chat 2026-10-23; ChatGPT web; model unknown; original SHA256 4d6195df504fb32532516022167173c62df92ac7b0542663e20e96803bda38ec; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "kiosk-posm-05": {"descriptionVi":"Kiosk bán hàng khung thép sơn đen, mái hộp đèn in hình sản phẩm, tủ kính trưng bày đế gỗ có đèn LED hắt chân. Dành cho thương hiệu kính mắt, đồng hồ, trang sức thuê điểm giữa sảnh trung tâm thương mại, giúp bày hàng an toàn, khách xem được từ bốn phía và dừng chân mua.","descriptionEn":"Retail kiosk with a black-painted steel frame, a printed lightbox canopy and glass display cases on timber bases with LED base lighting. For eyewear, watch and jewellery brands renting a spot in a mall atrium, it keeps goods secure, is viewable from all four sides and stops shoppers to buy.","altVi":"Kiosk khung thép đen, tủ kính bày kính mắt và mái in hình kính","altEn":"Black steel kiosk with glass eyewear case and canopy printed with lens graphics","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-05-shopping-centre-retail-kiosks-v2-audit-a024-v1.webp","sha256":"64dc0e70fce8d368127b6db59269bf5ada6135269bf6eb45dddf4f5b6c7a52a1","provenance":"AI-generated illustration; owner selected A024-v1 in HTML audit and confirmed in chat 2026-10-22; ChatGPT web gpt-image; original SHA256 4e8f7a271de3f239f60587b90ee588b897e8564659f9c8e0fe58010fdb03eb29; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "kiosk-posm-06": {"descriptionVi":"Kiosk gỗ cong có mái vòm, kệ tròn nhiều tầng bày mỹ phẩm, đèn LED hắt chân và cây xanh trang trí, quầy thu ngân tích hợp. Dành cho thương hiệu mỹ phẩm, chăm sóc da thuê điểm giữa sảnh trung tâm thương mại, giúp tạo không gian thương hiệu nổi bật, khách đi vòng xem và trải nghiệm sản phẩm.","descriptionEn":"Curved timber kiosk with an arched canopy, multi-tier round shelves for cosmetics, LED base lighting, decorative plants and an integrated till. For cosmetics and skincare brands renting an atrium spot in a mall, it creates a standout brand space that shoppers walk around and try products in.","altVi":"Kiosk gỗ cong, đèn LED hắt chân, bày mỹ phẩm từ dừa trong trung tâm","altEn":"Curved timber kiosk with LED base uplighting holding coconut cosmetic products","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-06-brand-activation-kiosks-audit-a025-v3.webp","sha256":"b6df6e1b0ee096b966cd15251ff0995f9fe288f1829c1aefcaf659d4699a0406","provenance":"AI-generated illustration; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-31; master PNG SHA256 a27da3b9df61ce02fab48d3de30377367d04872e95470d1948f59fb117a10ab8."},
  "kiosk-posm-07": {"descriptionVi":"Quầy gỗ trưng bày cong, mặt trước in hình sản phẩm có đèn LED hắt viền, kệ nhiều tầng phía sau và khung treo trang trí phía trên. Dành cho thương hiệu đặc sản, bánh kẹo đặt quầy ở trung tâm thương mại, giúp khách nếm thử, mua ngay và nhận ra thương hiệu qua hình ảnh nổi bật trên quầy.","descriptionEn":"Curved timber display counter with a printed product front edged in LED light, tiered shelving behind and a decorative hanging frame above. For specialty food and confectionery brands with a counter in a mall, it lets shoppers taste and buy on the spot and recognise the brand from the bold counter graphics.","altVi":"Quầy gỗ đèn LED hắt chân bày bánh kẹo, sản phẩm dừa trong trung tâm","altEn":"Timber counter with LED base uplighting holding sweets and coconut products in a mall","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-07-sampling-counters-v2-audit-a026-v2.webp","sha256":"55e583cb845918cad13895d3ace4807a3f54f9175743c74a54b6ffdb28a01d5c","provenance":"AI-generated illustration; owner selected A026-v2 in HTML audit and confirmed in chat 2026-10-22; ChatGPT web gpt-image; original SHA256 7967a4b5a3e09187aae31e8074efd5f814d72f2e284e042ea6994832b38837da; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "kiosk-posm-08": {"descriptionVi":"Quầy lễ tân hình cong làm bằng MDF cắt CNC, thân ốp sóng nan dọc sơn kem, mặt đá nhân tạo, LED hắt sáng chân quầy. Dành cho spa, phòng khám, văn phòng, showroom, đặt tại sảnh đón khách, giúp sảnh mềm mại, sang trọng và tạo ấn tượng đầu tiên chỉn chu với khách.","descriptionEn":"Curved reception desk built from CNC-machined MDF, its body clad in cream vertical fluting, with a solid-surface top and LED base lighting. For spas, clinics, offices and showrooms, in the welcome lobby, it softens the space, looks refined and gives a polished first impression.","altVi":"Cream curved reception counter with LED lighting under its base","altEn":"Cream curved reception counter with LED lighting along the base","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-08-event-reception-counters.webp","sha256":"eed1e44c261f0af7d29f1971ba37e5674670b76c9ccdfcb9cd0d9b95183e280e","provenance":"AI-generated illustration; ChatGPT web image edit (owner chat 6adf7558-6a64-83ec-9b2a-081319dd5fe7, card #869); upscaled RunningHub SeedVR2 tile to 3072; owner approved 2026-10-26 18:24Z; master PNG SHA256 422abeacb72b6272141c3f2430c24659693eeb944b9725f5d96e8e2468f69cec."},
  "kiosk-posm-09": {"descriptionVi":"Bộ bục trưng bày MDF sơn nhiều màu, cao thấp khác nhau, mỗi bục có hộp mica trong úp trên mặt để bảo vệ sản phẩm. Dành cho showroom, cửa hàng đồ uống, mỹ phẩm, trưng bày sản phẩm mới ở gần cửa kính, giúp từng chai nổi bật, tránh bụi, va chạm mà khách vẫn ngắm rõ.","descriptionEn":"Set of painted MDF plinths in several colours and heights, each topped with a clear acrylic cover to protect the product. For showrooms, drink and cosmetics stores showing new products near the window, they make each bottle stand out and keep dust and knocks away while staying fully visible.","altVi":"Ba bục MDF sơn xanh, kem, trắng có hộp mica trong đựng chai","altEn":"Three painted MDF plinths in blue, cream and white with clear acrylic bottle cases","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-09-product-display-plinths-v2.webp","sha256":"c147b90851691cd85a4b057604f2daf7118e3feeffeabfcd78c403588d8434d1","provenance":"AI-generated illustration; source ID imagegen:2026-10-15:kiosk-posm-09-a; original SHA256 012fc271dc886ccceb8b50e1f7bcddba322e0eb542e3175e5c7b2b8ab2a05d95; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "kiosk-posm-10": {"descriptionVi":"Đảo trưng bày MDF sơn xanh, mặt đá trắng, viền nẹp đồng, đèn LED hắt chân, kèm kệ tường cùng màu. Dành cho cửa hàng gốm, đồ mây tre, quà tặng, đặt giữa lối đi chính, giúp khách xem sản phẩm từ mọi phía, chia khu hàng rõ ràng và cửa hàng trông đồng bộ, sang hơn.","descriptionEn":"Painted green MDF island display with a white stone top, brass trim and LED base lighting, plus matching wall shelving. For ceramics, rattan and gift shops, placed in the main aisle, it lets shoppers see products from every side, zones the range clearly and makes the store look coordinated and refined.","altVi":"Đảo trưng bày màu xanh có đèn LED hắt chân, bày gốm và giỏ mây","altEn":"Green island display with LED base lighting holding ceramics and rattan baskets","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-10-island-displays-v2.webp","sha256":"45aca1bdf52282620f233c8b1ef090bf912b8b98ba1f97d35cd6a346290cba8f","provenance":"AI-generated illustration; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-31; master PNG SHA256 9ffc62b352955b6001239a6cf625ff39a1c5eb9835db2fa1445521dead3e9db9."},
  "kiosk-posm-11": {"descriptionVi":"Vách trưng bày cong ốp gỗ, mảng tranh in khẩu hiệu, kệ nổi có đèn LED, kèm quầy cong ốp lam và bục bày sản phẩm. Dành cho thương hiệu nến thơm, tinh dầu, quà tặng trong trung tâm thương mại, giúp cửa hàng nhỏ có điểm nhấn thương hiệu và bày nhiều sản phẩm gọn, ấm áp.","descriptionEn":"Curved timber display wall with a printed slogan panel and LED-lit floating shelves, plus a slatted curved counter and product plinths. For candle, essential oil and gift brands in malls, it gives a small store a brand focal point and displays many products neatly and warmly.","altVi":"Vách trưng bày cong có kệ gỗ, LED hắt và sản phẩm nến thơm","altEn":"Curved display wall with timber shelves, LED uplighting and scented candle products","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-11-branded-display-walls-audit-a030-v1.webp","sha256":"9cfb560a10a9f0260bf4ee3f37eb58b279f86b2a6eb810cfb2018e52f06409ac","provenance":"AI-generated illustration; ChatGPT web image edit (owner chat 6adf757d-8878-83ec-8d44-59066c923cbe, card #870); upscaled RunningHub SeedVR2 tile to 3072; owner approved 2026-10-26 18:24Z; master PNG SHA256 f248be8dc4882d00667c5d0ff81e61f964954abb2721731991847ebef584e71f."},
  "kiosk-posm-12": {"descriptionVi":"Bộ POSM gỗ đồng bộ gồm xe trưng bày mái gỗ, kệ tầng, bục, standee cắt hình lá và bảng chữ chiến dịch. Dành cho thương hiệu thực phẩm sạch, trái cây sấy, đồ ăn vặt làm gian hàng trong siêu thị, giúp gian hàng có câu chuyện rõ ràng, bày nhiều sản phẩm và mời khách dùng thử.","descriptionEn":"Matching timber POSM set of a roofed display cart, tiered shelves, plinths, leaf-shaped standees and campaign lettering boards. For clean food, dried fruit and snack brands with a supermarket booth, it gives the booth a clear story, holds plenty of products and invites shoppers to taste.","altVi":"Bộ POSM gỗ có kệ trưng bày, quầy xe và biển chữ Vị ngon thiên nhiên","altEn":"Timber POSM set with display shelves, cart counter and a sign reading natural flavour","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-12-campaign-posm-sets-audit-a031-v1.webp","sha256":"add347407290f73a8473208d2a5e723593ff1d1c709d86b6016e594a2a52b4db","provenance":"AI-generated illustration; ChatGPT web image edit (owner chat 6adf75a7-86b8-83ec-b6d4-e2d7b78a2951, card #856); upscaled RunningHub SeedVR2 tile to 3072; owner approved 2026-10-26 18:24Z; master PNG SHA256 a1dff5abe9e3a01fb157f3487355e7f3e396d163d7a80c446402308347d8c604."},
  "kiosk-posm-13": {"descriptionVi":"Gian hàng triển lãm khung gỗ ốp tấm tối, vách trưng bày mẫu vật liệu, quầy tư vấn, bục trưng bày và đèn LED hắt chân. Dành cho thương hiệu nội thất, vật liệu, gạch ốp tham gia triển lãm, giúp khách chạm và so sánh mẫu thật, ngồi trao đổi với nhân viên và nhớ thương hiệu.","descriptionEn":"Exhibition booth with a timber frame in dark panels, material sample walls, a consultation counter, plinths and LED base lighting. For furniture, materials and tile brands at trade shows, it lets visitors touch and compare real samples, sit down with staff and remember the brand.","altVi":"Gian hàng triển lãm có vách gỗ, kệ mẫu vật liệu và đèn LED hắt chân","altEn":"Exhibition booth with timber wall, material sample shelves and LED base uplighting","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-13-exhibition-booths-audit-a032-v3.webp","sha256":"760a1908e500a58e3e3acedc403aac7df553083ca358d72167ba85e0126f4af0","provenance":"AI-generated illustration; ChatGPT web image edit (owner chat 6adf75db-880c-83ec-b429-016ab7ca2ad4, card #871); upscaled RunningHub SeedVR2 tile to 3072; owner approved 2026-10-26 18:24Z; master PNG SHA256 0a7c16a280155b8b6bfadd5a889e5ed4a9bac3cd8581e1469e2d70e79bf8df39."},
  "kiosk-posm-14": {"descriptionVi":"Cụm quầy kệ gỗ gồm đảo trưng bày hai tầng chân ốp lam có đèn hắt và tủ kệ gỗ treo tường, xen chậu cây xanh. Dành cho cửa hàng đồ mỹ nghệ, gốm, đồ gia dụng thủ công, giúp bày sản phẩm theo từng nhóm, tạo không gian ấm và mời khách đi vòng xem hàng lâu hơn.","descriptionEn":"Timber display set with a two-tier slatted island lit at the base and wall shelving, mixed with potted plants. For handicraft, ceramics and handmade homeware shops, it groups products clearly, creates a warm space and invites shoppers to walk around and browse longer.","altVi":"Kệ gỗ đèn LED hắt sáng trưng bày bát đĩa gốm và chậu cây","altEn":"Timber shelf with LED uplighting displaying ceramic bowls, plates and potted plants","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-14-product-display-counters-and-shelving-audit-a033-v3.webp","sha256":"9442b0bc5b8b6fa681b6335ed833571213a7d83599dd013c4863b073153fcb2a","provenance":"AI-generated illustration; owner explicitly approved latest chat image A033-v3 on 2026-10-23; ChatGPT web; model unknown; original SHA256 fbd0e2bb81c0872464d33f664ecafba947a697d4aa1ff0b405e9e051f4003282; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "kiosk-posm-15": {"descriptionVi":"Tủ kính trưng bày ba tầng kệ kính, chân tủ gỗ ốp lam sóng có đèn hắt, hộp đèn in tên và họa tiết thương hiệu phía trên. Dành cho thương hiệu đồ mỹ nghệ, quà lưu niệm đặt tại trung tâm thương mại, sân bay, giúp bảo vệ hàng dễ vỡ mà khách vẫn ngắm rõ từng món.","descriptionEn":"Glass display case with three glass shelves, a wave-slatted timber base with uplighting and a printed brand lightbox on top. For handicraft and souvenir brands in malls and airports, it protects fragile pieces while letting shoppers see every item clearly.","altVi":"Tủ kính bày đồ mỹ nghệ dừa, biển gỗ in chữ, đèn LED trong tủ","altEn":"Glass cabinet of coconut-shell crafts with printed timber sign and LED lights inside","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-15-custom-display-cabinets-v2-audit-a034-v2.webp","sha256":"20f6b7b0b72c92fc25f59ad50afda771a6826e6ab2a87fda5c0f0d0b92992f39","provenance":"AI-generated illustration; owner selected A034-v2 in HTML audit and confirmed in chat 2026-10-22; ChatGPT web gpt-image; original SHA256 bf960aa701ed1a2d91cebb9a542494c719c16b1fa6d8f52d49026fe26408a012; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "kiosk-posm-16": {"descriptionVi":"Cụm kệ trưng bày gồm bục tròn ốp lam, kệ khung thép nhiều tầng và backdrop vòng cung in tranh phong cảnh, kèm cây xanh và đèn hắt. Dành cho thương hiệu mỹ nghệ, quà lưu niệm tham gia hội chợ, triển lãm, giúp kể câu chuyện nguồn gốc sản phẩm và thu hút khách bước vào gian hàng.","descriptionEn":"Display set of slatted round plinths, multi-tier steel-framed shelves and a curved backdrop printed with a landscape, plus plants and uplights. For handicraft and souvenir brands at fairs and exhibitions, it tells the story of where products come from and draws visitors into the booth.","altVi":"Bục gỗ nhiều bậc trưng bày bình gốm trước tranh thuyền và cọ","altEn":"Multi-tier timber plinth with ceramic vases in front of a boat and brush painting","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-16-custom-display-shelving-audit-a035-v4.webp","sha256":"ed0bae062ded6879f42db46c5e56e2f244e33f0c7d7f30c5171de46a55662403","provenance":"AI-generated illustration; owner explicitly approved latest chat image A035-v3 on 2026-10-23; ChatGPT web; model unknown; original SHA256 9d15e1bdfa2ed8f2ca8fde8278ceb8885ffed737e6eba364e340cfe2bcf34990; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "kiosk-posm-17": {"descriptionVi":"Kiosk mỹ phẩm khung gỗ sơn hồng phối viền vàng, kệ tường có đèn LED, gương tròn có đèn, quầy tư vấn mặt đá marble và ghế ngồi thử. Dành cho thương hiệu mỹ phẩm, chăm sóc da thuê điểm trong trung tâm thương mại, giúp khách ngồi thử sản phẩm, được tư vấn tại chỗ và nhớ phong cách thương hiệu.","descriptionEn":"Cosmetics kiosk with a pink-painted timber frame and gold trim, LED-lit wall shelves, a lit round mirror, a marble consultation counter and a trial stool. For cosmetics and skincare brands renting mall space, it lets shoppers sit and try products, get advice on the spot and remember the brand style.","altVi":"Kiosk mỹ phẩm sơn hồng vàng, kệ đèn LED, gương tròn và quầy đá marble","altEn":"Pink and gold cosmetics kiosk with LED shelves, round mirror and marble counter","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-17-shopping-centre-retail-kiosks-audit-a036-v3.webp","sha256":"5b9eacab54f409b622f5b4b45df7a29a64738c8c02befd180709720d20ee73d3","provenance":"AI-generated illustration; owner approved A036-v3 in chat 2026-10-23; ChatGPT web; model unknown; original SHA256 f1bd50f039546c9646ced73c4bd3c32c008ee991e400723b29c82fba4554407e; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "kiosk-posm-18": {"descriptionVi":"Kiosk tư vấn du lịch vách cong in tranh phong cảnh, mái gỗ uốn, quầy tư vấn ốp nan gỗ có đèn, ghế mây và kệ tờ rơi. Dành cho công ty du lịch, điểm đến địa phương quảng bá tour trong trung tâm thương mại, giúp thu hút người đi ngang, ngồi tư vấn và phát tài liệu ngay tại chỗ.","descriptionEn":"Travel consultation kiosk with curved walls printed with landscapes, a bent timber roof, a lit slatted counter, rattan stools and brochure racks. For tour companies and destinations promoting trips in malls, it draws in passers-by, lets staff sit and advise and hand out materials on the spot.","altVi":"Gian hàng gỗ cong có tranh in cảnh du lịch sông nước, quầy và ghế mây","altEn":"Curved timber booth with printed river tourism artwork, counter and rattan chairs","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-18-brand-activation-kiosks-audit-a037-v3.webp","sha256":"49a2549c585e12ea70328a926f9a656b255a1a3043deec16cef0e6778aceef53","provenance":"AI-generated illustration; edited by owner in ChatGPT web; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-27; master PNG SHA256 5553915cc337c10558a9170a93739ff0249e6aaf9872bd2659d0b9f8e586e130."},
  "kiosk-posm-19": {"descriptionVi":"Quầy sampling ốp nan tre, mái lá trang trí, bảng tên thương hiệu và bảng mời thử treo trên khung, kèm bình nước và kệ hàng mẫu. Dành cho thương hiệu thực phẩm, đồ uống đặc sản làm chương trình dùng thử trong siêu thị, hội chợ, giúp khách dừng lại nếm thử và tạo không khí miền quê gần gũi.","descriptionEn":"Sampling counter clad in bamboo slats with a thatched roof, a brand board and try-me signs hung on the frame, plus a drink dispenser and sample shelves. For specialty food and drink brands running tastings in supermarkets and fairs, it gets shoppers to stop and taste and creates a friendly countryside feel.","altVi":"Quầy sampling gỗ có bảng mời thử sản phẩm và bày đồ chế biến từ dừa","altEn":"Timber sampling counter with a sign inviting tastings and display of coconut processed goods","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-19-sampling-counters-audit-a038-v1.webp","sha256":"b8024114f8c7c164c5ce9e421883e393bc0c613c427550377ecb494d9fe8ea66","provenance":"AI-generated illustration; edited by owner in ChatGPT web; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-27; master PNG SHA256 92026a1616da2edb425fceec4ce60e501c225157ae48a0c2befbf188308cce9b."},
  "kiosk-posm-20": {"descriptionVi":"Quầy lễ tân cong ốp lam gỗ dọc, mặt đá trắng, chữ tên chương trình trên mặt quầy, đèn LED hắt chân, kèm vách cong và trang trí theo chủ đề. Dành cho ban tổ chức triển lãm, hội chợ, sự kiện, đặt ở lối vào, giúp đón khách, phát tài liệu, đăng ký và tạo ấn tượng đầu tiên chuyên nghiệp.","descriptionEn":"Curved reception counter clad in vertical timber slats with a white stone top, event lettering on the front and LED base lighting, plus a curved wall and themed decor. For exhibition, fair and event organisers at the entrance, it welcomes guests, hands out materials, handles registration and makes a professional first impression.","altVi":"Quầy tiếp tân gỗ cong, mặt đá trắng, chữ và dừa trang trí","altEn":"Curved vertical timber reception counter with white stone top and coconut decoration","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-20-event-reception-counters-audit-a039-v2.webp","sha256":"1ca8b97e3e3a6935ddb87c3ffd16f8ff7be9fe111642396e84b357f6ca7aa180","provenance":"AI-generated illustration; edited by owner in ChatGPT web; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-27; master PNG SHA256 fcec895c16c8652ac3fd694862e2464f1dab43aa62d4c083ee653235e52f1c7c."},
  "kiosk-posm-21": {"descriptionVi":"Bục trưng bày nhiều bậc gồm bệ tròn sơn trắng và khối gỗ ốp lam có đèn LED hắt, phía sau là vách vòm in tranh phong cảnh. Dành cho cửa hàng, gian hàng đồ mỹ nghệ, gốm, quà tặng, giúp bày sản phẩm theo tầng cao thấp, món nào cũng được nhìn rõ và kể câu chuyện nguồn gốc.","descriptionEn":"Multi-level display plinth of white-painted round bases and slatted timber blocks with LED uplighting, backed by an arched landscape print. For craft, ceramics and gift shops and booths, it arranges products at different heights so each piece is seen clearly and tells the story of where they come from.","altVi":"Bục bậc gỗ, bệ sơn trắng cong, tranh cọ dừa và đèn hắt","altEn":"Curved white plinth with timber steps, palm painting and uplighting","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-21-product-display-plinths-audit-a040-v2.webp","sha256":"98a2b1a5a21dc06404fe5b7c1b2b085e3b3e51a3f161b4395f9f569ea33df194","provenance":"AI-generated illustration; owner selected A040-v2 in HTML audit and confirmed in chat 2026-10-22; ChatGPT web gpt-image; original SHA256 7492121998bfcd05f2535c46023c1f3d86819ca70edb63c0c6b925582b723f81; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "kiosk-posm-22": {"descriptionVi":"Đảo trưng bày nhiều tầng bo cong, ốp gỗ hai tông, đèn LED hắt chân từng tầng, đặt giữa lối đi. Dành cho thương hiệu đồ mỹ nghệ, đồ gia dụng thủ công thuê điểm giữa sảnh trung tâm thương mại, giúp bày nhiều sản phẩm, khách xem được từ mọi phía và thu hút người đi ngang.","descriptionEn":"Multi-tier curved island display clad in two-tone timber with LED lighting under each tier, set in the walkway. For craft and handmade homeware brands renting a mall atrium spot, it shows many products, is viewable from all sides and draws in passers-by.","altVi":"Bục nhiều bậc gỗ tối màu, đèn hắt chân và bát đồ gỗ dừa","altEn":"Dark timber stepped plinth with base uplighting holding coconut wood bowls","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-22-island-displays-audit-a041-v1.webp","sha256":"07d48fbe914ed0eae00d6de4c99f003c5250f08c802e563297d8828f47215508","provenance":"AI-generated illustration; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-31; master PNG SHA256 d701cc517afb4afcce227a932ca4b1ef191e3c8e6f51747339ce0c5c95f1c862."},
  "kiosk-posm-23": {"descriptionVi":"Vách trưng bày cong in hình sản phẩm và nguyên liệu, kệ hắt đèn LED, kèm quầy tròn ốp nan gỗ và bục trưng bày nhiều tầng. Dành cho thương hiệu mỹ phẩm thiên nhiên mở gian hàng trong trung tâm thương mại, giúp sản phẩm nổi bật, khách nhận ra nguồn gốc nguyên liệu và dừng lại thử.","descriptionEn":"Curved display wall printed with products and ingredients, LED-lit shelves, a round slatted timber counter and multi-tier plinths. For natural cosmetics brands opening a mall booth, it makes products stand out, shows where ingredients come from and invites shoppers to stop and try.","altVi":"Mỹ phẩm dừa có vòm tranh in, kệ gỗ và kệ đèn LED hắt sáng","altEn":"Coconut cosmetics display bay with printed arch panel, timber shelves and LED-lit racks","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-23-branded-display-walls-audit-a042-v1.webp","sha256":"a2334b6c948d1070d36801af3fb95833e08d1be89b7d630f078ad9ed50b50b97","provenance":"AI-generated illustration; edited by owner in ChatGPT web; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-27; master PNG SHA256 57782bd636340d686e1259fc49ddd217af67662b05a33bdf59a3211e82c1ce66."},
  "kiosk-posm-24": {"descriptionVi":"Bộ POSM chiến dịch gồm standee bo góc, vách vòm in cảnh biển, bục tròn ốp nan gỗ và kệ đứng nhiều tầng bày sản phẩm. Dành cho nhãn hàng mỹ phẩm, đồ dùng mùa hè chạy chương trình tại trung tâm thương mại, siêu thị, giúp tạo không khí chiến dịch và đưa sản phẩm vào tầm mắt khách.","descriptionEn":"Campaign POSM set of rounded standees, an arched panel printed with a beach scene, slatted round plinths and a tall tiered shelf for products. For cosmetics and summer goods brands running promotions in malls and supermarkets, it builds the campaign mood and puts products right at eye level.","altVi":"Gian gỗ có tranh biển in, standee mỹ phẩm dừa và kệ hai bên","altEn":"Timber display bay with printed seascape panel, coconut cosmetics standee and side shelves","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-24-campaign-posm-sets-audit-a043-v1.webp","sha256":"250de996cabeb7b80a3020a7376f05f81ce124c32c138d5daca886091001c3ab","provenance":"AI-generated illustration; ChatGPT web image edit (owner chat 6adfd49c-b338-83ec-96c8-430ba0b1639c); upscaled RunningHub SeedVR2 tile to 3072; owner approved 2026-10-27 01:07Z; master PNG SHA256 c75e25a96630001175181584355a92b00dcfa9700287d41bc3141d40a192a335."},
  "kiosk-posm-25": {"descriptionVi":"Gian hàng triển lãm khung nhôm định hình, vách bạt in hình vùng nguyên liệu, kệ sản phẩm có đèn, quầy gỗ ốp lam và bàn ghế tiếp khách. Dành cho doanh nghiệp, hợp tác xã nông sản tham gia hội chợ, giúp giới thiệu sản phẩm theo nhóm, mời khách thử và trao đổi đơn hàng ngay tại gian.","descriptionEn":"Exhibition booth with an extruded aluminium frame, fabric walls printed with the source region, lit product shelves, a slatted timber counter and a seating area. For agricultural companies and cooperatives at trade fairs, it presents products by group, invites tasting and lets staff discuss orders right at the booth.","altVi":"Gian hàng triển lãm có kệ sản phẩm, bàn gỗ và tranh bạt in về dừa","altEn":"Exhibition booth with product shelves, timber table and printed fabric artwork","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-25-trade-fair-coconut-standard.webp","sha256":"d3f11d8a7f308fb26e48849cb6b0422d7f7550d9d3470292378ac8d10135c3c5","provenance":"Derivative of accepted source SHA-256 67c25939a98a3659b7f5d8b47c3f8687828a9b551de15e7630c0f659373cda93; source-assets/projects/advertising/taxonomy-20260910-review/acceptance.json; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "kiosk-posm-26": {"descriptionVi":"Gian hàng triển lãm đảo bốn mặt, mái bảng tên in hình nguyên liệu, quầy trưng bày bo cong ốp lam, quầy pha chế và đèn treo. Dành cho thương hiệu thực phẩm, đồ uống tham gia hội chợ lớn, giúp khách tiếp cận từ mọi phía, xem và nếm thử sản phẩm và nhận ra thương hiệu từ xa.","descriptionEn":"Four-sided island exhibition booth with a printed overhead name fascia, curved slatted display counters, a drinks bar and pendant lights. For food and drink brands at large fairs, it can be approached from every side, lets visitors see and taste products and shows the brand from afar.","altVi":"Gian hàng triển lãm bo cong với bảng dừa và quầy trưng bày sản phẩm dừa","altEn":"Curved exhibition island with coconut sign and product display counter","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-26-imagegen-20261018.webp","sha256":"ad70c869435f448a5c13cf56f98e77257cb79426335daf1776ab5c33df5e29b4","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:kiosk-posm-26-1; original SHA256 aa959c5254b2ed5b574aa08e238913bade0b59131b552a2ea4d177d20f90f060; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "kiosk-posm-27": {"descriptionVi":"Gian hàng hội chợ khung nhôm định hình, vách in hình sản phẩm, kệ gỗ nhiều tầng, quầy giới thiệu ốp lam và góc trình diễn có bàn ghế. Dành cho thương hiệu mỹ phẩm, chăm sóc da tham gia hội chợ, giúp trưng bày đủ dòng sản phẩm, làm mẫu trực tiếp cho khách và tư vấn ngay tại gian.","descriptionEn":"Trade fair booth with an extruded aluminium frame, walls printed with products, multi-tier timber shelves, a slatted welcome counter and a demo corner with seating. For cosmetics and skincare brands at fairs, it shows the full range, allows live demonstrations and lets staff advise visitors on the spot.","altVi":"Gian hàng triển lãm có kệ gỗ, bạt in hình dừa và bàn sản phẩm","altEn":"Exhibition booth with timber shelves, coconut-printed fabric and product table","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-27-trade-fair-coconut-cellulose.webp","sha256":"d0bf57e79844c6baaa827c7a5680bb810726641d44981cb13f8bd8595f9f6425","provenance":"Derivative of accepted source SHA-256 5c0a654a71025f6b1870b657429c5e4e5010ac4f929cf709849da3ce62be7f21; source-assets/projects/advertising/taxonomy-20260910-review/acceptance.json; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "kiosk-posm-28": {"descriptionVi":"Gian hàng triển lãm thiết kế cong, khung gỗ sơn hồng đất, mái vòm có tên thương hiệu, kệ đèn LED, quầy mặt đá và góc tiếp khách. Dành cho thương hiệu mỹ phẩm, làm đẹp tham gia hội chợ, giúp tạo không gian nổi bật giữa nhiều gian, bày sản phẩm sang và có chỗ ngồi tư vấn khách.","descriptionEn":"Curved exhibition booth with a terracotta-pink painted timber frame, an arched brand canopy, LED-lit shelving, a stone-top counter and a seating area. For cosmetics and beauty brands at trade fairs, it stands out among many booths, displays products elegantly and gives space to sit and advise visitors.","altVi":"Gian hàng cong màu hồng đất với kệ sản phẩm mỹ phẩm và khu tiếp khách","altEn":"Curved terracotta-pink booth with cosmetics shelves and a greeting area","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-28-trade-fair-beauty-statement.webp","sha256":"ccea7de9c6bcbac119217eefd4ac53abf64e4673ccc2236ede596266bf0c9fdc","provenance":"Derivative of accepted source SHA-256 6f6b2bda8a0a1b9d1feaf67be3e874f4125b792275088a738713db1f19c216cf; source-assets/projects/advertising/taxonomy-20260910-review/acceptance.json; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "kiosk-posm-29": {"descriptionVi":"Gian hàng triển lãm khung nhôm sơn đen, giá treo quần áo bằng thép, ma-nơ-canh, bục gỗ, kệ xếp đồ và đèn rọi ray. Dành cho thương hiệu thời trang tham gia hội chợ, tuần lễ thời trang, giúp trình bày bộ sưu tập rõ phong cách, khách đi vào xem, chạm chất liệu và hỏi đặt hàng.","descriptionEn":"Exhibition booth with a black-painted aluminium frame, steel clothing rails, mannequins, timber plinths, folding shelves and track spotlights. For fashion brands at fairs and fashion weeks, it presents the collection's style clearly and lets visitors walk in, feel fabrics and ask about orders.","altVi":"Gian hàng khung đen có giá treo quần áo và ma-nơ-canh","altEn":"Black-frame booth holding clothing racks and mannequins in a trade fair stand","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-29-trade-fair-fashion.webp","sha256":"aca3b04fedab2382eb885a498b2bdc1807667018e94ec627a131bf97a968c367","provenance":"Derivative of accepted source SHA-256 30fad3bc843b5c6d2b880ec84ff699310a6a4f3d440d1b1d4171c3b218d92d11; source-assets/projects/advertising/taxonomy-20260910-review/acceptance.json; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "kiosk-posm-30": {"descriptionVi":"Gian hàng hội chợ khung nhôm, vách in hình nguyên liệu, kệ thép chất bao mẫu, quầy tiếp khách và bàn ghế trao đổi. Dành cho doanh nghiệp cung cấp nguyên liệu, nông sản xuất khẩu tham gia hội chợ B2B, giúp khách mua sỉ xem mẫu thật, ngồi trao đổi đơn hàng và nhớ tên nhà cung cấp.","descriptionEn":"Trade fair booth with an aluminium frame, walls printed with raw materials, steel racks of sample sacks, a welcome counter and a meeting table. For raw material suppliers and agricultural exporters at B2B fairs, it lets wholesale buyers see real samples, sit down to discuss orders and remember the supplier.","altVi":"Gian hàng có bao hàng xếp kệ, bàn tròn và thùng xanh về nguyên liệu dừa","altEn":"Raw coconut material booth with sacks stacked on shelves, round table and green bins","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-30-trade-fair-coconut-ingredients.webp","sha256":"28d9187e6b012434e7710f5c41284fcb5b971c3bdb3ae321c94f87410b5c0edb","provenance":"Derivative of accepted source SHA-256 3e0fe6a7e1059a8d864edea3fdb09f611fc017d11486d9ded0970139fe637067; source-assets/projects/advertising/taxonomy-20260910-review/acceptance.json; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "mobile-retail-01": {"descriptionVi":"Xe đẩy bán hàng khung sắt sơn tĩnh điện, mặt và kệ gỗ ba tầng, bánh xe có khóa, biển tên in trên khung cao. Dành cho thương hiệu nước dừa, đồ uống đóng chai bán ở trung tâm thương mại, sảnh siêu thị, giúp bày nhiều hàng trong diện tích nhỏ và dễ dời chỗ theo lượng khách.","descriptionEn":"Powder-coated steel retail cart with a timber top and three shelves, locking wheels and a printed name board on a raised frame. For coconut water and bottled drink brands in malls and supermarket lobbies, it shows plenty of stock in a small footprint and moves easily with the crowd.","altVi":"Xe đẩy bán nước dừa có bánh xe, đặt giữa lối đi trung tâm thương mại","altEn":"Wheeled coconut water cart with a steel frame placed in a shopping centre walkway","source":"/assets/content/projects/advertising/mobile-retail/mobile-retail-01-mobile-retail-carts-v2.webp","sha256":"0bf24c40a8d0b440c609734b2190756655a0318732bfff1f7c806f1d06442f9d","provenance":"AI-generated illustration; source ID imagegen:2026-10-14:mobile-retail-01-a; original SHA256 9a1dbf8610a5bc93a7d595d3b1e9858de6adfd39ef8d44ea1f7cbffcaa5771ef; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "mobile-retail-02": {"descriptionVi":"Xe bán cà phê khung thép, thân in hình hạt cà phê, mặt quầy inox đặt bình giữ nhiệt, hộp đèn tên quán trên khung cao và bánh xe có khóa. Dành cho quán cà phê bán buổi sáng trước tòa văn phòng, trường học, bệnh viện, giúp phục vụ nhanh khách đi làm và nhận ra từ xa.","descriptionEn":"Coffee cart with a steel frame, a body printed with a coffee bean, a stainless top holding insulated urns, a name lightbox on a raised frame and locking wheels. For cafes selling mornings outside offices, schools and hospitals, it serves commuters fast and is easy to spot from afar.","altVi":"Xe cà phê có hộp đèn tiêu đề, máy pha và bình giữ nhiệt","altEn":"Coffee cart with lit header box, espresso machine and thermos flasks outdoors","source":"/assets/content/projects/advertising/mobile-retail/mobile-retail-02-mobile-coffee-carts-v2.webp","sha256":"c60361ea82b8e079720ac1c54e34665f83816044b66d113ec4993e99ff153582","provenance":"AI-generated illustration; source ID imagegen:2026-10-14:mobile-retail-02-a; original SHA256 86f5c817b577295beac18ea55321cf668cbc521c5c84cd8158eee4adf14ce15d; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "mobile-retail-03": {"descriptionVi":"Xe bán thức ăn khung thép sơn đen, thân ốp lam gỗ, mặt quầy inox, tủ kính nhỏ, mái che bật lên có đèn và bánh xe lớn. Dành cho quán ăn, thương hiệu đồ ăn nhanh bán ở sảnh tòa nhà, chợ đêm, sự kiện, giúp mở bán nhanh, dễ vệ sinh và trông chỉn chu như một quầy cố định.","descriptionEn":"Food cart with a black-painted steel frame, timber slat cladding, a stainless counter, a small glass case, a lift-up lit canopy and large wheels. For eateries and fast-food brands in building lobbies, night markets and events, it opens for business fast, cleans easily and looks as neat as a fixed counter.","altVi":"Xe đẩy khung thép đen, mặt gỗ, có bánh xe và mái che","altEn":"Food cart with black steel frame, timber counter, wheels and a canopy roof","source":"/assets/content/projects/advertising/mobile-retail/mobile-retail-03-mobile-food-carts.webp","sha256":"b379765fb0b73d47b4760b9c14a70ed7644b6e43b064f2427258b72c466d69c4","provenance":"AI-generated illustration; source ID imagegen:2026-09-01:mobile-retail:03; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "mobile-retail-04": {"descriptionVi":"Quầy bán hàng di động thân gỗ in hình sản phẩm, bánh xe có khóa, khung treo hộp đèn tên thương hiệu phía trên và mặt quầy đặt máy pha. Dành cho thương hiệu cà phê, đồ uống làm sampling trong siêu thị, đặt giữa lối đi, giúp khách dừng lại thử, mua ngay và nhớ tên sản phẩm.","descriptionEn":"Mobile counter with a printed timber body, locking wheels, a frame holding a brand lightbox overhead and a top for the brewing kit. For coffee and drink brands sampling in supermarkets, placed mid-aisle, it gets shoppers to stop, taste, buy on the spot and remember the product.","altVi":"Quầy cà phê di động có hộp đèn tiêu đề, đặt giữa lối đi siêu thị","altEn":"Mobile coffee counter with illuminated header box set in a supermarket aisle","source":"/assets/content/projects/advertising/mobile-retail/mobile-retail-04-imagegen-20261018-audit-a125-v1.webp","sha256":"5fef77116cc38e7abe82ae2b9ac8d87b42b27f5fc5c48fea706f08b077653557","provenance":"AI-generated illustration; owner selected A125-v1 in HTML audit and confirmed in chat 2026-10-22; ChatGPT web gpt-image; original SHA256 2d9e65683017216339741970bbedc467d7fa8d8b0abb23821249c6660b029474; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "mobile-retail-05": {"descriptionVi":"Quầy trưng bày di động khung đen có bánh xe khóa, kệ hai bên chất hàng, mặt trước in hình sản phẩm và mặt trên đặt máy tính tiền. Dành cho nhãn hàng đồ uống, thực phẩm làm khuyến mãi, sampling trong siêu thị, giúp đưa sản phẩm ra giữa lối đi, khách thử và mua ngay tại chỗ.","descriptionEn":"Mobile display counter with a black frame on locking wheels, stocked side shelves, a printed product front and a top for a till. For drink and food brands running promotions and sampling in supermarkets, it brings products into the aisle so shoppers can try and buy on the spot.","altVi":"Quầy trưng bày khung đen, bánh xe và bạt in chữ đặt trong siêu thị","altEn":"Black-framed mobile display with wheels and printed canopy inside a supermarket","source":"/assets/content/projects/advertising/mobile-retail/mobile-retail-05-owner-20260924.webp","sha256":"cee6d7de08a35ab9546abb9a2156a5bcd8e9ad25c2d8ba11d17674b778b54e6e","provenance":"AI-generated illustration; owner approved 2026-09-24; original SHA256 c9cafc6aae2e4de29c028f770996b7846c4c75cbae205fc530f64fd5480384b4; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "mobile-retail-06": {"descriptionVi":"Quầy pop-up khung thép đen có bánh xe, mặt trước hộp đèn in tên quán, mái phẳng, bảng menu đứng một bên và mặt quầy đặt máy pha. Dành cho quán cà phê, bánh ngọt mở điểm bán trước cửa hàng, sảnh tòa nhà, sự kiện, giúp khách thấy menu và tên quán rõ cả ban ngày lẫn tối.","descriptionEn":"Pop-up counter with a black steel frame on wheels, a lightbox front with the shop name, a flat canopy, a standing menu board and a top for the coffee machine. For cafes and bakeries selling outside the shop, in building lobbies and at events, it shows the menu and name clearly day and evening.","altVi":"Xe đẩy cà phê bánh ngọt, bảng menu hai bên, bánh xe và mặt gỗ","altEn":"Coffee and pastry cart with menu boards on both sides, wheels and timber top outdoors","source":"/assets/content/projects/advertising/mobile-retail/mobile-retail-06-mobile-pop-up-counters-v2-audit-a127-v3.webp","sha256":"8820b9ae9898e45908da17b4a58cc88b774b28504a0b8b8b3573b290d92c3362","provenance":"AI-generated illustration; ChatGPT web image edit with owner mask (chat 6ae5c766-1ecc-83ec-9240-11f009cc1ac2); upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-27; master PNG SHA256 58a40dbf8526314f72a9a8aaba494607bfc05be7bf195521b2a4396c6c994f8a."},
  "mobile-retail-07": {"descriptionVi":"Xe đẩy trưng bày bằng gỗ, kệ nhiều tầng có đèn, bảng hiệu sáng tên thương hiệu trên khung cao, thân xe in họa tiết lá và bánh xe có khóa. Dành cho thương hiệu mỹ phẩm, đồ thiên nhiên mở điểm bán tạm ở trung tâm thương mại, hội chợ, giúp bày đủ dòng sản phẩm gọn và dễ dời theo luồng khách.","descriptionEn":"Timber display cart with lit multi-tier shelves, a lit brand sign on a raised frame, a body printed with leaf motifs and locking wheels. For natural cosmetics brands opening pop-up points in malls and fairs, it shows the full range neatly and moves easily with shopper traffic.","altVi":"Xe đẩy gỗ có bảng hiệu sáng và kệ bày mỹ phẩm thiên nhiên","altEn":"Wooden display cart with illuminated sign and shelves of natural beauty products","source":"/assets/content/projects/advertising/mobile-retail/mobile-retail-07-imagegen-20261018-audit-a128-v1.webp","sha256":"e4a0f8687695ef80f90dc76a3679f607e4cc0ed203271d9167239b55ea7cf169","provenance":"AI-generated illustration; ChatGPT web image edit (owner chat 6adfd1a2-094c-83ec-9a07-d00ebab66898); upscaled RunningHub SeedVR2 tile to 3072; owner approved 2026-10-27 01:07Z; master PNG SHA256 8c6347bc2a43943032b46a49986be47d86b3ad01f5f92148cf3a297802066470."},
  "mobile-retail-08": {"descriptionVi":"Quầy đồ uống gỗ có bánh xe, mái gỗ in họa tiết, cánh gấp hai bên làm mặt bàn, mặt trước in tranh và khẩu hiệu. Dành cho quán cà phê, trà, đồ uống mở thêm điểm bán trước cửa hoặc ở sự kiện, giúp tận dụng vỉa hè, thu hút khách đi ngang và dọn vào trong dễ dàng.","descriptionEn":"Timber drinks counter on wheels with a printed timber roof, fold-out side flaps as extra tops and a front printed with artwork and a slogan. For cafes, tea and drink shops adding a point outside the door or at events, it makes use of the pavement, catches passers-by and rolls back inside easily.","altVi":"Quầy pha chế gỗ có mái đen họa tiết lá, bình thủy tinh và bánh xe","altEn":"Timber bar with black leaf-pattern roof, glass jars and wheels","source":"/assets/content/projects/advertising/mobile-retail/mobile-retail-08-folding-retail-counters-v2-audit-a129-v3.webp","sha256":"0878432fe93525f90a58073337d64b8643860319d92b6dc8dec2cb656c04b48c","provenance":"AI-generated illustration; owner approved A129-v3 in chat 2026-10-22; ChatGPT web; model unknown; original SHA256 29e2b444757fc573afc01704541fbbd50c350803cbdbbb81694b97c2c4bdf696; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "mobile-retail-09": {"descriptionVi":"Quầy bán hàng di động khung thép, thân composite trắng ốp gỗ, tủ kính cong trưng bày, mái tôn che và bánh xe có khóa. Dành cho quán kem, bánh ngọt, đồ ăn vặt bán ngoài trời ở công viên, sân trường, khu du lịch, giúp giữ hàng sạch, đẹp mắt và che mưa nắng cho người bán.","descriptionEn":"Mobile counter with a steel frame, white composite body with timber panels, a curved glass display case, a metal roof and locking wheels. For ice cream, pastry and snack sellers outdoors in parks, schools and resorts, it keeps food clean and attractive and shelters the seller from sun and rain.","altVi":"Quầy bán hàng di động có mái tôn, tủ kính cong và bánh xe ngoài trời","altEn":"Mobile retail counter with corrugated roof, curved glass case and wheels outdoors","source":"/assets/content/projects/advertising/mobile-retail/mobile-retail-09-outdoor-retail-counters-audit-a130-v1.webp","sha256":"fd9d6712966f712bf29e577a12adb55eb4b7528887026c009b27b848e4335209","provenance":"AI-generated illustration; owner selected A130-v1 in HTML audit and confirmed in chat 2026-10-22; ChatGPT web gpt-image; original SHA256 c828fcd8deb72ec28ad650e776d7a533942d0ee1484a3e1f82dc4d7a86e7b3ab; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "mobile-retail-10": {"descriptionVi":"Quầy pha chế di động khung thép sơn đen có bánh xe, mặt quầy inox, cửa tủ lam, kệ gỗ trên cao, chỗ đặt máy xay và tủ mát. Dành cho quán đồ uống, nhà hàng có khu ngoài trời, sự kiện, giúp mở thêm điểm pha chế nhanh, đủ chỗ cho dụng cụ và dễ dọn sau giờ bán.","descriptionEn":"Mobile drinks bar with a black-painted steel frame on wheels, a stainless top, louvred cabinet doors, overhead timber shelves and space for blenders and a fridge. For drink shops, restaurants with outdoor areas and events, it adds a bar fast, holds all the tools and clears away easily after service.","altVi":"Quầy pha chế khung thép đen có bồn rửa, tủ lạnh inox, bảng đồ uống","altEn":"Black steel mobile bar with sink, stainless fridge and a board listing mixed drinks","source":"/assets/content/projects/advertising/mobile-retail/mobile-retail-10-mobile-beverage-counters-v2-audit-a131-v2.webp","sha256":"1724fbfc72a063b7e5872686e93da20c04441d335f8c577d09ff47488265d034","provenance":"AI-generated illustration; ChatGPT web image edit with owner mask (chat 6ae5c784-5d64-83ec-b366-e809693038cb); upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-27; master PNG SHA256 5c761343fa2e808c2b711285781ee84a21ef9f118dd677989e39456e526e91bf."},
  "mobile-retail-11": {"descriptionVi":"Xe bán hàng thân gỗ, dải lam cong có LED hắt sáng, tủ kính bày bánh, mái bạt có đèn và bánh xe lớn. Dành cho tiệm bánh, quán cà phê mở điểm bán ở phố đi bộ, sân vườn, sự kiện, giúp bánh nổi bật, quầy có cá tính riêng và dễ dời đến nơi đông khách.","descriptionEn":"Timber cart with a curved slatted band lit by LED, a glass pastry case, a lit canvas canopy and large wheels. For bakeries and cafes selling on walking streets, gardens and events, it makes pastries stand out, gives the stall its own character and moves easily to busy spots.","altVi":"Xe bán hàng gỗ có mái bạt, tủ kính bánh ngọt và dải LED hắt sóng","altEn":"Timber sales cart with canvas awning, pastry glass case and wave LED light strip","source":"/assets/content/projects/advertising/mobile-retail/mobile-retail-11-imagegen-20261018-audit-a132-v2.webp","sha256":"9e9fbadc60d453baa51b85c48a9e7bdee387d8249310ac0a99d03cdb1c2e4417","provenance":"AI-generated illustration; owner selected A132-v2 in HTML audit and confirmed in chat 2026-10-22; ChatGPT web gpt-image; original SHA256 556b96b7bbb67c6ab603c5f47a25ada90d1823358d7c644c14b2fa350c79940c; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "mobile-retail-12": {"descriptionVi":"Xe bán hàng khung sắt sơn đen, thân ốp gỗ veneer, mái phẳng có đèn rọi, kệ mở phía trên, tủ cửa dưới chứa hàng và bánh xe có khóa. Dành cho thương hiệu đồ uống, đặc sản, phụ kiện mở điểm bán ở sảnh tòa nhà, khu ăn uống, giúp bày hàng gọn, cất hàng dự trữ và nhìn chỉn chu.","descriptionEn":"Retail cart with a black-painted steel frame, timber veneer body, a flat canopy with spotlights, open upper shelves, a lower storage cabinet and locking wheels. For drink, specialty food and accessory brands selling in building lobbies and food courts, it displays neatly, stores spare stock and looks well finished.","altVi":"Xe bán hàng gỗ veneer có mái, kệ mở, tủ dưới và bánh xe","altEn":"Veneer timber retail cart with roof, open shelves, lower cabinet and wheels","source":"/assets/content/projects/advertising/mobile-retail/mobile-retail-12-custom-mobile-retail-carts.webp","sha256":"82805d295c0a7650c22ea118cf3918a0b8aa385d5426caa08a161dd655818c9f","provenance":"AI-generated illustration; source ID imagegen:2026-09-01:mobile-retail:12; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "mobile-retail-13": {"descriptionVi":"Xe bán hàng thân gỗ in tranh phong cảnh, mái bạt cong, tủ kính bày bánh, đèn treo, cánh tủ mở chứa hàng và bánh xe lớn. Dành cho tiệm bánh, quán cà phê nhỏ bán ở vỉa hè, chợ phiên, sân vườn, giúp bánh luôn sạch, đẹp mắt và quầy có nét riêng dễ nhớ.","descriptionEn":"Timber cart with a printed landscape panel, a curved canvas roof, a glass pastry case, hanging lamps, storage doors and large wheels. For bakeries and small cafes selling on pavements, weekend markets and gardens, it keeps pastries clean and attractive and gives the stall a memorable look.","altVi":"Xe bán hàng gỗ có mái bạt, tủ kính bánh ngọt và đèn treo","altEn":"Timber sales cart with canvas awning, cake display case and hanging lamp","source":"/assets/content/projects/advertising/mobile-retail/mobile-retail-13-mobile-retail-carts-v2-audit-a134-v1.webp","sha256":"2ebb45daa052c3a6212bc210c27b83167d61bb597e3f66bea32eb16dee066ce7","provenance":"AI-generated illustration; owner selected A134-v1 in HTML audit and confirmed in chat 2026-10-22; ChatGPT web gpt-image; original SHA256 bee632893acb226a8fc6f08bdc3797190d161ebaa977c87479cd9b6c51e01f7b; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "mobile-retail-14": {"descriptionVi":"Xe cà phê pha máy khung thép, thân in hình sản phẩm, mặt quầy đặt máy pha và máy xay, hộp đèn tên thương hiệu trên khung cao, bánh xe có khóa. Dành cho khách sạn, trung tâm hội nghị, đơn vị tổ chức tiệc trà, giúp phục vụ cà phê pha tại chỗ cho khách mời và trông chỉn chu, chuyên nghiệp.","descriptionEn":"Espresso coffee cart with a steel frame, a printed product body, a top for the espresso machine and grinder, a brand lightbox on a raised frame and locking wheels. For hotels, conference centres and tea-break caterers, it serves freshly made coffee to guests on site and looks neat and professional.","altVi":"Quầy pha cà phê di động có hộp đèn tiêu đề, đặt trong sảnh tiệc","altEn":"Mobile coffee bar with lit header box set up in a banquet hall with guests","source":"/assets/content/projects/advertising/mobile-retail/mobile-retail-14-imagegen-20261018.webp","sha256":"d1a8ebe1944c36f661d75ef33ee705bf08536964e72f0f52de9a2159dd7ed403","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:mobile-retail-14-1; original SHA256 f9d931a0855f22da97d955d8a6d697f34ace6cebbeab7c31242cd5a135b6e980; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "mobile-retail-15": {"descriptionVi":"Xe bánh mì khung thép đen, thân gỗ, mặt quầy inox, tủ kính bày bánh, mái che có đèn, mặt trước in hình sản phẩm và bánh xe có khóa. Dành cho người bán bánh mì, đồ ăn sáng trên vỉa hè hay trước cửa hàng, giúp bán nhanh, dễ vệ sinh và khách nhận ra món từ xa.","descriptionEn":"Banh mi cart with a black steel frame, timber body, stainless counter, glass bread case, lit canopy, printed product front and locking wheels. For banh mi and breakfast sellers on pavements or outside shops, it speeds up service, cleans easily and shows the dish from afar.","altVi":"Xe bán hàng gỗ có decal bánh mì, mái che và bánh xe lớn","altEn":"Timber sales cart with bread decals, a canopy and large wheels","source":"/assets/content/projects/advertising/mobile-retail/mobile-retail-15-imagegen-20261018-audit-a136-v3.webp","sha256":"69f5eaf4a0b32f466071a96d3dc67b004070199f6575a6e763a2000f6b898f71","provenance":"AI-generated illustration; ChatGPT web image edit (owner chat 6adfd151-60a4-83ec-99a6-b6764d902042); upscaled RunningHub SeedVR2 tile to 3072; owner approved 2026-10-27 01:07Z; master PNG SHA256 51274db5cbe78ddd0565a9eabb1e760676359bd13305172af14cc5b7c7974fa8."},
  "mobile-retail-16": {"descriptionVi":"Xe bán nước dừa khung sắt sơn xanh, mái bạt có bảng tên, bình đựng nước, kệ ly và thân xe dán decal in hình sản phẩm. Dành cho thương hiệu nước dừa, đồ uống giải khát bán và sampling ở công viên, đường chạy bộ, sự kiện thể thao, giúp phục vụ nhanh, dễ di chuyển và nhận ra từ xa.","descriptionEn":"Green-painted steel coconut water cart with a canvas canopy and name board, drink dispensers, a cup shelf and a body wrapped in printed product decals. For coconut water and soft drink brands selling and sampling in parks, running routes and sports events, it serves fast, moves easily and is visible from afar.","altVi":"Xe bán nước dừa sơn xanh có bạt, bình đựng và decal in trên thân xe","altEn":"Green-painted coconut water cart with canopy, containers and printed decals on body","source":"/assets/content/projects/advertising/mobile-retail/mobile-retail-16-imagegen-20261018.webp","sha256":"dfab784205a06f119a037ccd779605780d3c2bd289ef00e1217a798405e25cc8","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:mobile-retail-16-1; original SHA256 df962a673c83ba799aae570c1ca1cb1d7d789578b4c760c854cc9bd2d7b4b22f; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "signage-raised-letters-01": {"descriptionVi":"Mặt dựng ốp tấm alu trắng xám, chữ nổi và logo khối hắt đèn LED phía sau, kèm lam gỗ đứng, gắn lên khung mặt tiền tầng trệt. Phù hợp showroom nội thất, cửa hàng mặt phố cần nhận diện thương hiệu rõ cả ngày lẫn đêm, mặt tiền gọn và che được phần kết cấu.","descriptionEn":"Grey-white aluminium composite facade with backlit raised letters and a block logo, plus vertical timber louvres, fixed to the ground-floor frontage. Suits furniture showrooms and street-front shops that need a brand seen day and night, with a tidy frontage that hides the structure.","altVi":"Mặt dựng ốp alu với chữ nổi NỘI THẤT hắt đèn, cạnh cửa kính showroom","altEn":"Aluminium composite facade with backlit raised letters reading NỘI THẤT beside a glass door","source":"/assets/content/projects/advertising/signage-raised-letters/signage-raised-letters-01-aluminium-composite-facades-v2-audit-a237-v1.webp","sha256":"cdff362461893800d6a8cb6e6af6ff38359337554c6c48243d24aa2405163e6f","provenance":"AI-generated illustration; owner selected A237-v1 in HTML audit and confirmed in chat 2026-10-22; ChatGPT web gpt-image; original SHA256 8d2ab62e1e3100e5d9e1f94b8ce98339dcc7a8bc56620daaea75546dc63bf66d; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "signage-raised-letters-02": {"descriptionVi":"Pano quảng cáo khổ lớn mặt bạt in phối cảnh, khung thép hộp dựng trên hai trụ chôn móng bê tông. Dành cho chủ đầu tư, nhà thầu đặt ngay trước công trình đang xây hoặc ven đường lớn, giúp giới thiệu dự án, thông tin liên hệ cho người qua lại suốt thời gian thi công.","descriptionEn":"Large advertising panel with a printed banner face showing the project render, on a box-steel frame raised on two posts with concrete footings. For developers and contractors in front of a building site or by a main road, it presents the project and contact details to passers-by throughout construction.","altVi":"Pano quảng cáo trên chân thép bên đường, cạnh công trình đang thi công","altEn":"Advertising panel on steel legs by the roadside next to a building under construction","source":"/assets/content/projects/advertising/signage-raised-letters/signage-raised-letters-02-v3.webp","sha256":"5b2dccfa441228ecf45d8ecdb1dd3a1b7cae3eb86b6cad5f77e99136254e71fc","provenance":"AI-generated illustration; source ID imagegen:2026-10-14:signage-raised-letters-02-a; original SHA256 17a4b5e0a983bb2008b5682faf418a1983f180b7a0e9a2da2a30a55e4697fa2b; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "signage-raised-letters-03": {"descriptionVi":"Pano quảng cáo tấm lớn mặt bạt in hình, khung thép hộp dựng trên một trụ thép cao, kèm dãy đèn pha chiếu sáng mặt pano. Dành cho trung tâm tiệc cưới, nhà hàng, khu du lịch, đặt ven quốc lộ, cửa ngõ thành phố, giúp xe chạy qua thấy thương hiệu từ xa cả ngày lẫn đêm.","descriptionEn":"Large printed banner billboard on a box-steel frame atop a single tall steel column, with floodlights along the top. For wedding venues, restaurants and resorts, placed by highways and city gateways, it shows the brand to passing traffic from far away, day and night.","altVi":"Pano sảnh tiệc đặt trên trụ thép cạnh đường ven sông lúc hoàng hôn","altEn":"Sunset view of a banquet hall panel on a steel pole beside a riverside road","source":"/assets/content/projects/advertising/signage-raised-letters/signage-raised-letters-03-large-format-outdoor-signs-v2.webp","sha256":"3dc4e5bfe8cf6bfa48e260caa32379731a99d023b308c95c2974b2d375a172c2","provenance":"AI-generated illustration; source ID imagegen:2026-10-14:signage-raised-letters-03-a; original SHA256 84f36e487bcb3c3c7e7baba0d6d92c9ef92667c8ad45d0754c78e197d6994919; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "signage-raised-letters-04": {"descriptionVi":"Hộp đèn bạt hiflex sáng mặt, khung sắt hộp, in hình và chữ nền xanh nổi bật, gắn kín ngang mặt tiền phía trên cửa. Dành cho cửa hàng đặc sản, tạp hóa, quán ăn mặt phố cần bảng hiệu lớn, chi phí vừa phải, giúp khách nhận ra cửa hàng từ xa và nổi bật khi trời tối.","descriptionEn":"Front-lit hiflex fabric lightbox on a box-steel frame with bold printed graphics on green, spanning the frontage above the door. For specialty shops, grocers and street eateries that need a big sign at moderate cost, it lets customers spot the shop from afar and stands out after dark.","altVi":"Hộp đèn bạt xanh sáng mặt ghi KẸO DỪA trên mặt tiền cửa hàng","altEn":"Green lit fabric sign reading KẸO DỪA on the facade of a shop","source":"/assets/content/projects/advertising/signage-raised-letters/signage-raised-letters-04-hiflex-fabric-light-boxes-v2.webp","sha256":"f8bad29dd2e74739f37deacc63ced44b318aa67ec9be6c02a833c9e2f05d19c8","provenance":"AI-generated illustration; source ID imagegen:2026-10-15:signage-raised-letters-04-a; original SHA256 10f46d4e8c6355bfa6d6ce088171c4e0e1071829b9181226c465ce5322f8e3a0; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "signage-raised-letters-05": {"descriptionVi":"Bảng hiệu mặt dựng ốp alu xanh navy, logo và chữ nổi trắng có đèn LED, chạy ngang mặt tiền kính tầng trệt. Dành cho ngân hàng, văn phòng giao dịch, chuỗi cửa hàng cần nhận diện thống nhất, giúp khách nhận ra chi nhánh từ đường lớn và mặt tiền trông chắc chắn, đáng tin.","descriptionEn":"Navy aluminium composite fascia sign with white raised letters and logo lit by LED, running across the ground-floor glass frontage. For banks, service branches and chain stores that need a uniform identity, it lets customers spot the branch from the main road and makes the frontage look solid and trustworthy.","altVi":"Bảng hiệu mặt dựng nền xanh navy, chữ trắng trên mặt tiền kính","altEn":"Navy blue facade panel with white bank lettering on a glass frontage","source":"/assets/content/projects/advertising/signage-raised-letters/signage-raised-letters-05-premium-3m-fabric-light-boxes-v2.webp","sha256":"0bbf8e1210de3a3f392a2b4d73a7c0984e401ea5975d9592569a73e60e212a8e","provenance":"AI-generated illustration; ChatGPT web image edit (owner chat 6adfd42a-52c4-83ec-a624-fd7c453f0fef); upscaled RunningHub SeedVR2 tile to 3072; owner approved 2026-10-27 01:07Z; master PNG SHA256 65c8890e2455cda516b62b47795a725c61369eb571658cd06823ce0049a68fb9."},
  "signage-raised-letters-06": {"descriptionVi":"Chữ nổi inox sáng chân, LED hắt quầng phía sau, gắn trên khối tường đá travertine đặt giữa thảm cỏ trước sảnh. Dành cho tòa văn phòng, khách sạn, resort, khu biệt thự, giúp khách nhận ra lối vào hoặc tên công trình từ xa và tạo cảnh quan sang trọng cả ban ngày lẫn tối.","descriptionEn":"Stainless raised letters with halo LED lighting behind, mounted on a travertine stone block set in the lawn before the lobby. For office buildings, hotels, resorts and villa estates, it shows guests the entrance or building name from afar and adds an upscale landscape feature day and night.","altVi":"Chữ nổi hắt sáng trên bệ đá travertine, có cây xanh và đèn cảnh quan","altEn":"Backlit raised letters on a travertine plinth with plants and landscape lights","source":"/assets/content/projects/advertising/signage-raised-letters/signage-raised-letters-06-v2.webp","sha256":"85084e4624b8bb8636a8c2e91243ceff72cdef4b500c1c35855fea8d6fa5fedd","provenance":"AI-generated illustration; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-31; master PNG SHA256 2ff5e9a436ba01c222df4bef98d1ee834b93ef33dc2bb8b72dbf588f247f7fca."},
  "signage-raised-letters-07": {"descriptionVi":"Bảng hiệu nền alu nâu chạy ngang mặt tiền, chữ nổi mica trắng tên tiệm và khẩu hiệu, gắn trên khung thép phía trên cửa kính. Dành cho tiệm bánh, quán cà phê, cửa hàng mặt phố, giúp tên tiệm nổi rõ, sạch sẽ, dễ đọc từ bên kia đường và hợp với mặt tiền nhỏ.","descriptionEn":"Brown aluminium fascia across the frontage with white acrylic raised letters for the shop name and tagline, mounted on a steel frame above the glass door. For bakeries, cafes and street-front shops, it makes the name stand out clean and readable from across the street and suits a narrow frontage.","altVi":"Chữ nổi trắng ghi TIỆM BÁNH trên bảng nâu, cạnh cửa kính mặt tiền","altEn":"White raised letters reading BAKERY on brown panel beside a glass door","source":"/assets/content/projects/advertising/signage-raised-letters/signage-raised-letters-07-acrylic-dimensional-letters-v2.webp","sha256":"f91e84e07022163d53d4f34c4965d7c0e3c27bbca8f273438482016f6ae198b2","provenance":"AI-generated illustration; source ID imagegen:2026-10-14:signage-raised-letters-07-a; original SHA256 eb2047c65355bfc6851a8638723ddc4e98e6b43bd6ed8256370a336003aae5a8; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "signage-raised-letters-08": {"descriptionVi":"Chữ nổi khối alu sơn trắng tên công ty và khẩu hiệu, gắn chân nổi cách tường lên vách sơn xám sảnh văn phòng. Dành cho công ty kiến trúc, thiết kế, văn phòng dịch vụ, đặt sau quầy lễ tân hoặc vách sảnh, giúp khách nhận ra công ty ngay khi bước vào và tạo ấn tượng chuyên nghiệp.","descriptionEn":"White-painted aluminium block letters for the company name and tagline, stood off from a grey lobby wall. For architecture, design and service firms, placed behind reception or on a lobby wall, they let visitors recognise the company as they walk in and create a professional impression.","altVi":"Chữ nổi 3D trắng gắn tường sảnh văn phòng cạnh bàn đựng bản vẽ","altEn":"White 3D dimensional letters on office lobby wall beside a table of drawings","source":"/assets/content/projects/advertising/signage-raised-letters/signage-raised-letters-08-aluminium-and-foam-dimensional-letters-v2.webp","sha256":"7be9361707f591ead8c6d40067766d66271a27f4260304c39e4924c0022cb551","provenance":"AI-generated illustration; source ID imagegen:2026-10-14:signage-raised-letters-08-a; original SHA256 5e82aeb3b09221cd07696ac986668959b4cc432d293a787d06a0e57801b78507; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "signage-raised-letters-09": {"descriptionVi":"Chữ nổi dựng đứng khung hộp, mặt mica trắng có đèn LED, nền xanh, gắn dọc góc tòa nhà, kèm biển tên nhỏ phía dưới. Dành cho siêu thị, trung tâm mua sắm, khách sạn nhiều tầng, giúp khách thấy thương hiệu từ xa ở cả hai hướng đường và nổi bật vào buổi tối.","descriptionEn":"Vertical blade of box letters with white LED-lit acrylic faces on blue, mounted down the corner of the building, with a small name sign below. For supermarkets, shopping centres and multi-storey hotels, it shows the brand from far off in both directions of the street and stands out at night.","altVi":"Chữ nổi LED dựng đứng trên mặt tiền tòa nhà, kèm biển xanh tên siêu thị","altEn":"Vertical dimensional LED letters on building facade with a blue supermarket name panel","source":"/assets/content/projects/advertising/signage-raised-letters/signage-raised-letters-09-building-logos-and-dimensional-lettering-v2.webp","sha256":"02f9305f51f3cfe4966a5781d29eb6ab35c3f53c6c982326155fa4d784d3b26e","provenance":"AI-generated illustration; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-31; master PNG SHA256 348c5b2d4aa78b1a47451aad2c5c04b387a59bbb2154653a52e24f42ce308f8b."},
  "signage-raised-letters-10": {"descriptionVi":"Bảng vẫy tròn hộp đèn hai mặt, mặt mica hút nổi in logo, viền nhôm sơn đen, treo bằng hai ty thép dưới mái hiên. Dành cho tiệm cà phê, trà bánh, cửa hàng nhỏ, giúp khách đi ngang thấy tên quán từ cả hai hướng, đèn sáng đều buổi tối và logo nổi khối rõ nét.","descriptionEn":"Double-sided round lightbox with vacuum-formed acrylic faces printed with the logo and a black aluminium rim, hung from two steel rods under the eaves. For cafes, tea and cake shops and small stores, it shows the name to passers-by from both directions, glows evenly at night and gives the logo crisp relief.","altVi":"Hộp đèn tròn treo trần có mặt mica in logo cà phê và chữ trà bánh","altEn":"Round ceiling-hung light box with clear face printed with coffee logo and tea and cake text","source":"/assets/content/projects/advertising/signage-raised-letters/signage-raised-letters-10-vacuum-formed-acrylic-projecting-signs-audit-a246-v1.webp","sha256":"3828ce0ac5984defb38456ba76499ae06a25ac61c405287788d821a3cc4bcc03","provenance":"AI-generated illustration; owner selected A246-v1 in HTML audit and confirmed in chat 2026-10-22; ChatGPT web gpt-image; original SHA256 178d39f494efcc0bc8979a195206d4e2500b6249933840fa83536443d1cc7670; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "signage-raised-letters-11": {"descriptionVi":"Bảng vẫy tròn khung thép sơn đen, mặt gắn bóng LED chấm tạo hình tách cà phê, treo trên tay đỡ vuông góc tường mặt tiền. Dành cho quán cà phê, tiệm bánh trên phố đi bộ hay hẻm nhỏ, giúp khách từ hai đầu vỉa hè nhận ra quán, nhất là khi trời tối, và tạo nét hoài cổ riêng.","descriptionEn":"Round projecting sign with a black steel frame and a face of LED bulb dots forming a coffee cup, hung on a bracket at right angles to the frontage. For cafes and bakeries on walking streets or alleys, it lets people from both ends of the pavement spot the shop, especially at night, with a vintage touch.","altVi":"Bảng vẫy tròn có LED chấm hình tách cà phê và khói bốc lên","altEn":"Round projecting sign with pixel LEDs forming a coffee cup and rising steam","source":"/assets/content/projects/advertising/signage-raised-letters/signage-raised-letters-11-animated-led-projecting-signs-audit-a247-v3.webp","sha256":"161982bb4ea13083e0c3452f09d63636fc7f472da4fc182e046b010eadb9cf62","provenance":"AI-generated illustration; owner approved A247-v3 in chat 2026-10-22; ChatGPT web; model unknown; original SHA256 f5917ebae759c6a32bd96dbe074bf1d3b92077d4c20cfd6baa7b9f19a55cb1ee; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "signage-raised-letters-12": {"descriptionVi":"Bảng vẫy hộp đèn tròn khung inox xước, mặt mica in logo và tên quán, gắn tay đỡ inox vuông góc với tường mặt tiền. Dành cho quán cà phê rang xay, tiệm trà, cửa hàng mặt phố, giúp khách đi bộ nhận ra quán từ hai hướng, bền ngoài trời và sáng đều về đêm.","descriptionEn":"Round lightbox with a brushed stainless frame and an acrylic face printed with logo and name, on a stainless bracket at right angles to the frontage. For roasters, tea shops and street-front stores, it lets walkers spot the shop from both directions, lasts outdoors and glows evenly at night.","altVi":"Bảng vẫy tròn khung inox, mặt mica in logo cà phê rang xay","altEn":"Round projecting sign with stainless frame and printed roasted coffee logo","source":"/assets/content/projects/advertising/signage-raised-letters/signage-raised-letters-12-stainless-steel-and-hiflex-projecting-signs-audit-a248-v1.webp","sha256":"c25698b77c47c0197b93071119cb2c25ed6d4061a2fc5250aab224c758894fb4","provenance":"AI-generated illustration; owner selected A248-v1 in HTML audit and confirmed in chat 2026-10-22; ChatGPT web gpt-image; original SHA256 468af112f29132832642725ec5a705ac17ae74b4c4039c913df3697caa5c7bd4; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "signage-raised-letters-13": {"descriptionVi":"Bảng hiệu ốp alu màu xanh bo theo góc mái sảnh, chữ nổi mặt mica trắng, chạy hai mặt tòa nhà. Dành cho bệnh viện, phòng khám, trường học, tòa văn phòng, giúp tên công trình đọc rõ từ cả hai hướng đường, trông sạch, hiện đại và đáng tin cậy.","descriptionEn":"Teal aluminium composite fascia wrapped around the corner of the entrance canopy, with white acrylic raised letters, across two sides of the building. For hospitals, clinics, schools and office buildings, it makes the name readable from both directions of the street and looks clean, modern and trustworthy.","altVi":"Biển chữ nổi trắng trên nền alu xanh teal, phía trên lối vào bệnh viện","altEn":"White raised lettering on teal aluminium panel above a hospital entrance","source":"/assets/content/projects/advertising/signage-raised-letters/signage-raised-letters-13-imagegen-20261018.webp","sha256":"a640762c830c31fc0d1bfc220c7e49cecd674af670f39d1fc1e7de62e6acebc0","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:signage-raised-letters-13-a-2; original SHA256 6195ce110e7671424f05a218cc9a16ceded15a46b0f81063ab749b0615e570ea; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "signage-raised-letters-14": {"descriptionVi":"Pano quảng cáo mặt tôn sơn đỏ, chữ và hình dán decal, khung thép hộp dựng trên hai trụ thép chân móng bê tông. Dành cho cửa hàng vật liệu xây dựng, đại lý, cơ sở ven quốc lộ, đường liên xã, giúp chỉ đường và giới thiệu mặt hàng cho người đi xa, bền nắng mưa và chi phí hợp lý.","descriptionEn":"Advertising panel with a red-painted steel sheet face with decal text and graphics, on a box-steel frame raised on two steel posts with concrete footings. For building materials stores, dealers and businesses on highways and rural roads, it gives directions and shows products to travellers, withstands weather and is reasonably priced.","altVi":"Pano tôn sơn đỏ trên trụ thép quảng cáo xi măng, gạch, sắt thép","altEn":"Red painted metal panel on steel post advertising cement, bricks and steel","source":"/assets/content/projects/advertising/signage-raised-letters/signage-raised-letters-14-large-outdoor-advertising-panels-v2.webp","sha256":"84d6e10c76a9849b126c90e20450930fe97d647f81fdc3e6c025b95567995652","provenance":"AI-generated illustration; source ID imagegen:2026-10-14:signage-raised-letters-14-a; original SHA256 2d29013d490f38abf7bee2603fe49819b52a20cbf1d0c280c9bbe9087d157d12; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "signage-raised-letters-15": {"descriptionVi":"Pano quảng cáo tấm lớn mặt bạt in, khung thép giằng dựng trên một trụ thép cao, sàn thao tác và dãy đèn pha phía trên. Dành cho khu du lịch, chủ đầu tư, nhãn hàng thuê vị trí ở vòng xoay, cửa ngõ thành phố, giúp hình ảnh được thấy từ xa cả ngày lẫn đêm và thay nội dung theo mùa.","descriptionEn":"Large printed banner billboard on a braced steel frame atop a tall single column, with a service walkway and floodlights. For resorts, developers and brands renting sites at roundabouts and city gateways, it is seen from far away day and night and changes content by season.","altVi":"Pano quảng cáo làng du lịch trên trụ thép, có đèn rọi phía trên","altEn":"Outdoor billboard for tourism village on steel pole with spotlight above","source":"/assets/content/projects/advertising/signage-raised-letters/signage-raised-letters-15-large-format-outdoor-signs-v2.webp","sha256":"4067ad8fa184512cbb4e7ac2e1fbf1ea0cebb17ff386feed1f807885b7917da5","provenance":"AI-generated illustration; source ID imagegen:2026-10-14:signage-raised-letters-15-a; original SHA256 6978bc6bb1dc4343da9feadec38902cb1f1257845325d2361fa2c38a55ee470c; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "signage-raised-letters-16": {"descriptionVi":"Hộp đèn vẫy cỡ nhỏ, mặt mica in hình sản phẩm sáng đều, khung nhôm mỏng có LED hắt sáng ra các mép nên cả viền hộp cũng phát sáng, treo trên tay đỡ vuông góc tường. Dành cho quán cà phê, tiệm trà, shop trong nhà hoặc dưới mái hiên, giúp góc quán có điểm nhấn trang trí, nổi bật về đêm và khách đi hai chiều đều thấy.","descriptionEn":"Small projecting lightbox with an evenly lit printed acrylic face and a slim aluminium frame whose LEDs also spill light around the edges, so the whole outline glows, hung on a bracket at right angles to the wall. For cafes, tea shops and stores indoors or under an awning, it adds a decorative accent, stands out at night and is seen from both directions.","altVi":"Hộp đèn vẫy nhỏ hắt sáng viền, in ly cà phê đá và chữ Đậm vị","altEn":"Small edge-glowing projecting lightbox printed with an iced coffee glass and bold coffee lettering","source":"/assets/content/projects/advertising/signage-raised-letters/signage-raised-letters-16-hiflex-fabric-light-boxes-v2-audit-a252-v1.webp","sha256":"b2631725ee9ebe59169c3a9ef379642efc41aee6db7c7b1a2a50f8bbb6a60dcf","provenance":"AI-generated illustration; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-31; master PNG SHA256 294670a02916f30a3f93af22040ed34ac2790b28bd51e1cbb1a96e8ac3c2d9dd."},
  "signage-raised-letters-17": {"descriptionVi":"Hộp đèn vẫy mặt mica xanh in logo và tên, khung nhôm sơn đen, gắn trên thanh vươn từ tường mặt tiền, LED bên trong sáng đều. Dành cho văn phòng bảo hiểm, phòng khám, đại lý dịch vụ trên phố, giúp khách đi hai chiều nhận ra văn phòng, nhất là khi trời tối.","descriptionEn":"Projecting lightbox with a blue acrylic face printed with logo and name in a black aluminium frame, on an arm from the frontage wall, evenly lit by LED inside. For insurance offices, clinics and service agencies on the street, it lets people walking either way recognise the office, especially after dark.","altVi":"Hộp đèn mica xanh có logo công ty bảo hiểm, gắn trên thanh vươn từ tường","altEn":"Blue acrylic light box with insurance logo on bracket projecting from wall","source":"/assets/content/projects/advertising/signage-raised-letters/signage-raised-letters-17-imagegen-20261018.webp","sha256":"a46fefa6800df9dec29a632766318e5324126ace1e22dadff173ded496d70219","provenance":"AI-generated illustration; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-31; master PNG SHA256 8cf580898da3ccacbaa103568720975458dbf791c41e65624a0c82090716231c."},
  "signage-raised-letters-18": {"descriptionVi":"Chữ nổi và logo inox mạ vàng xước, đèn LED hắt sáng phía sau tạo quầng trên tường, gắn chân nổi lên mảng tường đá. Dành cho phòng khám, spa, thẩm mỹ viện, văn phòng cao cấp, đặt ở mặt tiền hoặc sảnh, giúp thương hiệu trông sạch, sang, đáng tin và nổi bật khi tối.","descriptionEn":"Brushed gold-tone stainless raised letters and logo with LED halo lighting behind them, stood off a stone wall. For clinics, spas, beauty salons and premium offices, on the frontage or in the lobby, it makes the brand look clean, upscale and trustworthy and stand out after dark.","altVi":"Chữ nổi inox vàng có đèn LED hắt sáng phía sau trên tường đá","altEn":"Gold stainless steel letters with LED backlighting on a stone wall","source":"/assets/content/projects/advertising/signage-raised-letters/signage-raised-letters-18-halo-lit-stainless-steel-letters-audit-a254-v1.webp","sha256":"256941ef1bea0489903fe5cce231bf535903a653761fc2ae6fc95244cffaffdc","provenance":"AI-generated illustration; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-31; master PNG SHA256 94ee9310681077b7e53a7691dd88f76405c92e0076713408c5c616d352641eda."},
  "signage-raised-letters-19": {"descriptionVi":"Chữ nổi mica xanh lá có đèn LED, gắn trực tiếp lên tường phía trên kệ sản phẩm, gồm tên cửa hàng và khẩu hiệu. Dành cho cửa hàng mỹ phẩm, đặc sản, tiệm nhỏ trong nhà, giúp tạo điểm nhìn thương hiệu rõ ràng ngay khi khách bước vào và làm không gian bán hàng sáng, gọn.","descriptionEn":"Green acrylic raised letters with LED lighting, fixed straight to the wall above the product shelves, spelling the shop name and tagline. For cosmetics, specialty food and small indoor shops, they give a clear brand focus as customers enter and make the sales space bright and tidy.","altVi":"Chữ nổi mica xanh lá gắn tường phía trên kệ sản phẩm","altEn":"Green acrylic dimensional letters on wall above product shelves","source":"/assets/content/projects/advertising/signage-raised-letters/signage-raised-letters-19-acrylic-dimensional-letters-v2.webp","sha256":"77988ac9dc9d94d4a984fbeb5db5c5bd987bdd66126c725ea88339cc2dfdeec3","provenance":"AI-generated illustration; source ID imagegen:2026-10-15:signage-raised-letters-19-a; original SHA256 c176243d35d66609367fbda56a1c2d3ff9cdeb1b89cfe01701bded7ca82cda5c; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "signage-raised-letters-20": {"descriptionVi":"Chữ nổi và logo mica màu có đèn LED, gắn trên mặt dựng ốp alu trắng chạy ngang mặt tiền phía trên mái hiên. Dành cho nhà sách, cửa hàng mặt phố, chuỗi bán lẻ, giúp tên cửa hàng nổi bật, dễ đọc từ đầu phố và mặt tiền gọn, sáng cả ngày lẫn đêm.","descriptionEn":"Coloured acrylic raised letters and logo with LED lighting on a white aluminium composite fascia across the frontage above the awning. For bookshops, street-front stores and retail chains, it makes the name stand out and read easily from down the street, with a clean, bright frontage day and night.","altVi":"Chữ nổi đỏ ghi tên nhà sách và logo sách xanh trên mặt dựng alu trắng","altEn":"Red raised letters and blue book logo on white aluminium facade","source":"/assets/content/projects/advertising/signage-raised-letters/signage-raised-letters-20-imagegen-20261018.webp","sha256":"bae6c9d42abac4112833421166c5b97619fd12d74f5fc2d9ac7f8bb2b78efe5b","provenance":"AI-generated illustration; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-31; master PNG SHA256 63edc03eed79381457f664829ca4740e66b1b957476c329663fc79d4110bf41a."},
  "signage-raised-letters-21": {"descriptionVi":"Logo và chữ nổi khổ lớn mặt mica xanh viền trắng, dựng trên khung thép giằng trên mái nhà xưởng. Dành cho nhà máy, công ty chế biến, kho vận, giúp nhận diện doanh nghiệp từ đường lớn và khu công nghiệp, tạo hình ảnh quy mô, uy tín với khách hàng và đối tác.","descriptionEn":"Large logo and raised letters with green acrylic faces and white edges, built on a braced steel frame on the factory roof. For factories, processing plants and logistics companies, they identify the business from main roads and industrial estates and project scale and credibility to clients and partners.","altVi":"Chữ nổi xanh tên đơn vị nông sản gắn trên mái tòa nhà ba tầng","altEn":"Blue raised letters for an agro-processing name mounted on the roof of a three-storey building","source":"/assets/content/projects/advertising/signage-raised-letters/signage-raised-letters-21-building-logos-and-dimensional-lettering-v2.webp","sha256":"30cce69077781aac4d97fc9baa7c599f406286a3e352d5571658d414cab210ee","provenance":"AI-generated illustration; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-31; master PNG SHA256 55653ea9c72c5805aeb2f13e22f08b00588bd4f943b5b7bb7f7c111dcfc66713."},
  "signage-raised-letters-22": {"descriptionVi":"Bảng vẫy hộp đèn chữ nhật bo góc, mặt mica in tên cửa hàng và khẩu hiệu, viền cam, treo trên thanh sắt vuông góc mặt tiền. Dành cho tạp hóa, cửa hàng tiện lợi, quán nhỏ trên phố, giúp người đi hai chiều nhận ra cửa hàng từ xa và sáng rõ khi trời tối.","descriptionEn":"Rounded rectangular projecting lightbox with an acrylic face printed with the shop name and tagline and an orange rim, hung on a steel bar at right angles to the frontage. For grocers, convenience stores and small street shops, it lets traffic in both directions spot the store from afar and shines clearly after dark.","altVi":"Bảng vẫy mica cam bo góc ghi tên tạp hóa, treo bằng thanh sắt","altEn":"Orange rounded acrylic projecting sign hung on iron bar from facade","source":"/assets/content/projects/advertising/signage-raised-letters/signage-raised-letters-22-vacuum-formed-acrylic-projecting-signs-v2.webp","sha256":"7e10d604049cc9b969aa3c37bec3e7004f01039ed81f2f84cbcdd042359e064b","provenance":"AI-generated illustration; source ID imagegen:2026-10-14:signage-raised-letters-22-a; original SHA256 8ceafaa602592f2aaeffb1c55ea3a0b2b1e5577678d2e9b1db5c6d0380ddfe2f; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "office-signs-wayfinding-01": {"descriptionVi":"Biển số nhà inox xước chữ khắc sâu, viền đường sóng trang trí, bắt vít nổi lên tường cạnh cổng. Dành cho nhà phố, biệt thự, văn phòng nhỏ, giúp khách, shipper tìm đúng địa chỉ, bền ngoài trời không gỉ và làm lối vào gọn, sang hơn.","descriptionEn":"Brushed stainless steel house number with deep-engraved digits and a decorative wave line, screwed onto the wall beside the gate. For townhouses, villas and small offices, it helps guests and couriers find the address, resists rust outdoors and gives the entrance a neater, finer look.","altVi":"Biển số nhà inox xước, khắc đường sóng, gắn trên tường trắng cạnh cổng","altEn":"Brushed stainless house number plate with wave etching on a white wall beside gate","source":"/assets/content/projects/advertising/office-signs-wayfinding/office-signs-wayfinding-01-v2.webp","sha256":"d56ccd3077c07be4218325d4696b55e6978483201bea363b273241dc85317b64","provenance":"AI-generated illustration; source ID imagegen:2026-09-09:office-signs-wayfinding-01:v2; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "office-signs-wayfinding-02": {"descriptionVi":"Bộ biển chỉ dẫn gồm tấm mica trong in mũi tên và tấm inox xước in pictogram WC, người khuyết tật, bắt ốc pát inox chân nổi lên tường. Dành cho văn phòng, nhà hàng, trung tâm thương mại, đặt ở hành lang, giúp khách tự tìm nhà vệ sinh, lối đi nhanh và đồng bộ với nội thất hiện đại.","descriptionEn":"Wayfinding set of clear acrylic panels with printed arrows and brushed stainless panels with toilet and accessibility pictograms, fixed with standoff bolts. For offices, restaurants and malls, placed in corridors, it lets visitors find toilets and routes quickly and suits modern interiors.","altVi":"Mica trong có mũi tên trái phải và biển inox icon WC gắn tường bê tông","altEn":"Clear acrylic arrow sign and brushed stainless washroom icon sign on concrete wall","source":"/assets/content/projects/advertising/office-signs-wayfinding/office-signs-wayfinding-02-sign-samples-catalogue.webp","sha256":"e700067d98e256dc8c25256d9f69918081c61224eb34cd3a464c9c2a20fefc2d","provenance":"AI-generated illustration; ChatGPT web image generation 2026-10-24; owner approved audit #785 in chat; original SHA256 0aa16acec728727eccfcec6c07af5f42e1edd83a3394f4b17cb321828275ef14; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "office-signs-wayfinding-03": {"descriptionVi":"Hệ biển chỉ dẫn song ngữ Việt Anh dạng thanh, nền đen chữ trắng, khối màu kèm icon và mũi tên, gắn ốp hai mặt cột sảnh. Dành cho tòa văn phòng, đặt ở sảnh và nút giao hành lang, giúp khách, đối tác nước ngoài tự tìm thang máy, phòng họp, lối ra mà không phải hỏi lễ tân.","descriptionEn":"Bilingual Vietnamese and English strip signs, white text on black with colour blocks, icons and arrows, fixed to two faces of a lobby column. For office buildings, placed in lobbies and corridor junctions, they let visitors and foreign partners find lifts, meeting rooms and exits without asking reception.","altVi":"Biển đen ghi SẢNH, VĂN PHÒNG, PHÒNG HỌP, NHÀ VỆ SINH gắn trên cột đá","altEn":"Black multi-bar directional sign listing lobby, offices, meeting rooms and restrooms on stone post","source":"/assets/content/projects/advertising/office-signs-wayfinding/office-signs-wayfinding-03-street-name-signs-audit-a156-v5.webp","sha256":"bc0db81d6601042b63d6dcc3e5733d549faf8763d5d42ae35942feec5a3e9640","provenance":"AI-generated illustration; ChatGPT web image edit (owner chat 6adf73c3-8098-83ec-add4-160cfdefcad6, card #857); upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-26 19:11Z; master PNG SHA256 60051dc0c7fec2e56c0d4b6bedccfa7874797518c5f063a059fd9fb03f253bdb."},
  "office-signs-wayfinding-04": {"descriptionVi":"Totem chỉ dẫn đứng thân alu sơn đen, chữ và icon trắng song ngữ kèm mũi tên, đặt trên bệ đá chân đế. Dành cho khu đô thị, khu dân cư, công viên, đặt ở vỉa hè, ngã giao, giúp người đi bộ tìm đến công viên, cơ quan, bệnh viện và tạo vẻ đồng bộ, văn minh cho cả khu.","descriptionEn":"Freestanding totem with a black-painted aluminium body, white bilingual text, icons and arrows, on a stone plinth. For new urban areas, residential estates and parks, placed on pavements and junctions, it guides walkers to parks, offices and hospitals and gives the whole area a consistent look.","altVi":"Totem đen có icon công viên, cơ quan và bệnh viện trên bệ đá","altEn":"Black totem sign with park, office and hospital icons on a stone plinth","source":"/assets/content/projects/advertising/office-signs-wayfinding/office-signs-wayfinding-04-urban-wayfinding-pylon.webp","sha256":"82eda4dc43a50b11989ec40938f3b3202cff38c17b0197bf6641743b61dc9a66","provenance":"AI-generated illustration; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-31; master PNG SHA256 fb3f6f4b5ca2b0a4a14ceb18662780acc557fa394e0a529de5399c0bec1822c4."},
  "office-signs-wayfinding-05": {"descriptionVi":"Bảng chức danh để bàn bằng đồng xước mạ vàng, chữ khắc ăn mòn tô màu, gắn trên đế gỗ đỏ. Dành cho giám đốc, trưởng phòng ở ngân hàng, cơ quan, doanh nghiệp, đặt trên bàn làm việc, giúp khách biết ngay người tiếp mình và tạo vẻ trang trọng cho phòng lãnh đạo.","descriptionEn":"Desk name plate in brushed gold-tone brass with etched, colour-filled lettering on a red timber base. For directors and managers at banks, offices and companies, placed on the desk, it tells visitors at once who they are meeting and adds formality to an executive office.","altVi":"Bảng chức danh đồng vàng ghi GIÁM ĐỐC CHI NHÁNH trên đế gỗ","altEn":"Gold brass nameplate reading branch director on a timber base, on red wood desk","source":"/assets/content/projects/advertising/office-signs-wayfinding/office-signs-wayfinding-05-timber-and-brass-desk-nameplates-v2.webp","sha256":"f7ad2395ae89ed5df0e173728b7b86cbc73733f7ac7131edc1d5fc71bf75add6","provenance":"AI-generated illustration; source ID imagegen:2026-10-15:office-signs-wayfinding-05-a; original SHA256 81b7e76225dfe16bc68f7e190bc718dc5e903457621dd4eab6f3b20e41c848d8; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "office-signs-wayfinding-06": {"descriptionVi":"Bảng để bàn bằng mica trắng uốn chữ L, in UV chữ đậm và đường màu theo nhận diện thương hiệu. Dành cho văn phòng giao dịch, ngân hàng, bảo hiểm, phòng khám, đặt trên bàn tiếp khách hoặc quầy, giúp khách biết ngay chỗ cần đến và văn phòng trông chuyên nghiệp hơn.","descriptionEn":"White acrylic desk sign bent into an L shape, UV-printed with bold text and a brand colour line. For service offices, banks, insurers and clinics, placed on reception desks or counters, it tells visitors at once where to go and makes the office look more professional.","altVi":"Bảng để bàn mica trắng ghi BÀN TIẾP KHÁCH trên mặt bàn gỗ","altEn":"White acrylic tabletop sign reading RECEPTION DESK on a wooden desk","source":"/assets/content/projects/advertising/office-signs-wayfinding/office-signs-wayfinding-06-acrylic-desk-nameplates-v2.webp","sha256":"f7571a32573fa2773f4d89d82e477bf147bd57982bacc4e61fad8fd495fbb7ee","provenance":"AI-generated illustration; source ID imagegen:2026-10-15:office-signs-wayfinding-06-a; original SHA256 6b4cc87bb97380ccf6632ba9dbb7d09b7ca4cba6532af59a7a0bca39a63ab572; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "office-signs-wayfinding-07": {"descriptionVi":"Bộ biển chỉ dẫn inox xước in pictogram đen: thang máy, thang cuốn, cầu thang, WC và mũi tên, dán hoặc bắt vít lên tường. Dành cho tòa nhà văn phòng, nhà xưởng, bệnh viện, đặt ở hành lang, sảnh, giúp người lạ tìm lối nhanh, bền, dễ lau chùi và hợp nhiều kiểu nội thất.","descriptionEn":"Brushed stainless steel wayfinding set with black pictograms for lifts, escalators, stairs, toilets and arrows, bonded or screwed to the wall. For office buildings, factories and hospitals, placed in corridors and lobbies, it helps newcomers find their way fast, lasts, wipes clean and suits many interiors.","altVi":"Biển inox xước icon thang máy, cầu thang, WC, người, mũi tên trên tường bê tông","altEn":"Brushed stainless signs with lift, stair, washroom, person and arrow icons on concrete wall","source":"/assets/content/projects/advertising/office-signs-wayfinding/office-signs-wayfinding-07-stainless-pictogram-samples.webp","sha256":"815394c0c5d28b49f0fb5efc93a0c5ef0bab12d68bfdf121ff8bb6bc5d73bc23","provenance":"AI-generated illustration; ChatGPT web image generation 2026-10-24; owner approved audit #793 in chat; original SHA256 321023a8f1a5f3c34e844899f7aeaac9ac6f6c16a95e3ff8be4c7c17160324d7; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "office-signs-wayfinding-08": {"descriptionVi":"Bộ biển chỉ dẫn phối gỗ, đá và sơn màu, in pictogram WC, cầu thang, thang máy và mũi tên, gắn tường bằng keo hoặc vít âm. Dành cho tòa văn phòng, khách sạn boutique, showroom, đặt ở hành lang, giúp khách tìm lối dễ và biển trở thành điểm trang trí hợp nội thất.","descriptionEn":"Wayfinding set combining timber, stone and painted panels with pictograms for toilets, stairs, lifts and arrows, bonded or concealed-screwed to the wall. For offices, boutique hotels and showrooms, placed in corridors, it guides visitors easily and doubles as decor that suits the interior.","altVi":"Bộ biển chỉ dẫn WC, cầu thang, thang máy và mũi tên ốp gỗ và đá","altEn":"Wayfinding signs for washroom, stairs, lift and arrows faced in timber and stone","source":"/assets/content/projects/advertising/office-signs-wayfinding/office-signs-wayfinding-08-office-room-signs.webp","sha256":"3405f0dbdf5c6a1036f7b5fadc41621818d4f80414f5e7dafb23b3127aa2a82a","provenance":"AI-generated illustration; source ID imagegen:2026-09-01:office-signs-wayfinding:08; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "office-signs-wayfinding-09": {"descriptionVi":"Biển phòng họp mặt giả đá màu be in pictogram và chữ, dải nền đen có mũi tên phía dưới, gắn tường cạnh cửa kính mờ. Dành cho văn phòng, khách sạn, tòa nhà cao cấp, giúp khách tìm phòng họp dễ, biển bền, sang và hợp với tường đá, vách kính.","descriptionEn":"Meeting-room sign with a beige stone-effect face printed with a pictogram and text and a black strip with an arrow below, fixed beside a frosted glass door. For offices, hotels and premium buildings, it helps visitors find the meeting room easily and looks durable and refined against stone walls and glass.","altVi":"Biển phòng họp màu be có icon và mũi tên, phần dưới màu đen","altEn":"Beige meeting room sign with icon and arrow, black lower section","source":"/assets/content/projects/advertising/office-signs-wayfinding/office-signs-wayfinding-09-bien-phong-hop-20261111.webp","sha256":"bccaa373bc92a2ba24c2a921abad38f47529f2b27dbb53cb13efb6892e8cecfd","provenance":"AI-generated illustration; ChatGPT web gpt-image (owner chat 6af47257-bcf0-83ec-b42c-258c8122018c, latest image chosen by the owner); owner chose it 2026-11-11; original PNG SHA256 d98cf688ffc07d1f5667f222dd1e841d48bd26f7c6cc20ac10365e44fa7b7730. Site file encoded from the 1536 px JPEG preview of that PNG until the PNG is handed over."},
  "office-signs-wayfinding-10": {"descriptionVi":"Biển chỉ dẫn tầng dạng thanh đứng nền đen, chữ và pictogram trắng in song ngữ, góc chân ốp nẹp đồng, gắn tường cạnh cửa thang máy. Dành cho tòa văn phòng, khách sạn, đặt ở sảnh thang mỗi tầng, giúp khách ra khỏi thang là biết ngay hướng đến văn phòng, phòng họp, lối xuống.","descriptionEn":"Tall black floor directory with white bilingual text and pictograms and a brass corner accent, fixed to the wall beside the lift doors. For office buildings and hotels, placed in each lift lobby, it shows guests stepping out of the lift the way to offices, meeting rooms and stairs down.","altVi":"Biển chỉ dẫn đứng nền đen ghi Offices, Meeting Rooms và Lower Level","altEn":"Standing black-background sign reading Offices, Meeting Rooms and Lower Level","source":"/assets/content/projects/advertising/office-signs-wayfinding/office-signs-wayfinding-10-floor-wayfinding-signs-audit-a163-v1.webp","sha256":"c825805a565f4135ee5c8bcddd12e6b0659ffd75516b58e2c53795979d00cc10","provenance":"AI-generated illustration; ChatGPT web image edit (owner chat 6adf73e4-34e4-83ec-bab9-43c33d4a2199, card #872); upscaled RunningHub SeedVR2 tile to 3072; owner approved 2026-10-26 18:24Z; master PNG SHA256 07fd98e5d1033d884363e60c41bb2c2a69360dca57ff292bb9fe94b83611f590."},
  "office-signs-wayfinding-11": {"descriptionVi":"Bảng chỉ dẫn tầng đứng song ngữ, mặt nền kem in chữ, mũi tên và icon, viền đồng, chân phối terrazzo, gắn tường sảnh thang máy. Dành cho tòa văn phòng, khách sạn, tổ hợp thương mại, giúp khách biết vị trí sảnh, phòng họp, nhà vệ sinh, quán cà phê và hợp với nội thất sang trọng.","descriptionEn":"Tall bilingual floor directory with a cream face printed with text, arrows and icons, a brass edge and terrazzo base, fixed in the lift lobby. For office towers, hotels and mixed-use buildings, it shows where the lobby, meeting rooms, toilets and cafe are and suits upscale interiors.","altVi":"Bảng chỉ dẫn đứng nền kem ghi SẢNH, VĂN PHÒNG, PHÒNG HỌP, CẦU THANG kèm icon","altEn":"Standing cream-background sign listing lobby, offices, meeting rooms and stairs with icons","source":"/assets/content/projects/advertising/office-signs-wayfinding/office-signs-wayfinding-11-floor-directory-lobby.webp","sha256":"d17c5827d62ef5177e0a0ce44bda563dde5389cd06d4400991ea8172c5a59e77","provenance":"AI-generated illustration; ChatGPT web image edit (owner chat 6adf73e1-dacc-83ec-b661-941e3d846491, card #867); upscaled RunningHub SeedVR2 tile to 3072; owner approved 2026-10-26 18:24Z; master PNG SHA256 ef00155491e951af7d75387974e5f9dd066bd9568832fea8b00b1124ba27aadc."},
  "office-signs-wayfinding-12": {"descriptionVi":"Bộ biển cảnh báo và biển WC bằng alu mặt giả đồng, ghép tấm trắng in mũi tên, gắn tường bằng keo hoặc vít âm. Dành cho tòa văn phòng, khách sạn, nhà hàng, đặt ở hành lang, sảnh thang máy, giúp khách chú ý khu vực cần cẩn thận, tìm nhà vệ sinh nhanh và hợp nội thất ấm, sang.","descriptionEn":"Warning and toilet signs in copper-effect aluminium paired with white panels printed with arrows, bonded or concealed-screwed to the wall. For offices, hotels and restaurants, placed in corridors and lift lobbies, they flag hazards, point to toilets quickly and suit warm, upscale interiors.","altVi":"Biển cảnh báo tam giác và biển WC nam nữ màu đồng gắn tường","altEn":"Triangular warning sign and gold-toned men and women washroom plates on wall","source":"/assets/content/projects/advertising/office-signs-wayfinding/office-signs-wayfinding-12-warning-and-washroom-signs.webp","sha256":"f6ff379dd4036f3208f4ec181a6bf52690154d3ac2a5b5afae246d97f7a8d5cd","provenance":"AI-generated illustration; source ID imagegen:2026-09-01:office-signs-wayfinding:12; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "office-signs-wayfinding-13": {"descriptionVi":"Biển số nhà inox xước chữ dập nổi gồm số nhà và tên hẻm, viền gờ nổi, bắt vít bốn góc lên trụ cổng. Dành cho nhà ở trong hẻm, khu phố, biệt thự, giúp khách, shipper tìm đúng địa chỉ nhanh, không gỉ khi để ngoài trời và trông gọn hơn số nhà sơn hay dán.","descriptionEn":"Brushed stainless house number plate with embossed house number and alley name, a raised border and screws at four corners on the gate pillar. For homes in alleys, neighbourhoods and villas, it helps guests and couriers find the address fast, stays rust-free outdoors and looks neater than painted or stick-on numbers.","altVi":"Biển số nhà inox xước có chữ dập nổi và tên hẻm, gắn tường cổng","altEn":"Brushed stainless house plate with embossed numbers and a lane name on gate wall","source":"/assets/content/projects/advertising/office-signs-wayfinding/office-signs-wayfinding-13-etched-and-embossed-stainless-steel-house-number-v2.webp","sha256":"fc4f6e2a482cdd96f234cf19dc65a8920adb9d8e27054d8adf3e6d4032b7186d","provenance":"AI-generated illustration; source ID imagegen:2026-10-14:office-signs-wayfinding-13-a; original SHA256 323769faeabafbb255ca944213f8ba0d061566660a4e92f075d54ea5e9baee70; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "led-displays-lightboxes-01": {"descriptionVi":"Bảng LED ma trận đỏ chạy chữ kèm hình minh họa, khung nhôm đen, gắn kín ngang mặt tiền phía trên cửa quán. Dành cho quán cơm, quán ăn bình dân, cửa hàng mặt phố, giúp tên quán và món đặc trưng nổi bật khi trời tối, chi phí vừa phải và đổi lời chào, khuyến mãi dễ dàng.","descriptionEn":"Red LED matrix scrolling board with an illustration in a black aluminium frame, spanning the frontage above the shop door. For rice shops, casual eateries and street stores, it makes the name and signature dish stand out after dark at moderate cost and changes greetings and offers easily.","altVi":"Bảng LED ma trận đỏ trên mặt tiền quán cơm tấm","altEn":"Red LED matrix display on the facade of a broken-rice restaurant","source":"/assets/content/projects/advertising/led-displays-lightboxes/led-displays-lightboxes-01-single-colour-matrix-led-signs-audit-a075-v1.webp","sha256":"d751ac828fab9943f52cad5d5d08578e36c028d45f3f9139802aaac0d44e2c84","provenance":"AI-generated illustration; owner selected A075-v1 in HTML audit and confirmed in chat 2026-10-22; ChatGPT web gpt-image; original SHA256 d0a89887d5a0609ebcffbedc4d5d66abec3e3fae3e60f0a1b056741f58528c40; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "led-displays-lightboxes-02": {"descriptionVi":"Bảng LED ma trận chạy chữ nhiều màu đặt dưới bảng hiệu chữ nổi trên khung mặt tiền, kèm mái hiên và đèn chiếu. Dành cho siêu thị mini, cửa hàng tạp hóa, gắn ngay trên cửa chính, giúp đổi nhanh khuyến mãi, giờ mở cửa và thu hút người đi đường cả khi trời tối.","descriptionEn":"Multi-colour LED matrix scrolling board under a raised-letter sign on the shopfront frame, with an awning and spotlights. Made for mini-marts and grocery stores, mounted right above the entrance to change promotions and opening hours quickly and catch passers-by even after dark.","altVi":"Bảng LED ma trận chữ chạy gắn dưới hộp đèn mặt tiền siêu thị","altEn":"LED matrix running-text panel mounted below an illuminated supermarket facade sign","source":"/assets/content/projects/advertising/led-displays-lightboxes/led-displays-lightboxes-02-three-colour-matrix-led-signs-v2-audit-a076-v1.webp","sha256":"5d77ec47317d175026590649bdb57da1673c7852eef6f59fb136457ad800b7b1","provenance":"AI-generated illustration; owner selected A076-v1 in HTML audit and confirmed in chat 2026-10-22; ChatGPT web gpt-image; original SHA256 d45062a089db3009b5b8f724eb782830ae3b474914d483902fb864a25e85a48e; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "led-displays-lightboxes-03": {"descriptionVi":"Màn hình LED module full màu ngoài trời, khung cabinet thép chống nước, gắn trên mặt tiền quán, hiển thị hình món ăn và tên quán. Dành cho nhà hàng, quán lẩu, quán nướng mặt phố, giúp quán nổi bật về đêm và đổi nội dung, khuyến mãi theo mùa mà không phải làm lại bảng.","descriptionEn":"Outdoor full-colour LED module screen in a weatherproof steel cabinet, mounted on the restaurant front to show dishes and the shop name. For street-front restaurants, hotpot and grill houses, it makes the place stand out at night and changes content and seasonal offers without a new sign.","altVi":"Màn hình LED module ngoài trời trên mặt tiền quán lẩu buổi tối, thấy lưới module và viền cabinet","altEn":"Outdoor LED module screen above a hotpot restaurant at night, showing the module grid and cabinet edge","source":"/assets/content/projects/advertising/led-displays-lightboxes/led-displays-lightboxes-03-led-module-screen-20261118.webp","sha256":"f9d9a58e4db8e8b181e0329a5e237798fd7b02cc259322665974eefe799cf461","provenance":"AI-generated illustration; Codex gpt-6-sol image edit of the earlier led-displays-lightboxes-03 image; source ID codex-edit:2026-11-18:led-displays-lightboxes-03; original PNG SHA256 a9ea7177cb6d6f811c4c36de9e31540859c3301dcda5dd8228fc5bfc851b77ae; 1k master, owner approved 2026-11-18."},
  "led-displays-lightboxes-04": {"descriptionVi":"Bảng LED ma trận chữ đỏ khung nhôm đen, gắn trên vách ốp gỗ phía trên quầy giao dịch, kèm logo chữ nổi bên cạnh. Dành cho ngân hàng, bưu điện, cơ quan hành chính, giúp hiển thị lời chào, tỷ giá, thông báo cho khách đang chờ và đổi nội dung bằng máy tính trong vài phút.","descriptionEn":"Red LED matrix text board in a black aluminium frame on the timber wall above the service counters, with a raised logo beside it. For banks, post offices and public offices, it shows greetings, rates and notices to waiting customers, and the text changes from a computer in minutes.","altVi":"Bảng LED ma trận chữ đỏ gắn trên tường gỗ phía sau quầy giao dịch","altEn":"Red LED matrix panel on a timber wall above a bank teller counter","source":"/assets/content/projects/advertising/led-displays-lightboxes/led-displays-lightboxes-04-indoor-matrix-led-systems-v2.webp","sha256":"40893a8609b0d9aa59e2784530c1dbf36efe18b7ba891d05f6d02e66584741ef","provenance":"AI-generated illustration; source ID imagegen:2026-10-14:led-displays-lightboxes-04-a; original SHA256 d9e1118e17719312606938e201ac5b118b4aa51f85ea4e081e1af930351ceb65; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "led-displays-lightboxes-05": {"descriptionVi":"Bảng LED ma trận chạy chữ đỏ viền đèn xanh, khung nhôm chống nước, treo dưới mái quầy bán vé ngoài trời. Dành cho bến tàu, bến xe, khu du lịch, giúp khách thấy tên bến, giờ chạy và giá vé từ xa, kể cả ban đêm, và nhân viên đổi thông báo ngay khi cần.","descriptionEn":"Red LED matrix scrolling board with a green light border in a weatherproof aluminium frame, hung under the roof of an outdoor ticket booth. For ferry piers, bus stations and tourist sites, it shows the stop name, departures and fares from afar, even at night, and staff can change notices at once.","altVi":"Bảng LED chữ chạy đỏ ghi BẾN TÀU gắn dưới mái quầy bán vé ven sông","altEn":"Red running-text LED board reading BẾN TÀU under a riverside ticket booth canopy","source":"/assets/content/projects/advertising/led-displays-lightboxes/led-displays-lightboxes-05-outdoor-matrix-led-systems-v2.webp","sha256":"6374c0072d7a31c7bb49b0f4083656339279b93e734c48fb2d1d5ff96fe78b92","provenance":"AI-generated illustration; source ID imagegen:2026-10-14:led-displays-lightboxes-05-a; original SHA256 9841d01e079086d8d384ec7a5c634c792ed6b6784b624e0fb8cb8da0eb9bba3e; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "led-displays-lightboxes-06": {"descriptionVi":"Màn hình LED module full màu khổ lớn ghép cabinet, lắp trên khung thép phía sau sân khấu, kèm loa và hệ đèn sân khấu. Dành cho trung tâm hội nghị, nhà hàng tiệc, đơn vị tổ chức sự kiện, giúp trình chiếu chủ đề, video, slide rõ nét cho cả hội trường đông người thay cho phông bạt in.","descriptionEn":"Large full-colour LED module screen built from cabinets on a steel frame behind the stage, with speakers and stage lighting. For convention centres, banquet halls and event organisers, it shows themes, videos and slides sharply to a full hall and replaces printed backdrops.","altVi":"Màn LED sân khấu hiển thị KIẾN TẠO KHÔNG GIAN SỐ trong sảnh tiệc","altEn":"Large stage LED screen showing KIẾN TẠO KHÔNG GIAN SỐ slogan in banquet hall","source":"/assets/content/projects/advertising/led-displays-lightboxes/led-displays-lightboxes-06-event-led-screens-audit-a080-v1.webp","sha256":"6a9c8451bbf9437be6aad979bbf252f1263f4f90298338f7850775500498d138","provenance":"AI-generated illustration; ChatGPT web image edit (owner chat 6adfd448-309c-83ec-922c-12ddc1ba739c); upscaled RunningHub SeedVR2 tile to 3072; owner approved 2026-10-27 01:07Z; master PNG SHA256 b3821ca76a9d532a00f313d5779dc1947e9e309e62fb8540e9bffdc9671605c4."},
  "led-displays-lightboxes-07": {"descriptionVi":"Màn hình LED module full màu khổ lớn trong nhà, lắp sau sân khấu sàn gỗ hội trường, hiển thị tên hội nghị và hình ảnh chủ đề. Dành cho cơ quan, hiệp hội, doanh nghiệp tổ chức hội nghị, hội thảo, giúp nội dung rõ cho cả khán phòng và đổi chủ đề mỗi buổi chỉ bằng file trình chiếu.","descriptionEn":"Large indoor full-colour LED module screen behind a timber stage, showing the conference title and theme images. For agencies, associations and companies running conferences and seminars, it makes content clear to the whole room and changes theme each session with just a presentation file.","altVi":"Màn LED lớn trên sân khấu gỗ hiển thị nội dung về vùng nguyên liệu dừa","altEn":"Large LED screen on wooden stage displaying content about coconut raw-material regions","source":"/assets/content/projects/advertising/led-displays-lightboxes/led-displays-lightboxes-07-auditorium-led-screens.webp","sha256":"d8b1c878dc3d5f92dc174db62ccd3b0e3690ea2cfd2f50535dd8636c78959b95","provenance":"AI-generated illustration; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-31; master PNG SHA256 a7f30852f7849827b0a67063fb3321ebad024789489239ec5fe8741558a11a7a."},
  "led-displays-lightboxes-08": {"descriptionVi":"Màn hình LED trong nhà khung viền mảnh, gắn tường phía trên kệ hàng, chạy video sản phẩm. Dành cho cửa hàng đồ uống, mỹ phẩm, chuỗi bán lẻ, đặt đối diện cửa vào, giúp khách vừa bước vào đã thấy sản phẩm nổi bật và cửa hàng đổi nội dung khuyến mãi bất cứ lúc nào.","descriptionEn":"Slim-framed indoor LED screen wall-mounted above the product shelves, playing product video. For drink and cosmetics stores and retail chains, facing the entrance, it shows the hero product as customers walk in and lets the store change promotions at any time.","altVi":"Màn hình LED treo tường hiển thị cảnh rót sữa dừa phía trên kệ chai","altEn":"Wall-mounted LED screen showing coconut milk pouring above a bottle shelf","source":"/assets/content/projects/advertising/led-displays-lightboxes/led-displays-lightboxes-08-imagegen-20261019.webp","sha256":"40ef3c6ec0c4472b9629f2a543931c149832137577ffb4749ccfb33f894dc592","provenance":"AI-generated illustration; source ID imagegen:2026-10-19:led-displays-lightboxes-08-a-2; original SHA256 9424e7b1a6fcc90a19f21e484598f360e0b21577838f4bb9d82b88a49442f7ca; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "led-displays-lightboxes-09": {"descriptionVi":"Màn hình LED full màu ngoài trời khổ lớn, cabinet chống nước, gắn trên mặt dựng tòa nhà, chạy video và hình quảng cáo. Dành cho nhãn hàng tiêu dùng, trung tâm thương mại, chủ tòa nhà cho thuê quảng cáo, giúp sản phẩm được thấy từ xa trên phố đông và đổi chiến dịch nhanh mà không phải thay bạt.","descriptionEn":"Large outdoor full-colour LED screen with weatherproof cabinets on a building facade, playing ad videos and images. For consumer brands, malls and building owners selling ad space, it shows products from far along busy streets and switches campaigns quickly without changing banners.","altVi":"Màn hình LED lớn trên mặt dựng tòa nhà đang chiếu quảng cáo nước dừa","altEn":"Large LED screen on a building facade playing a coconut drink advertisement","source":"/assets/content/projects/advertising/led-displays-lightboxes/led-displays-lightboxes-09-large-format-led-displays.webp","sha256":"f12b5a6e7f99227e93abcaaaf93e04bc738489db09f13dcbd2318d6f30e31eb3","provenance":"AI-generated illustration; ChatGPT web image edit with owner mask (chat 6ae5f98d-0428-83ec-9fc2-6ec405a33356); upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-27; master PNG SHA256 091b8e43c8ae14d48c706529cba357d76cadeaa1b576b850c03d76900097fc77."},
  "led-displays-lightboxes-10": {"descriptionVi":"Bộ hộp đèn tranh ảnh món ăn khung nhôm đen mảnh, mặt in film hoặc bạt xuyên sáng, gắn phía trên quầy bán. Dành cho food court, quán ăn, chuỗi đồ uống, giúp khách nhìn món từ xa, chọn nhanh khi xếp hàng và ảnh món ăn trông hấp dẫn hơn nhờ đèn nền sáng đều.","descriptionEn":"Set of slim black aluminium lightboxes with backlit film or fabric food photos, mounted above the service counter. For food courts, eateries and drink chains, they let customers see dishes from afar, choose quickly while queuing and make food photos more appetising with even backlighting.","altVi":"Ba bảng ảnh phở, bún, cơm gà treo trên quầy food court, khung đen mảnh","altEn":"Three photo panels of pho, noodles and chicken rice on slim black frames above a counter","source":"/assets/content/projects/advertising/led-displays-lightboxes/led-displays-lightboxes-10-slim-led-light-boxes-v2.webp","sha256":"211767dda5390b46dc0bc851079917d17313295b81bba2a79e5a92035e1cd082","provenance":"AI-generated illustration; source ID imagegen:2026-10-14:led-displays-lightboxes-10-a; original SHA256 81aa99e28617064af42ff5b67fadbfe241f2540b87fca6f43addccd7c4145d1f; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "led-displays-lightboxes-11": {"descriptionVi":"Tranh hộp đèn khung nhôm đen mảnh, mặt in ảnh trên film xuyên sáng, đèn LED nền sáng đều, treo dọc tường hành lang. Dành cho khách sạn, resort, nhà hàng, văn phòng, giúp hành lang dài bớt tối và đơn điệu, tạo điểm nhấn trang trí và kể câu chuyện địa phương cho khách.","descriptionEn":"Slim black aluminium lightbox frames with photos on backlit film and even LED backlighting, hung along the corridor wall. For hotels, resorts, restaurants and offices, they make long corridors less dark and monotonous, add decorative accents and tell guests a local story.","altVi":"Tranh ảnh thuyền sông khung đen treo dọc hành lang khách sạn, mặt tranh sáng","altEn":"Black-framed river boat prints hung along hotel corridor with lit faces","source":"/assets/content/projects/advertising/led-displays-lightboxes/led-displays-lightboxes-11-magnetic-front-illuminated-frames-v2.webp","sha256":"a5a767ac3321a8f44976e989cc54e3db91e2fd64bc13999471e5c07a99426146","provenance":"AI-generated illustration; source ID imagegen:2026-10-14:led-displays-lightboxes-11-a; original SHA256 7530ee2e684f437d5115e61522f936c9a3446ebc4d0b450259780c984ad2ab06; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "led-displays-lightboxes-12": {"descriptionVi":"Hộp đèn tranh điện khung nhôm nắp bật, mặt in film xuyên sáng, đèn LED nền mỏng, gắn tường hành lang. Dành cho phòng khám, bệnh viện, ngân hàng, văn phòng, giúp hiển thị chỉ dẫn, quy trình khám rõ ràng, sáng đều và thay nội dung chỉ bằng cách bật nắp, không cần thợ.","descriptionEn":"Snap-frame aluminium lightbox with a backlit film print and slim LED backlighting, wall-mounted in the corridor. For clinics, hospitals, banks and offices, it shows directions and procedures clearly and evenly lit, and the print changes just by snapping the frame open, no technician needed.","altVi":"Hộp đèn nắp bật viền alu có chữ phòng khám và sơ đồ lối khám","altEn":"Snap-frame light box with aluminium edge showing clinic name and consultation route map","source":"/assets/content/projects/advertising/led-displays-lightboxes/led-displays-lightboxes-12-snap-frame-illuminated-displays-v2.webp","sha256":"e195b296c46142ceee7c52f16251a6b67faba9b986aa0d315ae62e7bd6e47913","provenance":"AI-generated illustration; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-31; master PNG SHA256 ad23c090ea3a6deac814d1b1ee99d9cfe3fb64f605065f74643ab2b5d9df974a."},
  "led-displays-lightboxes-13": {"descriptionVi":"Bảng LED ma trận chữ xanh lá khung nhôm chống nước, gắn trên dầm cổng nhà máy dưới bảng tên logo. Dành cho nhà máy, xưởng sản xuất, khu công nghiệp, giúp đăng tin tuyển công nhân, thông báo ca làm, lời chào khách ngay tại cổng và đổi nội dung nhanh từ máy tính.","descriptionEn":"Green LED matrix text board in a weatherproof aluminium frame, fixed to the factory gate beam below the logo sign. For factories, workshops and industrial parks, it posts hiring notices, shift updates and visitor greetings right at the gate, and the text changes quickly from a computer.","altVi":"Bảng LED ma trận xanh lá gắn trên cổng nhà máy để tuyển công nhân","altEn":"Green LED matrix sign mounted on a factory gate for worker recruitment","source":"/assets/content/projects/advertising/led-displays-lightboxes/led-displays-lightboxes-13-single-colour-matrix-led-signs-v2.webp","sha256":"3bfa2e474996f2db2720ae6a6fb4bd8f53c434be3097c1718051594d6fabec25","provenance":"AI-generated illustration; source ID imagegen:2026-10-14:led-displays-lightboxes-13-a; original SHA256 c2ca1127b6525ccfcb79fd8eadeb5e054cd5ce85a440478afb8b1e313b2fdc8b; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "led-displays-lightboxes-14": {"descriptionVi":"Bảng LED ma trận hai màu đỏ vàng, khung nhôm chống nước, gắn trên cổng gỗ lối vào nhà hàng, kèm đèn trang trí phía trên. Dành cho nhà hàng, quán ăn ven sông, khu ẩm thực, giúp giới thiệu món đặc trưng cho khách đi ngang, đổi món theo ngày và sáng rõ khi về đêm.","descriptionEn":"Two-colour red and yellow LED matrix board in a weatherproof aluminium frame, on the timber entrance gate with a decorative lamp above. For riverside restaurants, eateries and food courts, it introduces signature dishes to passers-by, changes the dish of the day and shines clearly at night.","altVi":"Bảng LED ma trận đỏ vàng ghi Món ngon ven sông, Cá kho, canh chua","altEn":"Red and yellow LED matrix sign reading tasty riverside dishes, braised fish, sour soup","source":"/assets/content/projects/advertising/led-displays-lightboxes/led-displays-lightboxes-14-three-colour-matrix-led-signs-v2.webp","sha256":"f18acdc67c72c3576c47dfa9234017bb06398623b002ca25c0a886020d12f58d","provenance":"AI-generated illustration; source ID imagegen:2026-10-14:led-displays-lightboxes-14-a; original SHA256 34474ef03d07cecf4ca608ca162e19ee8ff0066f8072a399873269d9d38f8ae1; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "led-displays-lightboxes-15": {"descriptionVi":"Bảng vẫy màn hình LED module ngoài trời hai mặt trên tay đỡ thép bắt vào mặt tiền, chạy quảng cáo chuyển tiền Western Union, nhìn rõ từ hai đầu phố.","descriptionEn":"Double-sided outdoor LED module screen built as a projecting sign on a steel arm fixed to the facade, showing a Western Union money-transfer ad visible from both directions along the street.","altVi":"Bảng vẫy màn hình LED hai mặt trên tay đỡ thép, hiển thị quảng cáo chuyển tiền Western Union","altEn":"Double-sided LED screen projecting sign on a steel arm showing a Western Union money-transfer ad","source":"/assets/content/projects/advertising/led-displays-lightboxes/led-displays-lightboxes-15-western-union-led-projecting-sign-20261121.webp","sha256":"7ce5d23ae093de1e42744ac1517bd2fdc6d51c07d60ce0ccc4b7b2d3d7c36344","provenance":"AI-generated illustration; Codex gpt-6-sol; source ID codex:2026-11-21:led-displays-lightboxes-15; brand named by the owner; original PNG SHA256 f77243a3be4852bc77a18cf945f1bd14ba9115b46bb3bd25e201570d63ae5355; 1k master, owner approved 2026-11-21."},
  "led-displays-lightboxes-16": {"descriptionVi":"Bảng LED ma trận chữ đỏ hai dòng, khung nhôm đen, treo trần bằng ty thép giữa hành lang. Dành cho bệnh viện, phòng khám, trung tâm hành chính, giúp người bệnh, người nhà thấy hướng đến khoa từ xa, bớt hỏi đường và nhân viên đổi nội dung chỉ dẫn khi cần.","descriptionEn":"Two-line red LED matrix board in a black aluminium frame, hung from the ceiling on steel rods mid-corridor. For hospitals, clinics and public service centres, it lets patients and families see the way to departments from afar, reduces asking for directions and staff can change the text as needed.","altVi":"Bảng LED ma trận đỏ treo trần chỉ khoa khám bệnh trong hành lang","altEn":"Red LED matrix sign hung from ceiling pointing to outpatient clinic in corridor","source":"/assets/content/projects/advertising/led-displays-lightboxes/led-displays-lightboxes-16-indoor-matrix-led-systems-v2.webp","sha256":"24e1d72b07f64f27edc6244ca122b4776895a7d2d27104b0faa45ef4f04b5069","provenance":"AI-generated illustration; ChatGPT web image edit with owner mask; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-31; master PNG SHA256 cbfbb7abafa0f6a8029937dcba203a2a087ef2a27d006a48fb179a81215dfafb."},
  "led-displays-lightboxes-17": {"descriptionVi":"Bảng LED ma trận chữ đỏ hai dòng, khung nhôm đen chống nước, treo trên tay đỡ thép vươn ra từ mái hiên. Dành cho cửa hàng phân bón, vật tư nông nghiệp, đại lý ven đường quê, giúp người đi hai chiều thấy tên cửa hàng từ xa, đổi lời chào hay khuyến mãi theo mùa vụ dễ dàng.","descriptionEn":"Two-line red LED matrix board in a weatherproof black aluminium frame, hung on a steel arm projecting from the eaves. For fertiliser shops, farm supply stores and roadside dealers in the countryside, it shows the shop name to traffic from both directions and changes greetings or seasonal offers easily.","altVi":"Bảng LED ma trận đỏ treo vươn trước cửa hàng bán phân bón","altEn":"Red LED matrix sign on a projecting arm in front of a fertiliser store","source":"/assets/content/projects/advertising/led-displays-lightboxes/led-displays-lightboxes-17-imagegen-20261019.webp","sha256":"1661dd832e27f790ad55fd1fa51b1ddb2ceda403c0fdf08be5860232a9461af7","provenance":"AI-generated illustration; ChatGPT web image edit with owner mask; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-31; master PNG SHA256 ca8729a77ad5b20b3370feb3dba05431dd5fcf6509b504fd183cc17be524c65f."},
  "led-displays-lightboxes-18": {"descriptionVi":"Màn hình LED module full màu ghép cabinet, dựng trên giàn truss nhôm sân khấu kèm đèn và loa, tháo lắp được. Dành cho đơn vị tổ chức sự kiện, hội nghị, lễ ra mắt sản phẩm, giúp trình chiếu chủ đề, video rõ nét trong nhà lẫn ngoài trời và dời đến địa điểm khác nhanh.","descriptionEn":"Full-colour LED module screen built from cabinets on an aluminium stage truss with lights and speakers, designed to be taken down and rebuilt. For event organisers, conferences and product launches, it shows themes and videos sharply indoors or out and moves quickly to the next venue.","altVi":"Màn hình LED sân khấu chiếu chủ đề ngành dừa, dựng trên giàn truss","altEn":"Stage LED screen on truss frame showing coconut industry theme graphics","source":"/assets/content/projects/advertising/led-displays-lightboxes/led-displays-lightboxes-18-event-led-screens.webp","sha256":"277de8ae144bd7efd8258926b4a333ef0c98da94822e54d5d1d0fc024569fffe","provenance":"AI-generated illustration; ChatGPT web image edit with owner mask (chat 6ae5fa09-eab8-83ec-bfba-c30dc31894dc); upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-27; master PNG SHA256 db2c76530facdf6974069658d8dc5a674abc64ed220f64281bfdbabadf7772b2."},
  "print-decals-01": {"descriptionVi":"Danh thiếp in trên giấy mỹ thuật dày, họa tiết hình học ba tông màu theo nhận diện thương hiệu, cắt góc vuông sắc nét. Dành cho chủ cửa hàng, công ty thiết kế, kiến trúc, dùng khi gặp khách và đối tác, giúp để lại ấn tượng chuyên nghiệp và đồng bộ với bộ nhận diện.","descriptionEn":"Business cards printed on thick art paper with a three-tone geometric pattern in the brand colours, cut with crisp square corners. Made for shop owners, design and architecture firms meeting clients and partners, leaving a professional impression that matches the brand identity.","altVi":"Hai danh thiếp giấy cứng in hình học cam, kem và đen trên bê tông","altEn":"Two card-stock business cards with orange, cream and black geometric print on concrete","source":"/assets/content/projects/advertising/print-decals/print-decals-01-business-cards.webp","sha256":"58f8d1bdbd0e6485eb85422f8a752710dabd66391b4eb197bda8fe7939ea92e8","provenance":"AI-generated illustration; source ID imagegen:2026-09-01:print-decals:01; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "print-decals-02": {"descriptionVi":"Tờ rơi khổ nhỏ in màu trên giấy couché, hình minh họa trái cây theo nhận diện thương hiệu, xếp tập dễ phát. Dành cho quán trà trái cây, cửa hàng đồ uống mới mở, phát tại quầy, ngoài phố hoặc kèm đơn giao hàng, giúp giới thiệu menu, khuyến mãi và kéo khách quay lại.","descriptionEn":"Small full-colour flyers on couché paper with fruit illustrations in the brand style, stacked for easy handing out. For fruit tea shops and newly opened drink stores, handed out at the counter, on the street or with delivery orders, they introduce the menu and promotions and bring customers back.","altVi":"Ba tờ rơi màu có hình cam, dâu và đào xếp trên mặt bàn xám","altEn":"Three colour flyers showing orange, strawberry and peach artwork on a grey table","source":"/assets/content/projects/advertising/print-decals/print-decals-02-flyers.webp","sha256":"e81d20666349e2eb48c79fbeeb3af2dbbfc73185114b88ae1cca7112ec50affb","provenance":"AI-generated illustration; source ID imagegen:2026-09-13:print-flyers-fnb-owner-r2-v3; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "print-decals-03": {"descriptionVi":"Bộ ấn phẩm gồm brochure gấp và hộp giấy cứng in họa tiết hình học cùng bảng màu thương hiệu, cán màng mờ. Dành cho công ty, cửa hàng cần bộ nhận diện in đồng bộ, dùng giới thiệu sản phẩm và đóng gói quà tặng, giúp khách nhớ thương hiệu qua mọi điểm chạm.","descriptionEn":"Print set of a folded brochure and a rigid paper box in the same geometric pattern and brand palette, with matte lamination. For companies and shops that need consistent printed identity, used to present products and package gifts, it keeps the brand memorable at every touchpoint.","altVi":"Brochure gấp và hộp giấy in họa tiết cam, xám, đen trên mặt đá","altEn":"Folded brochure and patterned paper box in orange, grey and black on stone","source":"/assets/content/projects/advertising/print-decals/print-decals-03-brochures-and-folded-leaflets.webp","sha256":"46749a8f440f7b69bdd99f76136e9918deb5dc55faa6741c158e251e21fa3235","provenance":"AI-generated illustration; source ID imagegen:2026-09-01:print-decals:03; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "print-decals-04": {"descriptionVi":"Catalogue khổ lớn bìa cứng, gáy vuông, in màu theo nhận diện, ruột giấy dày in ảnh sản phẩm. Dành cho công ty nội thất, vật liệu, sản xuất cần giới thiệu bộ sưu tập, dùng tại showroom, gửi đối tác và đại lý, giúp khách xem sản phẩm kỹ và thương hiệu chuyên nghiệp hơn.","descriptionEn":"Large-format hardcover, square-spined catalogues with printed covers in the brand colours and thick inner pages of product photos. For furniture, materials and manufacturing companies presenting collections, used in showrooms and sent to partners and dealers, they let clients study products and make the brand look more professional.","altVi":"Catalogue bìa xanh, xám, cam xếp chồng, một cuốn mở trên bàn","altEn":"Blue, grey and orange hardcover catalogues stacked, one open on a table","source":"/assets/content/projects/advertising/print-decals/print-decals-04-catalogues.webp","sha256":"dfde3ae0742354164debe487adb434ad9c2d3b139fb7d2a9059fe3792dee4bab","provenance":"AI-generated illustration; source ID imagegen:2026-09-01:print-decals:04; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "print-decals-05": {"descriptionVi":"Thiệp cưới in trên giấy mỹ thuật vân nổi, gấp đôi, kèm phong bì đồng màu, dây buộc và sáp niêm phong ép logo. Dành cho cô dâu chú rể, nhà hàng tiệc cưới, giúp thiệp trang nhã, có dấu ấn riêng và khách mời cảm nhận sự chu đáo ngay khi nhận thiệp.","descriptionEn":"Folded wedding invitations on textured art paper with matching envelopes, a cord tie and a wax seal pressed with a monogram. For couples and wedding venues, they look elegant and personal, and guests feel the care from the moment they receive them.","altVi":"Thiệp cưới và phong bì màu xám, kem có sáp niêm phong vàng","altEn":"Wedding invitation and envelope in grey and cream with gold wax seal on stone","source":"/assets/content/projects/advertising/print-decals/print-decals-05-wedding-and-invitation-cards.webp","sha256":"0ecf066b33899e26cfac43342dad8e9f28e58172280be114bfb9ae7d7d1a5a11","provenance":"AI-generated illustration; source ID imagegen:2026-09-01:print-decals:05; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "print-decals-06": {"descriptionVi":"Bộ thiệp gấp và phong bì in trên giấy mỹ thuật định lượng cao, phối màu xanh navy và cam theo nhận diện thương hiệu. Dành cho doanh nghiệp, cửa hàng gửi thiệp cảm ơn, thư mời sự kiện, chúc Tết đến khách và đối tác, giúp lời mời trang trọng và đồng bộ với thương hiệu.","descriptionEn":"Folded cards and envelopes printed on heavy art paper in navy and orange from the brand palette. For companies and shops sending thank-you cards, event invitations and New Year greetings to clients and partners, they make the invitation feel formal and on-brand.","altVi":"Thiệp gấp và phong bì xanh navy, chi tiết cam trên bàn màu be","altEn":"Folded navy cards and envelopes with orange accents on a beige table","source":"/assets/content/projects/advertising/print-decals/print-decals-06-certificates-and-envelopes.webp","sha256":"448da070b0b96d0f70a618b8a925f70c3d8afc05d49abe623a94450b15927025","provenance":"AI-generated illustration; source ID imagegen:2026-09-01:print-decals:06; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "print-decals-07": {"descriptionVi":"Bìa menu bọc da hoặc ốp gỗ veneer, gáy phối màu, bắt vít đồng để thay ruột menu khi đổi giá. Dành cho nhà hàng, quán bar, khách sạn, đặt trên bàn khách hoặc đưa khi gọi món, giúp thực đơn bền qua nhiều lượt dùng và thể hiện phong cách sang trọng của quán.","descriptionEn":"Menu covers wrapped in leather or timber veneer with contrasting spines and brass screw posts so pages can be swapped when prices change. For restaurants, bars and hotels, laid on tables or handed over at ordering, they survive heavy use and show the venue's upscale style.","altVi":"Ba bìa menu da và gỗ veneer màu đen, xanh rêu, nâu có khóa vít đồng","altEn":"Three menu covers in leather and veneer, black, moss green and brown, with brass screws","source":"/assets/content/projects/advertising/print-decals/print-decals-07-hard-cover-leather-and-timber-menus.webp","sha256":"a3aca0f3f4c444f09c531a7489d1c1907f3140df22b0fabcc54cb409de8bc300","provenance":"AI-generated illustration; source ID imagegen:2026-09-01:print-decals:07; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "print-decals-08": {"descriptionVi":"Phôi menu bằng tấm nhựa PP chống nước nhiều màu, bo góc, in UV trực tiếp nội dung thực đơn. Dành cho quán nước, quán nhậu, quán ăn ngoài trời, đặt trên bàn hoặc quầy order, giúp menu lau sạch được, không mục khi dính nước và dùng bền hơn menu giấy.","descriptionEn":"Waterproof PP plastic menu boards in several colours with rounded corners, UV-printed directly with the menu. For drink shops, beer houses and outdoor eateries, placed on tables or the order counter, they wipe clean, survive spills and last longer than paper menus.","altVi":"Các tấm nhựa chống nước nhiều màu xếp chồng, mặt trống chưa in","altEn":"Stacked waterproof plastic sheets in several colours with blank faces","source":"/assets/content/projects/advertising/print-decals/print-decals-08-waterproof-plastic-menus.webp","sha256":"4b20785e38a50d36924ff2d368e6fc35085e32b7cc387db5172d27ea7ee0e313","provenance":"AI-generated illustration; source ID imagegen:2026-09-01:print-decals:08; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "print-decals-09": {"descriptionVi":"Bộ menu gồm menu cuốn bìa giả da in màu theo nhận diện quán và kệ menu mica trong gắn đế gỗ để bàn. Dùng cho nhà hàng, quán cà phê, đặt trên bàn khách hoặc quầy order, giúp thực đơn đứng thẳng, dễ đọc, dễ lật và đồng bộ phong cách quán.","descriptionEn":"Menu set of a faux-leather booklet menu printed in the venue colours and clear acrylic menu stands on timber bases for tables. For restaurants and cafes, placed on tables or the order counter, it keeps the menu upright, easy to read and flip, and in line with the venue's style.","altVi":"Menu cuốn bìa màu xanh cùng đế mica gỗ để bàn","altEn":"Blue booklet menu alongside an acrylic and timber table stand","source":"/assets/content/projects/advertising/print-decals/print-decals-09-booklet-table-and-acrylic-menus.webp","sha256":"3e3408ea9602e93d150576ef199e9e9237046d53e128c9e888b090f0275d0cf4","provenance":"AI-generated illustration; source ID imagegen:2026-09-01:print-decals:09; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "print-decals-10": {"descriptionVi":"Banner bạt hiflex in màu khổ lớn, đóng khoen viền, căng bằng dây trên khung sắt sơn đen trước mặt tiền. Dành cho quán cà phê, cửa hàng cần quảng bá món mới, khai trương, khuyến mãi theo đợt, giúp nổi bật với chi phí thấp, lắp nhanh và thay nội dung dễ.","descriptionEn":"Large full-colour hiflex banner with eyelets around the edge, laced onto a black steel frame in front of the shop. For cafes and stores promoting new items, openings and seasonal deals, it stands out at low cost, goes up quickly and is easy to replace.","altVi":"Banner bạt hiflex in quảng cáo cà phê, treo trên khung sắt đen","altEn":"Hiflex fabric banner printed with coffee artwork hung on a black iron frame","source":"/assets/content/projects/advertising/print-decals/print-decals-10-hiflex-banner-printing-v2-audit-a211-v1.webp","sha256":"6cdaf5f979fdc157a70b18edb786973e1eb695c1c5e5d28275b3eecd27346ced","provenance":"AI-generated illustration; ChatGPT web image edit (owner chat 6adfd2e5-d558-83ec-872f-73e40836ae7b); upscaled RunningHub SeedVR2 tile to 3072; owner approved 2026-10-27 01:07Z; master PNG SHA256 1278e7999d4095db88216494d0773a0475266d145262ccd078c90255f37fbaa6."},
  "print-decals-11": {"descriptionVi":"Decal in màu dán kính mặt tiền, hình minh họa sản phẩm và tên cửa hàng, phối với bạt mái hiên cùng tông màu. Dành cho cửa hàng đặc sản, tiệm bánh kẹo, quán nhỏ mặt phố, giúp mặt kính thành biển quảng cáo, thu hút người đi đường mà vẫn nhìn được vào trong.","descriptionEn":"Full-colour window decals on the shopfront glass with product illustrations and the shop name, matched with an awning in the same colours. For specialty food, confectionery and small street shops, they turn the glass into advertising that catches passers-by while keeping the interior visible.","altVi":"Decal dán kính xanh có hình dừa và bạt mái xanh của cửa hàng","altEn":"Green window decal with coconut graphics and green awning of a candy shop","source":"/assets/content/projects/advertising/print-decals/print-decals-11-window-wall-vehicle-and-die-cut-decals-v2.webp","sha256":"b9ebb2de20480e8c9e7712d6c6d5bc3712f8380d2770946483883bc354644f9a","provenance":"AI-generated illustration; ChatGPT web (chat 6ae624fe-198c-83ec-8919-3c8fab92403c); upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-31; master PNG SHA256 dcd667e0c00c12ab816a58d2f35c578e7e3b85678c873806203351f319812ebb."},
  "print-decals-12": {"descriptionVi":"Tranh canvas in họa tiết trừu tượng mảng màu, căng trên khung gỗ thông, treo tường bằng móc hoặc dựng sàn. Dành cho căn hộ, văn phòng, quán cà phê, khách sạn, giúp tạo điểm nhấn cho mảng tường trống, đồng bộ với bảng màu nội thất và thay đổi không gian với chi phí thấp.","descriptionEn":"Canvas print with an abstract colour-block design stretched on a pine frame, hung on hooks or leaned against the wall. For apartments, offices, cafes and hotels, it adds a focal point to bare walls, ties into the interior palette and refreshes the space at low cost.","altVi":"Tranh canvas khung gỗ nền trắng với mảng xanh, đỏ, be trừu tượng","altEn":"Timber-framed canvas on white ground with abstract blue, red and beige blocks","source":"/assets/content/projects/advertising/print-decals/print-decals-12-canvas-and-decorative-wall-prints.webp","sha256":"da8beb3e5b501f4fe44aa5d3e1430b05dfd178d4e7b20322ceee34e48a0398b2","provenance":"AI-generated illustration; source ID imagegen:2026-09-01:print-decals:12; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "print-decals-13": {"descriptionVi":"Danh thiếp in trên giấy mỹ thuật dày, mặt trước in logo và tên công ty, mặt sau màu theo nhận diện, bo góc nhẹ. Dành cho kiến trúc sư, công ty thiết kế, xây dựng, dùng khi gặp khách và đối tác tại văn phòng, công trình, giúp tạo ấn tượng chuyên nghiệp, tinh tế ngay từ lần đầu.","descriptionEn":"Business cards on thick art paper with the logo and company name on the front, a brand colour on the back and slightly rounded corners. For architects, design and construction firms meeting clients and partners at the office or on site, they make a professional, refined first impression.","altVi":"Danh thiếp giấy trắng in tên công ty kiến trúc, đặt trên bàn gỗ","altEn":"White paper business cards printed with architecture firm name on a wooden desk","source":"/assets/content/projects/advertising/print-decals/print-decals-13-imagegen-20261019.webp","sha256":"164348870131619a55cb5a8c796378b5f07fd5d4ec21a805c8671e745828d80e","provenance":"AI-generated illustration; source ID imagegen:2026-10-19:print-decals-13-a-3; original SHA256 d89a35f97d44464f8e2b611ce54d7cb0cf74ac5fd8dc5f9c20cd193b5121ad20; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "print-decals-14": {"descriptionVi":"Tờ rơi in màu trên giấy couché, ảnh món ăn và thông tin khuyến mãi khai trương, khổ nhỏ dễ cầm. Dành cho quán bánh mì, quán ăn, cửa hàng mới mở, phát ở chợ, khu dân cư, trường học, giúp nhiều người biết đến quán nhanh với chi phí thấp và kéo khách ghé thử.","descriptionEn":"Small full-colour flyers on couché paper with food photos and opening offers, easy to hand out. For banh mi shops, eateries and new stores, handed out at markets, neighbourhoods and schools, they spread the word quickly at low cost and bring people in to try.","altVi":"Tờ rơi có ảnh bánh mì và ly trà đá, được phát ngoài chợ","altEn":"Flyer with photos of bread rolls and iced tea handed out at a market","source":"/assets/content/projects/advertising/print-decals/print-decals-14-flyers-v2.webp","sha256":"4e3aa2098ed3b755d42c1973e684c102c03e7332f07ce6993eada4b09c13fa42","provenance":"AI-generated illustration; source ID imagegen:2026-10-14:print-decals-14-a; original SHA256 971fd76f6905ac6f9689ccb7ff77aae108ca648c335b1b3416abb9a06013f3c6; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "print-decals-15": {"descriptionVi":"Kệ mica trong nhiều ngăn đựng brochure, tờ gấp đứng thẳng, kèm bộ ấn phẩm in giới thiệu sảnh tiệc, dịch vụ. Dành cho khách sạn, trung tâm hội nghị, phòng khám, showroom, đặt trên quầy lễ tân, giúp khách tự lấy thông tin khi chờ làm thủ tục và ấn phẩm luôn gọn gàng.","descriptionEn":"Multi-pocket clear acrylic stand holding brochures and leaflets upright, with printed materials presenting function halls and services. For hotels, conference centres, clinics and showrooms, placed on the reception desk, it lets guests pick up information while they wait and keeps the print tidy.","altVi":"Kệ mica đựng brochure và tờ gấp để trên quầy lễ tân khách sạn","altEn":"Acrylic brochure rack with leaflets set on a hotel reception counter","source":"/assets/content/projects/advertising/print-decals/print-decals-15-brochures-and-folded-leaflets-v2.webp","sha256":"2b3e949ec1cabc514655ae58010470487b1b441252651f8c99fa365e879048f1","provenance":"AI-generated illustration; source ID imagegen:2026-10-14:print-decals-15-a; original SHA256 968242ecf9f31c95e5bf843d4cc2e90f3807746500891c8a6dc1fc3b6d331f81; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "print-decals-16": {"descriptionVi":"Sách, catalogue bìa cứng in offset, bìa phối màu theo nhận diện, gáy vuông đóng chỉ dán keo. Dành cho nhà xuất bản, công ty cần in sách ảnh, hồ sơ năng lực, catalogue sản phẩm số lượng lớn, giúp ấn phẩm bền, màu in đều và thể hiện sự chỉn chu khi gửi khách, đối tác.","descriptionEn":"Hardcover books and catalogues printed offset, with covers in the brand palette and square sewn and glued spines. For publishers and companies printing photo books, company profiles and product catalogues in volume, they last, keep colour consistent and look polished when sent to clients and partners.","altVi":"Các cuốn sách bìa cứng nhiều màu xếp chồng trên bàn gỗ, gáy sách thẳng hàng","altEn":"Multicolour hardcover books stacked on timber table with spines aligned","source":"/assets/content/projects/advertising/print-decals/print-decals-16-catalogues.webp","sha256":"9a818ecb3784ae449fb8caf5a2b88b843e67af3c3b8cc4a2fd303b26d51c13de","provenance":"AI-generated illustration; source ID imagegen:2026-09-01:print-decals:16; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "kiosk-posm-44": {"descriptionVi":"Backdrop sự kiện dạng vòm cắt CNC từ gỗ ép, in bạt cảnh sông nước, viền ốp nan tre và cột chữ chủ đề, kèm bảng check-in tròn. Dành cho hội nghị, hội chợ xúc tiến thương mại, lễ ra mắt, dựng ở sảnh hoặc sân khấu, giúp không gian đúng chủ đề và tạo góc chụp hình cho khách.","descriptionEn":"Arched event backdrop CNC-cut from plywood, with a printed river scene, bamboo strip edging, theme-text columns and a round check-in board. For conferences, trade promotion fairs and launches, set in the lobby or on stage, it carries the theme and gives guests a photo spot.","altVi":"Backdrop vòm bạt in cảnh sông nước có chữ hội nghị xúc tiến thương mại","altEn":"Arched fabric backdrop with river scene and trade conference lettering","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-44-imagegen-20261018.webp","sha256":"3178f921eeb7565d25880b0c143221e73a55a0866797e7c025b6907139c782a4","provenance":"AI-generated illustration; ChatGPT web image edit (owner chat 6adfd3a3-0bd0-83ec-9259-a005bd90ca4b); upscaled RunningHub SeedVR2 tile to 3072; owner approved 2026-10-27 01:07Z; master PNG SHA256 b313ec01f8c1a28d77873f1bc49b84fde1fac781cc121e505aa26498af815ee6."},
  "kiosk-posm-45": {"descriptionVi":"Gian hàng hội chợ khung gỗ, vách nan dọc, kệ cong và quầy bo tròn có LED hắt, bảng tên cắt CNC gắn trên vòm và tranh in cảnh sông nước. Dành cho cơ sở đặc sản, OCOP, thương hiệu nông sản tham gia hội chợ, triển lãm, giúp gian hàng nổi bật, trưng bày gọn và thu hút khách ghé thử.","descriptionEn":"Trade fair booth with a timber frame, vertical slat walls, curved shelves and a rounded LED-lit counter, a CNC-cut name sign on the arch and a printed river scene. For specialty producers, OCOP and farm brands at fairs and expos, it stands out, displays products neatly and draws visitors to taste.","altVi":"Gian hàng gỗ đặc sản miền Tây có kệ sản phẩm, trái cây và quầy","altEn":"Timber specialty booth with product shelves, fruit display and sales counter","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-45-imagegen-20261018.webp","sha256":"c273d3a28c882e0238f79b489fcebad32aa76f2c77bc4232cca742555575459d","provenance":"AI-generated illustration; ChatGPT web image edit (owner chat 6adfd387-5cf4-83ec-b31c-b03f2e56c353); upscaled RunningHub SeedVR2 tile to 3072; owner approved 2026-10-27 01:07Z; master PNG SHA256 80c1f1ee99068e33f1917a836ee770471544645e017c3ea4d58c2ac490362188."},
  "kiosk-posm-46": {"descriptionVi":"Backdrop sân khấu hội nghị ghép tấm gỗ cắt CNC hình lá và sóng, in bạt phong cảnh, viền LED hắt sáng, kèm bục phát biểu đồng bộ. Dành cho hội nghị, hội thảo chuyên ngành tại khách sạn, dựng phía sau sân khấu, giúp chương trình trang trọng, nổi bật trên ảnh và đúng chủ đề.","descriptionEn":"Conference stage backdrop of CNC-cut wood panels in leaf and wave shapes with a printed landscape, LED edge lighting and a matching lectern. For conferences and industry seminars in hotels, behind the stage, it makes the event formal, photogenic and on-theme.","altVi":"Backdrop sân khấu bạt in cảnh vườn dừa có chữ hội nghị vùng nguyên liệu","altEn":"Stage backdrop printed with coconut garden scene and raw material conference lettering","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-46-imagegen-20261018.webp","sha256":"b4b7e5aae8871b3a331fc6f91c4bc976d5977b00983f45a9d9e5d6148a4a49b5","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:bd-hoi-nghi-1; original SHA256 6afa6447a8fe463d30ba6121c57c00667e5b3a2caa08ff1721f12e9f7f94bd84; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "kiosk-posm-47": {"descriptionVi":"Backdrop khai trương ghép tấm gỗ cắt CNC hình cánh sen, sơn hồng trắng, LED hắt viền, kèm cổng mặt tiền đồng bộ và hoa trang trí. Dành cho cửa hàng mỹ phẩm, phụ kiện, spa ngày khai trương, dựng trước mặt tiền, giúp cửa hàng nổi bật trên phố, tạo góc chụp hình và kéo khách vào.","descriptionEn":"Opening backdrop of CNC-cut wooden lotus petals painted pink and white with LED edge lighting, with a matching storefront arch and flowers. For cosmetics, accessory shops and spas on opening day, set at the shopfront, it makes the store stand out on the street, creates a photo spot and draws customers in.","altVi":"Backdrop hoa sen hồng có tên thương hiệu, dựng trước cửa hàng mỹ phẩm","altEn":"Pink lotus backdrop with brand name set in front of a cosmetics store","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-47-imagegen-20261018.webp","sha256":"53647e1a278146046e7c5584bd039a126fa35ba88c6fa2b84ddfdfd4c822b21f","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:bd-khai-truong-1; original SHA256 45ae2aada72fb7cb2f4ef319b9141e54d8f0319580515abf96d7a17517a4bbee; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "kiosk-posm-48": {"descriptionVi":"Mảng tường trang trí gỗ cắt CNC nhiều lớp khắc tranh sông nước, chữ tên nhà hàng nổi, LED hắt sáng viền, hai bên ốp nan tre. Dành cho nhà hàng, quán ăn đồng quê, đặt trên vách chính khu ăn uống, giúp không gian đậm chất miền Tây, làm điểm nhấn và góc chụp hình cho thực khách.","descriptionEn":"Feature wall of layered CNC-cut wood carved with a river scene, raised restaurant name, LED edge lighting and bamboo-clad sides. For restaurants and countryside-style eateries, on the main dining wall, it gives a strong Mekong Delta feel, a focal point and a photo corner for diners.","altVi":"Vách trang trí gỗ khắc chữ hắt đèn trong nhà hàng miền Tây","altEn":"Carved timber wall panel with backlit lettering inside a western-region restaurant","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-48-imagegen-20261018.webp","sha256":"e7cf1b44c3a2f376b0ba36b949c012cff021b49ef09efe17a01a65011b8000f3","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:bd-nha-hang-1; original SHA256 c15b3214f07c019e12d42e10e7163a23ba718fe5ff23082a638fcbb4150e5833; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "kiosk-posm-49": {"descriptionVi":"Backdrop showroom dạng vòm, phù điêu sóng nước và cây dừa cắt CNC từ gỗ ép sơn trắng, logo nổi, hai bên kệ vòm có LED. Dành cho cửa hàng đặc sản, mỹ phẩm, showroom sản phẩm, đặt sau quầy thu ngân, giúp thương hiệu nổi bật, không gian sang nhẹ nhàng và tạo góc chụp hình.","descriptionEn":"Arched showroom backdrop with a relief of waves and palm trees CNC-cut from white-painted plywood, a raised logo and LED-lit arched shelves at both sides. For specialty food, cosmetics and product showrooms, behind the till, it showcases the brand, adds soft elegance and creates a photo spot.","altVi":"Vách khắc gỗ hắt đèn có tên thương hiệu tại cửa hàng sản phẩm dừa","altEn":"Carved timber wall with backlit brand name in a coconut product shop","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-49-imagegen-20261018.webp","sha256":"edc0c8d9d9872fd91f1482f98eb34defd810daec8958c2f7ae34b2e82279f68b","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:bd-showroom-1; original SHA256 c0940bdb6e2902e67bb76fc283bc1a748fc090dd3192f6fd05a136ab01c66dc3; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "kiosk-posm-50": {"descriptionVi":"Cổng chào tiệc cưới khung gỗ ép cắt CNC dạng vòm, phủ vải voan, cắm hoa tươi và đèn lồng, ghép nhiều lớp tạo chiều sâu. Dành cho tiệc cưới tại gia, nhà hàng, sân vườn, dựng ở lối vào, giúp không gian lãng mạn, dẫn khách vào tiệc và là phông chụp ảnh đẹp cho cô dâu chú rể.","descriptionEn":"Wedding entrance arch of CNC-cut plywood, draped with chiffon, fresh flowers and lanterns, layered for depth. For home, restaurant and garden weddings, at the entrance, it sets a romantic mood, leads guests in and gives the couple a beautiful photo backdrop.","altVi":"Cổng chào trang trí hoa hồng cam và đèn lồng cho tiệc cưới ngoài trời","altEn":"Welcome arch decorated with orange roses and lanterns for outdoor wedding","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-50-imagegen-20261018.webp","sha256":"c525b04769e6df50d02fcea0f1405298c3cf39c9eec0eac5735a1522b998ff73","provenance":"AI-generated illustration; ChatGPT web image edit (owner chat 6adfd365-4208-83ec-af8f-57fa7fa79f6b); upscaled RunningHub SeedVR2 tile to 3072; owner approved 2026-10-27 01:07Z; master PNG SHA256 28ca2e759527185848ba965764644815f28c293df40d051ad5b624c595398761."},
  "kiosk-posm-51": {"descriptionVi":"Backdrop sân khấu khung sắt căng bạt in hai lớp, hai cánh gà in khẩu hiệu, kèm bục phát biểu và thảm đỏ. Dành cho trường học, cơ quan tổ chức lễ khai giảng, tổng kết, mít tinh ngoài trời, dựng trên sân trường, giúp buổi lễ trang trọng, đúng chủ đề và dựng tháo nhanh trong ngày.","descriptionEn":"Stage backdrop of printed banner stretched on a steel frame in two layers, with slogan side wings, a lectern and a red carpet. For schools and agencies holding opening ceremonies, year-end events and outdoor rallies, set up in the schoolyard, it makes the ceremony formal and on-theme and goes up and down within the day.","altVi":"Backdrop bạt in lễ khai giảng có bục sân khấu và bục phát biểu","altEn":"Printed fabric backdrop for opening ceremony with stage and speaker podium","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-51-imagegen-20261018.webp","sha256":"12f12c62818ddf2244ca56bdf9f0b44b83a7252c00672365e91ba5fe50c864ec","provenance":"AI-generated illustration; ChatGPT web image edit (owner chat 6adfd346-7cd4-83ec-add9-8f74b7e7b0cc); upscaled RunningHub SeedVR2 tile to 3072; owner approved 2026-10-27 01:07Z; master PNG SHA256 043dd9ad8fa723029b450e0185ce51101fe73cb61a4be5470ada6ee728c9aac3."},
  "kiosk-posm-52": {"descriptionVi":"Vách lễ tân ốp gỗ CNC uốn sóng, logo chữ nổi hắt sáng, quầy lễ tân mặt đá trắng chân gỗ uốn lượn có LED. Dành cho văn phòng giao dịch, công ty, trung tâm dịch vụ, đặt tại sảnh đón khách, giúp ấn tượng đầu tiên chuyên nghiệp, thương hiệu dễ nhớ và sảnh ấm cúng.","descriptionEn":"Reception wall clad in wave-curved CNC wood with a backlit raised logo, and a white stone-top desk with a flowing wooden base and LED lighting. For transaction offices, companies and service centres, in the welcome lobby, it makes a professional first impression, a memorable brand and a warm lobby.","altVi":"Logo chữ hắt đèn trên tường cong ốp gỗ của sảnh văn phòng giao dịch","altEn":"Backlit logo lettering on a curved timber-clad wall in an office lobby","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-52-imagegen-20261018.webp","sha256":"9ea63a0c964982a6d782cba15ff65b6d6db0a2b858fcec02eb8731699078e483","provenance":"AI-generated illustration; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-31; master PNG SHA256 959311363bb9e3cd8c2c96c7534c1da59443e8ab44fd8920d3bae97517e2a718."},
  "kiosk-posm-53": {"descriptionVi":"Gian hàng hội chợ dựng khung tre, mái lá dừa, kệ gỗ, bảng tên gỗ khắc chữ và biển tròn treo cột, kèm tranh in cảnh chợ nổi. Dành cho cơ sở đặc sản miền Tây, OCOP, hợp tác xã nông sản dự hội chợ, giúp gian hàng mang chất miệt vườn, nổi bật giữa khu triển lãm và khách dễ ghé thử.","descriptionEn":"Trade fair booth with a bamboo frame, coconut-leaf roof, wooden shelves, an engraved wooden name board and round hanging signs, plus a printed floating-market scene. For Mekong Delta specialty brands, OCOP and farm cooperatives at fairs, it brings an orchard feel, stands out in the hall and invites visitors to taste.","altVi":"Gian tre lá, kệ sản phẩm và nhãn tròn: kẹo dừa, bánh tráng, mắm cá","altEn":"Bamboo and leaf booth with product shelves and round labels for candy, rice paper and fish paste","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-53-imagegen-20261018.webp","sha256":"fc0e72323cbac961eacfbb6e8365e73bafadabaddc840a0874e06ba532c4405f","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:gian-trien-lam-bu-01-1; original SHA256 df88cc879b0cc89120eabebef315e47b80d0bdf9dd2d740c577adb37cc1696da; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "kiosk-posm-54": {"descriptionVi":"Kiosk gỗ đặt trong trung tâm thương mại, quầy ốp nan có LED hắt, kệ trưng bày nhiều tầng, bảng tên hộp đèn và tranh in họa tiết dừa. Dành cho thương hiệu đặc sản dừa, bánh kẹo, nông sản, đặt ở sảnh trung tâm thương mại, giúp sản phẩm nổi bật giữa lối đi, trưng bày gọn và khách dễ dừng lại mua.","descriptionEn":"Wooden mall kiosk with a slatted LED-lit counter, multi-tier display shelves, a lightbox name sign and coconut-themed printed panels. For coconut specialty, confectionery and farm brands, in a mall atrium, it stands out in the aisle, displays products neatly and makes it easy to stop and buy.","altVi":"Kiosk gỗ có biển đặc sản dừa và kệ kẹo dừa trong trung tâm thương mại","altEn":"Timber kiosk with coconut specialty sign and candy shelves in a shopping centre","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-54-imagegen-20261018.webp","sha256":"432e5db0939aecd4ce7aaecfaba44b92fafc9a2194eb44020a0b36fce4d90a16","provenance":"AI-generated illustration; ChatGPT web image edit (owner chat 6adfd327-9610-83ec-b5ac-394880730cd9); upscaled RunningHub SeedVR2 tile to 3072; owner approved 2026-10-27 01:07Z; master PNG SHA256 1d91b52830370f0e14bd48d0ffa6a831c90e8d2f316804c264bb1ed738789e31."},
  "kiosk-posm-55": {"descriptionVi":"Xe đẩy bán hàng khung gỗ, mái che, bánh xe lớn, thân in decal hình dừa, bảng tên trên mái và bảng menu bên hông, có LED hắt sáng. Dành cho người bán nước dừa, đồ uống, đặc sản ở phố đi bộ, công viên, bờ kè, giúp quầy nổi bật, dễ đẩy di chuyển và thu hút khách cả ngày lẫn tối.","descriptionEn":"Wooden vending cart with a canopy, large wheels, a coconut-printed decal body, a roof name sign, a side menu board and LED lighting. For coconut water, drinks and specialty sellers on walking streets, parks and riverbanks, it stands out, moves easily and draws customers day and evening.","altVi":"Xe đẩy gỗ bán nước dừa tươi có bảng hiệu vàng và bánh xe ở đáy","altEn":"Wooden cart selling fresh coconut water with gold sign board and base wheels","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-55-imagegen-20261018.webp","sha256":"684acec3f1f69da4e6617d9228d226f5a23badaac9de662f60161668cded5c71","provenance":"AI-generated illustration; ChatGPT web image edit (owner chat 6adfd309-47a8-83ec-9acd-5021dc477af9); upscaled RunningHub SeedVR2 tile to 3072; owner approved 2026-10-27 01:07Z; master PNG SHA256 4ea1e4619e289a52ba5d33029064ed7aa04d468f5d4636a67e093c4721bcbf11."},
  "led-displays-lightboxes-31": {"descriptionVi":"Bảng LED trang trí cắt theo hình, mặt mica in UV hình hoa sen và tên quán, viền và chữ LED neon ánh vàng, gắn lên vách gỗ. Dành cho nhà hàng chay, quán ăn, spa muốn có điểm nhấn trang trí, giúp không gian ấm cúng, tên quán nổi bật và thành góc khách thích chụp hình.","descriptionEn":"Shaped decorative LED sign, UV-printed acrylic with lotus flowers and the venue name, edged and lettered in warm LED neon, mounted on a timber wall. For vegetarian restaurants, eateries and spas wanting a decorative focal point, it warms the space, highlights the name and becomes a favourite photo spot.","altVi":"Bảng LED trang trí hình hoa sen có chữ, viền sáng ấm trên tường gỗ","altEn":"Decorative LED sign shaped as lotus with lettering and warm glow on timber wall","source":"/assets/content/projects/advertising/led-displays-lightboxes/led-displays-lightboxes-31-imagegen-20261018.webp","sha256":"8ec5b8a16c398f83c2d00f03af79e8d340149d15fd4304fbf4d221b00ed88947","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:led-decor-bu-01-1; original SHA256 470b3dd795e65f747463be1585933dd1adfd6e362530d2012bb647b81a38791a; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "led-displays-lightboxes-32": {"descriptionVi":"Bảng hiệu treo hình tròn viền gỗ, mặt in tên quán và nhóm món, treo bằng tay đỡ vươn ra từ tường, kèm bảng chữ đứng cạnh cửa và đèn rọi. Dành cho quán trà, cà phê, tiệm bánh nhỏ, giúp khách đi ngang biết quán bán gì, tạo phong cách mộc mạc và nổi bật khi lên đèn.","descriptionEn":"Round hanging sign with a timber rim and a face printed with the shop name and menu categories, on an arm from the wall, plus a vertical board by the door and spotlights. For small tea shops, cafes and bakeries, it tells passers-by what is on offer, sets a rustic style and stands out when lit.","altVi":"Bảng gỗ tròn treo có chữ trà, cà phê, bánh ngọt, ăn vặt, không đèn LED","altEn":"Round hanging timber sign listing tea, coffee, cakes and snacks without LED lighting","source":"/assets/content/projects/advertising/led-displays-lightboxes/led-displays-lightboxes-32-imagegen-20261018.webp","sha256":"32c22fa8199af974aa6354bf109b858d8b1edee1d04d1e23d13d57c8f2efb2d2","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:led-decor-bu-01-2; original SHA256 1f54b5a1e2463fdd33c83e50455ef353206b6e6e0316311da412cbcf91dfd569; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "led-displays-lightboxes-33": {"descriptionVi":"Cổng vòm trang trí khung thép uốn, ốp nan tre, gắn tiểu cảnh hoa sen bằng mica và LED, kèm bảng tên quán cắt hình có đèn. Dành cho nhà hàng, quán ăn sân vườn, khu ẩm thực, lễ hội, giúp lối vào nổi bật về đêm, thành điểm chụp hình và kéo khách đi ngang ghé vào.","descriptionEn":"Decorative archway of bent steel clad in bamboo strips, with acrylic and LED lotus sculptures and a shaped, lit name board. For restaurants, garden eateries, food streets and festivals, it makes the entrance stand out at night, becomes a photo spot and draws passers-by inside.","altVi":"Cổng vòm LED hình hoa sen phát sáng có bảng quán ăn phía trên","altEn":"Glowing LED lotus-shaped arch gateway with eatery sign above","source":"/assets/content/projects/advertising/led-displays-lightboxes/led-displays-lightboxes-33-imagegen-20261018.webp","sha256":"ec47da2ae3b6b5e5bff423fb69137fa4e05ac8953f30cf93b772aaa938c1ee31","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:led-decor-bu-02-1; original SHA256 9fb7761425e6b9d59e076cbd83686cdef3e3c6f3082f2a04e5226bf0c5d279fc; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "led-displays-lightboxes-34": {"descriptionVi":"Bảng vẫy LED khung nhôm đen, chữ LED điểm nhiều màu, hình minh họa món ăn và viền LED điểm, treo trên tay sắt vuông góc mặt tiền. Dành cho quán cơm, bún, phở, quán ăn bình dân, giúp khách đi hai chiều thấy món bán từ xa, nhất là buổi tối, với chi phí vừa phải.","descriptionEn":"Projecting LED sign in a black aluminium frame with multi-colour dot LED lettering, a food illustration and a dot LED border, hung on a steel arm at right angles to the frontage. For rice, noodle and pho shops and casual eateries, it shows traffic in both directions what is served from afar, especially in the evening, at moderate cost.","altVi":"Bảng vẫy LED đen có chữ cơm bún, hủ tiếu và hình tô phở","altEn":"Black LED projecting sign with rice noodle lettering and bowl of pho graphic","source":"/assets/content/projects/advertising/led-displays-lightboxes/led-displays-lightboxes-34-owner-20261019.webp","sha256":"96cd35f9c675185dba692a31c01eb63e96eb4f9b263d3902f87dba08214acad8","provenance":"AI-generated illustration edited by the owner; source ID owner-edit:2026-10-19:led-sign-02-2; original SHA256 1ef91a76c0ff47d6e282b02b199a4c43e21ed4e6b73db3ba4eb9fd3e313200b1; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "led-displays-lightboxes-35": {"descriptionVi":"Bảng LED đúc hai mặt, chữ và biểu tượng thùng hàng sáng nhiều màu, viền đèn xanh chạy, gắn tay vẫy thép dưới mái hiên. Dành cho điểm nhận gửi hàng, đại lý chuyển phát, tiệm tạp hóa kiêm gửi hàng, giúp người đi hai chiều đường thấy dịch vụ ngay và tìm đúng điểm gửi.","descriptionEn":"Double-sided dot LED sign with multicolour text and a parcel icon, a running green border and a steel projecting arm under the awning. For parcel drop-off points, courier agents and grocery stores that take parcels, it shows the service to traffic from both directions and helps senders find the right spot.","altVi":"Bảng vẫy LED viền xanh lá có chữ điểm nhận gửi hàng và hình hộp bìa","altEn":"Green-edged LED projecting sign reading parcel pickup point with a cardboard box graphic","source":"/assets/content/projects/advertising/led-displays-lightboxes/led-displays-lightboxes-35-owner-20261019.webp","sha256":"d1a6aca0e0f127466d6dc285e69a955fe38e6e77f9aecc1ec891d344300e3fe9","provenance":"AI-generated illustration edited by the owner; source ID owner-edit:2026-10-19:led-sign-03-1; original SHA256 ff146b57259bc04f9e5cfb86757c979eacd4f6039e92e13239699850b572449f; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "led-displays-lightboxes-36": {"descriptionVi":"Bảng vẫy LED khung nhôm đen, chữ LED điểm đỏ vàng, biểu tượng LED neon, viền LED điểm xanh, treo trên khung sắt trước cửa tiệm. Dành cho tiệm chụp ảnh, in ấn, photocopy, dịch vụ giấy tờ, giúp liệt kê rõ dịch vụ, khách nhìn từ xa biết tiệm làm gì và nổi bật khi tối.","descriptionEn":"Projecting LED sign in a black aluminium frame with red and yellow dot LED lettering, an LED neon icon and a blue dot LED border, hung on a steel frame outside the shop. For photo studios, print and copy shops and document services, it lists services clearly so people know from afar what the shop does, and stands out at night.","altVi":"Bảng vẫy LED viền xanh có chữ chụp ảnh, in ảnh thẻ, photo, scan","altEn":"Blue-edged LED projecting sign for photo studio with passport photos and scanning service","source":"/assets/content/projects/advertising/led-displays-lightboxes/led-displays-lightboxes-36-owner-20261019.webp","sha256":"d0337bf4a5008f4485417f513c2969bf2e0a0820e9c17004696c5ccb37364118","provenance":"AI-generated illustration edited by the owner; source ID owner-edit:2026-10-19:led-sign-04-1; original SHA256 256c99a55c1f50aa42f81b058a5ff612ba69966032dbc33aebbaa78a4a923711; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "led-displays-lightboxes-37": {"descriptionVi":"Tranh đèn trang trí in UV hình cô dâu và hoa trên mica, viền và đường nét LED neon ánh vàng ấm, khung đen treo tường. Dành cho tiệm áo cưới, studio cưới, tiệm hoa, giúp không gian lãng mạn hơn, tạo góc chụp hình cho khách và thể hiện phong cách tiệm.","descriptionEn":"Decorative light artwork with a bride and flowers UV-printed on acrylic, outlined and detailed in warm LED neon, in a black frame on the wall. For bridal shops, wedding studios and florists, it makes the space more romantic, gives clients a photo spot and expresses the shop's style.","altVi":"Tranh cô dâu in trên nền có viền đèn LED vàng ấm, treo tường cạnh gương","altEn":"Bridal portrait print with warm yellow LED edge hung on wall beside a mirror","source":"/assets/content/projects/advertising/led-displays-lightboxes/led-displays-lightboxes-37-imagegen-20261018.webp","sha256":"832c8ad546b9924a0fd72df76f5bdd28513ccb4ebdb2823ea205de5cdc68c313","provenance":"AI-generated illustration; ChatGPT web image edit with owner mask (chat 6ae5fa39-91a4-83ec-bde4-16e7b02be8fb); upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-27; master PNG SHA256 f5e2af7d5ab3d374cd6d6301f46d505613c6ffbc63f82bd2028840976807d5f9."},
  "led-displays-lightboxes-38": {"descriptionVi":"Bảng LED đúc chạy chữ và hình, viền đèn nháy, khung nhôm đen, treo bằng giá sắt dưới mái hiên. Dành cho tiệm sửa xe, thay nhớt, vá vỏ ven đường, treo trước cửa tiệm, giúp khách chạy xe nhìn thấy dịch vụ từ xa cả ngày lẫn tối và ghé vào nhanh.","descriptionEn":"Dot LED sign with lit text and graphics, a flashing border and a black aluminium frame, hung on a steel bracket under the awning. For roadside motorbike repair, oil change and tyre shops, hung at the shopfront, it shows the services to riders from afar day and evening and brings them in.","altVi":"Bảng vẫy LED đỏ có chữ sửa xe, icon xe máy và viền đèn chạy","altEn":"Red LED projecting sign with repair lettering, scooter icon and chasing light border","source":"/assets/content/projects/advertising/led-displays-lightboxes/led-displays-lightboxes-38-owner-20261019.webp","sha256":"5617ea29959dfee8441d4f734cacfc478673da74a00b40f1dc509889f95a37d5","provenance":"AI-generated illustration edited by the owner; source ID owner-edit:2026-10-19:led-sign-06-1; original SHA256 1c58fa2a27231f1470812f686420009f61dbdc3be2f98bcf9bd86fc055bafe22; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "led-displays-lightboxes-39": {"descriptionVi":"Biển neon LED uốn hình xe mô tô và cờ đua, gắn trên tấm mica đen, nguồn điện giấu phía sau. Dành cho cửa hàng phụ tùng, đồ chơi xe, mũ bảo hiểm, gắn vách trưng bày hoặc sau quầy, giúp không gian mang chất thể thao, làm điểm nhấn hút mắt và hợp chụp hình.","descriptionEn":"LED neon sign shaped like a motorbike and a racing flag on a black acrylic backing, with the power supply hidden behind. For motorbike parts, accessory and helmet shops, mounted on a display wall or behind the counter, it adds a sporty feel, catches the eye and makes a good photo spot.","altVi":"Biển neon đen hình xe máy và cờ caro gắn tường cạnh kệ mũ bảo hiểm","altEn":"Black neon sign of motorbike and chequered flag on wall beside helmet shelf","source":"/assets/content/projects/advertising/led-displays-lightboxes/led-displays-lightboxes-39-imagegen-20261018.webp","sha256":"cf17222985a09417104325c29037ec971bd4c80659e92b59c02c9d4002da1864","provenance":"AI-generated illustration; ChatGPT web image edit with owner mask (chat 6ae5fa7b-ffa0-83ec-8e39-8c4607ab4943); upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-27; master PNG SHA256 fa61d7c9b9573fde58cf65b75596040e2a8747003b6b5e9b932cd5d198b61035."},
  "led-displays-lightboxes-40": {"descriptionVi":"Bảng LED neon khung thép đứng có bánh xe, mặt in hình ly trà trái cây và chữ uốn neon nhiều màu. Dành cho quán trà, quán nước ép, quầy đồ uống, đặt trước cửa hoặc trong lối vào, giúp quán rực rỡ về đêm, quảng bá món chủ lực và dễ đẩy cất khi đóng cửa.","descriptionEn":"Free-standing LED neon board on a wheeled steel frame, printed with fruit tea drinks and multicolour neon lettering. For tea, juice and drinks bars, at the door or in the entrance, it lights up the shop at night, promotes signature drinks and rolls away at closing.","altVi":"Bảng neon chữ trà trên khung đen có bánh xe, cạnh quầy bar và cây xanh","altEn":"Neon tea sign on black wheeled frame beside bar counter and greenery","source":"/assets/content/projects/advertising/led-displays-lightboxes/led-displays-lightboxes-40-imagegen-20261018.webp","sha256":"5d51651fe81b757605f83f731919e86d085a442643b84102000e7073d6e46ca6","provenance":"AI-generated illustration; ChatGPT web image edit with owner mask (chat 6ae5faae-8684-83ec-8e5e-ec153c9eb928); upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-27; master PNG SHA256 86d9d70da7f1497781a2b248e2a86c3ffd3eaeb0dac55130f05030ae900dc56c."},
  "led-displays-lightboxes-41": {"descriptionVi":"Bảng LED đúc hình khiên, chữ và hình cây dừa, ngôi nhà, mặt trời lặn sáng nhiều màu, treo trên tay vẫy sắt uốn hoa văn. Dành cho nhà nghỉ, homestay, khách sạn nhỏ, gắn vuông góc cột hoặc tường sảnh, giúp khách tìm thấy chỗ nghỉ về đêm và tạo cảm giác thân thiện.","descriptionEn":"Shield-shaped dot LED sign with multicolour text, a palm tree, a house and a sunset, hung from an ornate wrought-iron bracket. For guesthouses, homestays and small hotels, projecting from a column or lobby wall, it helps guests find the place at night and feels welcoming.","altVi":"Bảng vẫy LED viền vàng có hình nhà sàn, cọ dừa và chữ nhà nghỉ","altEn":"Gold-edged LED projecting sign with stilt house, palm graphics and guesthouse lettering","source":"/assets/content/projects/advertising/led-displays-lightboxes/led-displays-lightboxes-41-imagegen-20261018.webp","sha256":"f1935dcbeeacb7caf87cf32558d6aff07908b96facf26e670612509acbec5112","provenance":"AI-generated illustration; ChatGPT web image edit with owner mask (chat 6ae5fd2a-a46c-83ec-bfd6-479ea0232a4a); upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-27; master PNG SHA256 5b2c0fe3147985871363b6325a646e0ad1e2e5451614e32f8851eb5b6b39f623."},
  "led-displays-lightboxes-42": {"descriptionVi":"Bảng LED đúc hình chữ nhật, chữ uốn lượn nhiều màu, hình micro, nốt nhạc và ngôi sao nháy sáng, khung nhôm treo hiên. Dành cho quán cà phê ca nhạc, phòng trà, quán acoustic, treo trước cửa hoặc góc hiên, giúp quán nổi bật về đêm và báo ngay cho khách có nhạc sống.","descriptionEn":"Rectangular dot LED sign with flowing multicolour script, a microphone, musical notes and twinkling stars, in an aluminium frame hung from the porch. For live-music cafes, tea rooms and acoustic bars, at the door or porch corner, it stands out at night and tells guests there is live music.","altVi":"Bảng vẫy LED ghi tên quán cà phê hát, kèm hình micro và nốt nhạc","altEn":"LED projecting sign with karaoke cafe name, microphone and musical note graphics","source":"/assets/content/projects/advertising/led-displays-lightboxes/led-displays-lightboxes-42-owner-20261019.webp","sha256":"da02fabb599e02b1d9f8a69c7b8c6d4577c8c8e5974d2024ee1e4dcb679eff2c","provenance":"AI-generated illustration edited by the owner; source ID owner-edit:2026-10-19:led-sign-09-1; original SHA256 5fb9bf9dffdd9de77754efcf44632b3676193ae7de9e2f973854ae6c190091c5; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "led-displays-lightboxes-43": {"descriptionVi":"Tranh LED neon trang trí, hình ly cà phê in UV trên mica cắt theo đường viền, chữ và viền LED neon, gắn tường phía trên ghế sofa. Dành cho quán cà phê, trà sữa, tiệm bánh, giúp làm mảng tường trống thành điểm nhấn, tạo không khí ấm buổi tối và là góc chụp hình cho khách.","descriptionEn":"Decorative LED neon artwork with a coffee glass UV-printed on contour-cut acrylic, plus LED neon lettering and outline, mounted on the wall above the sofa. For cafes, bubble tea shops and bakeries, it turns a blank wall into a focal point, warms the evening mood and gives customers a photo spot.","altVi":"Bảng LED neon hình ly cà phê đá và chữ cà phê gắn trên tường quán","altEn":"Neon LED sign shaped as an iced coffee glass with coffee lettering on a cafe wall","source":"/assets/content/projects/advertising/led-displays-lightboxes/led-displays-lightboxes-43-imagegen-20261018.webp","sha256":"378d0b85c8f1d5d11dfb63564748af8202a23d2ee5917f46113b399c8704894b","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:led-neon-uv-ca-phe-2; original SHA256 e71c3b21f53bf6255f27ab2d2bdffb1790cfde2874dbe529dc4aec5349b21db1; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "led-displays-lightboxes-44": {"descriptionVi":"Tranh LED neon góc chụp hình, cảnh sông nước in UV trên mica cắt theo hình, chữ và viền LED neon nhiều màu, gắn tường phía trên băng ghế gỗ. Dành cho quán cà phê, nhà hàng, khu du lịch, giúp tạo góc check-in để khách chụp và chia sẻ, quảng bá quán miễn phí trên mạng xã hội.","descriptionEn":"Photo-spot LED neon artwork with a river scene UV-printed on contour-cut acrylic and multi-colour LED neon lettering and outline, above a timber bench. For cafes, restaurants and tourist sites, it creates a check-in corner that guests photograph and share, promoting the venue for free on social media.","altVi":"Bảng LED neon viền sáng cắt hình thuyền, cọ và hoa sen gắn tường","altEn":"Neon LED panel with glowing edge cut into boat, brush and lotus shapes on wall","source":"/assets/content/projects/advertising/led-displays-lightboxes/led-displays-lightboxes-44-imagegen-20261018.webp","sha256":"2e93e12830f2c81d124f623529e23b2eb26bfd84bc979a9c66bcb12719ad2018","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:led-neon-uv-goc-chup-2; original SHA256 80e71303646ac0a389664f2c0060bf7dc8afe87db59dd6dc0a62f25a8d215bc6; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "led-displays-lightboxes-45": {"descriptionVi":"Tranh LED neon hình túi xách, kính mát và hoa in UV trên mica cắt theo hình, chữ và viền LED neon hồng, gắn tường sau quầy thu ngân. Dành cho shop phụ kiện, thời trang, mỹ phẩm, giúp tên cửa hàng nổi bật, tạo phông chụp hình cho khách và làm cửa hàng trẻ trung, dễ nhớ.","descriptionEn":"LED neon artwork with a handbag, sunglasses and flowers UV-printed on contour-cut acrylic and pink LED neon lettering and outline, on the wall behind the till. For accessory, fashion and cosmetics shops, it highlights the shop name, gives customers a photo backdrop and makes the store youthful and memorable.","altVi":"Bảng LED neon hình túi xách và kính mát có chữ phụ kiện trên tường","altEn":"Neon sign of a handbag and sunglasses with accessory lettering on wall","source":"/assets/content/projects/advertising/led-displays-lightboxes/led-displays-lightboxes-45-imagegen-20261018.webp","sha256":"2e00302698d6c2d181c51b0ef58259d2c35ca3cffa08f361de1cea4e47d00565","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:led-neon-uv-quay-shop-2; original SHA256 276fece7f0ce6850c9f64fd0e4b1f98fbfdd26778e356153ddd05fac5959c2ac; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "led-displays-lightboxes-46": {"descriptionVi":"Tranh LED neon hình hoa sen in UV trên mica cắt theo hình, chữ và viền LED neon ánh vàng dịu, gắn tường phía trên giường massage. Dành cho spa, thẩm mỹ viện, phòng trị liệu, giúp tạo ánh sáng dịu, không khí thư giãn, và khẳng định phong cách thương hiệu trong từng phòng.","descriptionEn":"LED neon artwork with a lotus UV-printed on contour-cut acrylic and soft warm LED neon lettering and outline, mounted above the massage bed. For spas, beauty salons and treatment rooms, it gives soft light and a relaxing mood and carries the brand style into every room.","altVi":"Bảng LED neon hình hoa sen có chữ thư giãn phía trên giường spa","altEn":"Neon lotus sign with relaxation lettering above a spa treatment bed","source":"/assets/content/projects/advertising/led-displays-lightboxes/led-displays-lightboxes-46-imagegen-20261018.webp","sha256":"b230e85f70fdf09dea72106140df0a8cdbbfee40fe43ddb0910566b1bede6b1b","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:led-neon-uv-spa-2; original SHA256 44b06ebc9519baaa323860165241ff488c29861de0584a5bad34bbda65c72fbf; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "office-signs-wayfinding-41": {"descriptionVi":"Biển tên gỗ tự nhiên khắc chữ nổi màu đồng, gắn trên trụ cổng bằng vít ẩn. Dành cho homestay, resort nhỏ, nhà vườn ven sông, đặt ở cổng vào, giúp khách tìm đúng chỗ, tạo cảm giác mộc gần thiên nhiên và hợp với kiến trúc sân vườn.","descriptionEn":"Natural wood name plaque with raised bronze-tone lettering, fixed to the gate pillar with hidden screws. For homestays, small resorts and riverside garden houses, at the entrance, it helps guests find the place and gives a natural, rustic welcome that suits garden architecture.","altVi":"Biển gỗ nâu có chữ homestay ven sông, gắn trên cột cổng trắng","altEn":"Brown timber sign with riverside homestay lettering on white gate post","source":"/assets/content/projects/advertising/office-signs-wayfinding/office-signs-wayfinding-41-imagegen-20261018.webp","sha256":"079dcdc945689eaed0f16e3081cb97548767cd4b8f178e744824de3958532169","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:bang-ten-bu-01-1; original SHA256 0389b2dcdfcb0eea340f3e5b1ee3f6bbc8f263e6b8e8e24b4e96a28b32c86bfd; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "office-signs-wayfinding-42": {"descriptionVi":"Biển số nhà mica trắng chữ đen cắt nổi, kèm địa chỉ khu phố, gắn chân cách lên trụ cổng ốp đá. Dành cho nhà phố, biệt thự, văn phòng, gắn ở cổng hoặc tường rào, giúp khách, shipper tìm nhà nhanh, chữ rõ từ xa và làm mặt tiền gọn đẹp.","descriptionEn":"White acrylic house number plate with black raised numerals and the neighbourhood address, on stand-offs on a stone-clad gate pillar. For townhouses, villas and offices, at the gate or fence, it helps visitors and couriers find the house fast, reads clearly from afar and tidies the facade.","altVi":"Biển số nhà mica trắng chữ đen gắn trên trụ ốp đá cẩm thạch","altEn":"White acrylic house number plate with black numerals on marble-clad pillar","source":"/assets/content/projects/advertising/office-signs-wayfinding/office-signs-wayfinding-42-imagegen-20261018.webp","sha256":"0cbff5fe56fee05ee98cb63e9f4bebf628d1e7b370ba7916017e661fe5b9c3d4","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:bang-ten-bu-02-1; original SHA256 68515cc8fd26363db59fe117664a1c311971047b3cd4c60033141173dee1a37a; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "office-signs-wayfinding-43": {"descriptionVi":"Biển tên alu mặt xước bo viền, chữ in UV, gắn chân cách trên vách ốp lam gỗ với LED hắt sáng phía sau. Dành cho trung tâm ngoại ngữ, công ty tư vấn du học, văn phòng tuyển dụng, đặt phía sau quầy lễ tân, giúp sảnh chuyên nghiệp, tên đơn vị nổi bật và tạo tin tưởng cho học viên.","descriptionEn":"Brushed aluminium composite name panel with rounded edges and UV-printed text, on stand-offs on a wood-louvre wall with LED backlighting. For language centres, study-abroad consultancies and recruitment offices, behind reception, it makes the lobby professional, highlights the name and builds trust with students.","altVi":"Biển tên alu có đèn hắt phía sau, gắn trên tường gỗ lam","altEn":"Aluminium name sign with rear backlight fixed on blue-grey timber wall","source":"/assets/content/projects/advertising/office-signs-wayfinding/office-signs-wayfinding-43-imagegen-20261018.webp","sha256":"59fa6afbd124a66704eb15b21d98fc47be066705e809524b539ca87f6118a4f2","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:bang-ten-bu-03-1; original SHA256 9a7a39b4d5a51c5df888afc4fb90c1a1ec4895b45bedf3fc8eaa2ebaa3339409; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "office-signs-wayfinding-44": {"descriptionVi":"Biển số nhà mica nâu vân gỗ, số và địa chỉ cắt nổi màu vàng đồng, viền nổi, gắn trên trụ cổng có đèn hắt. Dành cho nhà phố, biệt thự, nhà vườn, gắn ở cổng hoặc tường rào, giúp khách và shipper tìm nhà nhanh, chữ rõ cả ban đêm và mặt tiền sang hơn.","descriptionEn":"Brown wood-grain acrylic house number plate with raised gold numerals, address and border, fixed on a gate pillar under a downlight. For townhouses, villas and garden homes, at the gate or fence, it helps visitors and couriers find the house fast, reads clearly at night and dresses up the facade.","altVi":"Biển số nhà nền nâu viền vàng gắn trên cột cổng","altEn":"Brown house number plate with gold border fixed on gate pillar","source":"/assets/content/projects/advertising/office-signs-wayfinding/office-signs-wayfinding-44-imagegen-20261018.webp","sha256":"11740b751e95b99e35d5fb025d0d4d57013561f6e8d149d885cdcf3ee80ea4fe","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:bang-ten-bu-04-1; original SHA256 7e11e7f1a9af308550c0aa65fedd760c64f3ed9cc17811e333d834802d6c2cde; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "office-signs-wayfinding-45": {"descriptionVi":"Bảng tên gỗ sẫm màu chữ đồng nổi, ghi tên phòng khám, dịch vụ và địa chỉ, bắt vít lên trụ cổng. Dành cho phòng khám Đông y, nhà thuốc nam, phòng mạch tư nhân, gắn ở cổng hoặc tường mặt tiền, giúp bệnh nhân tìm đúng địa chỉ và tạo cảm giác trang nhã, đáng tin.","descriptionEn":"Dark wood name board with raised brass lettering showing the clinic name, services and address, screwed to the gate pillar. For traditional medicine clinics, herbal pharmacies and private practices, at the gate or facade, it helps patients find the address and feels refined and trustworthy.","altVi":"Biển gỗ ghi phòng khám đông y, châm cứu và bốc thuốc nam trên cột","altEn":"Timber sign listing traditional medicine clinic, acupuncture and herbal dispensing on post","source":"/assets/content/projects/advertising/office-signs-wayfinding/office-signs-wayfinding-45-imagegen-20261018.webp","sha256":"c9f8d9b943746c42e78add707d8f33552bace5f6fceecf79ccb2c1ec2030ddb5","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:bang-ten-bu-05-1; original SHA256 392b7e18191bd0faa215c50fb40de3b6dc52954f5ee99425351ea9e017f3d2e3; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "office-signs-wayfinding-46": {"descriptionVi":"Bảng chức danh để bàn đế gỗ, mặt đồng vàng xước khắc chữ chức danh, dáng tam giác vững. Dành cho văn phòng công ty, cơ quan, ngân hàng, đặt trên bàn làm việc từng người, giúp khách biết đúng người cần gặp, bàn làm việc gọn và tạo vẻ chuyên nghiệp.","descriptionEn":"Desk title plate with a wooden base and a brushed gold brass face engraved with the job title, in a stable triangular profile. For company offices, agencies and banks, on each person's desk, it shows visitors who to talk to, keeps desks tidy and looks professional.","altVi":"Bảng chức danh để bàn có chữ kế toán trên đế gỗ, tấm đồng vàng","altEn":"Desk nameplate with accountant lettering on timber base and gold brass plate","source":"/assets/content/projects/advertising/office-signs-wayfinding/office-signs-wayfinding-46-imagegen-20261018.webp","sha256":"ccc99f155806a96be517d31fd9c30ee63967f44fdb169ed9c33c2af622c831d8","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:chuc-danh-bu-01-1; original SHA256 87825f9c00e94c121d3ea3a2dc8be80932731e80401cd8f050fa2abab725e397; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "office-signs-wayfinding-47": {"descriptionVi":"Bảng chức danh gỗ khắc laser chữ chức danh, đế gỗ sẫm màu, đặt dọc bàn họp. Dành cho phòng họp công ty, hợp tác xã, nhà hàng tiếp khách, đặt trước từng chỗ ngồi, giúp xếp chỗ rõ ràng, khách mời biết ai giữ vai trò gì và bàn họp đồng bộ, ấm cúng.","descriptionEn":"Laser-engraved wooden title plates on dark wood bases, set along the meeting table. For company meeting rooms, cooperatives and hospitality dining rooms, in front of each seat, they make seating clear, show guests who holds which role and give the table a consistent, warm look.","altVi":"Bảng gỗ để bàn ghi trưởng phòng, kế toán, thủ quỹ và lễ tân","altEn":"Timber desk sign listing department head, accountant, cashier and receptionist","source":"/assets/content/projects/advertising/office-signs-wayfinding/office-signs-wayfinding-47-imagegen-20261018.webp","sha256":"23ddec0d5573384c2d9b1adafc0460431d61a67b73222e0b65c1c450a84ddce3","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:chuc-danh-bu-02-1; original SHA256 87ae8007b9efde6f7083064c93680c269e5d54b825ed003235aefd4eb0540d23; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "office-signs-wayfinding-48": {"descriptionVi":"Bảng chức danh để bàn đế gỗ sẫm, mặt mica kem khắc laser chữ chức danh, bo góc tròn. Dành cho văn phòng công ty, phòng kế toán, cơ quan, đặt trên bàn làm việc, giúp khách và đồng nghiệp tìm đúng người, bàn làm việc chỉn chu và hợp không gian nội thất gỗ.","descriptionEn":"Desk title plate with a dark wood base and a cream acrylic face laser-engraved with the role, rounded at the corners. For company offices, accounting departments and agencies, on work desks, it helps visitors and colleagues find the right person, tidies the desk and suits wood-toned interiors.","altVi":"Bảng chức danh để bàn gỗ ghi kế toán trưởng với mặt mica kem","altEn":"Cream acrylic face reading chief accountant set on a timber base","source":"/assets/content/projects/advertising/office-signs-wayfinding/office-signs-wayfinding-48-imagegen-20261018.webp","sha256":"5bf917de1a8128592648e74081596c2fae2a1700d0b60f60dd008f75c38cb520","provenance":"AI-generated illustration; ChatGPT web image edit (owner chat 6adfd1f3-a3cc-83ec-9332-edaa7cb6f322); upscaled RunningHub SeedVR2 tile to 3072; owner approved 2026-10-27 01:07Z; master PNG SHA256 ae14df539f3845c10adb67112b20b03ef79ff6a50ca70734120e1bfbdcb93b3a."},
  "office-signs-wayfinding-49": {"descriptionVi":"Bảng chức danh mica trong kẹp nam châm vào đế gỗ, lá in UV chức danh và họa tiết, thay nội dung không cần dụng cụ. Dành cho ngân hàng, quầy giao dịch, lễ tân khách sạn, đặt trên quầy phục vụ, giúp khách tìm đúng nhân viên và dễ đổi tên khi thay ca, thay người.","descriptionEn":"Clear acrylic title plate held by magnets on a wooden base, with a UV-printed insert of the role and a motif, changed without tools. For banks, service counters and hotel receptions, on the counter, it helps customers find the right staff member and swaps easily between shifts or staff.","altVi":"Ba bảng mica đế gỗ ghi lễ tân, thủ quỹ, giao dịch viên","altEn":"Three acrylic desk signs on timber bases marking receptionist, cashier and teller","source":"/assets/content/projects/advertising/office-signs-wayfinding/office-signs-wayfinding-49-imagegen-20261018.webp","sha256":"e91714dc49f5939e7a9ab6786dd74034583cb80d06e0f4ee9e968a1d807cc256","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:chuc-danh-bu-04-1; original SHA256 bbe3586e092b7f53ae63c75cef4b88e4bbac03502524d6c4fb5ed12fa4c94f56; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "office-signs-wayfinding-50": {"descriptionVi":"Bảng chức danh mica khối dày đặt trên đế gỗ, mặt in UV chữ chức danh và họa tiết sóng xanh, nhiều cỡ. Dành cho ngân hàng, quầy giao dịch, chăm sóc khách hàng, đặt trên quầy tư vấn hoặc thu ngân, giúp khách tìm đúng bộ phận, quầy trông đồng bộ và chuyên nghiệp.","descriptionEn":"Thick block-acrylic title plates on wooden bases, UV-printed with the role and a blue wave motif, in several sizes. For banks, service counters and customer care desks, on advisory or cashier counters, they guide customers to the right desk and keep counters consistent and professional.","altVi":"Hai bảng mica sóng xanh đế gỗ ghi tư vấn khách hàng và thủ ngân","altEn":"Two wavy blue acrylic desk signs on timber bases for client advisor and cashier","source":"/assets/content/projects/advertising/office-signs-wayfinding/office-signs-wayfinding-50-imagegen-20261018.webp","sha256":"ba61133dc19da6b0ae30f78c59357ff66c1758f9ecef28810af52f82c8f9f4d9","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:chuc-danh-bu-04-2; original SHA256 c3fe801e4825745c6c429e8f85315aef508d2a1c32b5de6dad3ed3a9caf1283c; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "office-signs-wayfinding-51": {"descriptionVi":"Bảng chức danh để bàn mặt đồng xước mạ vàng, chữ in hoặc ăn mòn màu đen, cắm trên đế gỗ tự nhiên. Dành cho phòng kế toán, trưởng phòng, giám đốc ở công ty, cơ quan, đặt trên bàn làm việc, giúp khách nhận ra đúng người cần gặp và tạo vẻ chỉn chu cho phòng làm việc.","descriptionEn":"Desk name plate with a brushed gold-tone brass face, black printed or etched lettering, set in a natural timber base. For accounting, managers and directors in companies and offices, placed on the desk, it helps visitors find the right person and makes the office look polished.","altVi":"Bảng để bàn mạ vàng ghi KẾ TOÁN trên đế gỗ đỏ, cạnh sổ và bút","altEn":"Gold-plated tabletop sign reading ACCOUNTING on red timber base beside a notebook and pen","source":"/assets/content/projects/advertising/office-signs-wayfinding/office-signs-wayfinding-51-imagegen-20261018.webp","sha256":"cc849483a3a8d55ec48cbad9ddde7e542a70b30d61635d137affe1b70a586755","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:chuc-danh-bu-05-1; original SHA256 7cd8783b907569fb47bb0196ab2709bca64a5ee85e32ea8fefb81277f408258b; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "office-signs-wayfinding-52": {"descriptionVi":"Bảng chức danh gỗ sáng màu khắc chữ, chân đế gỗ đậm, nhiều cỡ cho chủ tọa, thư ký, đại biểu. Dành cho hội nghị, đại hội, lễ ký kết, đặt trên bàn chủ tọa và bàn đại biểu, giúp sắp xếp vị trí trang trọng, người dự nhìn rõ vai trò và dùng lại nhiều kỳ họp.","descriptionEn":"Light wood title plates with engraved text on dark wood bases, in sizes for chair, secretary and delegates. For conferences, congresses and signing ceremonies, on the presidium and delegate tables, they arrange seating formally, show roles clearly and are reused across sessions.","altVi":"Bảng gỗ để bàn ghi chủ tọa, thư ký và đại biểu trên bàn hội nghị","altEn":"Timber desk signs marking chair, secretary and delegate places at a conference table","source":"/assets/content/projects/advertising/office-signs-wayfinding/office-signs-wayfinding-52-imagegen-20261018.webp","sha256":"6dd1a2200bd5d324686afce091333c53549649373489a8939f6c11ee9d106aff","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:chuc-danh-bu-06-1; original SHA256 0f0fdb7f50ec1f4a6047cd98909ed78bf09c36cefd911d700a8bcb22a8ab4f86; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "office-signs-wayfinding-53": {"descriptionVi":"Bộ kỷ niệm chương phối pha lê, gỗ óc chó, inox xước và kim loại vàng, khắc laser chữ và họa tiết theo chủ đề, mỗi mẫu một kiểu dáng. Dành cho doanh nghiệp làm lễ kỷ niệm thành lập, vinh danh nhân viên, đối tác, giúp mỗi hạng giải có hình thức riêng, đồng bộ phong cách và mang dấu ấn địa phương.","descriptionEn":"Award set combining crystal, walnut, brushed stainless and gold-tone metal, laser-engraved with text and themed motifs, each piece a different shape. For companies celebrating anniversaries and honouring staff and partners, it gives each award tier its own form in a consistent style with a local touch.","altVi":"Các kỷ niệm chương mica và gỗ khắc laser, đặt trên bàn gỗ","altEn":"Laser-engraved acrylic and timber plaques arranged on a wooden table","source":"/assets/content/projects/advertising/office-signs-wayfinding/office-signs-wayfinding-53-imagegen-20261018.webp","sha256":"b8ecaac26b7ad65e39ea9ee0fe8dded769b5f20535170b17e8cb1c33dc78fc96","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:ky-niem-chuong-bu-01-1; original SHA256 63ad9eda00cec1f7807d6bdb729a753280f79a7454b592e15352483f5c41045e; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "print-decals-25": {"descriptionVi":"Bộ bao bì giấy kraft gồm túi quai xách và hộp có quai, hộp nắp gài, in tranh minh họa và tên sản phẩm. Dành cho tiệm bánh, cơ sở đặc sản, quà tặng địa phương, giúp đựng bánh gọn, đẹp khi làm quà, thân thiện môi trường và khách nhận ra thương hiệu qua hình in.","descriptionEn":"Kraft packaging set of handled bags, handled carry boxes and tuck-lid boxes, printed with illustrations and product names. For bakeries, specialty food makers and local gift brands, it holds goods neatly, looks good as a gift, is eco-friendly and builds recognition through its artwork.","altVi":"Túi và hộp giấy kraft in hình cây dừa và chữ bánh nhà làm","altEn":"Kraft bags and boxes printed with coconut palm and homemade cake lettering","source":"/assets/content/projects/advertising/print-decals/print-decals-25-imagegen-20261018.webp","sha256":"0268a1375a34b4b6f5d56d20cb3e9140a5f3107cc637dfe29c5a29fe75e092e0","provenance":"AI-generated illustration; upscaled RunningHub SeedVR2 tile, edited by owner; owner approved to site 2026-10-26 23:04Z; master PNG SHA256 44662baf7f89b2dbafd544d1faac4ac14915d947c3456488dab99f550b9e7dfd."},
  "print-decals-26": {"descriptionVi":"Bộ bao bì giấy kraft cho đặc sản dừa gồm túi quai dây, hộp quà có cửa sổ, nhãn dán hũ thủy tinh và chai, in họa tiết miền sông nước. Dành cho cơ sở đặc sản, OCOP, cửa hàng quà tặng, bày tại quầy hoặc gửi làm quà, giúp sản phẩm đồng bộ, đẹp mắt và xứng tầm quà biếu.","descriptionEn":"Kraft packaging set for coconut specialties with a rope-handle bag, a window gift box and labels for glass jars and bottles, printed with river-delta artwork. For specialty producers, OCOP brands and gift shops, shown at the counter or given as gifts, it unifies the range, looks appealing and looks gift-worthy.","altVi":"Túi và hộp quà giấy kraft in cây dừa, cạnh hũ cơm dừa và dầu dừa","altEn":"Kraft gift bags and boxes printed with a coconut palm beside coconut rice and oil jars","source":"/assets/content/projects/advertising/print-decals/print-decals-26-imagegen-20261018.webp","sha256":"77f683fd6aa0a65fd61760d44664f8d38486008b28dcfcbfd4dd818df9e7a97f","provenance":"AI-generated illustration; upscaled RunningHub SeedVR2 tile, edited by owner; owner approved to site 2026-10-26 23:04Z; master PNG SHA256 370b2a49928b837fd6cbaa9a57bcdc9172f64bdfc6180233793cb86c6f033836."},
  "print-decals-27": {"descriptionVi":"Vé sự kiện in màu trên giấy cứng có cuống xé, kèm vòng đeo tay giấy Tyvek in màu phân loại khách, ban tổ chức. Dành cho lễ hội, hội chợ, sự kiện ngoài trời, giúp kiểm soát ra vào nhanh, phân khu khách rõ ràng và tạo ấn tượng đẹp theo chủ đề sự kiện.","descriptionEn":"Full-colour event tickets on card stock with tear-off stubs, plus colour-coded printed Tyvek paper wristbands for guests and staff. For festivals, fairs and outdoor events, they speed up entry control, separate guest zones clearly and look good in the event theme.","altVi":"Vé tham dự in họa tiết miền Tây và vòng tay giấy ghi chữ khách mời","altEn":"Event tickets with western-region motifs and paper wristbands marked for guests","source":"/assets/content/projects/advertising/print-decals/print-decals-27-imagegen-20261018.webp","sha256":"22292357d0b181ace3cffdab23b4304d03729175affcecb1a02c030cab090900","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:bao-bi-bu-03-1; original SHA256 ed4319f5a3f1f25a006445093f893483caa4876ec98b6a2d4e0db70bdea676f1; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "print-decals-28": {"descriptionVi":"Thẻ thành viên và thẻ tích điểm in trên giấy cứng hoặc nhựa, họa tiết sông nước, bo góc, kèm giá gỗ chia ngăn để thẻ. Dành cho quán cà phê, quán nước, tiệm trà, đặt tại quầy hoặc bàn, giúp giữ chân khách quay lại, ghi nhận ưu đãi và tạo ấn tượng thương hiệu đồng bộ.","descriptionEn":"Membership and loyalty cards printed on board or plastic with river artwork and rounded corners, with an engraved wooden holder with compartments. For cafes, drink stalls and tea shops, at the counter or on tables, they bring customers back, track rewards and give a consistent brand impression.","altVi":"Giá gỗ đựng thẻ thành viên và thẻ tích điểm in hình thuyền","altEn":"Timber holder with membership and loyalty cards printed with boat motif","source":"/assets/content/projects/advertising/print-decals/print-decals-28-imagegen-20261018.webp","sha256":"11c14d331b223a8a27d82e059e4e4c47dce280835971fcd0846254480713dd55","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:bao-bi-bu-04-1; original SHA256 6322ea0c523ab4ba2c24f3133bae286cb852e02d70576009fbfd980ced8b306b; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "print-decals-29": {"descriptionVi":"Bộ ấn phẩm nhận diện gồm túi giấy kraft quai xách, ly giấy và thẻ treo, in họa tiết và logo đồng bộ. Dành cho shop thời trang, quán cà phê, cửa hàng quà tặng, giúp mọi món khách cầm về đều mang thương hiệu, tạo cảm giác chỉn chu và khách nhớ cửa hàng lâu hơn.","descriptionEn":"Branded print set of handled kraft bags, paper cups and swing tags with matching motifs and logo. For fashion boutiques, cafes and gift shops, it puts the brand on everything customers take home, feels polished and keeps the shop in mind longer.","altVi":"Ly giấy, túi kraft và thẻ treo in họa tiết sen trên bàn gỗ","altEn":"Paper cups, kraft bags and hang tags printed with lotus motifs on timber table","source":"/assets/content/projects/advertising/print-decals/print-decals-29-imagegen-20261018.webp","sha256":"9f3552e4e8ac9f5e63a97bd278e52ba3558b78db4b3d24e541ef6b191ed31394","provenance":"AI-generated illustration; ChatGPT web image edit (owner chat 6adfd25c-4a40-83ec-9cc3-a5b59140d3f6); upscaled RunningHub SeedVR2 tile to 3072; owner approved 2026-10-27 01:07Z; master PNG SHA256 7dd932275bd836db2cfeccb9016a3ba903f37cfd397056fc7abb3e90f7214f17."},
  "print-decals-30": {"descriptionVi":"Thực đơn để bàn in hai mặt, ép bóng hoặc cán màng, kẹp trong khung gỗ có khoen lật trang, minh họa món và giá rõ ràng. Dành cho quán cà phê, quán ăn sân vườn, đặt trên từng bàn, giúp khách tự xem món, gọi nhanh hơn và thực đơn bền, lau chùi được.","descriptionEn":"Double-sided laminated table menu held in a wooden frame with flip rings, with illustrated items and clear prices. For cafes and garden eateries, on every table, it lets guests browse on their own, order faster, and stays durable and wipeable.","altVi":"Thực đơn khung gỗ có vòng kim loại, in hình cây dừa và cà phê","altEn":"Table menu with timber frame and metal ring printed with palm and coffee artwork","source":"/assets/content/projects/advertising/print-decals/print-decals-30-imagegen-20261018.webp","sha256":"8f8bca3e2b66736489c05c9e72d968f78eb1db0c196c2a9bfa1a110585d4a620","provenance":"AI-generated illustration; ChatGPT web image edit with owner mask (chat 6ae5c743-2164-83ec-977b-b0ac7c6c55a3); upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-27; master PNG SHA256 939deddf1606efdc56aa68b1ac12a86f7457804a2d845cb04f25eb5e53320fb6."},
  "print-decals-31": {"descriptionVi":"Bộ ba bảng menu gỗ treo trần bằng dây cáp, mặt in decal danh mục đồ uống, giá và hình minh họa trái cây. Dành cho quán nước trái cây, cà phê, quầy sinh tố, treo phía trên quầy pha chế, giúp khách xem món từ xa khi xếp hàng, gọi nhanh và dễ thay decal khi đổi giá.","descriptionEn":"Set of three wooden menu boards hung from the ceiling on cables, faced with printed decals listing drinks, prices and fruit illustrations. For juice bars, cafes and smoothie counters, above the bar, they let queuing guests read the menu from afar, order faster, and take new decals when prices change.","altVi":"Ba tấm menu gỗ treo bằng dây, in nước trái cây, cà phê và trà","altEn":"Three timber menu boards hung on cords printed with juice, coffee and tea","source":"/assets/content/projects/advertising/print-decals/print-decals-31-imagegen-20261018.webp","sha256":"44a9f105dd6c3d5f62ad477304c2ec60873d3496d15f123866741b3664b925fc","provenance":"AI-generated illustration; owner hand-edited 2026-10-31; owner approved to site 2026-10-31; master PNG SHA256 c36760cb02d431e82f46271fecfea2d9de73e8a8c5341f8457bed046a116fa78."},
  "print-decals-32": {"descriptionVi":"Bìa thực đơn đan mây khắc tên quán và họa tiết sông nước, kèm bộ menu khung gỗ gáy khoen, trang in giấy chịu nước. Dành cho quán ăn ven sông, nhà hàng đặc sản, đặt sẵn trên bàn hoặc đưa khi khách vào, giúp thực đơn mang chất miền Tây, bền khi dùng ngoài trời và dễ thay trang giá.","descriptionEn":"Woven rattan menu cover engraved with the restaurant name and river artwork, plus a wooden-frame ring-bound menu with water-resistant printed pages. For riverside eateries and specialty restaurants, on tables or handed to guests, it carries a Mekong Delta feel, holds up outdoors and allows easy price updates.","altVi":"Menu bìa mây đan ghi tên quán và hai menu gỗ mở ra trên bàn","altEn":"Woven rattan cover menu and two timber menus opened on a table","source":"/assets/content/projects/advertising/print-decals/print-decals-32-imagegen-20261018.webp","sha256":"d71181403bc3e503c9b7df1befc5e2553072eee621ecc2dd770aeef3aa86548a","provenance":"AI-generated illustration; ChatGPT web image edit (owner chat 6adfd21b-8e1c-83ec-914f-743c5dbb4ed0); upscaled RunningHub SeedVR2 tile to 3072; owner approved 2026-10-27 01:07Z; master PNG SHA256 89dcdb48aa6d5feacd9b67bbf9d41e66364b8a3dd9605a6d92814c27771061e7."},
  "print-decals-33": {"descriptionVi":"Bảng menu chữ A khung gỗ hai mặt, dán decal in món, hình và giá, gấp gọn khi cất. Dành cho quán bún, quán ăn, quán nước vỉa hè, đặt trước cửa hoặc lối vào, giúp người đi đường xem món và giá ngay, quyết định ghé vào nhanh và dễ thay decal khi đổi thực đơn.","descriptionEn":"Double-sided wooden A-frame menu board with printed decals of dishes, photos and prices, folding flat for storage. For noodle shops, eateries and pavement drink stalls, at the door or entrance, it lets passers-by see dishes and prices at once, decide to stop quickly, and takes new decals when the menu changes.","altVi":"Bảng menu chữ A bằng gỗ in món bún riêu, bún mắm và hủ tiếu","altEn":"A-frame timber menu board printed with crab noodle and fish noodle dishes","source":"/assets/content/projects/advertising/print-decals/print-decals-33-imagegen-20261018.webp","sha256":"13d6ed5827eb3da148e6d2cb693ac7676ed3a0fcf4d5b4907c227cd7448f2b89","provenance":"AI-generated illustration; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-31; master PNG SHA256 991f80b179f65a394a0aab4fdc3cb8ff54863e487f732e0ad83576153f443ddd."},
  "print-decals-34": {"descriptionVi":"Bảng menu hộp đèn LED treo trần bằng ty, khung gỗ bo góc, mặt in decal xuyên sáng danh mục bánh mì, bánh ngọt, đồ uống kèm hình. Dành cho tiệm bánh, quán cà phê bánh, treo phía trên quầy và tủ bánh, giúp khách xem món từ xa khi xếp hàng, gọi nhanh và quầy trông sáng sủa, đồng bộ.","descriptionEn":"Ceiling-hung LED menu lightbox on rods, with a rounded wooden frame and a backlit translucent decal face listing breads, pastries and drinks with photos. For bakeries and bakery cafes, above the counter and display case, it lets queuing guests read the menu from afar, order faster, and keeps the counter bright and consistent.","altVi":"Hộp đèn LED treo trần dài có menu bánh mì, bánh ngọt và đồ uống","altEn":"Long LED ceiling light box with bread, cake and drink menu","source":"/assets/content/projects/advertising/print-decals/print-decals-34-imagegen-20261018.webp","sha256":"bc202ab32decd47d5a2e6705c520db929445dd78d4087b67761bdfa5247fb4fd","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:menu-bu-05-1; original SHA256 69d5cf66d1629f84567f886539e5c1fcf092567570f336b9d0acbc3fec84b457; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "print-decals-35": {"descriptionVi":"Hộp đèn menu ba ô khung gỗ treo trần, mặt in decal xuyên sáng hình bánh mì, bánh ngọt, đồ uống và bảng giá. Dành cho tiệm bánh, quán cà phê, quầy đồ ăn sáng, treo phía trên tủ bánh, giúp chia rõ từng nhóm món, khách chọn nhanh và dễ thay decal khi đổi giá hay thêm món.","descriptionEn":"Three-panel menu lightbox with a wooden frame hung from the ceiling, faced with backlit translucent decals of breads, pastries, drinks and prices. For bakeries, cafes and breakfast counters, above the display case, it separates each menu group, speeds up choosing and takes new decals when prices or items change.","altVi":"Ba bảng menu bánh mì, bánh ngọt và nước uống treo trên quầy tủ bánh","altEn":"Three menu boards for bread, cakes and drinks hung over a cake display cabinet","source":"/assets/content/projects/advertising/print-decals/print-decals-35-imagegen-20261018.webp","sha256":"8f0cbd396a65f9c10b30dbd4ef7c687e5a1b560d05969650c26f130cc3eaead6","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:menu-bu-05-2; original SHA256 d24aa5e2d1b07d7f4229c3b308b6e787855ec2553dc5f02fc32ed2c663f40fe3; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "print-decals-36": {"descriptionVi":"Mặt tiền cửa hàng hoàn chỉnh gồm bảng hiệu ốp alu chữ nổi có đèn, bảng vẫy hộp đèn tròn, decal in họa tiết dán kính và decal thùng xe giao hàng đồng bộ màu. Dành cho siêu thị đặc sản, chuỗi cửa hàng nhà phố, giúp cả mặt tiền thống nhất nhận diện, khách nhận ra từ xa và mỗi chi tiết hỗ trợ nhau thu hút người đi đường.","descriptionEn":"Complete shopfront combining an aluminium composite fascia with lit raised letters, a round projecting lightbox, patterned window decals and a matching delivery box decal. For specialty supermarkets and townhouse store chains, it unifies the whole frontage, is recognised from afar and each element works together to draw passers-by.","altVi":"Mặt tiền siêu thị dừa với bảng alu chữ nổi, bảng vẫy tròn và decal dán kính","altEn":"Coconut store facade with aluminium fascia and raised letters, round projecting sign and window decals","source":"/assets/content/projects/advertising/print-decals/print-decals-36-chatgpt-20261031.webp","sha256":"216c346eeca640fb0f77c4110676254ef48b4351112eabdf56517b48696ee46b","provenance":"AI-generated illustration; ChatGPT web (chat 6ae63347-1410-83ec-876b-bd196831f728); upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-31; master PNG SHA256 b9dac4e6741b65c6d39d1de39c74c4bdb8f72a070f048526d2bfa02c1d635ac5."},
  "print-decals-37": {"descriptionVi":"Bộ bao bì in cho trà sữa gồm ly nhựa in logo, ly giấy có nắp và túi giấy quai xoắn, cùng màu xanh nhận diện. Dành cho quán trà sữa, đồ uống mang đi, giao hàng, dùng tại quầy và khi đóng gói, giúp thương hiệu theo ly đi khắp nơi, khách nhớ tên và đơn mang đi trông chỉn chu.","descriptionEn":"Printed bubble tea packaging set with logo plastic cups, lidded paper cups and a twisted-handle paper bag in the brand green. For bubble tea and takeaway drinks shops and delivery, at the counter and when packing, it carries the brand everywhere, makes the name memorable and makes takeaway orders look neat.","altVi":"Ly nhựa, ly giấy và túi giấy in logo đặt trên bàn gỗ","altEn":"Plastic cups, paper cups and paper bags printed with logo on timber table","source":"/assets/content/projects/advertising/print-decals/print-decals-37-bao-bi-20261111.webp","sha256":"27252c6542417b8d810c765c859efcd851317165bb3a59e7263e769ebcc60ff8","provenance":"AI-generated illustration; ChatGPT web gpt-image (owner chat 6af42a94-9144-83ec-a4e4-c3bfd37776ad); owner approved 2026-11-11; original PNG SHA256 79e4e9458c7fac40bfb8c65f5149e48b8dc6507f9777530a7ef9c4897819e1a6."},
  "print-decals-39": {"descriptionVi":"Bộ bao bì in cho cà phê muối gồm khay giấy xách bốn ly, ly giấy có nắp và ly nhựa in logo, đồng bộ tông nâu. Dành cho quán cà phê, thương hiệu đồ uống mang đi, dùng tại quầy và giao hàng, giúp khách xách nhiều ly gọn, không đổ và nhận diện thương hiệu rõ trên từng ly.","descriptionEn":"Printed packaging set for salted coffee with a four-cup paper carrier, lidded paper cups and logo plastic cups in matching brown. For cafes and takeaway drinks brands, at the counter and for delivery, it lets customers carry several cups without spills and shows the brand clearly on each cup.","altVi":"Hộp bốn ly, ly giấy nắp và ly nhựa in tên đồ uống, bàn gỗ","altEn":"Four-cup carrier, lidded paper cups and plastic cups printed with drink name on wood","source":"/assets/content/projects/advertising/print-decals/print-decals-39-bao-bi-20261111.webp","sha256":"5547b65766cb3259c9d35583729d47e3fa915e7215a87895f9ec421115e8dfb7","provenance":"AI-generated illustration; ChatGPT web gpt-image (owner chat 6af4474f-0d90-83ec-a193-6730c480be89); owner approved 2026-11-11; original PNG SHA256 7b86ddea9d056096dc3982415df6ae2041fde5f53e47dbadf6bd1c9f7785dc69."},
  "print-decals-38": {"descriptionVi":"Bộ bao bì giấy kraft in cho quán cơm gồm túi quai giấy, hộp cơm chữ nhật và tô giấy có nắp, in logo và khẩu hiệu. Dành cho quán cơm, bếp ăn văn phòng, đơn giao hàng, dùng khi đóng gói mang đi, giúp món ăn đựng phần ăn gọn, không thấm, thân thiện môi trường và quảng bá tên quán theo từng phần.","descriptionEn":"Kraft packaging set for a rice eatery with a paper carrier bag, a rectangular meal box and a lidded paper bowl, printed with the logo and slogan. For rice shops, office canteens and delivery orders, used when packing takeaway, it holds meals neatly without leaks, is eco-friendly and promotes the shop with every meal.","altVi":"Túi giấy kraft, hộp giấy và hộp tròn in logo trên bàn gỗ","altEn":"Kraft paper bags, paper boxes and round boxes printed with logo on a wooden table","source":"/assets/content/projects/advertising/print-decals/print-decals-38-bao-bi-20261111.webp","sha256":"695bae28ba3cae20c16f90153961f85da622f30a8f71fbb4d96292e8704be547","provenance":"AI-generated illustration; ChatGPT web gpt-image (owner chat 6af4580c-ced8-83ec-883e-8a5bfb8c380c); owner approved 2026-11-11; original PNG SHA256 64a8eb39418654ac06758b7d7ea6ac13463c1047dcdbc6dc9b90d9634b28b170."},
  "signage-raised-letters-37": {"descriptionVi":"Chữ nổi LED hắt sáng phía sau gắn trên ô văng mặt tiền ốp alu sáng màu, kèm khẩu hiệu nhỏ và hộp đèn biểu tượng kính mắt vuông góc. Dành cho tiệm kính mắt, nha khoa, cửa hàng nhà phố, gắn trên mặt tiền, giúp tên tiệm rõ ràng cả ngày lẫn đêm và người đi hai chiều đều thấy.","descriptionEn":"Halo-lit raised letters on a light aluminium-clad facade band, with a small tagline and a projecting eyeglasses icon lightbox. For opticians, dental clinics and townhouse shops, on the facade, it shows the name clearly day and night and is seen from both directions.","altVi":"Chữ nổi LED hắt sáng trên mặt tiền có tên tiệm kính mắt","altEn":"Halo-lit LED dimensional letters on facade with eyewear shop name","source":"/assets/content/projects/advertising/signage-raised-letters/signage-raised-letters-37-imagegen-20261018.webp","sha256":"719eabb1844d874541dff4cfc7029dcf797b5b4bbe4acede394953d21b6a028a","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:signage-dusk-a-3; original SHA256 82de0bd8de935eb5f78697166f3f9b02fc584f1d70242b6025388a2aeb6528fb; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "led-displays-lightboxes-47": {"descriptionVi":"Bảng LED đúc hai mặt, chữ và biểu tượng điện thoại sáng nhiều màu, viền đèn chạy, gắn tay vẫy thép vào cột hoặc tường. Dành cho cửa hàng điện thoại, phụ kiện, sửa chữa điện tử, gắn vuông góc mặt tiền, giúp người đi hai chiều đường đều thấy tiệm và nhận ra dịch vụ ngay.","descriptionEn":"Double-sided dot LED sign with multicolour text and a phone icon, a running border and a steel projecting arm fixed to a column or wall. For phone, accessory and electronics repair shops, mounted at right angles to the facade, it is seen from both directions of the street and names the service at once.","altVi":"Bảng vẫy LED viền xanh có chữ sửa điện thoại, phụ kiện","altEn":"Blue-edged LED projecting sign reading phone repair and accessories on a shop front","source":"/assets/content/projects/advertising/led-displays-lightboxes/led-displays-lightboxes-47-owner-20261019.webp","sha256":"f57a1d10fa1a82d0f846111d9bb4ed6d50481f4f8020028ddacebbc9acae3f67","provenance":"AI-generated illustration edited by the owner; source ID owner-edit:2026-10-19:led-sign-01-3; original SHA256 91aeb91dac2e9f31f751271d18e996b2fe84d825c73f2854c17dd55d82af5352; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "led-displays-lightboxes-48": {"descriptionVi":"Tranh LED neon hình ly cà phê và hạt cà phê in UV trên mica cắt theo hình, chữ và viền LED neon ánh vàng, gắn tường khu bàn. Dành cho quán cà phê ven sông, sân vườn, quán có không gian mở, giúp tên món và thương hiệu nổi bật buổi tối và tạo không gian ấm, gần gũi.","descriptionEn":"LED neon artwork with a coffee glass and beans UV-printed on contour-cut acrylic, with warm LED neon lettering and outline, mounted on the wall by the tables. For riverside and garden cafes and open-air venues, it highlights the drink and brand in the evening and creates a warm, friendly space.","altVi":"Bảng LED neon cà phê cắt hình trên tường, phía dưới là bàn ghế gỗ","altEn":"Neon coffee sign cut to shape on a wall with timber tables and chairs below","source":"/assets/content/projects/advertising/led-displays-lightboxes/led-displays-lightboxes-48-imagegen-20261018.webp","sha256":"e6aab108422653cfc6fe2b40ce177761a59624be4b13dd083d8ca1c9acd26ff8","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:led-neon-uv-ca-phe-1; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-31; master PNG SHA256 d9ccfd18bb91272d1f00aa209dbf1b085255658edecc54c75ff3f54b748b8024."},
  "led-displays-lightboxes-49": {"descriptionVi":"Tranh LED neon góc chụp hình, hoa nhiệt đới và chiếc xuồng in UV trên mica cắt theo hình, chữ và viền LED neon ánh vàng, gắn tường phía trên băng ghế gỗ. Dành cho quán cà phê sân vườn, nhà hàng, homestay, giúp tạo góc check-in ấm áp, khách lưu lại ảnh và nhớ đến quán.","descriptionEn":"Photo-spot LED neon artwork with tropical flowers and a small boat UV-printed on contour-cut acrylic and warm LED neon lettering and outline, above a timber bench. For garden cafes, restaurants and homestays, it creates a warm check-in corner where guests take photos and remember the place.","altVi":"Bảng LED cắt hình hoa, lá và thuyền có chữ góc kỷ niệm gắn tường","altEn":"LED panel cut into flower, leaf and boat shapes with memory corner lettering","source":"/assets/content/projects/advertising/led-displays-lightboxes/led-displays-lightboxes-49-imagegen-20261018.webp","sha256":"080402ebc0718adac909a88ae3fa376b0f77f5c63dcc2c7d19a94bb6fde1acea","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:led-neon-uv-goc-chup-1; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-31; master PNG SHA256 8729711505f6f0a2a5ffd7c60b43529816d1c293e08f6d2a1d453a6e7b684ab5."},
  "led-displays-lightboxes-50": {"descriptionVi":"Tranh LED neon túi xách, kính mát và hoa in UV trên mica cắt theo hình, viền LED neon trắng ấm, chữ LED neon hồng, gắn tường sau quầy. Dành cho shop phụ kiện, thời trang nữ, tiệm nail, giúp quầy thu ngân thành điểm nhấn, khách chụp hình check-in và nhận ra thương hiệu.","descriptionEn":"LED neon artwork with a handbag, sunglasses and flowers UV-printed on contour-cut acrylic, a warm white LED neon outline and pink LED neon lettering, behind the counter. For accessory, women's fashion and nail shops, it makes the till a focal point, invites check-in photos and builds brand recognition.","altVi":"Bảng LED neon phụ kiện phía trên quầy thu ngân trong cửa hàng","altEn":"Neon accessory sign above the cash counter inside a retail shop","source":"/assets/content/projects/advertising/led-displays-lightboxes/led-displays-lightboxes-50-imagegen-20261018.webp","sha256":"6267888ed29909383daa43fab1aa8123b806b07bc4a2485378392c0e228a823c","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:led-neon-uv-quay-shop-1; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-31; master PNG SHA256 47176b0458ba4320bafc6f899e70828b018ce112bef2990937af3bba8a56701c."},
  "led-displays-lightboxes-51": {"descriptionVi":"Tranh LED neon hoa sen in UV trên mica cắt theo hình, chữ và viền LED neon ánh vàng dịu, gắn tường cạnh giường massage. Dành cho spa, resort, phòng trị liệu, giúp phòng có điểm nhấn nhẹ nhàng, ánh sáng thư giãn thay đèn trần chói và khách nhớ không gian thương hiệu.","descriptionEn":"LED neon lotus artwork UV-printed on contour-cut acrylic with soft warm LED neon lettering and outline, mounted beside the massage bed. For spas, resorts and treatment rooms, it adds a gentle focal point and relaxing light instead of harsh ceiling lights and makes the brand space memorable.","altVi":"Bảng LED cắt hình hoa sen có chữ thư giãn gắn tường phòng spa","altEn":"LED panel cut into lotus shape with relaxation text on a spa room wall","source":"/assets/content/projects/advertising/led-displays-lightboxes/led-displays-lightboxes-51-imagegen-20261018.webp","sha256":"f10df9292dd4cf9d4748e80892bd711eb9a5044682e5757bb422f6bc7c89f799","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:led-neon-uv-spa-1; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-31; master PNG SHA256 603a725fff92c8ed9ecab14856851f140cb0e7f0a881fae8f181cbb10f02e688."},
  "led-displays-lightboxes-52": {"descriptionVi":"Biển LED neon uốn chữ nhiều màu và hình tô bún, gắn trên tấm mica cắt theo đường viền, treo trên vách quán. Dành cho quán cơm, bún, hủ tiếu, quán ăn bình dân, gắn trên tường chính hoặc mặt tiền, giúp khách nhận ra món bán từ xa, quán sáng vui mắt về đêm và làm điểm chụp hình.","descriptionEn":"LED neon sign with multicolour lettering and a noodle bowl, on contour-cut acrylic hung on the restaurant wall. For rice, noodle and hu tieu eateries, on the main wall or facade, it shows what is served from afar, brightens the shop at night and makes a photo spot.","altVi":"Bảng LED neon cắt hình tô bún có chữ cơm bún hủ tiếu gắn trên tường","altEn":"Neon LED sign cut as noodle bowl with rice noodle lettering on wall","source":"/assets/content/projects/advertising/led-displays-lightboxes/led-displays-lightboxes-52-chatgpt-20261031.webp","sha256":"8a2e709d7edc6c8ca3e4da3266cf01c479fdf6c626d3b71b63d3f0c2c79b7e3e","provenance":"AI-generated illustration; ChatGPT web (chat 6ae6252b-8174-83ec-b438-3d76b4ce5be0); upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-31; master PNG SHA256 5870fbd6b5892360a49265d7a8d0a5b3b9c89ca3eabd8e521346a4983ce6e26f."},
  "kiosk-posm-56": {"descriptionVi":"Cụm quầy kệ gỗ gồm vách cong có logo, kệ vòm nhiều tầng và đảo trưng bày tròn có đèn LED hắt chân. Dành cho thương hiệu đồ thủ công, đồ gia dụng mỹ nghệ thuê mặt bằng trong trung tâm thương mại, giúp tạo một góc cửa hàng có câu chuyện riêng và khách đi vòng xem được mọi phía.","descriptionEn":"Timber display set with a curved logo wall, multi-tier arched shelving and a round island lit with LED at the base. For handicraft and homeware brands renting mall space, it creates a store corner with its own story and lets shoppers walk round to see every side.","altVi":"Kệ gỗ cong có biển in chữ và đèn hắt sáng cho đồ mỹ nghệ","altEn":"Curved timber display shelf with printed sign and uplighting for handicraft goods","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-14-product-display-counters-and-shelving-audit-a033-v1.webp","sha256":"c1dc4018acaed904cba682f198e5e13c08b25d00f803ee944a9871a84dc497e2","provenance":"AI-generated illustration; owner selected A033-v1 in HTML audit and confirmed in chat 2026-10-22; ChatGPT web gpt-image; original SHA256 2e4cc2b879b18df0289535eba04719f19da75d2b92ea7d380a83f071282294c0; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "kiosk-posm-57": {"descriptionVi":"Standee khung ống thép trắng bo góc, đế đối trọng đổ nước hoặc cát, mặt căng poster in hình sản phẩm. Dành cho quán cà phê, cửa hàng đồ uống, tiệm bánh, đặt ngay cửa ra vào kể cả ngoài trời có gió, giúp giới thiệu món mới cho khách đi ngang mà không lo đổ ngã.","descriptionEn":"Standee with a rounded white steel tube frame and a ballast base filled with water or sand, carrying a printed product poster. For cafes, drink shops and bakeries, placed right at the entrance even outdoors in wind, it introduces new items to passers-by without the risk of falling over.","altVi":"Standee khung trắng có poster sữa hạt, đặt trước cửa quán cà phê","altEn":"White standee frame with nut milk poster placed outside a coffee shop door","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-33-owner-20260924-audit-a052-v1.webp","sha256":"b46f0aeee9270c9f0ef3f8a2cc199c2e3ff4e6e772e10b53bfbd05ff22a4ef43","provenance":"AI-generated illustration; upscaled RunningHub SeedVR2 tile, edited by owner; owner approved to site 2026-10-26 23:04Z; master PNG SHA256 a522cda25d8eada99240098b43128b8e57d3270966708161b9e2616c32c92230."},
  "kiosk-posm-58": {"descriptionVi":"Standee khung sắt sơn đen, chân đế vuông chắc, mặt lồng poster in hình sản phẩm, đặt đứng trước cửa tiệm. Dành cho tiệm bánh, quán cà phê, cửa hàng thực phẩm, giúp khách đi ngang thấy món đang bán, khuyến mãi trong ngày và dễ mang vào trong khi đóng cửa.","descriptionEn":"Black-painted steel-framed standee with a square base and a printed product poster, standing in front of the shop. For bakeries, cafes and food stores, it shows passers-by what is on sale and today's offers, and is easy to carry inside at closing.","altVi":"Standee khung đen có poster bánh tươi, ảnh bánh mì và bánh ngọt","altEn":"Black standee frame with fresh bakery poster showing bread and cakes outside a shop","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-34-owner-20260924-audit-a053-v1.webp","sha256":"45666b79f1ea4e1b88850f59fdd23bfd1b77e7dbfbe24d5542d9fc65429c571b","provenance":"AI-generated illustration; edited by owner in ChatGPT web; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-27; master PNG SHA256 336b28354683ffb670f951baac15bba3019e61635f3709e95ace913e4528a09f."},
  "kiosk-posm-59": {"descriptionVi":"Standee chân chữ T khung ống trắng, căng bạt in hình sản phẩm và thông điệp thương hiệu, đặt đứng trước cửa hàng. Dành cho cửa hàng đồ dùng xanh, quán cà phê, cửa hàng quà tặng, giúp khách đi ngang hiểu nhanh cửa hàng bán gì, thay bạt theo chiến dịch và cất gọn sau giờ bán.","descriptionEn":"T-base standee with a white tube frame and a stretched banner printed with products and the brand message, standing in front of the store. For eco-goods shops, cafes and gift stores, it tells passers-by at a glance what is sold, swaps banners per campaign and packs away after hours.","altVi":"Standee bạt khung trắng có chữ và đồ dùng tre gỗ phía sau","altEn":"White-frame fabric standee with lettering and bamboo and timber goods behind","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-35-owner-20260924-audit-a054-v1.webp","sha256":"5691bda92bbba4c99cc3a5bbde69dd4a1d53f8ea802f75065cd49c910bc0d153","provenance":"AI-generated illustration; ChatGPT web image edit by owner (chat 6ae0088d-3700-83ec-8579-dd0779f3588b); upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-27; master PNG SHA256 c1b7b51ad34eee178275801e6c0def5052a05f9d1fa62c68622aa054caaea941."},
  "kiosk-posm-60": {"descriptionVi":"Standee chân chữ T khung ống trắng, căng bạt in họa tiết hoa và tên bộ sưu tập, đặt đứng trước cửa hàng. Dành cho shop thời trang, lụa, đồ thiết kế, giúp giới thiệu bộ sưu tập mới đúng phong cách thương hiệu, thu hút khách đi ngang và thay nội dung theo mùa dễ dàng.","descriptionEn":"T-base standee with a white tube frame and a stretched banner printed with floral artwork and the collection name, standing at the shop entrance. For fashion, silk and designer boutiques, it introduces new collections in the brand's style, draws passers-by in and changes easily each season.","altVi":"Standee bạt chân trắng có chữ và hoa sen đặt trước cửa hàng","altEn":"White-base fabric standee with lettering and lotus artwork in front of a shop","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-36-owner-20260924-audit-a055-v1.webp","sha256":"ce2d1927b05137a7f75caf3a053889450f5e0f1f2f675594cf6263627bba18a2","provenance":"AI-generated illustration; owner hand-edited 2026-10-31; master PNG SHA256 d44eca8db24e7bc3d16cf95c425d3b23229c75fde9b7feef088f6afba49b1dd5."},
  "kiosk-posm-61": {"descriptionVi":"Standee chữ X chân thép, bạt in hình cây xanh và thông điệp không gian sống, dựng gọn trên mặt bằng nhỏ. Dành cho cửa hàng cây cảnh, vườn ươm, shop trang trí nội thất, đặt trước cửa hoặc vỉa hè, giúp giới thiệu sản phẩm, mời khách ghé xem và dễ thay nội dung theo mùa.","descriptionEn":"X-banner stand with steel legs and a banner printed with plants and a living-space message, fitting on a small footprint. For plant shops, nurseries and home decor stores, placed at the door or on the pavement, it presents products, invites browsers in and is easy to update by season.","altVi":"Standee X bạt in hình chậu cây xanh và chữ vườn mát đặt trước cửa hàng","altEn":"Fabric X-stand printed with potted green plants and garden lettering in front of a shop","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-37-owner-20260924-audit-a056-v1.webp","sha256":"26f4915a800bf417840633fc5395861d692b4795d065ad4eb55abdef43afe057","provenance":"AI-generated illustration; upscaled RunningHub SeedVR2 tile, edited by owner; owner approved to site 2026-10-26 23:04Z; master PNG SHA256 c25da08e75d56ba113cb2a6b2eb1026d5043f9a972818ae4bd404350e6d43bf5."},
  "kiosk-posm-62": {"descriptionVi":"Gian hàng triển lãm khung gỗ, vách nan dọc, hộp đèn LED in hình dừa, kệ hốc có đèn và quầy cong ốp nan. Dành cho thương hiệu mỹ phẩm, thực phẩm từ dừa tham gia triển lãm, hội chợ, giúp gian hàng sáng đẹp, sang trọng, khách dễ thấy từ xa và có không gian tư vấn sản phẩm.","descriptionEn":"Exhibition booth with a timber frame, vertical slat walls, coconut-printed LED lightboxes, lit niche shelves and a curved slatted counter. For coconut cosmetics and food brands at expos and fairs, it looks bright and upscale, is seen from afar and gives room to advise customers.","altVi":"Gian hàng cong gỗ có ảnh dừa, kệ sản phẩm và đèn treo trong hội chợ","altEn":"Curved timber booth with coconut photos, product shelves and hanging lights at fair","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-62-trade-fair-coconut-beauty-booth.webp","sha256":"4a3f898d6110429a49de791727614b9b95323eba38e1340246e3a08320ed4297","provenance":"AI-generated illustration; owner approved 2026-10-23; moved from the Commercial hero pool; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "kiosk-posm-63": {"descriptionVi":"Gian hàng hội chợ gỗ, hộp đèn in tranh phong cảnh, kệ hốc có đèn, bục trưng bày nhiều tầng cao thấp cho đồ thủ công. Dành cho cơ sở thủ công mỹ nghệ, làng nghề dừa, OCOP tham gia hội chợ, giúp sản phẩm được trưng bày nổi khối, khách đi vòng xem dễ và gian hàng có cá tính.","descriptionEn":"Wooden trade fair booth with landscape-printed lightboxes, lit niche shelves and multi-height display plinths for handicrafts. For handicraft makers, coconut craft villages and OCOP brands at fairs, it presents products in depth, lets visitors walk around easily and gives the booth character.","altVi":"Gian hàng gỗ với tường kệ, bàn và đồ thủ công trang trí","altEn":"Timber booth with shelf wall, table and handcrafted decorative objects","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-63-trade-fair-coconut-craft-booth.webp","sha256":"53b7abfd69bde6d99b3bd220982efe90c75b0c91a36869935c94452c0a5cabf4","provenance":"AI-generated illustration; owner approved 2026-10-23; moved from the Commercial hero pool; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "signage-raised-letters-38": {"descriptionVi":"Chữ nổi hộp LED sáng mặt mica trắng sữa, thành inox hoặc nhôm, gắn trên tường đá ốp thấp có đèn hắt chân. Dành cho quán cà phê sân vườn, nhà hàng, resort, đặt ở cổng hoặc lối vào, giúp tên quán sáng rõ về đêm, sang trọng và thành điểm check-in của khách.","descriptionEn":"Front-lit LED channel letters with opal white acrylic faces and stainless steel or aluminium returns, mounted on a low stone wall with base uplighting. For garden cafes, restaurants and resorts, at the gate or entrance, it lights the name clearly at night, looks upscale and becomes a check-in spot.","altVi":"Chữ nổi phát sáng gắn trên tường đá của quán cà phê ban đêm","altEn":"Glowing raised letters on stone wall of a cafe at night","source":"/assets/content/projects/advertising/signage-raised-letters/signage-raised-letters-06-v2-audit-a242-v5.webp","sha256":"06b14e45678052721990aa2d415d3c637ffcef12f757019e13e39e0194f23004","provenance":"AI-generated illustration; owner selected A242-v5 in HTML audit and confirmed in chat 2026-10-22; ChatGPT web gpt-image; original SHA256 b210bdd1781709bbabf6e4918479b190b86eb91202ad0f3aa673ebf550fa1522; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "signage-raised-letters-39": {"descriptionVi":"Chữ hộp kim loại sơn cam gắn bóng đèn LED tròn trên mặt chữ, đặt trên bệ đá thấp trong sân vườn. Dành cho nhà hàng nướng, quán nhậu, khu ẩm thực ven sông, đặt ở lối vào, giúp tên quán ấm áp, đậm chất vintage, nổi bật về đêm và hút khách chụp hình.","descriptionEn":"Orange-painted metal box letters fitted with round LED bulbs on the faces, set on a low stone plinth in the garden. For grill restaurants, pubs and riverside food areas, at the entrance, it gives the name a warm vintage glow, stands out at night and invites photos.","altVi":"Chữ đèn bóng tròn trên tường đá trước nhà hàng về đêm","altEn":"Round-bulb lettering on a stone wall in front of a restaurant at night","source":"/assets/content/projects/advertising/signage-raised-letters/signage-raised-letters-06-v2-audit-a242-v6.webp","sha256":"e1f0776537a338b87fb035746d1ee3c7cf619d42a23d111297d725fb7d163db9","provenance":"AI-generated illustration; owner-selected ChatGPT web image; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-27; master PNG SHA256 2e2ed2fb5178407a365cacf1a4e7bcd0d42904ed1b1a8b39655df4347d400a88."},
  "signage-raised-letters-40": {"descriptionVi":"Chữ nổi LED sáng mặt mica trắng kèm logo hình lá, thành nhôm, đặt trên bệ đá trước sân nhà hàng. Dành cho nhà hàng đồng quê, quán ăn sân vườn, khu nghỉ dưỡng, đặt ở cổng hoặc bãi đậu xe, giúp khách tìm thấy quán từ xa về đêm và tạo ấn tượng đầu tiên chỉn chu.","descriptionEn":"Front-lit LED raised letters in white acrylic with a leaf logo and aluminium returns, set on a stone plinth before the restaurant yard. For countryside restaurants, garden eateries and resorts, at the gate or car park, it helps guests find the place from afar at night and makes a polished first impression.","altVi":"Chữ nổi trắng phát sáng kèm logo lá, đặt trên bồn cây trước nhà hàng","altEn":"White glowing raised letters with a leaf logo on a planter in front of a restaurant","source":"/assets/content/projects/advertising/signage-raised-letters/signage-raised-letters-06-v2-audit-a242-v1.webp","sha256":"aef9b301ff0fd7bcc1824c8df40427c25fdf5846dd379ffa3bb78ca2a45ad163","provenance":"AI-generated illustration; owner selected A242-v1 in HTML audit and confirmed in chat 2026-10-22; ChatGPT web gpt-image; original SHA256 f9ef054454738bd5164ae0743d49a5b6f31b76e3622ce657a197d63682160a6b; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "office-signs-wayfinding-54": {"descriptionVi":"Hệ biển chỉ dẫn song ngữ dạng thanh, nền đen chữ trắng, khối màu theo khu kèm icon và mũi tên, gắn trên cột tầng thương mại. Dành cho trung tâm thương mại, siêu thị lớn, đặt gần thang cuốn và lối giao, giúp khách tìm nhà vệ sinh, thang máy, khu ăn uống nhanh và giảm hỏi đường.","descriptionEn":"Bilingual strip signs, white text on black with zone colour blocks, icons and arrows, fixed to a column on the retail floor. For shopping malls and hypermarkets, placed near escalators and junctions, they help shoppers find toilets, lifts and food courts quickly and cut down on asking for directions.","altVi":"Biển đen nhiều thanh ghi Restrooms, Elevators, Escalator, Dining, Exit trên cột","altEn":"Black multi-bar sign with English labels for restrooms, elevators, escalator and exit on pole","source":"/assets/content/projects/advertising/office-signs-wayfinding/office-signs-wayfinding-54-shopping-mall-audit-a156-v3.webp","sha256":"18d5e2fe124c0bef60d8fb32f550740f2278ca0c161f6b6f2d9501baea7363b7","provenance":"AI-generated illustration; ChatGPT web image edit (owner chat 6adfd1e3-5f04-83ec-992a-69601e4ffe58); upscaled RunningHub SeedVR2 tile to 3072; owner approved incl. design system 2026-10-27 01:54Z; master PNG SHA256 f17c1ae02b9b32b33f0834bd39ebe28a5b4f88283c1e1a8eb0f0c8e9024f7e02."},
  "office-signs-wayfinding-55": {"descriptionVi":"Bảng chức danh để bàn inox xước gấp chữ L, khắc hoặc in chữ song ngữ, mặt nghiêng dễ đọc. Dành cho văn phòng giám đốc, phòng họp, ngân hàng, đặt trên bàn làm việc, giúp khách nhận biết đúng người, hợp nội thất hiện đại và bền, không phai màu.","descriptionEn":"Brushed stainless steel desk title plate bent into an L shape, engraved or printed in two languages on an angled, easy-to-read face. For directors' offices, meeting rooms and banks, on the desk, it shows visitors who they are meeting, suits modern interiors and lasts without fading.","altVi":"Bảng chức danh để bàn inox xước ghi giám đốc trên bàn gỗ","altEn":"Brushed stainless desk nameplate reading director title on a timber desk","source":"/assets/content/projects/advertising/office-signs-wayfinding/office-signs-wayfinding-55-stainless-desk-nameplate.webp","sha256":"0f291a704fb3e029c47f2775e19e7db6a2f3356893435865a64cff3af85b4836","provenance":"AI-generated illustration; ChatGPT web image generation 2026-10-24; owner approved audit #798 in chat; original SHA256 f3a7eb77275da937c90209235c9cc06c6faafbe7f244aee7330b3427c40ae5cb; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "office-signs-wayfinding-56": {"descriptionVi":"Cúp pha lê dáng cánh buồm cắt vát cạnh, khắc chữ danh hiệu và năm, gắn đế pha lê đen. Dành cho doanh nghiệp tri ân đối tác, khách hàng, nhà phân phối, trao trong lễ tổng kết hoặc hội nghị, giúp món quà sang trọng, trong suốt bắt sáng và lưu giữ lâu dài.","descriptionEn":"Sail-shaped crystal trophy with bevelled edges, engraved with the title and year, on a black crystal base. For companies thanking partners, customers and distributors, presented at year-end or conferences, it is a premium gift that catches the light and lasts for years.","altVi":"Cúp pha lê trong suốt khắc chữ đối tác tin cậy trên bàn họp","altEn":"Clear crystal trophy engraved with trusted partner text on meeting table","source":"/assets/content/projects/advertising/office-signs-wayfinding/office-signs-wayfinding-56-ky-niem-chuong-20261111.webp","sha256":"87b2e44f5f6dea6c2e74f016cd839e3f7c3b2cafab0baa5605a443b3bb445807","provenance":"AI-generated illustration; ChatGPT web gpt-image (owner chat 6af42b8d-a07c-83ec-8ae5-e6f4c8656812); owner approved 2026-11-11; original PNG SHA256 7cb48adf816655eaa87db5aab89cdf8e62d3b420d2ee5503376a253edd36a569."},
  "office-signs-wayfinding-58": {"descriptionVi":"Kỷ niệm chương gỗ dáng lá cắt CNC, khảm thêm lớp mica vàng và gỗ sẫm, khắc laser danh hiệu, gắn đế gỗ. Dành cho doanh nghiệp, hợp tác xã, trường học trao cho người gắn bó lâu năm, giúp phần thưởng ấm áp, mộc mạc, khác biệt với cúp kim loại và hợp không gian văn phòng.","descriptionEn":"Leaf-shaped CNC-cut wooden award inlaid with gold acrylic and dark wood layers, laser-engraved with the title, on a wooden base. For companies, cooperatives and schools honouring long-serving members, it feels warm and natural, stands apart from metal trophies and suits office shelves.","altVi":"Cúp gỗ khắc chữ cống hiến bền bỉ, có lớp mặt vàng phía sau","altEn":"Timber trophy engraved with lasting dedication text and gold backing layer","source":"/assets/content/projects/advertising/office-signs-wayfinding/office-signs-wayfinding-58-ky-niem-chuong-20261111.webp","sha256":"b818bd6cd5798bc9ce1a5bd41bfe489f1a1b8bffd843e1e73db2d8ed4ad0ced0","provenance":"AI-generated illustration; ChatGPT web gpt-image (owner chat 6af43840-9024-83ec-adaf-e21b5ad680d7); owner approved 2026-11-11; original PNG SHA256 4ba9d1d231bca588c8116a3af1891b213c2c19f506b74a2fb338727d26604872."},
  "office-signs-wayfinding-57": {"descriptionVi":"Kỷ niệm chương mica hai lớp, lớp màu cam cắt hình ngọn lửa ghép mica trong in chữ danh hiệu, gắn đế mica. Dành cho doanh nghiệp vinh danh nhân viên kinh doanh, đại lý xuất sắc, trao tại lễ tổng kết, giúp giải thưởng rực rỡ, nhẹ, giá hợp lý khi làm số lượng nhiều.","descriptionEn":"Two-layer acrylic award with an orange flame-cut layer over clear acrylic printed with the title, on an acrylic base. For companies honouring top sales staff and dealers at year-end events, it is vivid, light and affordable in quantity.","altVi":"Cúp mica trong và cam uốn lượn, khắc chữ doanh số vượt trội","altEn":"Clear and orange curved acrylic trophy engraved with outstanding sales wording","source":"/assets/content/projects/advertising/office-signs-wayfinding/office-signs-wayfinding-57-ky-niem-chuong-20261111.webp","sha256":"431871f3868a4d3b6d2964d084692c76d60163011e297cce4d77bc0667c03577","provenance":"AI-generated illustration; ChatGPT web gpt-image (owner chat 6af437e0-c9d0-83ec-b6eb-6f5c7062f285); owner approved 2026-11-11; original PNG SHA256 1b16c3fe62117d16ee6a545f9ee4958bdcdcdfa4dd3a1e7bf1229a73e2f97b31."},
  "office-signs-wayfinding-59": {"descriptionVi":"Hệ biển chỉ dẫn song ngữ dạng thanh, nền đen chữ trắng, icon lớn và khối màu theo khoa, gắn lên cột đá sảnh chờ. Dành cho bệnh viện, phòng khám, đặt ở sảnh đăng ký và lối vào, giúp người bệnh, người nhà tự đến đúng khoa khám, nhà thuốc, thang máy và lối ra, giảm tải cho quầy hướng dẫn.","descriptionEn":"Bilingual strip signs, white text on black with large icons and department colour blocks, fixed to a stone column in the waiting hall. For hospitals and clinics, placed at registration and entrances, they guide patients and families to departments, pharmacy, lifts and exits, easing the load on the help desk.","altVi":"Bốn thanh xanh, nâu, xám ghi Khoa Khám bệnh, Nhà thuốc, Thang máy, Lối ra","altEn":"Four-bar sign in blue, brown and grey listing clinic, pharmacy, lift and exit","source":"/assets/content/projects/advertising/office-signs-wayfinding/office-signs-wayfinding-59-bien-chi-dan-20261111.webp","sha256":"33f278e4535e71cfeddecca2cf0142dafd98208f2d4084900b9e2ce153021edc","provenance":"AI-generated illustration; ChatGPT web gpt-image (owner approved 2026-11-11, round 2 of G9-2); original PNG SHA256 97de74910e150184fdd6dd41b8a7035edee5ebeaf7cc19dec0370d2c506c20d4. Site file encoded from the 1536 px JPEG preview of that PNG until the PNG is handed over."},
  "signage-raised-letters-41": {"descriptionVi":"Bảng vẫy hộp đèn hình oval mica trắng, chữ xanh dán decal hoặc in UV, khung inox gắn tay vẫy ra vỉa hè. Dành cho phòng khám, nhà thuốc, văn phòng dịch vụ nhà phố, gắn vuông góc mặt tiền, giúp người đi hai chiều đường thấy ngay tên và giờ khám, đèn sáng rõ khi trời tối.","descriptionEn":"Oval acrylic lightbox projecting sign with green decal or UV-printed text on white, in a stainless frame on an arm over the pavement. For clinics, pharmacies and townhouse service offices, at right angles to the facade, it shows the name and hours to both directions of traffic and lights up after dark.","altVi":"Bảng vẫy oval trắng ghi tên phòng khám treo trên mặt tiền tòa nhà","altEn":"White oval projecting sign with clinic name hung on building facade","source":"/assets/content/projects/advertising/signage-raised-letters/signage-raised-letters-41-imagegen-20261019.webp","sha256":"7561436834b46da8194bba877553198069016a344da12cea92cafaedb94dff5b","provenance":"AI-generated illustration; source ID imagegen:2026-10-19:signage-raised-letters-10-a-1; original SHA256 f79cba3d871e8cacd85149151e59b156f237453bac7b9aca9f978c98cf7009ad; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "signage-raised-letters-42": {"descriptionVi":"Bảng vẫy hộp đèn tròn mặt mica sữa, logo hạt cà phê và chữ nổi, viền khung kim loại, gắn tay thép vươn ra từ cột mặt tiền. Dành cho quán cà phê, quán ăn trên phố, giúp tên quán sáng đều khi chạng vạng, dễ nhận ra từ hai đầu đường và hợp với mặt tiền kiểu cũ.","descriptionEn":"Round lightbox sign with an opal acrylic face, a coffee bean logo and raised lettering in a metal rim, on a steel arm projecting from the front column. For street cafes and eateries, it lights the name evenly at dusk, is easy to spot from both ends of the street and suits older-style frontages.","altVi":"Hộp đèn tròn mặt mica in tên quán cà phê, gắn tay vươn trước cửa hàng","altEn":"Round acrylic light box with printed coffee shop name on a bracket in front of the door","source":"/assets/content/projects/advertising/signage-raised-letters/signage-raised-letters-42-imagegen-20261019.webp","sha256":"be672d25ed49cb3480c1d405ab59a4594bf51c4e120ae8583184f68c49ded38e","provenance":"AI-generated illustration; source ID imagegen:2026-10-19:signage-detail-x3-1; original SHA256 91650ee1e1bbcff4f7bd08047743c5c20183d207663b75048086b064600eb1ae; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "kiosk-posm-64": {"descriptionVi":"Kiosk bánh ngọt khung sắt sơn xanh, quầy gỗ ốp nan có hộp đèn tên thương hiệu, tủ kính trưng bày bánh phía trên. Dành cho thương hiệu bánh, đồ ăn vặt mở điểm bán trong siêu thị, trung tâm thương mại, giúp quầy gọn, bánh hiện rõ qua kính và tên thương hiệu sáng nổi giữa lối đi.","descriptionEn":"Pastry kiosk with a green-painted steel frame, a slatted wooden counter with a lit brand lightbox and a glass display case on top. For bakery and snack brands opening a stand in supermarkets and malls, it keeps the counter compact, shows the pastries through glass and lights the brand in the aisle.","altVi":"Kiosk bánh ngọt có bảng đèn ghi tên tiệm bánh trong siêu thị","altEn":"Cake kiosk with illuminated bakery name sign inside a supermarket","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-64-imagegen-20261024.webp","sha256":"724969b3bb97545f7dbec686a9d8c9ca3bd93f1ba41777f334cf9fb5c19d18d2","provenance":"AI-generated illustration; source ID imagegen:2026-10-24:hero-kiosk-a-banh-mien-tay-4; original SHA256 f8742671bb2fa851752e521ddb412ae6f31f0177dd1986c5fb47aded9211f667; upscaled RunningHub SeedVR2 tile to 3072, owner approved 2026-10-26."},
  "kiosk-posm-65": {"descriptionVi":"Tủ trưng bày đứng khung nhôm bo góc, kệ kính có LED hắt từng tầng, hộp đèn in hình quảng cáo phía trên, tủ có cánh bên dưới. Dành cho cửa hàng nước hoa, mỹ phẩm cao cấp, đặt giữa sàn hoặc sát tường, giúp sản phẩm sáng lấp lánh, khách nhìn được nhiều phía và có chỗ chứa hàng.","descriptionEn":"Free-standing display cabinet with a rounded aluminium frame, LED-lit glass shelves, a printed ad lightbox on top and closed storage below. For perfume and premium cosmetics stores, in the middle of the floor or against a wall, it makes products sparkle, is seen from several sides and stores stock.","altVi":"Hai tủ kính trưng bày nước hoa, kệ có đèn LED hắt sau trong cửa hàng","altEn":"Two glass perfume cabinets with LED backlit shelves inside a store","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-65-ke-trung-bay-20261026.webp","sha256":"d0141405fc92fad9b8db0072019ea66c61f363149d71ff3bf507e0db898ba965","provenance":"AI-generated illustration; ChatGPT web gpt-image (owner chat 6adf0fe8-7f04-83ec-932d-ee1162b64f97, card #810); upscaled RunningHub SeedVR2 tile x2 to 3072; owner approved 2026-10-26; upscaled PNG SHA256 b58795010e88f4bda781066e456c9ff627b880714bf86b8396b1a286cb402d76."},
  "kiosk-posm-66": {"descriptionVi":"Vách kệ hốc bo góc gỗ MDF sơn kem, đèn LED viền hốc, hộp đèn in hình người mẫu, kèm bục trưng bày nhiều tầng hình oval. Dành cho cửa hàng mỹ phẩm thiên nhiên, mỹ phẩm từ dừa, giúp sản phẩm trưng bày theo bậc, nổi bật dưới đèn và cửa hàng mang phong cách nhẹ nhàng, sạch sẽ.","descriptionEn":"Rounded-niche wall shelving in cream-painted MDF with LED-edged niches, a model-image lightbox and a tiered oval display island. For natural and coconut cosmetics stores, it shows products in tiers, highlights them under the light and gives the store a soft, clean style.","altVi":"Kệ mỹ phẩm tông kem xanh, đảo trưng bày nhiều tầng và tranh người mẫu","altEn":"Cream and green cosmetics shelving with a tiered island and model artwork","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-66-ke-trung-bay-20261026.webp","sha256":"bfd6183730f932eb2088c17697fb1695eb5e4cad45458b83c32bdc8d5b713b46","provenance":"AI-generated illustration; ChatGPT web image edit with owner mask; upscaled RunningHub SeedVR2 tile to 3072; owner approved to site 2026-10-31; master PNG SHA256 3b3be8b34ebf3be31ddd77cc54d76540389f9c875bf9f7ada415c0144ca089a8."},
  "kiosk-posm-67": {"descriptionVi":"Hệ kệ trưng bày quần áo gỗ MDF sơn kem, thanh treo có LED hắt, hộp đèn in hình bộ sưu tập, kèm bàn đảo gấp đồ ở giữa. Dành cho shop thời trang nữ, boutique, đặt dọc tường và giữa cửa hàng, giúp trang phục treo thoáng, đủ sáng thử mặc và khách dễ xem theo bộ.","descriptionEn":"Clothing display system in cream-painted MDF with LED-lit hanging rails, a collection lightbox and a central folding table. For women's fashion shops and boutiques, along the walls and in the middle, it hangs garments airily, lights them for fitting and lets shoppers browse by outfit.","altVi":"Shop thời trang với kệ hắt đèn, giá treo quần áo và tủ kệ kính","altEn":"Fashion shop with backlit shelves, clothing racks and glass display cabinets","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-67-ke-trung-bay-20261026.webp","sha256":"686ea1f0034d9ee08b440a52e12d7cc44405cbb15dd413e8e79721c29862d3b8","provenance":"AI-generated illustration; ChatGPT web gpt-image (owner chat 6adf2ab8-464c-83ec-b540-764c553cfac0, card #847); upscaled RunningHub SeedVR2 tile x2 to 3072; owner approved 2026-10-26; upscaled PNG SHA256 08dabe3b28bcc8732f36acdcab0f492e6fd22acfc9d2c297b2fe228f6abe276c."},
  "kiosk-posm-68": {"descriptionVi":"Vách kệ hốc vòm gỗ MDF, kệ kính có LED hắt, hộp đèn in hình người mẫu, kèm bục trưng bày thấp cho giày. Dành cho cửa hàng túi xách, giày dép, phụ kiện thời trang, đặt dọc tường chính, giúp từng món nổi bật như trưng bày bảo tàng và khách dễ chọn theo phong cách.","descriptionEn":"Arched niche wall units in MDF with LED-lit glass shelves, a model-image lightbox and a low plinth for shoes. For handbag, shoe and fashion accessory stores, along the main wall, each piece stands out as if in a gallery and shoppers can choose by style.","altVi":"Kệ hốc vòm hắt đèn trưng bày túi xách, giày và kính râm trong shop","altEn":"Backlit arched alcove shelves holding handbags, shoes and sunglasses in shop","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-68-ke-trung-bay-20261026.webp","sha256":"15e611cb705eb9a3f6f489f8404b4bf78bdd72c49afd272b3110530ed510f698","provenance":"AI-generated illustration; ChatGPT web gpt-image (owner chat 6adf2ac2-81a8-83ec-b28e-ba88057a38e5, card #848); upscaled RunningHub SeedVR2 tile x2 to 3072; owner approved 2026-10-26; upscaled PNG SHA256 24364f83ccc1176f9c7e0f61c7e38314e37275d692be03457e348bee56aec0a8."},
  "kiosk-posm-69": {"descriptionVi":"Vách hốc so le gỗ MDF sơn kem, mỗi hốc có LED hắt sáng, hộp đèn in hình nước hoa phía trên. Dành cho cửa hàng nước hoa, mỹ phẩm cao cấp, đặt ở tường chính hoặc cạnh lối vào, giúp từng chai được tôn lên riêng, mặt tường thành điểm nhấn và khách dễ so sánh mùi hương.","descriptionEn":"Staggered niche wall in cream-painted MDF with LED lighting in each niche and a perfume-image lightbox above. For perfume and premium cosmetics stores, on the main wall or by the entrance, it sets off each bottle, turns the wall into a feature and helps shoppers compare scents.","altVi":"Kệ ô vuông hắt đèn trưng bày chai nước hoa, có tranh hoa phía trên","altEn":"Backlit square-cell shelves holding perfume bottles with floral artwork above","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-69-ke-trung-bay-20261026.webp","sha256":"feb7c764a5bf5e5409cb67260b1e13254bade2a3c3c9c2de39343062f5292b83","provenance":"AI-generated illustration; ChatGPT web gpt-image (owner chat 6adf2b24-fc84-83ec-b6c3-ef8d065a3ed0, card #849); upscaled RunningHub SeedVR2 tile x2 to 3072; owner approved 2026-10-26; upscaled PNG SHA256 fe5fc78940cfffa897baae0611ee822ac23987ba554a747eb795022c56d6e0dc."},
  "kiosk-posm-70": {"descriptionVi":"Vách kệ treo tường gỗ MDF phủ melamine, kệ có LED hắt sáng, tủ ngăn kéo bên dưới, kèm hộp đèn in hình người mẫu. Dành cho cửa hàng mỹ phẩm, spa bán lẻ, đặt dọc tường chính, giúp sản phẩm sắp xếp gọn theo dòng, bắt sáng đẹp và tận dụng tối đa mặt tường trưng bày.","descriptionEn":"Wall shelving in melamine-faced MDF with LED-lit shelves, drawer cabinets below and a model-image lightbox. For cosmetics stores and retail spas, along the main wall, it arranges products neatly by line, lights them attractively and makes full use of wall space.","altVi":"Kệ trưng bày mỹ phẩm tông kem có đèn hắt và tranh người mẫu","altEn":"Cream-toned cosmetics shelves with uplighting and model artwork","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-70-ke-trung-bay-20261026.webp","sha256":"828e23e137835f260cdd214d71b8e3d4a46e08827ae691113642e8b2127ad94f","provenance":"AI-generated illustration; ChatGPT web gpt-image (owner chat 6adf2b96-11dc-83ec-a8d6-f1bfae810064, card #850); upscaled RunningHub SeedVR2 tile x2 to 3072; owner approved 2026-10-26; upscaled PNG SHA256 c6228cfcc3d433e95d583608c7bdf3ce3615673642e90b07ff0c4afe0acb429c."},
  "kiosk-posm-71": {"descriptionVi":"Kiosk mỹ phẩm giữa sảnh trung tâm thương mại, quầy bo tròn ốp gỗ có LED hắt chân, kệ hốc vòm phía sau và hộp đèn in hình người mẫu. Dành cho thương hiệu mỹ phẩm, chăm sóc da, giúp điểm bán nổi bật giữa sảnh, khách xem được từ nhiều phía và có chỗ dùng thử, tư vấn.","descriptionEn":"Cosmetics kiosk in a mall atrium with a rounded wood-clad counter with LED base lighting, arched niche shelves behind and a model-image lightbox. For cosmetics and skincare brands, it stands out in the atrium, can be viewed from several sides and has room for testing and advice.","altVi":"Kiosk mỹ phẩm dừa có hốc vòm hắt đèn và tranh người mẫu trong trung tâm","altEn":"Coconut cosmetics kiosk with backlit arched niches and model artwork in mall","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-71-ke-trung-bay-20261026.webp","sha256":"ca79265ec83e001629006e4ed138ac51d75d060196891f962a4a093c7d261f56","provenance":"AI-generated illustration; ChatGPT web gpt-image (owner chat 6adf2d98-dbd0-83ec-8ea0-fd1bda1eef3a, card #851); upscaled RunningHub SeedVR2 tile x2 to 3072; owner approved 2026-10-26; upscaled PNG SHA256 77316cf985a6998e3f642762a970bce93cf4ff27c9e71055aea720fccc72b36e."},
  "kiosk-posm-72": {"descriptionVi":"Tủ trưng bày hốc vòm gỗ MDF sơn màu đất nung, kệ có LED hắt, tủ đựng hàng bên dưới, kèm đảo trưng bày ốp sóng giữa phòng. Dành cho showroom mỹ phẩm, nước hoa, thương hiệu làm đẹp, giúp không gian ấm, sang, có nhận diện riêng và khách xem sản phẩm từ mọi phía.","descriptionEn":"Arched niche display cabinets in terracotta-painted MDF with LED-lit shelves and storage below, plus a fluted island display in the centre. For cosmetics and perfume showrooms and beauty brands, it creates a warm, upscale space with its own identity and lets customers browse from every side.","altVi":"Kệ trưng bày mỹ phẩm hốc vòm cung, đèn hắt và tranh người mẫu trên tường","altEn":"Arched alcove cosmetics shelves with uplighting and model artwork on wall","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-72-ke-trung-bay-20261026.webp","sha256":"d68501cb44edd56d0897c1ace311eb9bcef85ac1ce295cd6b92f3748a3afd784","provenance":"AI-generated illustration; ChatGPT web gpt-image (owner chat 6adf2bb9-b598-83ec-9f35-430736b1648d, card #852); upscaled RunningHub SeedVR2 tile x2 to 3072; owner approved 2026-10-26; upscaled PNG SHA256 590a440a792524b1574d7ff8be95fac5a37c2b461b43c6fd7ed6372f69a6f15c."},
  "kiosk-posm-73": {"descriptionVi":"Vách trưng bày gỗ MDF với kệ tròn gắn hộp đèn LED tròn phía sau, hộp đèn in hình dài phía trên, kèm bục trụ ốp sóng. Dành cho cửa hàng mỹ phẩm thiên nhiên, mỹ phẩm từ dừa, đặt tại tường chính, giúp sản phẩm nổi bật trên nền sáng, tạo điểm nhấn thị giác và khách chụp ảnh.","descriptionEn":"Display wall in MDF with round shelves backed by circular LED lightboxes, a long printed lightbox on top and a fluted pillar plinth. For natural and coconut cosmetics stores, on the main wall, it makes products pop against the glow, creates a visual focal point and invites photos.","altVi":"Kệ tròn hắt đèn trưng bày mỹ phẩm spa, có tranh người mẫu phía trên","altEn":"Backlit round shelves with spa cosmetics and model artwork above","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-73-ke-trung-bay-20261026.webp","sha256":"a0a405cd2b92a71b749913e4cd8da0eb91ee29334306b37fbdf8510179288136","provenance":"AI-generated illustration; ChatGPT web gpt-image (owner chat 6adf10b0-1edc-83ec-be4b-13f67a4b5d68, card #853); upscaled RunningHub SeedVR2 tile x2 to 3072; owner approved 2026-10-26; upscaled PNG SHA256 519eaf667e6a5aff9bb5b871e5211190da30b7d29d5b67777f23267a667c09f9."},
  "kiosk-posm-74": {"descriptionVi":"Backdrop kỷ niệm khung gỗ ép cắt CNC nhiều lớp, chữ số nổi và dải sóng sơn nhũ vàng, in bạt màu xanh trắng, kèm sân khấu thảm. Dành cho doanh nghiệp tổ chức lễ kỷ niệm năm thành lập, tiệc tri ân khách hàng tại khách sạn, giúp sự kiện trang trọng, đúng nhận diện và ảnh chụp đẹp.","descriptionEn":"Anniversary backdrop of layered CNC-cut plywood with raised numerals and gold-finished wave bands, printed in blue and white, with a carpeted stage. For companies celebrating founding anniversaries and customer appreciation nights in hotels, it makes the event formal, on-brand and photogenic.","altVi":"Backdrop xanh dương có số mười lăm nổi ba chiều và viền vàng","altEn":"Blue backdrop with raised three-dimensional numerals and gold trim","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-74-backdrop-20261111.webp","sha256":"15ef5bb82c680b0e96ab2278dfb9095442a2ebddeafb0b5ff816d05ab7ce6155","provenance":"AI-generated illustration; ChatGPT web gpt-image (owner chat 6af44824-6320-83ec-93b9-9fc870d77c12); owner approved 2026-11-11; original PNG SHA256 80b792301183557332a96181620812b5c56cf1aa7a9f5eb2afb80b2f6f75540a."},
  "kiosk-posm-76": {"descriptionVi":"Backdrop tiệc tất niên với tường sequin vàng ở giữa, hai bên tấm formex cắt cong màu xanh navy và kem, viền LED, chữ nổi. Dành cho doanh nghiệp tổ chức tiệc cuối năm, gala tại khách sạn, giúp sân khấu lấp lánh dưới đèn, tạo không khí lễ hội và góc chụp ảnh cho nhân viên.","descriptionEn":"Year-end party backdrop with a gold sequin wall in the centre, curved foam-PVC side panels in navy and cream with LED edging, and raised letters. For companies holding year-end parties and galas in hotels, it shimmers under stage lights, sets a festive mood and gives staff a photo spot.","altVi":"Backdrop vàng sequin có chữ year end party với cổng vòm xanh navy","altEn":"Gold sequin backdrop with year end party lettering beside a navy arch","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-76-backdrop-20261111.webp","sha256":"fe0d6a83c2a8861a38a9ae78d2aab63bf8fcd8f39f4f674b04fffb6e2f65a7c0","provenance":"AI-generated illustration; ChatGPT web gpt-image (owner chat 6af450a2-aa00-83ec-8a13-79fd6b608213); owner approved 2026-11-11; original PNG SHA256 c301db7587dd17be8b9d1e883491173d6575be8762e8d0863f68c8b747c8e05c."},
  "kiosk-posm-75": {"descriptionVi":"Backdrop khai trương gỗ ép cắt CNC dạng vòm, sơn hồng trắng, chữ nổi mạ vàng, viền LED, cắm hoa tươi hai bên. Dành cho spa, thẩm mỹ viện, tiệm nail ngày khai trương, dựng trước cửa hoặc sảnh, giúp sự kiện sang trọng, tạo góc chụp hình cho khách và quảng bá thương hiệu.","descriptionEn":"Arched opening backdrop of CNC-cut plywood painted pink and white, with gold-plated raised letters, LED edging and fresh flowers on both sides. For spas, beauty clinics and nail salons on opening day, at the door or lobby, it makes the event elegant, gives guests a photo spot and promotes the brand.","altVi":"Backdrop spa hồng trắng có chữ vàng, hoa và viền đèn LED","altEn":"Pink and white spa backdrop with gold lettering, flowers and LED edge lights","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-75-spa-20261111.webp","sha256":"95b9d8deb51cbeca46fca37ef27dcc8560ca84b8d643f948f834bdb18fc47390","provenance":"AI-generated illustration; ChatGPT web gpt-image (owner chat 6af46231-5064-83ec-a0be-ed613a7aee85, latest image chosen by the owner); owner approved 2026-11-11; original PNG SHA256 d2318c6d35bb5a1b6849a015b828d98d510f652a5de4a66baf87479709358ca3."},
  "kiosk-posm-77": {"descriptionVi":"Quầy cong dán veneer óc chó vân lượn, nẹp đồng viền mặt và LED hắt dưới mặt quầy, kèm vách veneer có kệ nổi hắt đèn. Dành cho showroom, cửa hàng mỹ nghệ, nội thất cao cấp, đặt làm quầy đón khách hoặc bàn trưng bày, giúp không gian sang trọng và sản phẩm nổi bật dưới ánh sáng ấm.","descriptionEn":"Curved counter in figured walnut veneer with brass edge trim and LED lighting under the top, plus a veneer wall with lit floating shelves. For showrooms and premium craft or furniture stores, used as a welcome desk or display table, it adds luxury and makes products stand out in warm light.","altVi":"Quầy gỗ uốn lượn viền inox, LED hắt và kệ bát đĩa gốm","altEn":"Curved timber counter with stainless edging, uplighting and shelves of ceramic dishes","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-77-ke-dua-20261111.webp","sha256":"22ef0a37e6e910a3c0215b32bbb92050d37d7a7e269e0d79f0cca83df09ac213","provenance":"AI-generated illustration; ChatGPT web gpt-image (owner approved 2026-11-11, round 3 of G8-1, ceiling changed to a flat plaster ceiling); original PNG SHA256 d8477346 (full hash in the owner PC record.json). Site file encoded from the 1536 px JPEG preview of that PNG until the PNG is handed over."},
  "kiosk-posm-79": {"descriptionVi":"Gian hàng triển lãm khung gỗ tự nhiên, bảng tên gỗ khắc chữ, vách treo dụng cụ phía sau, quầy và hộp gỗ trưng bày sản phẩm. Dành cho thương hiệu dụng cụ thợ mộc, đồ gỗ, máy cầm tay dự triển lãm, giúp sản phẩm treo rõ từng món, khách cầm thử dễ và gian hàng đúng chất nghề.","descriptionEn":"Exhibition booth with a natural timber frame, an engraved wooden name board, a tool pegboard wall behind and a counter and wooden boxes for products. For woodworking tool, furniture and power tool brands at expos, it hangs each item clearly, lets visitors handle products and fits the craft's character.","altVi":"Tường đục lỗ treo bào, đục, kẹp và đĩa cưa trong gian hàng gỗ sáng màu","altEn":"Pegboard wall holding planes, chisels, clamps and saw blades in light timber booth","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-79-gian-hang-dung-cu-20261113.webp","sha256":"8ef0f08a21cc33c0a7c2608adc09ce9d81ab6847802b41d41ada8d004a12054f","provenance":"AI-generated illustration; ChatGPT web gpt-image (chat 6af6300f-6274-83ec-acec-7691218782b7); owner approved 2026-11-13; original PNG SHA256 49e67b72115b14a5e66b55935741938ec0485f6458e29326e201f1af65e02ad3."},
  "kiosk-posm-80": {"descriptionVi":"Backdrop hội nghị khung formex cắt cong nhiều lớp, chữ nổi, mặt in bạt phong cảnh sông nước, viền cánh gà màu xanh lá, dựng trên sân khấu thảm đỏ. Dành cho hội nghị khách hàng, đại hội cổ đông tại sảnh khách sạn, giúp sự kiện chuyên nghiệp, ảnh chụp đẹp và nhấn mạnh thông điệp thương hiệu.","descriptionEn":"Conference backdrop of a layered curved foam-PVC frame with raised letters, a printed river landscape and green side wings, on a red-carpeted stage. For customer conferences and shareholder meetings in hotel ballrooms, it makes the event professional, photogenic and on-message for the brand.","altVi":"Backdrop bạt in hình sông nước có chữ hội nghị khách hàng trên sân khấu","altEn":"Printed fabric backdrop with river scene and customer conference text on stage","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-80-backdrop-hoi-nghi-20261113.webp","sha256":"08611aff800abbb12074b16db7960f0ab42cbea260ed75cc751b081f7535e62c","provenance":"AI-generated illustration; ChatGPT web gpt-image (chat 6af6197b-f13c-83ec-875c-bf769550caa9); owner approved 2026-11-13; original PNG SHA256 7d3dc2c872f9140e164a506663694ac0ecac7b64109c293deac46285666e95ce."},
  "kiosk-posm-81": {"descriptionVi":"Backdrop khai trương khung giàn thép, căng bạt in chữ và biểu tượng, kèm kệ hoa chúc mừng hai bên, đặt trước cửa. Dành cho phòng khám, cửa hàng, công ty ngày khai trương, dựng trên vỉa hè trước mặt tiền, giúp người đi đường biết sự kiện, tạo không khí và tái sử dụng khung nhiều lần.","descriptionEn":"Opening backdrop on a steel truss with a printed banner of text and icons, flanked by congratulation flower stands, set at the entrance. For clinics, shops and companies on opening day, on the pavement before the facade, it tells passers-by about the event, sets the mood and the frame is reused many times.","altVi":"Backdrop bạt in có chữ khai trương phòng khám trên khung sắt trước cửa","altEn":"Printed fabric backdrop with clinic opening text on iron frame in front of door","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-81-backdrop-khai-truong-20261113.webp","sha256":"397a4b28ee48f9575ad2988dad374d45ddf66142d58868ea68d2db38f5be58a3","provenance":"AI-generated illustration; ChatGPT web gpt-image (chat 6af61980-baf0-83ec-af4b-79e04d4642ae); owner approved 2026-11-13; original PNG SHA256 21765622dc74e75bd624ce3362a87e0ad498c0012628e895188186fb5a4f64e2."},
  "kiosk-posm-82": {"descriptionVi":"Backdrop tất niên gỗ ép cắt CNC dạng cuộn thư, sơn đỏ trắng, viền LED, gắn hoa giấy lớn và chữ nổi. Dành cho doanh nghiệp, cơ quan tổ chức tiệc tất niên, họp mặt cuối năm tại sảnh khách sạn, giúp không khí Tết ấm áp, trang trọng và tạo góc chụp ảnh tập thể.","descriptionEn":"Year-end backdrop of CNC-cut plywood in a scroll shape painted red and white, with LED edging, large paper flowers and raised lettering. For companies and agencies holding year-end parties and gatherings in hotel lobbies, it brings a warm, formal Tet mood and a group photo corner.","altVi":"Backdrop đỏ vàng có hoa, quạt giấy và viền đèn LED","altEn":"Red and gold backdrop with flowers, paper fans and LED edge lighting","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-82-backdrop-tat-nien-20261113.webp","sha256":"2186bfd90841ee3e81a6f98a433a6a34e2a02504033d54d037892cccebe7db06","provenance":"AI-generated illustration; ChatGPT web gpt-image (chat 6af6199e-3224-83ec-815d-3ad591b6e292); owner approved 2026-11-13; original PNG SHA256 695566b7e6a6a36d7a39adf17f9de606d7d6f0d6b3f126645e00cb1e6c97db7b."},
  "print-decals-40": {"descriptionVi":"Menu bìa cứng gấp đôi đứng được, in hình món chè, giá và minh họa miền Tây, cán màng chống nước. Dành cho quán chè, quán tráng miệng, cà phê, đặt trên từng bàn, giúp khách xem món ngay khi ngồi, gọi nhanh hơn và thực đơn bền, lau sạch được.","descriptionEn":"Folded hardboard menu that stands on its own, printed with dessert photos, prices and Mekong Delta illustrations, laminated against water. For sweet soup, dessert shops and cafes, on every table, it shows the menu as soon as guests sit, speeds up ordering and stays durable and wipeable.","altVi":"Menu bìa cứng mở đôi có tranh miền Tây, ghi các loại chè","altEn":"Hardcover bifold menu with western-region painting and dessert listings","source":"/assets/content/projects/advertising/print-decals/print-decals-40-menu-che-20261113.webp","sha256":"03c3691ee1d585eddc931ba5c23d4e596a923e5f45ede46a45d7a1edbea3ae1a","provenance":"AI-generated illustration; ChatGPT web gpt-image (chat 6af618b3-740c-83ec-b112-ea02407fa1c1); owner approved 2026-11-13; original PNG SHA256 8568d6da828cdb1be367d5158db752374773b210f1f7c2a6cdf1ed6a69d86a9c."},
  "print-decals-41": {"descriptionVi":"Bộ bao bì in cho trà sữa gồm túi giấy quai xoắn, ly nhựa in logo và đai giấy cầm ly, cùng họa tiết tông hồng nâu. Dành cho quán trà sữa, đồ uống mang đi, đơn giao hàng, dùng tại quầy và khi đóng gói, giúp khách cầm ly không lạnh tay, thương hiệu đồng bộ và dễ nhận ra trên mạng xã hội.","descriptionEn":"Printed bubble tea packaging set with a twisted-handle paper bag, logo plastic cups and paper cup sleeves in a pink-brown pattern. For bubble tea and takeaway drinks shops and delivery, at the counter and when packing, it keeps hands from the cold, unifies the brand and makes it recognisable on social media.","altVi":"Túi giấy quai và ly nhựa in tên trà sữa đặt trên bàn gỗ","altEn":"Handled paper bags and plastic cups printed with milk tea name on timber table","source":"/assets/content/projects/advertising/print-decals/print-decals-41-bao-bi-tra-sua-20261113.webp","sha256":"4a82712300f7322c05f68b5c2273429e613a8ff3c3f9323978870d47cb75a4bf","provenance":"AI-generated illustration; ChatGPT web gpt-image (chat 6af618ec-662c-83ec-9500-9f52effcc614); owner approved 2026-11-13; original PNG SHA256 518aa32c3b3351be07170308b752f7baa2d3abdb4e8c511c6a6ee2727e946e36."},
  "office-signs-wayfinding-61": {"descriptionVi":"Biển phòng in decal mờ song ngữ dán thẳng lên kính cửa, kèm dải decal mờ che tầm nhìn ngang cửa. Dành cho bệnh viện, phòng khám, phòng tư vấn, giúp người bệnh tìm đúng phòng, giữ riêng tư bên trong mà phòng vẫn đủ sáng, thay nội dung dễ và chi phí thấp.","descriptionEn":"Bilingual room sign in frosted printed decal applied straight onto the door glass, with a frosted privacy band across the door. For hospitals, clinics and consulting rooms, it helps patients find the right room, keeps privacy inside while letting light through, and is cheap and easy to change.","altVi":"Decal dán kính ghi phòng khám trên cửa kính phòng khám","altEn":"Frosted decal reading clinic on the glass door of a consulting room","source":"/assets/content/projects/advertising/office-signs-wayfinding/office-signs-wayfinding-61-bien-phong-kinh-20261113.webp","sha256":"0a1d03a911646d6220e31c33911e5efeeb96ad73279d7c49117408eb03109242","provenance":"AI-generated illustration; ChatGPT web gpt-image (chat 6af6240d-0c14-83ec-b98a-83940513ad3b); owner approved 2026-11-13; original PNG SHA256 e2d4e821f6fa7cc9aa14c3262dce4bddb6effec6eb17359525ae55393328d1ce."},
  "office-signs-wayfinding-62": {"descriptionVi":"Biển số phòng mica đen in hoặc khắc chữ vàng, bo cạnh, dán băng keo hai mặt hoặc bắt vít lên cửa gỗ. Dành cho khách sạn, nhà nghỉ, homestay, văn phòng, gắn trên cửa từng phòng ngang tầm mắt, giúp khách tìm đúng phòng nhanh, hành lang gọn và đồng bộ với nội thất.","descriptionEn":"Black acrylic room number sign with gold printed or engraved text and finished edges, fixed to the wooden door with double-sided tape or screws. For hotels, guesthouses, homestays and offices, on each door at eye level, it helps guests find their room fast and keeps corridors tidy and in tune with the interior.","altVi":"Biển số phòng mica đen chữ vàng gắn trên cửa gỗ khách sạn","altEn":"Black acrylic room number sign with gold numerals on hotel timber door","source":"/assets/content/projects/advertising/office-signs-wayfinding/office-signs-wayfinding-62-bien-phong-khach-san-20261113.webp","sha256":"9ba9020f51ab96a5843fc76cfe7e201ac0f1102d78b1b693216fc1f1330fe9ab","provenance":"AI-generated illustration; ChatGPT web gpt-image (chat 6af623d1-b6a8-83ec-ae8e-b3d13e1a4dcf); owner approved 2026-11-13; original PNG SHA256 ffcbeecac5a65b7b16c83de7f092a9576dde59efa97e7f0a2c6151b848fca4bc."},
  "office-signs-wayfinding-63": {"descriptionVi":"Biển phòng giám đốc tấm kính cường lực sơn đen, chữ mica vàng gương song ngữ, bắt bốn chân đinh vàng lên tường cạnh cửa. Dành cho phòng lãnh đạo ở văn phòng công ty, ngân hàng, khách sạn, giúp khách nhận ra phòng ngay và tạo vẻ trang trọng, sang cho khu làm việc.","descriptionEn":"Director's office sign on black-painted tempered glass with bilingual gold mirror acrylic lettering, fixed with four gold standoffs beside the door. For executive offices in companies, banks and hotels, it lets visitors recognise the room immediately and adds a formal, upscale feel to the workspace.","altVi":"Biển kính cường lực đen chữ vàng ghi phòng giám đốc, gắn tường cạnh cửa gỗ","altEn":"Black tempered glass sign with gold lettering for a director's office beside a timber door","source":"/assets/content/projects/advertising/office-signs-wayfinding/office-signs-wayfinding-63-bien-phong-giam-doc-20261113.webp","sha256":"429bd0173df52a58ffb5b93561f6d1115c54269ee1158b4b7d394ebf7fe3cd42","provenance":"AI-generated illustration; ChatGPT web gpt-image (chat 6af6303c-dd24-83ec-8de8-a6c28e33fb48); owner approved 2026-11-13; original PNG SHA256 8558d3ffe9914677fd87747416dec4f75ee420fb326a26c9de60acda8bc1973e."},
  "office-signs-wayfinding-64": {"descriptionVi":"Bảng để bàn mica trong chữ L, kẹp lá in chữ hướng dẫn xanh đậm trên nền trắng, đặt vững trên mặt quầy. Dành cho bệnh viện, phòng khám, cơ quan hành chính, đặt tại bàn hướng dẫn hoặc tiếp nhận, giúp người bệnh và người dân tìm đúng chỗ hỏi, giảm chờ đợi và dễ thay nội dung.","descriptionEn":"Clear L-shaped acrylic desk sign holding a printed insert with dark blue guidance text on white, standing steady on the counter. For hospitals, clinics and public offices, at information or reception desks, it helps patients and citizens find the right desk, cuts waiting and is easy to update.","altVi":"Bảng bàn hướng dẫn mica trắng chữ xanh đặt trên quầy gỗ bệnh viện","altEn":"White acrylic information desk sign with blue lettering on hospital timber counter","source":"/assets/content/projects/advertising/office-signs-wayfinding/office-signs-wayfinding-64-ban-huong-dan-20261113.webp","sha256":"1768df998c21b3699f35b518216eeed695867faf84bc63e72802578db79a560e","provenance":"AI-generated illustration; ChatGPT web gpt-image (chat 6af62446-e0a8-83ec-9973-68ecf1db8cf4); owner approved 2026-11-13; original PNG SHA256 293e0061fae264dad84a11d49bfd1b534a01df687ee975715d09c6f16bd0ea43."},
  "office-signs-wayfinding-65": {"descriptionVi":"Bảng chức danh đế gỗ đỏ, mặt đồng vàng xước khắc chữ, xếp dọc bàn hội đồng phủ khăn trắng. Dành cho cơ quan, trường học, hội nghị, đại hội cổ đông, đặt trước chỗ ngồi chủ tọa và thành viên, giúp vị trí rõ ràng, nghi thức trang trọng và dùng lại nhiều kỳ họp.","descriptionEn":"Title plates on red wood bases with engraved brushed brass faces, lined along a white-clothed board table. For agencies, schools, conferences and shareholder meetings, in front of chair and member seats, they make places clear, keep the ceremony formal and are reused across sessions.","altVi":"Bảng chức danh gỗ mặt vàng ghi thư ký đặt trên bàn họp có khăn trắng","altEn":"Gold-faced timber nameplate reading secretary on a meeting table with white cloth","source":"/assets/content/projects/advertising/office-signs-wayfinding/office-signs-wayfinding-65-chuc-danh-hoi-dong-20261113.webp","sha256":"d8ea4e31c61103671d8a1a7e77cf1ae5ebd544b91b6e09c544c6da3c3d868908","provenance":"AI-generated illustration; ChatGPT web gpt-image (chat 6af6187d-e4cc-83ec-a4b1-2c31f73249c6); owner approved 2026-11-13; original PNG SHA256 39f2ba5ca083d5b5c752fccc1a4d7c9b0dbbbb7a50f3fc6e9f4a521bc47bf422."},
  "office-signs-wayfinding-66": {"descriptionVi":"Bảng chức danh mica trong in UV chữ xanh trên nền trắng có họa tiết sóng, cắm trên đế gỗ sáng. Dành cho ngân hàng, văn phòng tư vấn, quầy giao dịch, đặt trên bàn nhân viên, giúp khách biết ngay người phụ trách, quầy gọn gàng và đồng bộ màu nhận diện thương hiệu.","descriptionEn":"Clear acrylic title plate UV-printed with blue text on white with a wave motif, slotted into a light wood base. For banks, advisory offices and service counters, on staff desks, it tells customers who is in charge, keeps counters tidy and matches the brand colours.","altVi":"Bảng mica sóng xanh đế gỗ ghi chuyên viên tư vấn trên bàn văn phòng","altEn":"Wavy blue acrylic sign on timber base reading consultant on an office desk","source":"/assets/content/projects/advertising/office-signs-wayfinding/office-signs-wayfinding-66-chuc-danh-tu-van-20261113.webp","sha256":"d04c5b9e9ed6bf711324939f1b7456b6ea59b3ce270954ad018fab6eee9e615b","provenance":"AI-generated illustration; ChatGPT web gpt-image (chat 6af61882-7eb4-83ec-ade8-a8f616e04a74); owner approved 2026-11-13; original PNG SHA256 40231e296151e4a8297a20243123534e817e136d168029d9595bfce66ad27706."},
  "office-signs-wayfinding-67": {"descriptionVi":"Bảng lễ tân để bàn gỗ sẫm, chữ song ngữ inox hoặc mica mạ vàng gương gắn nổi, đế gỗ vững. Dành cho khách sạn, resort, nhà hàng, văn phòng, đặt trên quầy lễ tân, giúp khách nhận biết quầy ngay khi bước vào, tạo vẻ sang trọng và hợp quầy đá, quầy gỗ.","descriptionEn":"Dark wood reception desk sign with raised bilingual letters in mirror-gold stainless steel or acrylic on a solid wooden base. For hotels, resorts, restaurants and offices, on the reception counter, it marks the desk as soon as guests walk in, adds elegance and suits stone or wood counters.","altVi":"Bảng lễ tân gỗ tối có chữ vàng đặt trên mặt đá","altEn":"Dark timber reception sign with gold lettering on a stone top","source":"/assets/content/projects/advertising/office-signs-wayfinding/office-signs-wayfinding-67-chuc-danh-le-tan-20261113.webp","sha256":"0e12140490f531fed98e59ff5222b5aef5d9b4759ab9e5b6b8a86c22e9fad6b9","provenance":"AI-generated illustration; ChatGPT web gpt-image (chat 6af6244e-3350-83ec-8fdd-009e4fe48a65); owner approved 2026-11-13; original PNG SHA256 f76805ba3cd78851d4b34d7b5889e89dcd9127d056045d37f40333ae9459acb2."},
  "office-signs-wayfinding-68": {"descriptionVi":"Kỷ niệm chương pha lê dáng giọt nước cắt nhiều mặt, khắc chữ ghi nhận và họa tiết hoa sen, gắn đế pha lê đen. Dành cho bệnh viện, phòng khám, tổ chức trao cho bác sĩ, nhân viên tận tâm, giúp lời tri ân trang trọng, đặt trên bàn làm việc bắt sáng đẹp và giữ mãi.","descriptionEn":"Faceted teardrop crystal award engraved with a recognition message and a lotus motif, on a black crystal base. For hospitals, clinics and organisations thanking dedicated doctors and staff, it makes the tribute formal, catches the light on a desk and is kept for good.","altVi":"Cúp pha lê nhiều cạnh khắc chữ ghi nhận tận tâm, đế đen","altEn":"Multi-faceted crystal trophy engraved with dedication recognition text on black base","source":"/assets/content/projects/advertising/office-signs-wayfinding/office-signs-wayfinding-68-ky-niem-chuong-pha-le-20261113.webp","sha256":"1d1d7b61286fd5377228cb163a056426457078d584f99ac3253712e24a996ee7","provenance":"AI-generated illustration; ChatGPT web gpt-image (chat 6af61911-53e4-83ec-8a2d-29d74ac7a038); owner approved 2026-11-13; original PNG SHA256 b95c9166f6025d8e42a253e971bb6d80b96b26141b23cdecb2502ca868e4ce1d."},
  "office-signs-wayfinding-69": {"descriptionVi":"Bảng kỷ niệm để bàn khung gỗ sẫm, mặt đồng vàng xước khắc chữ, chân đế gỗ dựng nghiêng. Dành cho doanh nghiệp, cơ quan tặng đối tác, nhân viên dịp kỷ niệm thành lập, đặt trên bàn làm việc hoặc kệ, giúp lời tri ân trang trọng, bền màu và lưu giữ lâu năm.","descriptionEn":"Desk commemorative plaque with a dark wood frame, an engraved brushed gold brass face and an angled wooden stand. For companies and agencies giving partners or staff anniversary gifts, on desks or shelves, it makes the tribute formal, keeps its colour and lasts for years.","altVi":"Bảng kỷ niệm gỗ có mặt vàng xước, đặt trên bàn làm việc","altEn":"Wood anniversary plaque with brushed gold face on office desk","source":"/assets/content/projects/advertising/office-signs-wayfinding/office-signs-wayfinding-69-ky-niem-chuong-go-dong-20261113.webp","sha256":"50cdc01a3bf88061431bf2615514e2fa9649852c84623201c8de737402f2a24e","provenance":"AI-generated illustration; ChatGPT web gpt-image (chat 6af63042-3308-83ec-9d59-040ab5191ae5); owner approved 2026-11-13; original PNG SHA256 27a700069c56559ccb40f97d6f35ea898c4f3f5a497181ca310ff06a72a2f9bf."},
  "office-signs-wayfinding-70": {"descriptionVi":"Cúp mica trong dáng lục giác cắt vát, in UV màu xanh vàng, ngôi sao và chữ vinh danh, gắn đế mica. Dành cho doanh nghiệp, trường học trao cho nhân viên, học sinh xuất sắc tại lễ tổng kết, giúp giải thưởng rực rỡ, nhẹ, giá hợp lý và in được tên từng người.","descriptionEn":"Clear hexagonal acrylic trophy with bevelled edges, UV-printed in blue and gold with stars and recognition text, on an acrylic base. For companies and schools rewarding top staff and students at year-end events, it is vivid, light, affordable and personalised with each name.","altVi":"Ba cúp mica trong hình khiên ghi vinh danh nhân viên xuất sắc trên bàn","altEn":"Three clear acrylic shield trophies with staff honour text on a table","source":"/assets/content/projects/advertising/office-signs-wayfinding/office-signs-wayfinding-70-ky-niem-chuong-mica-uv-20261113.webp","sha256":"3e77151887d30eb4d31c38afa03b217a406b3bd94734435e727f7e9012183527","provenance":"AI-generated illustration; ChatGPT web gpt-image (chat 6af6194c-6ab4-83ec-9b44-e76f9a9ecd6a); owner approved 2026-11-13; original PNG SHA256 fc8a4603106c88090d40b2bdb489a6557a4423751ecd7d8fa0f4ecac4ac9d7a3."},
  "led-displays-lightboxes-53": {"descriptionVi":"Bảng LED chữ đỏ chạy giờ mở cửa, gắn ngay dưới bảng hiệu hộp đèn vòm in ảnh chó mèo có đèn rọi. Dành cho phòng khám thú y, tiệm thú cưng, cửa hàng nhà phố, gắn trên mặt tiền, giúp khách biết giờ mở cửa cả khi tiệm đóng và nhận diện tiệm từ xa.","descriptionEn":"Red LED message strip showing opening hours, fixed right below an arched lightbox sign printed with a cat and dog, with spotlights. For vet clinics, pet shops and townhouse stores, on the facade, it shows hours even when shuttered and identifies the shop from afar.","altVi":"Mặt tiền có bảng hiệu hộp đèn vòm in ảnh chó mèo và bảng LED đỏ báo giờ mở cửa","altEn":"Shopfront with arched lightbox sign showing a cat and dog and red LED opening hours","source":"/assets/content/projects/advertising/led-displays-lightboxes/led-displays-lightboxes-53-led-phong-kham-thu-y-20261114.webp","sha256":"4cd6b58e72202c6502cbedbeca0faeee2e9b4a839c8ac7e416c18d54af0956ed","provenance":"AI-generated illustration; ChatGPT web gpt-image (chat 6af8c431-414c-83ec-b68d-595445666f11), edited by owner in ChatGPT from the 2026-11-13 image; owner approved 2026-11-14; original PNG SHA256 c593d31ecff4d40f831ea642935f0a4907d1f5a49117bbd6407f13acc030ca00."},
  "office-signs-wayfinding-60": {"descriptionVi":"Biển công ty inox xước, chữ ăn mòn hoặc in UV, gắn chân cách lên trụ cổng sơn xám. Dành cho công ty tư vấn, thiết kế, văn phòng luật, doanh nghiệp nhà phố, gắn ở cổng hoặc tường mặt tiền, giúp khách tìm đúng địa chỉ, thể hiện sự chuyên nghiệp và bền trước nắng mưa.","descriptionEn":"Brushed stainless steel company plate with etched or UV-printed text, on stand-offs on a grey gate pillar. For consultancies, design and law firms and townhouse businesses, at the gate or facade, it helps visitors find the address, looks professional and withstands sun and rain.","altVi":"Biển inox xước ghi tên công ty tư vấn gắn trụ cổng văn phòng","altEn":"Brushed stainless sign with consulting firm name on office gate pillar","source":"/assets/content/projects/advertising/office-signs-wayfinding/office-signs-wayfinding-60-bang-ten-cong-ty-20261113.webp","sha256":"299cb749f4bf10c52b09eaae0777cde2d151a5a090e46e9c6aff4a6ba4ad6dea","provenance":"AI-generated illustration; ChatGPT web gpt-image (chat 6af63037-6ca0-83ec-9c3d-e66550dca4b3); owner approved 2026-11-13; original PNG SHA256 c68bbf3fb7a9256b04203440388ca5e7ee7abfeb148429b7177d8790324b7c3c."},
  "office-signs-wayfinding-71": {"descriptionVi":"Cúp gỗ dáng lá cắt CNC, gân lá khắc sâu tông hai màu, chữ danh hiệu khắc laser, gắn đế gỗ óc chó. Dành cho trường học, câu lạc bộ, doanh nghiệp trao giải nhất cho cuộc thi, giúp giải thưởng độc đáo, thân thiện môi trường và đẹp khi trưng bày trên kệ.","descriptionEn":"Leaf-shaped CNC-cut wooden trophy with deeply carved two-tone veins and a laser-engraved title, on a walnut base. For schools, clubs and companies awarding first prizes in contests, it is distinctive, eco-friendly and handsome on a display shelf.","altVi":"Cúp gỗ hình lá khắc hạng nhất đặt trên đế gỗ trên bàn","altEn":"Leaf-shaped timber trophy engraved with first prize on wooden base on desk","source":"/assets/content/projects/advertising/office-signs-wayfinding/office-signs-wayfinding-71-ky-niem-chuong-la-dua-20261113.webp","sha256":"5eb1acc3f97587b264b74347b38ebb9b09ec7bbc271699a4e04fb9f1fb598d21","provenance":"AI-generated illustration; ChatGPT web gpt-image (chat 6af63047-a58c-83ec-93d2-507fdd20cfd6); owner approved 2026-11-13; original PNG SHA256 dad96a0d987e161c21493ea1505724981dc50b3b706c6ae19ecc781de9f33136."},
  "print-decals-42": {"descriptionVi":"Bộ bao bì giấy cho kẹo dừa gồm hộp giấy in hình dừa và cảnh sông nước, túi giấy quai dây cùng bộ nhận diện. Dành cho cơ sở sản xuất kẹo dừa, đặc sản, OCOP, bày bán tại cửa hàng, quầy du lịch hoặc làm quà biếu, giúp sản phẩm đẹp mắt, đồng bộ và dễ bán cho khách du lịch.","descriptionEn":"Paper packaging set for coconut candy with printed boxes showing coconuts and river scenes and a matching rope-handle paper bag. For coconut candy makers, specialty and OCOP brands, sold in shops, tourist counters or as gifts, it makes products attractive, consistent and easy to sell to tourists.","altVi":"Túi quai xách và hộp giấy in hình dừa kèm kẹo dừa trên bàn gỗ","altEn":"Handled bag and paper box printed with coconut graphics beside candy on timber table","source":"/assets/content/projects/advertising/print-decals/print-decals-42-bao-bi-keo-dua-20261113.webp","sha256":"ccc862b2360b7c5d657073224b7e08376fbb47f31e564fe02da5099f20d5f952","provenance":"AI-generated illustration; ChatGPT web gpt-image, edited by owner in ChatGPT and handed over from his Downloads; owner approved 2026-11-13; original PNG SHA256 5ba0415a9bf016939d99ac6dbd6453b6e90e189415b97cbb27c4c953785bdb73."},
  "print-decals-43": {"descriptionVi":"Thẻ khách thân thiết và vé mời in trên giấy mỹ thuật, ép kim hoặc in màu họa tiết hoa sen, cảnh sông nước. Dành cho khách sạn, resort, nhà hàng, đặt trên khay cói tại quầy lễ tân hoặc gửi kèm phòng, giúp chăm sóc khách quen, mời tham dự sự kiện và nâng hình ảnh thương hiệu.","descriptionEn":"Loyalty cards and invitation tickets printed on fine art paper with foil or colour lotus and river motifs. For hotels, resorts and restaurants, displayed on a sedge tray at reception or placed in rooms, they reward regulars, invite guests to events and lift the brand image.","altVi":"Thẻ giấy khách thân thiết và vé mời tiệc tối xếp trên khay cói","altEn":"Paper loyalty cards and dinner invitation tickets stacked on woven tray","source":"/assets/content/projects/advertising/print-decals/print-decals-43-the-ve-moi-20261113.webp","sha256":"014653eb23ce3ffbffcbcee504c455117d3aea36ef91c03f1f2cafd031c64028","provenance":"AI-generated illustration; ChatGPT web gpt-image, edited by owner in ChatGPT and handed over from his Downloads; owner approved 2026-11-13; original PNG SHA256 3a5ff391a13d9c00f7432e5b1d381aeb1f419adc0de79c40a04637e44456bec2."},
});

